local P = LoreForeverPacks.Begin("LoreForever_Lang_deDE")
P.entries["zone:razorfenkraul"] = {n="Kral der Klingenhauer",s="Versteckt im äußersten Süden des Brachlands liegt Kral der Klingenhauer, das uralte Kernland der Borstennacken Kalimdors. Diese wilden Stämme verehren das dichte Labyrinth aus gigantischem Dornengestrüpp als heilige Ruhestätte ihres Stammvaters, des gefallenen Halbgottes Agamaggan. Heute ist der Kral unter der Tyrannei der Borstennacken-Matriarchin Charlga Klingenflanke aggressiv und feindselig geworden, deren finstere Machenschaften die gesamte Region bedrohen.",h="Versteckt im äußersten Süden des Brachlands liegt Kral der Klingenhauer, das uralte Kernland der...",kw={"agamaggan","brachland","charlga","halmgar","kral","borstennacken","ramtusk","razorfen","razorflank","geißel"},ang={["class:Shaman"]="Die Geomantie der Borstennacken krümmt die Erde und die Elemente um das Blut von Agamaggan und gewährt einen schonungslosen Einblick in urtümliche schamanistische Mächte, die mit grausamer Absicht geführt werden.",["faction:Horde"]="Die Aggressionen innerhalb des Krals zu neutralisieren, ist unerlässlich, um Versorgungswagen und junge Siedlungen in den südlichen Weiten des Brachlands zu schützen.",["race:Tauren"]="Die Borstennacken machen Mulgore seit Langem die Grenzen streitig, und ihre Schändung der Erde durch finstere Bündnisse macht die Säuberung des Krals zu einer lebenswichtigen Angelegenheit der Stammesverteidigung.",["race:Undead"]="Apotheker aus Unterstadt zeigen reges Interesse an den bizarren Reagenzien, dem Fledermausguano und den Gerüchten über Übergriffe der Geißel innerhalb des Dornengestrüpps."},sec={{t="Blut des Ebergottes",b="Vor zehntausend Jahren stürzte sich der kolossale wilde Gott Agamaggan während des verheerenden Krieges der Ahnen in den Kampf gegen die Brennende Legion. Der große Eber fand schließlich in der Schlacht den Tod, doch sein Opfer bewahrte das Leben auf Azeroth. Legenden besagen, dass überall dort, wo sein Blut in die Erde sickerte, gewaltige dornenbewehrte Ranken emporwuchsen und dichte, wehrhafte Labyrinthe in den südlichen Ebenen bildeten. Die Borstennacken, die Agamaggan als ihren göttlichen Urahn verehren, beanspruchten dieses kolossale Dickicht als ihr heiliges Land und machten das größte davon zum Razorfen."},{t="Der Ehrgeiz der Greisin",b="Kral der Klingenhauer wird mit eisernem Hauer von der Ältestengreisin Charlga Klingenflanke beherrscht. Unter ihrer despotischen Führung haben die schamanistischen Borstennacken ihre traditionellen Grenzscharmützel aufgegeben, um einen aggressiven, koordinierten Krieg gegen rivalisierende Stämme, regionale Handelswege und junge Siedlungen der Horde zu führen. Weitaus schlimmer sind beunruhigende Gerüchte und Späherberichte über untote Unholde, die nahe dem Dornengestrüpp umherschleichen. Es steht zu befürchten, dass Charlga begonnen hat, mit Abgesandten der gefürchteten Geißel zu verhandeln, um verbotene Nekromantie zu nutzen und die Wildheit ihres Stammes zu stärken."}},faq={{q="Was ist Kral der Klingenhauer?",a="Kral der Klingenhauer ist ein uraltes unterirdisches Netzwerk gewaltiger dorniger Ranken im südlichen Brachland. Es dient als spirituelles Kernland und Festung des Volks der Borstennacken, die das verschlungene Labyrinth als ihre angestammte Heimat betrachten.",al={"was ist rfk","kral von razorfen erklärung","razorfen übersicht"}},{q="Wie entstanden die riesigen Dornen?",a="Das riesige Dornengestrüpp spross vor zehntausend Jahren während des Krieges der Ahnen aus der Erde, hervorgegangen direkt aus dem vergossenen Blut des gefallenen Eber-Halbgottes Agamaggan.",al={"warum gibt es riesige dornen","woher stammt das dornengestrüpp","agamaggan dornen"}},{q="Wer beherrscht den Kral der Klingenhauer?",a="Der Kral wird von Charlga Klingenflanke beherrscht, einer skrupellosen Borstennacken-Greisin und Schamanin, die den Stamm der Razorfen anführt und Angriffe auf benachbarte Dörfer und Reisende lenkt.",al={"wer ist der boss von rfk","charlga klingenflanke","greisin des krals"}},{q="Warum sorgt sich die Horde um den Kral der Klingenhauer?",a="Neben den ständigen Überfällen der Borstennacken auf neu gegründete Siedlungen im Brachland haben Späher der Horde Untote um das Dickicht schleichen sehen, was furchterregende Befürchtungen weckt, dass Charlga sich mit der Geißel verbündet.",al={"warum kümmert sich die horde","horde rfk interesse","bedrohung im brachland"}},{q="Warum interessieren sich die Streitkräfte der Allianz für den Kral?",a="Die aggressive Ausbreitung von Charlgas Stamm bedroht Vorposten nahe Feralas und den Tausend Nadeln, was Kommandanten und Späher der Allianz in Thalanaar dazu veranlasst, den Tod der Greisin anzustreben, um die Grenze zu stabilisieren.",al={"allianz quests rfk","warum reist die allianz hierher","thalanaar quest"}},{q="Welche Bedeutung hat der Sieg über Erdrufer Halmgar für die Geschichte?",a="Der Sieg über Erdrufer Halmgar, einen seltenen und einflussreichen Geomanten tief im Dickicht, versetzt der erdschöpfenden Priesterschaft der Borstennacken einen schweren Schlag. Indem der Kral solch mächtiger Elementarbeschwörer beraubt wird, werden Charlga Klingenflankes Verteidigungsanlagen geschwächt und die Fähigkeit der Borstennacken beeinträchtigt, die heiligen Dornen von Agamaggan zu manipulieren.",al={"was geschieht nach erdrufer halmgars tod","erdrufer halmgar geschichte","halmgar besiegt"}}},fx={["59c8bcc4"]={q="Wer hat all diese Dornen im Kral der Klingenhauer erschaffen?",a="Niemand hat sie von Hand erschaffen. Vor zehntausend Jahren, während des Krieges der Ahnen, fiel der kolossale Eberhalbgott Agamaggan im Kampf gegen die Brennende Legion. Wo sein göttliches Blut in den Boden sickerte, brachen massive, undurchdringliche, dornenbewachsene Gebüsche aus der Erde hervor und bildeten das labyrinthartige Dickicht, das Ihr heute seht.",al={"wer hat die dornen erschaffen","wer baute die dornen","ursprung der dornen im kral der klingenhauer"}},["4843f165"]={q="Was sind Stacheleber?",a="Stacheleber sind primitive, aggressive, eberähnliche Humanoide, die in Kalimdor beheimatet sind. Sie haben muskulöse, gebeugte Rücken, die mit scharfen, defensiven Stacheln übersät sind. Es wird angenommen, dass sie die sterblichen Nachkommen des Halbgottes Agamaggan sind; sie verehren seine Ruhestätten und verteidigen ihre dornigen Gebiete erbittert gegen alle Außenstehenden.",al={"was sind stacheleber","wer sind die stacheleber","stacheleber hintergrundgeschichte"}},ea4583b3={q="Warum leben die Stacheleber in einem riesigen Dornenlabyrinth?",a="Das Dornenlabyrinth ist direkt aus dem Blut ihres gefallenen Gottes Agamaggan hervorgegangen. Für die Stacheleber ist der Kral der Klingenhauer heiliger Boden und seine tatsächliche Ruhestätte. Das Gestrüpp bietet ihnen sowohl heilige Verehrung als auch natürliche, nahezu undurchdringliche Festungen gegen ihre regionalen Feinde.",al={"warum in dornen leben","warum leben stacheleber hier","stacheleber dornenlabyrinth"}},b1fd1d2b={q="Ist Charlga Klingenflanke die Anführerin aller Stacheleber?",a="Nicht aller Stacheleber, aber sie beherrscht den mächtigen Stamm der Klingenhauer, der sich im Kral verschanzt hat. Als gerissene Matrone und Geomantin vertrieb sie die dortigen Tauren aus dem südlichen Brachland und übt weitreichende Autorität aus, obwohl rivalisierende Stacheleberstämme, die über ganz Kalimdor verstreut sind, sich selbst regieren.",al={"charlga klingenflanke anführerin","wer führt alle stacheleber an","hat charlga das sagen über alle"}},["8ed48c28"]={q="Wer ist Agathelos der Tobende?",a="Agathelos ist ein massiver, wilder Eber, der im Kral der Klingenhauer haust. Stacheleber verehren Eber als lebende Symbole ihres Gottes Agamaggan und betrachten besonders große und beharrliche Bestien wie Agathelos als direkte Segnungen und heilige Manifestationen der ursprünglichen Macht des Großen Ebers.",al={"wer ist agathelos","hintergrundgeschichte von agathelos der tobende","agathelos rieseneber"}},["4f663063"]={q="Spioniert die Horde auch im Kral der Klingenhauer herum?",a="Ja. Die Plünderer von Charlga Klingenflanke verüben ständig brutale Angriffe auf Siedlungen der Horde im gesamten Brachland und haben die Tauren aus ihren angestammten südlichen Gebieten vertrieben. Sowohl die Orcs als auch die Tauren entsenden aktiv Krieger, um die Macht der Matrone zu brechen und die Bedrohung durch die Stacheleber zu beenden.",al={"ist die horde hier","präsenz der horde im kral der klingenhauer","horde im kral der klingenhauer"}},["5328604f"]={q="Wer ist Agamaggan?",a="Agamaggan, der Große Eber, war ein Uralter Wächter und einer der ersten und mächtigsten Wilden Götter, die Azeroth durchstreiften. Die Stacheleber verehren ihn als ihren Schöpfer, huldigen seinem Andenken und beziehen spirituelle sowie geomantische Kraft aus seinem Blut und den riesigen Dornenclustern, die aus seinem Opfer hervorgegangen sind.",al={"wer ist agamaggan","agamaggan der große eber","agamaggan hintergrundgeschichte"}},bc4e6730={q="Starb Agamaggan im Krieg der Ahnen?",a="Ja. Vor zehntausend Jahren folgte Agamaggan dem Ruf von Cenarius, Azeroth vor der Brennende Legion zu verteidigen. Er wütete über den Kontinent und zermalmte Tausende von Dämonen, bevor er schließlich im Kampf gegen eine überwältigende dämonische Armee fiel und sein Leben opferte, damit Malfurion Sturmgrimm den Brunnen der Ewigkeit erreichen konnte.",al={"wie starb agamaggan","agamaggan krieg der ahnen","ist agamaggan gestorben"}},e47b7687={q="Verehren die Stacheleber Agamaggan immer noch?",a="Das tun sie, mit fanatischer Hingabe. Schamanen und Geomanten der Stacheleber beten zu Agamaggan um Stärke im Kampf, verehren riesige Eber als seinen Segen und horten Blutedelsteine, die aus seinem versteinerten Blut geformt wurden. Sie glauben, dass seine physischen Überreste sie und ihre heilige Heimat beschützen.",al={"verehren die stacheleber noch immer agamaggan","stacheleber religion","verehrung von agamaggan"}},["7583b13a"]={q="Wer sind die Typen vom Totenschädel?",a="Der Totenschädel ist eine militante Fraktion der Stacheleber, die auf dem Schlachtfeld von Oberanführer Rammhauer angeführt wird und an der Seite des Stammes der Klingenhauer operiert. Rammhauer leitet ihre disziplinierten, kampferprobten Truppen an, um das Dornenlabyrinth fest im Griff zu halten und bösartige Kriege gegen ihre Nachbarn zu führen.",al={"stamm des totenschädels","wer sind die vom totenschädel","totenschädel-stacheleber"}},["4bc36485"]={q="Werden die Stacheleber hier Siedlungen im Brachland angreifen?",a="Das tun sie bereits. Unter dem Kommando der Matrone Charlga Klingenflanke schwärmen aggressive Plünderer ständig aus den Dornen in die umliegenden Ländereien aus. Sie haben Reisende in der Nähe des großen Aufzugs belästigt, rivalisierende Stämme überfallen und Siedlungen sowie Karawanen der Horde an den Rand eines offenen Krieges gedrängt.",al={"werden stacheleber das brachland angreifen","brachland unter angriff durch stacheleber","stacheleber-überfälle im brachland"}},ed4c33ec={q="Was ist der Unterschied zwischen dem Kral und den Hügeln?",a="Beide sind massive Dornennetzwerke, die durch den Fall von Agamaggan entstanden sind, aber sie erfüllen unterschiedliche Rollen. Kral der Klingenhauer ist das angestammte Herz, wo Charlga Klingenflanke lebende Stacheleberplünderer versammelt. Hügel der Klingenhauer, weiter südöstlich in der Nähe des riesigen skelettierten Mauls des Halbgottes gelegen, ist unter den dunkleren Einfluss der Geißel gefallen.",al={"unterschied zwischen kral und hügeln","kral der klingenhauer gegen hügel der klingenhauer","kral oder hügel"}},["974f5634"]={q="Ist die Geißel im Kral der Klingenhauer involviert?",a="Ja. Beunruhigende Berichte und abgefangene Schreiben enthüllen, dass Charlga Klingenflanke begonnen hat, mit Agenten der Geißel zu verhandeln. Späher haben Untote in der Nähe des Kral der Klingenhauer gesichtet, was die ernste Sorge aufkommen lässt, dass die Schergen des Lichkönigs versuchen, durch diese ahnungslosen Stämme einen Fuß auf Kalimdor zu fassen.",al={"geißel im kral der klingenhauer","gibt es untote im kral der klingenhauer","präsenz der geißel im kral"}},a384c7af={q="Wer ist Amnennar?",a="Amnennar der Kältebringer ist ein mächtiger Agent der Geißel, der sich in den benachbarten Hügel der Klingenhauer niedergelassen hat. Er arbeitet hinter den Kulissen, manipuliert die Führung der Stacheleber und befehligt die Streitkräfte des Totenschädels, um das südliche Gestrüpp in eine Festung der Untoten zu verwandeln.",al={"wer ist amnennar","amnennar der kältebringer","amnennar hintergrundgeschichte"}},af015f4e={q="Wie bin ich im Kral der Klingenhauer gelandet?",a="Ihr seid in die südlichsten Ausläufer des Brachlandes gereist, in die Nähe der hoch aufragenden Klippen mit Blick auf Tausend Nadeln. Während Ihr Euch durch das umkämpfte Buschland vorkämpftet, fandet Ihr das riesige Dickicht aus blutgenährtem Gestrüpp, das aus dem Kadaver des uralten Eber-Gottes Agamaggan entsprang. Direkt in diese massiven, versteinerten Dornenranken gehauen liegt der westliche Eingang zum Kral, wo Verteidiger der Stacheleber den Zugang gegen jeden bewachen, der es wagt, in ihr heiliges Territorium einzudringen.",al={"wie bin ich hierher gekommen","wie erreicht man den kral der klingenhauer","wo ist der kral der klingenhauer"}},["141f6ea5"]={q="Was soll ich im Kral der Klingenhauer tun?",a="Ihr seid hier, um die feindselige Macht des Stammes der Klingenhauer zu brechen und ihre aggressive Expansion über das Brachland aufzuhalten. Unter der Führung ihrer Matrone Charlga Klingenflanke haben diese fanatischen Stacheleber ihre gewaltsamen Übergriffe auf benachbarte Siedlungen und Karawanen verstärkt. Euer Ziel ist es, Euch durch die verschlungenen Dornengänge zu kämpfen, die Führung des Totenschädels zu zerschmettern und Charlga zur Strecke zu bringen, bevor ihre dunkle Geomantie und ihre mutmaßlichen Geschäfte mit finsteren Mächten der Untoten einen umfassenden Krieg entfachen.",al={"was ist meine mission hier","warum bin ich im kral der klingenhauer","was mache ich hier"}}},fp="14,218,21.427.0,20.423.1,23.142.0,34.156.0,25.170.0,48.182.0,48.157.0,59.248.0"}
P.entries["zone:redridge"] = {n="Rotkammgebirge",s="Östlich des Waldes von Elwynn erstreckt sich das Rotkammgebirge mit reißenden Flüssen, bewaldeten Hängen und der stillen Weite des Immerruhsees. Trotz seiner malerischen Höhen wird die Region von feindseligen Schattenfellgnollen und den vorrückenden Schwarzfelsorcs der Dunklen Horde belagert. Da das Militär des Königreichs durch interne Konflikte in Sturmwind gebunden ist, muss sich die Seenhainer Stadt am See auf umherziehende Söldner verlassen, um die Stellung zu halten.",h="Östlich des Waldes von Elwynn erstreckt sich das Rotkammgebirge mit reißenden Flüssen, bewaldeten Hängen und...",kw={"schwarzfelsorcs","der immerruhsee","seenhain","magistrat solomon","marschall marris","rotkammgebirge","renders tal","steinwacht","burg steinwacht","verner gutmark"},ang={["faction:Alliance"]="Seenhain dient als wichtiger Stützpunkt an der Front, an dem junge Soldaten der Allianz ihre Fähigkeiten im Kampf gegen organisierte Orc- und Gnollstreitkräfte schulen.",["faction:Horde"]="Die im Rotkammgebirge verschanzen Schwarzfelsorcs gehören zur feindseligen Dunklen Horde und sind daher ebenso Feinde von Thralls Horde wie der Menschen in Seenhain.",["profession:Herbalism"]="An den gemäßigten Berghängen gedeihen Wilddornrose, Beulengras, Maguskönigskraut und Flitzdistel.",["profession:Mining"]="Die felsigen Klippen und Täler rund um den Immerruhsee bieten zahlreiche Vorkommen von Kupfer und Zinn sowie seltene Silberadern, insbesondere in der Nähe der Rethbanhöhlen."},sec={{t="Eine belagerte Bastion",b="Das Rotkammgebirge gehörte einst zu den friedlichsten Gegenden des Königreichs und versorgte Sturmwind mit Bauholz, Süßwasserfischen und Feldfrüchten. Heute ist dieses ruhige Leben Vergangenheit. Die Seenhainer Ortschaft ist ständig befestigt, um aggressive Überfälle abzuwehren. Im Osten ist Burg Steinwacht, einst eine stolze Bastion des Königreichs, unter die Kontrolle abtrünniger Schwarzfelsorcs gefallen. Sie sperren Straßen und drohen, die östlichen Täler vollständig zu überrennen."},{t="Das geteilte Gebirge",b="Geografisch bilden diese Gipfel einen Teil des Gebirgszugs, der sich durch den Subkontinent Azeroth zieht. Vor Jahrhunderten reichte die Bergkette viel weiter nach Norden, bis der Dunkeleisenklan versehentlich den Feuerlord Ragnaros heraufbeschwor, die Erde aufriss und den feurigen Krater des Schwarzfels schuf. Diese Katastrophe trennte die nördlichen Gipfel ab, die nun die ascheverhangene Brennende Steppe bilden, und ließ nur die südlichen Täler des Rotkammgebirges üppig, grün und anfällig für Angriffe von den darüberliegenden Hängen zurück."},{t="Von der Krone vernachlässigt",b="Während Magistrat Solomon und Marschall Marris um Verstärkung bitten, hat der Regentschaftsrat in Sturmwind Seenhain praktisch sich selbst überlassen. Verzweifelte Bitten an die Späherkuppe und Dunkelhain bleiben erfolglos, da beide befreundeten Siedlungen durch ihre eigenen Krisen geschwächt sind. Da nirgends Verstärkung in Sicht ist, müssen die örtlichen Magistrate jeden fähigen Söldner anheuern, der bereit ist, den Uferpfad zu wagen, die Gnolllager zu säubern und den Schatten zurückzudrängen, der über dem Immerruhsee liegt."},{t="Die verborgenen Loyalitäten",b="Der abtrünnige Hexenmeister Morganth verbündete sich zunächst mit den Schwarzfelsorcs, um Burg Steinwacht einzunehmen, verriet sie dann jedoch und unterwarf die Schattenfellgnolle vom Turm von Ilgalar aus seinem Willen. Bei den Ermittlungen zu den Schwarzfelsorcs gefundene Berichte belegen zudem ein Bündnis zwischen den Orcs und dem schwarzen Drachenschwarm."}},faq={{q="Warum schickt Sturmwind keine Soldaten, um Seenhain zu helfen?",a="Die überlebenden königlichen Soldaten in Seenhain sind nach dem Verlust von Burg Steinwacht deutlich in der Unterzahl. Magistrat Solomon hat um Truppen, Waffen, Nahrung und Vorräte gebeten, doch Sturmwinds Streitkräfte sind stark beansprucht und die benachbarten Siedlungen haben ihre eigenen Probleme. Die Garnison ist daher auf Abenteurer angewiesen, die helfen, die Region zu halten.",al={"warum keine wachen aus sturmwind","warum ist das rotkammgebirge verlassen","wo ist sturmwinds armee"}},{q="Wer kontrolliert Burg Steinwacht?",a="Burg Steinwacht wurde von Schwarzfelsorcs überrannt, die der Dunklen Horde angehören. Von dieser befestigten Bergfestung aus bedrohen sie die östlichen Täler und Reisende auf dem Uferpfad. Ihre Beziehungen zu anderen örtlichen Gefahren werden im Verlauf der Ermittlungen beleuchtet.",al={"wer ist in steinwacht","feinde in steinwacht","was geschah mit steinwacht"}},{q="Welche Gefahren lauern im Immerruhsee?",a="Vom Ufer aus wirkt der Immerruhsee friedlich, doch seine Gewässer sind von feindseligen Murlocstämmen verseucht, die die nahegelegenen Docks und Ruinen überfallen. Schwimmer müssen sich außerdem vor räuberischen Dreschonern unter der Oberfläche in Acht nehmen, was immer wieder Gerüchte über Wassermonster nährt, die in der Tiefe umherstreifen.",al={"monster im immerruhsee","gefahren am see im rotkammgebirge","murlocs im immerruhsee"}},{q="Gibt es Außenposten der Horde im Rotkammgebirge?",a="Nein. Im Rotkammgebirge gibt es keine Siedlungen, Händler oder Flugpunkte der Horde. Reisende der Horde, die das Gebiet durchqueren, sind gewöhnlich zwischen der Brennenden Steppe im Norden und den Sümpfen des Elends im Südosten unterwegs und müssen sich dabei über von der Allianz gehaltene Straßen und durch feindselige Wildnis bewegen.",al={"siedlungen der horde im rotkammgebirge","ist das rotkammgebirge von der horde oder der allianz","flugpunkt der horde im rotkammgebirge"}},{q="Was sind die Drei Ecken?",a="Die Drei Ecken sind ein wichtiger Straßenknotenpunkt in der südwestlichen Ecke des Rotkammgebirges. Sie verbinden den Uferpfad mit der östlichen Grenze des Waldes von Elwynn und der Straße nach Dämmerwald und bilden so einen wichtigen Verkehrsknotenpunkt, der häufig von umherstreifenden Gnollen und wilden Tieren angegriffen wird.",al={"drei ecken","straßenkreuzung drei ecken","kreuzung im rotkammgebirge"}},{q="Warum ist der nördliche Weg zur Brennenden Steppe so gefährlich?",a="Der Pfad, der nördlich an Renders Lager vorbeiführt, steigt direkt in die Brennende Steppe hinauf, eine öde Vulkanlandschaft, die von mächtigen Schwarzfelsorcs, Feuerelementaren und Drachkin beherrscht wird. Der plötzliche Anstieg der Gefahr macht den nördlichen Gebirgspass zu einem der tödlichsten Aufstiege im Süden Azeroths.",al={"nördliche straße im rotkammgebirge","grenze zur brennenden steppe im rotkammgebirge","nördlicher pass im rotkammgebirge"}}},fx={d1ce2561={q="Was soll ich im Rotkammgebirge tun?",a="Seenhain ist in einer verzweifelten Lage und wurde von der Krone so gut wie aufgegeben. Ihr seid hier, um auf die Bitten von Magistrat Solomon und Marschall Marris um Verteidigung zu antworten. Die Stadt ist schwer bedrängt von marodierenden Schattenhautgnollen entlang der Straßen und wilden Schwarzfelsorcs, die Burg Steinwacht eingenommen haben. Da die königliche Garnison zahlenmäßig unterlegen ist und The Everstill Bridge zerstört wurde, müsst Ihr die Gnolle zurückschlagen, die Vorhut der Orcs zurückdrängen und verhindern, dass dieser friedliche Zufluchtsort am See völlig zusammenbricht.",al={"was mache ich hier","warum bin ich hier","was ist mein ziel im rotkammgebirge","was ist meine mission hier"}},bf444872={q="Ist das Rotkammgebirge gefährlich?",a="Trotz seines idyllischen Aussehens ist das Rotkammgebirge außerordentlich gefährlich. Die Orcs des Schwarzfels kontrollieren die östlichen Schluchten und die Burg, Shadowhide-Gnolle plündern die Wälder und Murlocs tummeln sich an den Ufern des Sees. Sogar die nördliche Straße grenzt an die sengenden Gipfel der Brennenden Steppe, wo monströse Bedrohungen, die weit über eine durchschnittliche Patrouille hinausgehen, direkt hinter den Talpässen lauern.",al={"ist das rotkammgebirge sicher","gefahrenstufe rotkammgebirge","wie gefährlich ist das rotkammgebirge"}},["1cc45818"]={q="Warum ist jeder in Seenhain so besorgt?",a="Seenhain befindet sich im aktiven Belagerungszustand. Die Orcs des Schwarzfels haben Burg Steinwacht direkt auf der anderen Seite des Sees eingenommen, Shadowhide-Gnolle bedrängen die Stadt von den Hügeln aus und Murlocs befallen die Wasserwege. Da die Brücke zerstört ist und keine Verstärkung aus Sturmwind eintrifft, befürchten die Stadtbewohner, dass ein umfassender Angriff sie jeden Moment auslöschen könnte.",al={"warum hat seenhain angst","bedrohung in seenhain","warum besorgnis in seenhain"}},["851f5e81"]={q="Steht Seenhain kurz vor dem Fall?",a="Ohne Eingreifen von außen ist die Lage von Seenhain düster. Die örtliche Stadtwache ist den Orc-Plünderern, Gnollrudeln und Seeungeheuern zahlenmäßig weit unterlegen. Ihre Festung in Steinwacht wurde leicht überrannt und die Verteidiger von Seenhain wurden an das westliche Ufer des Sees zurückgedrängt, wo sie mit Mühe einen Verteidigungswall entlang der zerstörten Brücke halten.",al={"wird seenhain fallen","ist seenhain dem untergang geweiht","kann seenhain überleben"}},["7ced12b0"]={q="Hat Sturmwind Hilfe nach Seenhain geschickt?",a="Seenhain hat Sturmwind, Westfall und Dunkelhain um Hilfe gebeten, doch die benachbarten Siedlungen sind mit ihren eigenen Krisen beschäftigt. General Marcus Jonathan wurde ebenfalls um Verstärkung gebeten. Die königlichen Soldaten, die Seenhain noch verteidigen, haben nach dem Fall von Burg Steinwacht weiterhin einen Mangel an Truppen und Vorräten.",al={"hat sturmwind seenhain geholfen","sturmwind hilfe für seenhain","hat sturmwind truppen ins rotkammgebirge geschickt"}},["3a3ab87f"]={q="Wer hat hier das Sagen?",a="Seenhain wird von Magistrat Solomon regiert, der zivile Angelegenheiten und städtische Belange vom Rathaus von Seenhain aus beaufsichtigt. Militärische und Verteidigungsoperationen unterstehen Marschall Marris, der die örtliche Wache leitet und Verteidigungsbemühungen nahe der Brücke koordiniert.",al={"wer führt das rotkammgebirge","wer regiert seenhain","anführer des rotkammgebirges"}},["1dd15680"]={q="Wer ist Magistrat Solomon?",a="Magistrat Solomon ist das gewählte Oberhaupt von Seenhain und oberster Richter des Gerichts von Seenhain. Gealtert und erschöpft trägt er die Last, die Stadt mit Nahrung zu versorgen, organisiert zu halten und politisch mit dem Königreich verbunden zu lassen, während er verzweifelt auswärtige und regionale Anführer um militärische Entlastung bittet.",al={"magistrat solomon","wer ist solomon","solomon rotkammgebirge"}},["0e63cf14"]={q="Untersteht Marschall Marris Magistrat Solomon?",a="Ja. Solomon repräsentiert die zivile Autorität und das Gericht des Königreichs in Seenhain, während Marschall Marris das dort stationierte Kontingent der Sturmwindgarde befehligt. Die beiden arbeiten eng zusammen, wobei Solomon die diplomatische und städtische Überlebenssicherung verwaltet, während Marris taktische Scharmützel und Truppeneinsätze handhabt.",al={"untersteht marris solomon","rang von marschall marris und solomon","wer steht im rang über wem in seenhain"}},["7b7fd7c0"]={q="Wer sind die Orcs des Schwarzfels und warum sind sie im Rotkammgebirge?",a="Der Clan des Schwarzfels ist ein rücksichtsloser Überrest der Alten Horde, der im Norden vom Schwarzfels aus operiert. Im Gegensatz zu Thralls Horde in Kalimdor lehnen diese Abtrünnigen jeden Frieden mit der Allianz ab. Sie sind von der Brennenden Steppe in das Rotkammgebirge herabgestiegen, um die Region zu erobern, und nutzen Burg Steinwacht als Stützpunkt, um Seenhain zu zerschlagen.",al={"orcs des schwarzfels im rotkammgebirge","warum sind orcs im rotkammgebirge","wer ist der clan des schwarzfels im rotkammgebirge"}},["114fb915"]={q="Woher kommen die Orcs des Schwarzfels?",a="Sie marschierten aus südlicher Richtung über die gezackten nördlichen Gebirgspässe direkt von der Brennenden Steppe und der Schwarzfelsspitze, ihrer alten Festung aus dem Zweiter Krieg, hierher. Sie errichteten Außenposten wie Render's Camp, bevor sie Burg Steinwacht überwältigten.",al={"woher kommen die orcs im rotkammgebirge","herkunft der orcs des schwarzfels","woher kommen die orcs"}},["9f02e3ae"]={q="Sind die Orcs des Schwarzfels dieselben Orcs aus den Kriegen?",a="Ja. Sie sind abgehärtete Veteranen und direkte Nachkommen des Clans des Schwarzfels aus dem Erster Krieg und Zweiter Krieg, die sich weigerten, sich zu ergeben oder Thralls neuem schamanistischen Pfad zu folgen. Sie behalten ihre ursprünglichen blutrünstigen Praktiken und ihre dunkle Magie bei und halten fest an ihrer ursprünglichen Mission, die menschlichen Königreiche auszulöschen.",al={"stammen die orcs des schwarzfels aus dem ersten krieg","orcs des schwarzfels aus dem zweiten krieg","sind das dieselben orcs aus den alten kriegen"}},["09fb7c4a"]={q="Was sind die Gnolle des Rotkammgebirges? Warum greifen sie an?",a="Die örtlichen Shadowhide-Gnolle sind wilde, hyänenartige Humanoide, die die Hügel und Täler des Rotkammgebirges bewohnen. Obwohl sie von Natur aus territorial und räuberisch sind, wird ihre derzeitige koordinierte Gewalt von dunklen Einflüssen angetrieben, die ihre verstreuten Rudel zu einer organisierten Armee vereint haben, die darauf aus ist, menschliche Siedlungen abzuschlachten.",al={"gnolle im rotkammgebirge","warum greifen gnolle das rotkammgebirge an","shadowhide-gnolle"}},ba7471d2={q="Arbeiten die Gnolle mit den Orcs zusammen?",a="Die Shadowhide-Gnolle dienen dem abtrünnigen Hexenmeister Morganth im Turm von Ilgalar. Ihre Beziehung zu den Orcs des Schwarzfels kann durch Berichte untersucht werden, die in der Region geborgen wurden.",al={"sind gnolle und orcs verbündet","arbeiten gnolle für den schwarzfels","arbeiten orcs und gnolle zusammen"}},["74e139ea"]={q="Wer ist Yowler?",a="Yowler ist der Anführer der Gnolle des Rotkammgebirges. Er haust in den Hügeln oberhalb von Seenhain und versammelt das Rudel gegen die Stadt. Verner Gutmark bittet Abenteurer, ihn zu besiegen und seine Pfote zurückzubringen.",al={"wer ist yowler","yowler gnollanführer","yowler rotkammgebirge"}},b25dfaa0={q="Warum ist die The Everstill Bridge kaputt und warum ist das wichtig?",a="Die The Everstill Bridge ist schwer beschädigt. Sie ist von enormer Bedeutung, da sie den schmalen Hals des Immerruhsees überspannt und als wichtigste Verkehrsverbindung von Seenhain zum östlichen Ufer und nach Steinwacht dient. Ihre Zerstörung behindert den Handel und die Verteidigung der Stadt und erschwert jeden Gegenangriff auf feindliche Lager.",al={"the everstill bridge zerstört","warum ist die brücke in seenhain zerstört","zerstörte brücke im rotkammgebirge"}},b35f81a4={q="Warum hat Sturmwind die The Everstill Bridge nicht repariert?",a="Sturmwind hat keine Gelder, Vorräte oder Steinmetze zur Unterstützung geschickt. Die Verantwortung liegt vollständig bei den Arbeitern vor Ort unter der Leitung von Großknecht Oslow, deren Reparaturarbeiten ständig durch Murloc-Überfälle und den Verlust von Vorräten unterbrochen und sabotiert werden.",al={"warum wurde die brücke nicht repariert","sturmwind brückenreparatur seenhain","wer repariert die brücke"}},["834d2ea2"]={q="Warum gibt es schwarze Drachenwelpen im Rotkammgebirge?",a="Schwarze Drachenwelpen sind durch die Pässe aus der Brennenden Steppe herabgeströmt und befallen den Uferpfad und die südlichen Schluchten. Sie schleichen durch die felsigen Bergrücken, kundschaften das Gebiet aus und lauern Passanten auf, was als düstere Warnung dient, dass die Brut von Deathwing in der Nähe aktiv ist.",al={"drachenwelpen im rotkammgebirge","schwarze drachen im rotkammgebirge","warum drachenwelpen im rotkammgebirge"}},ce7dd1a7={q="Arbeiten die Drachen mit den Orcs zusammen?",a="Die wachsende Präsenz des Schwarzfels und Sichtungen von schwarzen Drachenwelpen beunruhigen Seenhain. Magistrat Solomon bittet Reisende, seine Sorgen an Hochlord Bolvar Fordragon weiterzuleiten. Weitere Untersuchungen offenbaren die Art der Bedrohung.",al={"sind schwarze drachen mit dem schwarzfels verbündet","bündnis von orcs und drachen","arbeiten orcs des schwarzfels mit drachen"}},["7d7bd3f8"]={q="Warum kämpft hier ein Abenteurer statt der Wachen?",a="Die Wachen von Seenhain sind vollständig mit der Verteidigung des Stadtperimeters beschäftigt, sodass niemand für Offensivangriffe übrig bleibt. Da angeforderte Verstärkungen weiterhin nicht verfügbar sind, haben Magistrat Solomon und Marschall Marris keine andere Wahl, als reisende Abenteurer anzuheuern, um die Orcs zurückzudrängen, die Gnolle auszudünnen und den Uferpfad zu sichern.",al={"warum tue ich das im rotkammgebirge","warum abenteurer im rotkammgebirge","wo sind die wachen im rotkammgebirge"}},["839c7682"]={q="Wo ist die Armee von Sturmwind?",a="Die Streitkräfte von Sturmwind sind überdehnt. Königliche Soldaten verbleiben in Seenhain nach ihrer Niederlage bei Burg Steinwacht, aber die wiederholten Bitten der Stadt nach frischen Truppen und Vorräten haben nicht die Verstärkungen gebracht, die ihre Verteidiger benötigen.",al={"wo sind die soldaten von sturmwind","warum keine armee aus sturmwind","standort der armee von sturmwind"}},de572e98={q="Wie bin ich im Rotkammgebirge gelandet?",a="Ihr seid wahrscheinlich den Straßen von Wald von Elwynn aus nach Osten durch die Kreuzung Drei Ecken gefolgt oder über den Fluss aus den dunklen Wäldern von Dämmerwald im Südwesten gekommen. Als junger Champion, der die menschlichen Lande unterstützt, führen Eure Reisen natürlich hierher, sobald die abgelegenen Probleme rund um Sturmwind nach stärkeren Händen verlangen. Die Hilferufe von Seenhain erreichen die benachbarten Gebiete und ziehen reisende Abenteurer den Uferpfad hinauf in diese umkämpften Höhen.",al={"wie bin ich hierher gekommen","wie habe ich das rotkammgebirge erreicht","warum bin ich ins rotkammgebirge gekommen"}},["85c0e73f"]={q="Was ist das Rotkammgebirge?",a="Das Rotkammgebirge ist eine höhergelegene, malerische Region östlich des Wald von Elwynn und südlich der Brennende Steppe. Bekannt für seine reißenden Flüsse, hoch aufragenden Ulmen und den schimmernden Der Immerruhsee, galt es lange Zeit als eine der friedlicheren Ländereien im südlichen Azeroth. Heute wird seine stille Schönheit durch eindringende Schwarzfels-Orcs, gewalttätige Gnolle und feindselige Murlocs im See erschüttert.",al={"was ist das rotkammgebirge","zone rotkammgebirge","erzähl mir vom rotkammgebirge"}},["5d244582"]={q="Ist das Rotkammgebirge Teil des Königreichs Sturmwind?",a="Ja, das Rotkammgebirge steht unter dem Schutz und der Herrschaft des Königreichs Sturmwind, obwohl seine lokalen Anführer seit dem Zweiter Krieg die täglichen Angelegenheiten weitgehend unabhängig regiert haben. Der Magistrat Solomon aus Seenhain bittet den Thron von Sturmwind immer noch formell um Verteidigung und verlässt sich auf den Handel und die gegenseitige Loyalität der Allianz, selbst wenn königliche Truppen nirgendwo in Sicht sind.",al={"gehört das rotkammgebirge zu sturmwind","ist das rotkammgebirge allianz","ist seenhain teil von sturmwind"}},["8563150d"]={q="Warum gibt es einen See inmitten des Rotkammgebirges?",a="Der Immerruhsee sammelt auf natürliche Weise das Abflusswasser der umliegenden Gebirgszüge. Sein klares, ruhiges Wasser versorgte Seenhain einst mit reichlich Fisch und sauberem Wasser, obwohl es in letzter Zeit von bösartigen Murloc-Stämmen überrannt und von lauernden Dreschern unter der Oberfläche heimgesucht wurde.",al={"warum der immerruhsee","ursprung des sees im rotkammgebirge","was ist der see im rotkammgebirge"}},["8de34bfa"]={q="Was ist im Rotkammgebirge passiert?",a="Das Rotkammgebirge war einst eine friedliche Wiege menschlicher Gehöfte bis zum Erster Krieg, als Kriegshäuptling Schwarzfaust und die Hexenmeister des Schattenrats die Ritter von Sir Anduin Lothar besiegten und die Menschen ins Exil trieben. Nach dem Zweiter Krieg von der Allianz zurückerobert und wiederaufgebaut, wurde die Region kürzlich erneut belagert, nachdem Schwarzfels-Orcs aus den Bergen herabstiegen und Burg Steinwacht einnahmen.",al={"geschichte des rotkammgebirges","was passierte im rotkammgebirge","rotkammgebirge erster krieg"}}},fp="18,271,21.379.0,17.453.0,22.430.0,22.309.1,52.324.0,29.235.0,37.186.0,41.258.0,26.229.0,60.279.0"}
P.entries["zone:riverglades"] = {n="Flusslande",s="Die Flusslande sind ein umkämpftes Flusstal östlich der Brennenden Steppe und des Ödlands, das historisch vom Königreich Sturmwind beansprucht wurde. Während des Ersten Krieges von der Alten Horde überrannt und von der Krone weitgehend aufgegeben, bleibt die Region ein Schlachtfeld, auf dem einheimische menschliche Loyalisten mit modernen Horde-Außenposten und der örtlichen Tierwelt aneinandergeraten. Sie grenzen im Südwesten an das Rotkammgebirge, im Süden an die Sümpfe des Elends und blicken über das Meer nach Tanaris.",h="Die Flusslande sind ein umkämpftes Flusstal östlich der Brennenden Steppe und des Ödlands, das historisch vom...",kw={"schwarzfelspass","bruderschaft des pferds","demar brant","burg farholde","feste krol'dok","hafen von powderfuse","rotkammpass","flusslande","rog'mar","sonnengrund"},ang={["faction:Alliance"]="Allianzsoldaten finden in den Flusslanden alte Wunden wieder aufgerissen vor, wo Überreste der Bruderschaft des Pferds einen unbesungenen Kreuzzug fortführen, um Land zurückzuholen, das Sturmwind während des Ersten Krieges aufgab.",["faction:Horde"]="Für die Horde sichert der Aufbau von Außenposten wie Rog'mar einen sicheren Küstenstützpunkt und hält den Druck auf alte menschliche Festungen aufrecht, die östlich des Rotkammgebirges verharren.",["race:Human"]="Menschliche Reisende werden in Sonnengrund Zeugen eines tragischen Kapitels ihres eigenen Erbes – eine Mahnung an den hohen Tribut des Ersten Krieges an der Ostgrenze ihres Königreichs."},sec={{t="Ein vergessenes Grenzland",b="Historisch Teil des Königreichs Sturmwind, verfielen die Flusslande während des Ersten Krieges in Ruinen, als die Alte Horde durch die Region fegte. Ihre zentrale Siedlung, Sonnengrund, wurde von den Orcs geplündert, die ihren Magierturm nur verschonten, um die menschliche Zauberei zu studieren, bevor sie die überlebenden Dorfbewohner versklavten. Obwohl Soldaten aus Sturmwind den Versuch unternahmen, die Gefangenen zu befreien und wieder aufzubauen, hielt das Königreich das gesamte Tal schließlich für verloren und lenkte Ressourcen zur Verteidigung der zentralen Heimatgebiete um. Jahrelang blieb die Region weitgehend von der formellen Unterstützung der Krone abgeschnitten."},{t="Der Kampf um Farholde",b="Obwohl sie von Sturmwinds oberster Führung zurückgelassen wurden, gaben die menschlichen Verteidiger ihre Heimat nie vollständig auf. Unter Ritterkommandant Demar Brant von der legendären Bruderschaft des Pferds halten die verbliebenen Loyalisten Burg Farholde als Bastion gegen die Wildnis und feindliche Invasoren. Unterdessen unterhält die moderne Horde in der Nähe an Außenposten wie Rog'mar und Bolder'ok eine eigene starke Präsenz, was dafür sorgt, dass der uralte Konflikt um die Lichtungen weiter schwelt."},{t="Geografie und Reisen",b="Entlang der Küste des Verbotenen Meeres erstrecken sich die Flusslande, flankiert von bergigem Gelände und gewundenen Wasserläufen. Reisende zu Fuß können nach Westen durch den Schwarzfelspass zur Brennenden Steppe gelangen, sich nach Südwesten durch den Rotkammpass in Richtung Rotkammgebirge schlängeln, nach Süden in die Sümpfe des Elends navigieren oder nach Nordwesten am Zwielichtschleier vorbei ins Ödland wandern. An der Küste bietet der Hafen von Powderfuse eine Seepassage, die direkt über den Ozean mit Dampfdruckpier in Tanaris verbindet."}},faq={{q="Was sind die Flusslande?",a="Die Flusslande sind eine umkämpfte Region östlich des Ödlands und der Brennenden Steppe, die am Verbotenen Meer liegt. Einst ein blühendes Territorium von Sturmwind, sind sie heute eine aktive Grenze, die von der Allianz bei Burg Farholde und der Horde bei Rog'mar umkämpft wird.",al={"flusslande übersicht","was ist diese zone","über flusslande"}},{q="Was geschah mit Sonnengrund?",a="Sonnengrund wurde während des Ersten Krieges von der Alten Horde überfallen und zerstört. Die Orcs nahmen die überlebenden Dorfbewohner als Sklaven gefangen und ließen einen örtlichen Magierturm intakt, um die menschliche Magie zu entschlüsseln. Obwohl Soldaten aus Sturmwind die Gefangenen befreiten und versuchten, den Ort wieder aufzubauen, gab das Königreich das Gebiet letztlich auf, um sich auf seine westlichen Grenzen zu konzentrieren.",al={"sonnengrund geschichte","fall von sonnengrund","was geschah mit der stadt"}},{q="Wer kontrolliert Burg Farholde?",a="Burg Farholde wird von Allianz-Loyalisten unter der Führung von Ritterkommandant Demar Brant von der Bruderschaft des Pferds gehalten. Seine Streitkräfte haben Jahre damit verbracht, für die Rückeroberung der Flusslande zu kämpfen, nachdem Sturmwind das Gebiet ursprünglich als verloren abgeschrieben hatte.",al={"wer führt farholde","allianz in flusslande","bruderschaft des pferds"}},{q="Wie erreicht man Tanaris von den Flusslanden aus?",a="Ein Küstenschiff verkehrt regelmäßig zwischen dem Hafen von Powderfuse am Ostufer der Flusslande und Dampfdruckpier in Tanaris und bietet eine direkte Seeverbindung über das Meer.",al={"schiff nach tanaris","schiff hafen von powderfuse","wie man nach tanaris gelangt"}},{q="Welche Pässe führen in andere Zonen?",a="Ihr könnt nach Südwesten durch den Rotkammpass reisen, um das Rotkammgebirge zu erreichen, oder direkt nach Süden in Richtung der Sümpfe des Elends wandern. Im Westen führt der Schwarzfelspass an den Borstenhügeln vorbei zur Brennenden Steppe, während die Pfade nördlich des Zwielichtschleiers direkt ins Ödland führen.",al={"wie man nach rotkamm gelangt","pässe von flusslanden","ausgänge von flusslanden"}},{q="Was ist die Feste Krol'dok?",a="Die Feste Krol'dok ist ein befestigter Dungeon-Komplex in den Flusslanden, der einen bedeutenden feindlichen Machtsitz in dem umkämpften Gebiet darstellt.",al={"feste krol'dok","flusslande dungeon","welcher dungeon ist hier"}}},fp="11,291,22.431.0,25.415.0,20.414.0,24.187.0,28.295.0,27.212.0,46.146.0,34.266.0,28.127.0"}
P.entries["zone:ruinsoflordaeron"] = {n="Ruinen von Lordaeron",s="Direkt über der unterirdischen Unterstadt gelegen, sind die Ruinen von Lordaeron die hohlen Überreste des einst mächtigen Reiches der Menschen im Norden. Während des Dritten Krieges an die Geißel und Prinz Arthas gefallen, wimmelt es auf den oberirdischen Straßen und rissigen Plätzen heute von umherwandernden Monstrositäten, rachsüchtigen Gespenstern und abscheulichen Experimentatoren. Sowohl die Allianz als auch die Horde entsenden Expeditionen in diese verheerte Zitadelle, um Relikte der gefallenen Vergangenheit zu bergen oder die Schrecken zu beseitigen, die über der Hauptstadt der Verlassenen lauern.",h="Direkt über der unterirdischen Unterstadt gelegen, sind die Ruinen von Lordaeron die hohlen Überreste des...",kw={"bjork","lordaeron captain","neue seuche","rath'mael","ruinen von lordaeron","the abandoned","the baron","tirisfal","unterstadt","viktor the vile","witherfang"},ang={["class:Paladin"]="Lordaeron war die Wiege der Ritter der Silbernen Hand; seine entweihten Hallen zu durchschreiten, um Schrecken zu tilgen und ruhelose Hauptleute zur Ruhe zu betten, ist eine feierliche Pflicht vor dem Licht.",["faction:Alliance"]="Der Vorstoß nach Lordaeron erlaubt es der Allianz, direkt an der Schwelle zur Hauptstadt der Verlassenen zuzuschlagen und den Geistern ihrer abgeschlachteten nördlichen Brüder Gerechtigkeit und Frieden zu bringen.",["race:Human"]="Menschliche Abenteurer betrachten die zerstörte Hauptstadt als geweihten Boden, der durch Verrat geraubt wurde, und versuchen, verlorene Erbstücke zurückzuerlangen und gefallene Verwandte zu ehren.",["race:Undead"]="Für die Verlassenen sind die Ruinen darüber ihre einstige Heimat und ihr ewiger Friedhof. Ihre Säuberung sichert die eigene Haustür und versorgt die Apotheker mit Komponenten zur Entwicklung der Neuen Seuche."},sec={{t="Der Hof eines gefallenen Reiches",b="Capital City war einst das Kronjuwel der Östlichen Königreiche, der Sitz von König Terenas Menethil II. und das schlagende Herz der menschlichen Zivilisation. Als Prinz Arthas aus Northrend zurückkehrte, erschlug er seinen Vater im Thronsaal und entfesselte die Untoten auf die Bürgerschaft. Während die Verlassenen heute in den Katakomben der Unterstadt darunter hausen, bleiben die oberirdischen Ruinen eine verlassene Dämmerzone. Eingestürzte Torbögen und von Unkraut überwuchertes Pflaster bieten wilden Bestien wie Witherfang und geistesgestörten Überbleibseln der Vergangenheit Zuflucht."},{t="Qual und Pestilenz",b="Die Gefahren auf dem ruinierten Gelände gehen über ruhelose Tote hinaus. Apotheker und finstere Gestalten wie Viktor the Vile arbeiten im Schatten daran, neue Seuchen zu erproben, während verdrehte Experimente wie The Abandoned frei umherstreifen. Zornige Geister wie Rath'mael und verfluchte Gefolgsleute wie The Baron spuken durch die eingestürzten Korridore, gefangen in endloser Pein, und greifen jeden lebenden oder untoten Eindringling an, der ihren Weg kreuzt."},{t="Geister der königlichen Garde",b="Zu den ergreifendsten Gefahren in den oberen Ruinen gehören die spektralen Überreste der Verteidiger der Stadt, die im Erscheinen eines geisterhaften Lordaeron Captain gipfeln. Noch immer an ihre zerbrochenen Eide gebunden, betrachten diese Erscheinungen jeden, der sich dem Thron nähert, als Eindringling. Den Captain und seine Soldaten zur Ruhe zu betten, bringt einen bittersüßen Abschluss für eine ununterbrochene Wacht, die seit dem Tag des Falls der Hauptstadt andauert."}},faq={{q="Wo befindet sich der Dungeon Ruinen von Lordaeron?",a="Der Dungeon befindet sich direkt auf den oberirdischen Ebenen von Capital City in Tirisfal, unmittelbar über dem Eingangsnetzwerk, das hinab in die Hauptstadt der Verlassenen, die Unterstadt, führt.",al={"ruinen von lordaeron ort","wo ist der lordaeron dungeon","unterstadt dungeoneingang"}},{q="Warum sind sowohl die Horde als auch die Allianz an diesem Ort interessiert?",a="Für die Allianz ist der Vorstoß nach Lordaeron eine heilige Pilgerreise, um verlorene Familienerbstücke zu bergen, königliche Wappenabzeichen zu sammeln und gefallenen Vorfahren die letzte Ruhe zu schenken. Für die Horde, insbesondere die Verlassenen, ist die Säuberung der oberen Ruinen unerlässlich, um das Umfeld von Unterstadt zu sichern und Forschungsproben für die neue Seuche der Royal Apothecary Society zu beschaffen.",al={"warum in die ruinen von lordaeron","allianz quests lordaeron","horde quests lordaeron"}},{q="Wer ist Viktor the Vile?",a="Viktor the Vile ist eine der bösartigen Gestalten, die die Gesetzlosigkeit der Ruinen ausnutzen; er führt abscheuliche Experimente durch und trägt zur schwärenden Verderbnis bei, die die obere Hauptstadt mit verdrehten Monstrositäten verseucht hält.",al={"viktor the vile lore","wer ist viktor the vile"}},{q="Was ist „The Abandoned“, dem man in den Ruinen begegnet?",a="The Abandoned ist eine groteske untote Monstrosität, die in den Ruinen zurückgelassen wurde. Wie viele Flickwerk-Abscheulichkeiten, die während und nach der Eroberung durch die Geißel erschaffen wurden, wandert sie ziellos durch die verfallenen Kammern und greift alles an, was ihr begegnet.",al={"the abandoned boss","wer ist the abandoned"}},{q="Welche Bedeutung hat der Sieg über den Lordaeron Captain für die Geschichte?",a="Das Bezwingen des spektralen Lordaeron Captain erlöst einen hochrangigen königlichen Verteidiger aus einer endlosen, zermürbenden Pflicht. Seit dem ersten Massaker der Geißel durch Ehre gebunden, hat der Captain Jahre damit verbracht, ein zerstörtes Königreich vor allen zu bewachen, die sich nähern. Den Captain zur Ruhe zu betten, durchbricht einen qualvollen Kreislauf phantomhafter Knechtschaft und ermöglicht es, seine blutbefleckten Abzeichen zu bergen.",al={"lordaeron captain besiegen","bedeutung lordaeron captain","was passiert wenn captain stirbt"}},{q="Sind die Ruinen von Lordaeron von der Unterstadt getrennt?",a="Ja. Während die Verlassenen in den Höhlen der Unterstadt darunter hausen, sind die Ruinen an der Oberfläche ein aktives Kampfgebiet, das von ruhelosen Geistern, wilden Raubtieren und experimentellen Bedrohungen überrannt ist, welche die Verlassenen noch nicht vollständig beseitigt haben.",al={"ist unterstadt in diesem dungeon","ruinen vs unterstadt"}}},fx={["1b77984b"]={q="Was ist dieser Ort, die Ruinen von Lordaeron?",a="Ihr steht in den zertrümmerten Überresten der Hauptstadt, einst das Juwel der menschlichen Zivilisation und das Herz des Königreichs Lordaeron. Während des Dritten Krieges verriet Prinz Arthas sein Königreich, schlachtete seinen Vater König Terenas im Thronsaal darüber ab und entfesselte die untote Geißel auf ihren Straßen. Heute liegen ihre zerbrochenen Bögen und versengten Türme über der unterirdischen Unterstadt und dienen als bitteres Denkmal für das gefallene Königreich.",al={"was sind die ruinen von lordaeron","hintergrundgeschichte ruinen von lordaeron","was war das für ein ort"}},eb89374f={q="Wer lebte hier, bevor es zerstört wurde?",a="Diese Stadt war die Heimat des größten nördlichen Königreichs der Menschheit, regiert von der Menethil-Dynastie. Adlige, Priester des Heiligen Lichts, Soldaten und Hunderttausende einfacher Leute gingen einst über diese gepflasterten Straßen. Tragischerweise haben viele dieser ehemaligen Bürger ihre Heimat nie wirklich verlassen; von der Pest dahingerafft, bilden ihre wiederbelebten Leichen sowohl die gedankenlose Geißel, die die Pestländer heimsucht, als auch die befreiten Verlassenen, die nun in den Höhlen darunter wohnen.",al={"wer lebte hier früher","ursprüngliche bewohner von lordaeron","wer war zuerst hier"}},["6e6195fd"]={q="Warum ist hier alles kaputt und verbrannt?",a="Als Prinz Arthas mit Frostgram zurückkehrte, erschlug er König Terenas und überließ die Stadt der Geißel. Untote Schrecken wüteten durch die Alleen, brannten Gebäude nieder und metzelten jeden nieder, der versuchte, Widerstand zu leisten. Später, während des Bürgerkriegs unter den Untoten, kämpften Sylvanas Windläufer und ihre Verlassenen gegen Schreckenslords und verbliebene Legionen der Geißel durch genau diese Innenhöfe und rissen nieder, was von der großartigen Architektur der Stadt übrig geblieben war.",al={"warum ist lordaeron zerstört","wie wurde lordaeron verbrannt","warum ist es in ruinen"}},dd470a5c={q="Wer hat Lordaeron zerstört?",a="Das Königreich wurde von innen heraus durch seinen eigenen Kronprinzen, Arthas Menethil, unter dem korrumpierenden Flüstern des Lichkönigs zertrümmert. Ausgesandt, um den Kult der Verdammten und ihre Pest der Untoten aufzuhalten, wurde Arthas rücksichtslos, nahm die verfluchte Runenklinge Frostgram im gefrorenen Norden an und ergab seine Seele. Als Todesritter zurückkehrend, schlug er seinen Vater nieder und lieferte die Stadt den Klauen der Geißel aus.",al={"wer hat lordaeron zerstört","wer brachte lordaeron zu fall","zerstörer von lordaeron"}},f5a9164f={q="Wo ist Arthas jetzt?",a="Arthas verließ den zerstörten Kontinent Lordaeron vor Jahren und segelte zurück über Das große Meer nach Nordend, als der Lichkönig vom Dämonenjäger Illidan Sturmgrimm bedroht wurde. Er kämpfte sich die eisige Spitze des Frostthrons hinauf und ist aus dem Blickfeld der Allgemeinheit in den gefrorenen Einöden verschwunden, wobei er ein Königreich hinterließ, das in rivalisierende Fraktionen von Untoten und Überlebenden zersplittert ist.",al={"wohin ist arthas gegangen","wo ist prinz arthas","arthas standort"}},["2fe0baef"]={q="Ist jemand aus der Stadt entkommen?",a="Ein paar Glückliche entkamen dem Gemetzel. Vor dem endgültigen Zusammenbruch achtete die Zauberin Jaina Prachtmeer auf die Warnungen eines mysteriösen Propheten und führte Tausende menschlicher Flüchtlinge über das Meer nach Kalimdor, wo sie den Hafen von Theramore gründeten. Andere flohen nach Süden in Richtung des Königreichs Sturmwind oder griffen zu den heiligen Waffen, um zurückzukämpfen, wobei sie den fanatischen Scharlachroten Kreuzzug und die wachsame Argentumdämmerung bildeten.",al={"haben bürger von lordaeron überlebt","hat jemand den fall von lordaeron überlebt","überlebende von lordaeron"}},["9cf7434f"]={q="Warum gibt es eine Stadt der Untoten unter den Ruinen?",a="Als die Macht des Lichkönigs schwand, brach Sylvanas Windläufer dessen mentale Kontrolle über eine Vielzahl von Untoten. Sie nannten sich die Verlassenen und stürzten die dämonischen Schreckenslords, die die Hauptstadt hielten. Die Ruinen darüber waren zu exponiert für feindliche Augen und ständige Angriffe des Scharlachroten Kreuzzugs, also entschied Sylvanas, die riesigen unterirdischen Krypten und Kanalisationen in eine schwer befestigte Festung zu verwandeln.",al={"warum existiert die unterstadt","warum ist die unterstadt unter lordaeron","untote stadt unter ruinen"}},["55ddf3da"]={q="Wer hat die Unterstadt gebaut?",a="Das Fundament begann unter der Hauptstadt als königliche Verliese, Kanalisationen und tiefe Krypten, die von den Menschen von Lordaeron erbaut wurden. Während des Dritten Krieges begannen Arthas und die Geißel, diese unterirdischen Korridore zu einem ausgeklügelten Netzwerk zu erweitern, das ein Zentrum der Macht der Geißel werden sollte. Nachdem sie dem Schreckenslord Varimathras die Kontrolle entrissen hatten, vollendeten Sylvanas und die Verlassenen den Ausbau der Unterstadt als ihre ständige Hauptstadt.",al={"wer erschuf die unterstadt","konstruktion der unterstadt","wer hat die unterstadt ausgegraben"}},c0ee4f6f={q="War die Unterstadt schon immer da unten?",a="Nicht in ihrem modernen, weitläufigen Zustand. Zu Zeiten von König Terenas bestand das Untergeschoss lediglich aus Schlossverliesen, Aquädukten, Abwasserkanälen und Familiengräbern. Erst nach dem Fall des Königreichs höhlten Abscheulichkeiten der Geißel und Arbeiter der Verlassenen die massiven Ringe und Viertel aus, die Ihr heute seht, und verwandelten Versorgungstunnel in eine weitläufige unterirdische Bastion der Toten.",al={"war die unterstadt schon immer da","existierte die unterstadt vorher","alte unterstadt"}},dc41e367={q="Wer hat hier das Sagen?",a="Fürstin Sylvanas Windläufer, die Banshee-Königin, befehligt diese Ruinen und die Unterstadt darunter. Einst die Waldläufergeneralin von Silbermond, wurde sie von Arthas erschlagen, als rachsüchtige Banshee wiedererweckt und holte sich schließlich ihre physische Leiche zurück. Durch reine Willenskraft und List befreite sie ihre untoten Brüder und Schwestern und schmiedete die Verlassenen, die sie mit rücksichtsloser Entschlossenheit von ihrem Thron im Royal Quarter aus führt.",al={"wer regiert die ruinen von lordaeron","anführer der unterstadt","wer kontrolliert diesen ort"}},["3d3094f9"]={q="Ist Sylvanas eine Königin oder etwas anderes?",a="Ihr Volk verehrt sie als Banshee-Königin und Fürstin der Verlassenen, aber sie ist kein erblicher Adel von Lordaeron. Der Titel spiegelt die tragische Natur ihres Todes durch die Hand von Prinz Arthas wider, der ihre Seele aus ihrem Körper riss, damit sie als wimmernde Banshee dienen konnte. Obwohl der Titel an Monarchie erinnert, entspringt ihre Autorität der Befreiung, dem Überleben und dem absoluten militärischen Kommando.",al={"ist sylvanas eine königin","titel banshee-königin","was ist sylvanas titel"}},ac534dbb={q="Antwortet Sylvanas Thrall gegenüber?",a="Auf dem Papier erkennt Sylvanas Kriegshäuptling Thrall als den obersten Befehlshaber der Horde an, und sie stimmte ihrer Zweckallianz zu. In der Realität behält die Banshee-Königin die vollständige Autonomie über die Verlassenen und ihre nördlichen Gebiete. Thralls Wort wird respektiert, und Gesandte der Verlassenen laufen in Orgrimmar umher, aber Fürstin Sylvanas antwortet in erster Linie ihrem eigenen Überleben und den Ambitionen ihres Volkes.",al={"beziehung sylvanas thrall","gehorcht sylvanas thrall","steht sylvanas unter thrall"}},["6b51523d"]={q="Was ist in diesem Thronsaal dort oben die Treppe hinauf passiert?",a="Der Thronsaal war der Ort des katastrophalen Verrats, der das Königreich beendete. Prinz Arthas, frisch zurückgekehrt aus Nordend, marschierte an willkommen heißenden Bürgern und läutenden Glocken vorbei in diese Kammer. Als sein Vater, König Terenas, sich vom Thron erhob, um ihn zu begrüßen, zog Arthas Frostgram, verkündete, dass er seinem Vater nachfolgen würde, und stieß die verfluchte Runenklinge durch das Herz des alten Königs.",al={"was passierte im thronsaal","geschichte thronsaal von lordaeron","thronsaal historisch"}},["6e83c082"]={q="Ist das die Stelle, an der Terenas getötet wurde?",a="Ja. Wenn Ihr direkt vor das zerbrochene Podest tretet, steht Ihr auf genau den Pflastersteinen, auf denen König Terenas Menethil II. seinen letzten Atemzug tat. Ein schwacher, dunkler Fleck ist auf dem Steinboden immer noch sichtbar, von dem es heißt, er sei das Blut des alten Königs, das in das Mauerwerk sickerte, als sein Sohn ihn niederschlug. Selbst jetzt hallen spektrales Flüstern und Glocken leise in der Kammer nach.",al={"wo wurde terenas getötet","ist das terenas blut","ort an dem könig terenas starb"}},ea8d978d={q="Was ist mit Terenas' Krone passiert?",a="Terenas' goldene Krone fiel zu Boden, als Arthas ihn im Thronsaal ermordete. Ihr Fall markiert das Ende seiner Herrschaft und die Katastrophe, die Lordaeron ereilte.",al={"warum liegt die krone auf dem boden","könig terenas krone ruinen","terenas krone blut"}},bb044bc8={q="Sind die Verlassenen tatsächlich Teil der Horde?",a="Ja, obwohl es größtenteils ein Pakt zum gegenseitigen Überleben ist. Umgeben vom Scharlachroten Kreuzzug, feindseligen Menschen und der verbleibenden Geißel sandten die Verlassenen Botschafter über das Meer, um Verbündete zu suchen. Die Horde, die einen Stützpunkt in den Östlichen Königreichen benötigte, um der Allianz entgegenzuwirken, stimmte zu, ihnen den Eintritt zu gewähren, was den Verlassenen dringend benötigte militärische Unterstützung und internationales Ansehen verschaffte.",al={"verlassene horde allianz","sind untote in der horde","warum sind die verlassenen bei der horde"}},["50000697"]={q="Warum hat Thrall Untote in die Horde aufgenommen?",a="Thrall wurde hauptsächlich durch die Fürsprache von Erzruide Hamuul Runetotem und den Tauren überzeugt, die glaubten, die Verlassenen seien tragische Opfer, die eines Tages Erlösung oder ein Heilmittel für ihr Leiden finden könnten. Darüber hinaus erkannte Thrall die strategische Notwendigkeit eines etablierten Stützpunkts in den Östlichen Königreichen, um zu verhindern, dass die Allianz den nördlichen Kontinent unangefochten dominiert.",al={"warum erlaubte thrall die untoten","thrall verlassene grund","warum nahm die horde die verlassenen auf"}},["9af0f393"]={q="Vertrauen ihnen die Orcs und Tauren?",a="Nicht vollständig. Während die Tauren sie mit tiefem Mitleid betrachten und hoffen, ihr Leiden zu heilen, hegen viele Orcs tiefe Bedenken gegenüber dunkler Magie, Nekromantie und der finsteren Natur der Unterstadt. Thrall behält Sylvanas' Handlungen genau im Auge, und stationierte Botschafter sind misstrauisch gegenüber dem, was in den Laboren der Royal Apothecary Society gebraut wird.",al={"vertrauen orcs den verlassenen","tauren verlassene vertrauen","vertraut die horde untoten"}},["849f698a"]={q="Ist es sicher für mich, hier zu stehen?",a="Das hängt ganz von Eurer Loyalität ab. Wenn Ihr für die Horde kämpft, erkennen die Verlassenen und ihre Abscheulichkeiten Euch als Verbündeten an, obwohl die Schatten darüber zwielichtige Kreaturen und verweilende Geister bergen. Wenn Ihr unter dem Banner der Allianz marschiert, befindet Ihr Euch tief im Feindesland; Wachen der Verlassenen und Schreckenswachen werden Euch auf Sicht niederschlagen.",al={"sind die ruinen von lordaeron sicher","bin ich hier sicher","gefahr in lordaeron stehen"}},aac358a1={q="Werden mich die Wachen angreifen?",a="Todeswachen der Verlassenen und königliche Monstrositäten, die rund um die Ruinen stationiert sind, werden Reisende der Horde ignorieren oder beschützen, doch sie sind gegenüber Champions der Allianz brutal feindselig. Zudem lauern in den isolierten Korridoren und Dungeon-Flügeln der Ruinen oben feindselige Abtrünnige und Monster, die jeden angreifen, der ihren Weg kreuzt, ungeachtet der Loyalität.",al={"greifen unterstadt-wachen an","sind ruinen-wachen feindselig","greifen mich wachen an"}},e9ec8c01={q="Gibt es immer noch Geißel in der Nähe?",a="Ja. Während Sylvanas den Großteil der Geißel aus der Hauptstadt vertrieben hat, ist die Geißel gleich hinter den Grenzen in den Westlichen Pestländern noch stark verschanzt. Selbst in den dunkleren Nischen und vergessenen Untergeschossen dieser Ruinen halten sich noch geistlose Untote und Überbleibsel der Geißel auf, die nur darauf warten, jedes lebende Fleisch zu zerfetzen, das sich zu weit vorwagt.",al={"geißel in ruinen von lordaeron","ist die geißel in der nähe der unterstadt","gibt es dort geißel"}},["0a975308"]={q="Was ist das für eine Seuche, von der alle reden?",a="Sie sprechen von der Seuche des Untodes, einem schrecklichen biomagischen Ansteckungsherd, der vom Lichkönig und seinen Nekromanten entwickelt wurde. Durch den Kult der Verdammten über infiziertes Getreide in ganz Lordaeron verteilt, tötete sie jeden, der es innerhalb weniger Stunden verzehrte, und belebte ihre Leichen sofort als gehorsame, verrottende Knechte der Geißel wieder.",al={"was ist die seuche des untodes","welche seuche ist gemeint","lordaeron-seuche"}},["290f94a8"]={q="Wer hat die ursprüngliche Seuche erschaffen?",a="Die ursprüngliche Seuche wurde von den Schreckenslords der Brennenden Legion entwickelt und vom Lichkönig, Ner'zhul, perfektioniert, während er auf dem Frostthron in Nordend gefangen war. Um sie in Lordaeron freizusetzen, rekrutierte er den abtrünnigen Dalaran-Erzmagier Kel'Thuzad, der den Kult der Verdammten gründete und die Getreidevorräte vergiftete.",al={"wer erschuf die seuche des untodes","schöpfer der ursprünglichen seuche","wer machte die seuche"}},["89f62638"]={q="Stellt Sylvanas eine neue her?",a="Ja. Lady Sylvanas hat die Königliche Apothekergesellschaft damit beauftragt, eine 'neue Seuche' zu brauen. Ihr Ziel ist es, eine Biowaffe zu erschaffen, die stark genug ist, um sowohl die Geißel als auch die Lebenden gleichermaßen auszulöschen, um so das Überleben der Verlassenen und die Rache an Arthas zu sichern. Ihre geheimen Tests finden genau jetzt im Apothekarium unter uns statt.",al={"erschafft sylvanas eine seuche","neue seuche der verlassenen","neue seuche unterstadt"}},dcb566d2={q="Wer ist der Lichkönig und was will er?",a="Der Lichkönig ist der oberste Herrscher der Geißel, erschaffen aus dem gequälten Geist des Orc-Schamanen Ner'zhul, der auf dem Frostthron in Eis eingeschlossen war. Sein Ziel war es, Azeroth für die Brennende Legion weichzuklopfen, aber er hegte seine eigenen schrecklichen Ambitionen: alles sterbliche Leben auszurotten und es durch ein ewiges, vereintes Imperium des Untodes unter seinem absoluten mentalen Befehl zu ersetzen.",al={"wer ist der lichkönig","was will der lichkönig","motive des lichkönigs"}},["3a9893a7"]={q="Wo ist der Lichkönig jetzt?",a="Er regiert vom Frostthron auf dem Eiskronengletscher auf dem fernen, gefrorenen Kontinent Nordend aus. Nach Illidans Angriff, der sein eisiges Gefängnis zum Bersten brachte, rief der Lichkönig Arthas nach Nordend zurück, um ihre Geister zu verschmelzen und seine Macht zu bewahren, weit weg vom zerstörten Königreich Lordaeron.",al={"wo ist der lichkönig","standort des lichkönigs","wo ist der frostthron"}},["0138c577"]={q="Kontrolliert er immer noch die Verlassenen?",a="Nein. Als der Frostthron durch Illidans Zauberei gespalten wurde, begann der telepathische Griff des Lichkönigs zu brechen. Sylvanas und viele andere Untote erlangten ihren freien Willen zurück und lösten sich aus seinem kollektiven Geist. Obwohl er versucht, sie zurückzugewinnen, widerstehen die Verlassenen nun gewaltsam seinem Flüstern und kämpfen erbittert, um ihre Autonomie zu wahren.",al={"kontrolliert der lichkönig die verlassenen","kann der lichkönig die verlassenen befehligen","freier wille der verlassenen"}},["6a523c60"]={q="Wer ist der Scharlachrote Kreuzzug und warum hassen sie Untote?",a="Der Scharlachrote Kreuzzug ist ein Orden religiöser, menschlicher Fanatiker, der aus den zerschlagenen Überresten der Ritter der Silbernen Hand und den Rittern von Lordaeron gebildet wurde. Traumatisiert von der Seuche, die ihre Heimat zerstörte, sind sie von Paranoia zerfressen. In ihren Augen sind alle Untoten ausnahmslos Abscheulichkeiten, und jeder Lebende, der mit ihnen verkehrt, gilt als befleckt und ist zur Hinrichtung markiert.",al={"wer ist der scharlachrote kreuzzug","warum hasst der scharlachrote kreuzzug untote","scharlachroter kreuzzug lore"}},b59db3a3={q="Sind sie dieselben wie die Argentumdämmerung?",a="Nein, sie sind bittere Rivalen mit gemeinsamen Wurzeln. Beide gingen aus der Asche der Ritter der Silbernen Hand hervor, doch als der Scharlachrote Kreuzzug blinder Fanatik und Fremdenfeindlichkeit verfiel, spalteten sich gemäßigte Paladine ab, um die Argentumdämmerung zu gründen. Die Dämmerung heißt alle Völker willkommen und konzentriert sich darauf, das Land gegen die Geißel zu verteidigen, statt wahllos zu säubern.",al={"scharlachroter kreuzzug gegen argentumdämmerung","sind scharlachrote und argentumdämmerung gleich","unterschied zwischen scharlachroten und argentum"}},ca88b6f6={q="Greifen sie auch lebende Spieler an?",a="Ja. Der Scharlachrote Kreuzzug glaubt, dass jeder, der nicht ihr purpurrotes Wappen trägt, insgeheim die Seuche in sich trägt oder mit den Untoten kollaboriert. Ob Ihr ein Orc, ein Taure, ein Nachtelf oder ein menschlicher Soldat aus Sturmwind seid, ihre Fanatiker werden Euch als Träger der Verderbnis brandmarken und auf Sicht angreifen.",al={"greift der scharlachrote kreuzzug die allianz an","greifen scharlachrote lebende an","scharlachroter kreuzzug feindselig gegenüber lebenden"}},["861c7602"]={q="Was macht die Königliche Apothekergesellschaft da unten?",a="Diese finstere Gilde aus Apothekern und ehemaligen Magiern der Verlassenen operiert vom Apothekarium in der Unterstadt aus und arbeitet unermüdlich unter Lady Sylvanas' Dekret. Ihr Hauptauftrag ist die Entwicklung einer katastrophalen 'neuen Seuche', die sowohl die Geißel als auch die lebenden Völker auslöschen kann, wobei sie rücksichtslose Experimente durchführen, um die Vorherrschaft der Verlassenen zu sichern.",al={"was macht die königliche apothekergesellschaft","zweck der königlichen apothekergesellschaft","apotheker unterstadt"}},["3c47ce18"]={q="Experimentieren sie an Menschen?",a="Ja. Tief im Apothekarium sind gefangene Kreuzfahrer des Scharlachroten Kreuzzugs, Ghule der Geißel und verschiedene Bestien in Eisenkäfigen eingesperrt. Die Apotheker unterziehen diese Gefangenen schmerzhaften chemischen Cocktails und bösartigen Seuchenstämmen, um auszuwerten, wie schnell Fleisch verrottet und wie die Ansteckung sowohl lebende als auch nekrotische Physiologie beeinflusst.",al={"experimentiert apotheker an menschen","experimente der königlichen apothekergesellschaft","foltern unterstadt-apotheker menschen"}},f7d23701={q="Ist Arthas noch am Leben, und könnte ich jemals gegen ihn kämpfen?",a="Arthas ist nicht im sterblichen Sinne tot, sondern vollständig zu einem Todesritter-Champion der Geißel korrumpiert. Er ist weit über das Meer in Nordend, außerhalb der Reichweite von jedem in Lordaeron. Euer Kampf findet genau jetzt gegen die Bedrohungen statt, die hier verweilen: die lokalen Kommandeure der Geißel, der Scharlachrote Kreuzzug und die abtrünnigen Bestien, die diese Ruinen befallen.",al={"kann ich gegen arthas kämpfen","ist arthas am leben","werden wir arthas gegenüberstehen"}},["9fc2648e"]={q="Ist er jetzt der Lichkönig?",a="Flüstereien aus dem Norden behaupten, dass Arthas die Turmspitze von Eiskrone bestieg, um den Lichkönig aus Illidans Belagerung zu befreien, das Eis zerschlug, um den Helm der Herrschaft aufzusetzen und seine Seele mit Ner'zhul zu verschmelzen. Für die Welt im Allgemeinen bleibt der genaue Zustand Nordends in eisiges Geheimnis gehüllt, aber seine dunkle Präsenz lastet über allen Untoten.",al={"ist arthas der lichkönig","wurde arthas zum lichkönig","identität von arthas als lichkönig"}},["89a21402"]={q="Wie bin ich in den Ruinen von Lordaeron gelandet?",a="Ihr seid durch die zerbröckelnden äußeren Tore der gefallenen Hauptstadt in Tirisfal gegangen, direkt über den Aufzügen, die in die Unterstadt hinabführen. Ob Ihr einem militärischen Ruf gefolgt seid, Gerüchten über ungezügelte Schrecken nachgegangen seid, die an der Leiche des Königreichs kleben, oder feindliches Gebiet durchquert habt, um heilige Überbleibsel der Vergangenheit zurückzuerobern – Eure Reise führte Euch in die versiegelten, umkämpften Innenhöfe, wo die Schatten der Geißel und die Geister der alten Menschheit noch immer verweilen.",al={"wie kam ich hierher","wie landete ich hier","warum bin ich in den ruinen von lordaeron","wie bin ich hier angekommen"}},bb4abd7f={q="Was soll ich in den Ruinen von Lordaeron tun?",a="Ihr seid hier, um die Schrecken zu säubern, die in den Ruinen an der Oberfläche über der Hauptstadt der Verlassenen eitern. Für die Horde bedeutet das, abtrünnige Bestien der Geißel zu jagen, verlorene Insignien zurückzuholen und tödliche Gebräue für die Königliche Apothekergesellschaft zu testen. Für die Allianz ist es ein verdeckter Schlag, um angestammten Boden zu reinigen, heilige Erbstücke wie das Crest of Lordaeron zurückzuholen und wandernden, gequälten Geistern Trost zu spenden, die noch keinen Frieden gefunden haben.",al={"was mache ich hier","was ist meine mission hier","was soll ich in den ruinen tun","was ist mein ziel hier"}}},fp="18,278,27.503.0,22.413.0,25.302.1,48.174.0,61.277.0,23.179.0,49.228.0,61.384.1,54.227.0"}
P.entries["zone:scarlet"] = {n="Das Scharlachrote Kloster",s="Eingebettet in die nordöstlichen Hügel von Tirisfal war Das Scharlachrote Kloster einst eine friedliche Zuflucht und ein Zentrum der Gelehrsamkeit für die Kirche des Heiligen Lichts. Nach dem Fall von Lordaeron wurde es vom Scharlachroten Kreuzzug eingenommen und schwer befestigt, um als ihr wichtigster Vorposten im Westen zu dienen. Heute ist es eine weitläufige Festung, die in vier Flügel unterteilt ist, in denen fanatische Eiferer trainieren, Gefangene foltern und einen kompromisslosen Krieg gegen alle Außenstehenden führen.",h="Eingebettet in die nordöstlichen Hügel von Tirisfal war Das Scharlachrote Kloster einst eine friedliche...",kw={"waffenkammer","kathedrale","doan","friedhof","herod","library","mograine","scharlachroter kreuzzug","das scharlachrote kloster","tirisfal","whitemane"},ang={["class:Mage"]="Der Library-Flügel beherbergt seltene historische und theologische Wälzer, die von Arkanist Doan bewacht werden, dem führenden Arkanisten des Kreuzzugs.",["class:Paladin"]="Das Kloster war einst ein heiliger Sitz der Priesterschaft von Lordaeron, was seinen Abstieg in scharlachroten Fanatismus zu einer tragischen Mahnung darüber macht, wie Hingabe in Wahnsinn umschlagen kann.",["class:Priest"]="Ursprünglich ein Sitz der Kirche des Heiligen Lichts, zeigen seine prächtigen Kapellen, wie heilige Macht noch immer von Sterblichen ausgeübt werden kann, die von Hass und Rachegelüsten zerfressen sind.",["race:Undead"]="An den Grenzen von Tirisfal gelegen, stellt Das Scharlachrote Kloster eine existenzielle Bedrohung für die Verlassenen dar, schleust Spione nach Todesend ein und foltert gefangene Untote in seinen Kerkern."},sec={{t="Eine gefallene Zuflucht",b="Vor dem Dritten Krieg diente das Kloster als stolzer Sitz der Priesterschaft von Lordaeron und als Zentrum für Gelehrsamkeit und Erleuchtung. Nach den Verheerungen durch die Geißel säuberten überlebende Kreuzfahrer die Hallen von verbliebenen Untoten und Spinnen und verwandelten die ruhigen Archive und Innenhöfe in eine befestigte Garnison. Getrieben von Paranoia und Trauer sah der Scharlachrote Kreuzzug bald alle Außenstehenden – ob lebendig oder untot, Mensch oder andersartig – als Träger der Seuche an, die mit Feuer geläutert werden müssen."},{t="Die vier Flügel",b="Hinter dem Grand Vestibule des Klosters liegen vier verschiedene Viertel. Der Friedhof ist eine unheilige Freiluftterrasse, auf der gefallene Kreuzfahrer als untote Scheusale auferstehen und Folterer Gefangenen Geständnisse entlocken. Die Library bewahrt kostbare theologische Schriften und historische Wälzer, bewacht vom abtrünnigen Magier Arkanist Doan und seinen Hunden. Die Waffenkammer dient als Übungsgelände, auf dem scharlachrote Waffenmeister wie Herod fanatische Rekruten zu eisernen Kriegern drillen. Am tiefsten im Inneren steht die Kathedrale, das erhabene Herz der Festung, von wo aus die Führung des Kreuzzugs ihren Feldzug durch den verheerten Norden lenkt."},{t="Der Fall der Hochinquisitorin",b="Das innere Heiligtum der Kathedrale wird von Scharlachroter Kommandant Mograine und der wahren Herrin des Klosters, Hochinquisitor Whitemane, befehligt. Whitemanes Niederlage versetzt der operativen Führung des Kreuzzugs in Tirisfal einen schweren Schlag. Ihre Fähigkeit, blendendes Heiliges Licht zu kanalisieren und gefallene Champions wiederzubeleben, ließ die Garnison ihren Anhängern unbesiegbar erscheinen. Ihr Tod zerstört den Anschein göttlicher Sendung, der den Eifer des Klosters anfachte, entlarvt die Führung des Kreuzzugs als sterblich und schwächt ihren Feldzug gegen die Verlassenen und die benachbarten Lande erheblich."}},faq={{q="Warum ist der Scharlachrote Kreuzzug lebenden Abenteurern der Allianz feindlich gesinnt?",a="Der Kreuzzug ist extremer geistiger Umnachtung und Paranoia verfallen. In ihren Augen ist jeder, der nicht ihren scharlachroten Wappenrock trägt, ein potenzieller Träger der Seuche der Geißel. Sie unterscheiden nicht länger zwischen Freund und Feind und betrachten alle Außenstehenden als verdorbene Wesen, die geläutert werden müssen, bevor sie die Verderbnis verbreiten können.",al={"warum scharlachrote menschen angreifen","scharlachroter kreuzzug feindselig allianz","warum sie verrückt sind"}},{q="Was geschieht, wenn Ihr Hochinquisitor Whitemane besiegt?",a="Die Niederlage von Hochinquisitor Whitemane enthauptet die westliche Militärführung des Scharlachroten Kreuzzugs. Als spirituelle Führerin des Klosters hielten ihre wundersamen Wiederbelebungskräfte die Moral der Truppen aufrecht und sorgten dafür, dass Kommandant Mograine an ihrer Seite weiterkämpfte. Ihr Tod nimmt dem Kreuzzug seine mächtigste Priesterin in Tirisfal und lässt die Garnison in Unordnung zurück, wodurch ihre Bedrohung für die umliegende Region erheblich sinkt.",al={"was bedeutet der tod von whitemane","whitemane besiegt geschichte","kathedrale ende"}},{q="Was ist Der scharlachrote Schlüssel und wo ist er zu finden?",a="Der scharlachrote Schlüssel wird tief im Library-Flügel des Klosters aufbewahrt, in Arkanist Doans Geldkassette hinter seinem persönlichen Arbeitszimmer. Der Besitz dieses Schlüssels ist erforderlich, um die äußeren Tore sowohl der Waffenkammer als auch der Kathedrale aufzuschließen.",al={"wo ist der scharlachrote schlüssel","wie man waffenkammer und kathedrale öffnet","kloster schlüssel"}},{q="Warum befindet sich Arkanist Doan im Scharlachroten Kloster?",a="Arkanist Doan ist ein mächtiger menschlicher Magier, der dem Scharlachroten Kreuzzug dient, überzeugt davon, dass arkane Magie eine notwendige Waffe ist, um Lordaeron von der Geißel zu säubern. Er verwaltet den weitläufigen Library-Flügel des Klosters und bewacht den scharlachroten Schlüssel in seinem Arbeitszimmer.",al={"wer ist arkanist doan","doan geschichte","magier in bibliothek"}},{q="Wer war Alexandros Mograine und wie ist er mit diesem Ort verbunden?",a="Alexandros Mograine, der berühmte Aschenbringer, war ein legendärer Paladin der Silbernen Hand und neben Hochgeneral Abbendis und Großinquisitor Isillien einer der Gründer des Scharlachroten Kreuzzugs. Sein Sohn Renault befehligt nun gemeinsam mit Hochinquisitor Whitemane die Kathedrale.",al={"mograine kloster geschichte","aschenbringer kloster","renault mograine vater"}},{q="Was unterscheidet den Friedhof-Flügel so sehr vom Rest des Klosters?",a="Während der Rest des Klosters den äußeren Anschein makelloser Hingabe wahrt, fault auf dem Friedhof der Fanatismus des Kreuzzugs von innen heraus. Hier befinden sich die brutalen Folterkammern unter der Leitung von Befrager Vishas, während verwahrloste Krypten und ruhelose Tote von gefallenen Zauberwirkern wie Blutmagier Thalnos geerntet oder manipuliert werden.",al={"warum friedhof untot ist","thalnos geschichte","befrager vishas"}}},fx={["0c05301c"]={q="Wer ist der Scharlachrote Kreuzzug?",a="Der Scharlachrote Kreuzzug ist ein fanatischer militärischer Orden aus menschlichen heiligen Kriegern und Priestern, der aus den Überresten der Ritter der Silbernen Hand gebildet wurde. Verzehrt von Trauer und Hass nach der Geißelung von Lordaeron, haben sie sich ganz der Ausrottung der Untoten verschrieben und setzen ihre Mission mit extremer Rücksichtslosigkeit und Paranoia durch.",al={"wer ist der scharlachrote kreuzzug","was ist der scharlachrote kreuzzug","lore scharlachroter kreuzzug"}},b0ef06b1={q="Sind die Mitglieder des Scharlachroten Kreuzzugs Menschen?",a="Ja, ihre Ränge bestehen ausschließlich aus Menschen aus dem gefallenen Reich Lordaeron. Sie hegen eine heftige Intoleranz gegenüber allen nicht-menschlichen Völkern, ungeachtet von Bündnissen oder früheren Bindungen, und erachten Außenstehende als unwürdig oder von Natur aus durch die Seuche befleckt.",al={"nur menschen im kreuzzug","volk des kreuzzugs","ist der scharlachrote kreuzzug menschlich"}},["1402011d"]={q="Warum greife ich eine Kirche voller Paladine an?",a="Obwohl sie die Insignien heiliger Orden tragen und das Licht führen, sind die Kommandanten des Klosters in gewalttätigen Extremismus verfallen. Ob Ihr dem Ruf von Raleigh the Devout folgt, um die korrupte Führung des Ordens zu säubern, oder im Namen von Varimathras in der Unterstadt zuschlagt, um einen aggressiven Nachbarn vor seiner Haustür zu neutralisieren, Ihr seid dort, um ihre militärische Macht zu brechen.",al={"warum scharlachrotes kloster angreifen","warum paladine dort töten","grund für kampf im kloster"}},["18e8d4ac"]={q="Ist der Scharlachrote Kreuzzug tatsächlich böse?",a="Sie begannen mit einer edlen Sache – Lordaeron von der Geißel der Untoten zu befreien. Doch Trauma und Paranoia haben ihren Zweck völlig verzerrt. Sie foltern nun unschuldige Reisende, brandmarken jeden Außenstehenden als verseucht und schlachten jeden ab, der nicht ihren Wappenrock trägt, wodurch sie im Streben nach Läuterung jeden moralischen Verstand verlieren.",al={"ist scharlachroter kreuzzug böse","sind das die bösen","sind kreuzzügler böse"}},fe2faadd={q="Unterstützt die Allianz den Scharlachroten Kreuzzug?",a="Nicht offiziell. Während manche in Sturmwind Sympathien für die überlebenden heiligen Krieger von Lordaeron hegen mögen, hat die unterschiedslose Feindseligkeit des Kreuzzugs formelle Bindungen zerrissen. Abenteurer und Persönlichkeiten der Allianz wie Raleigh the Devout betrachten ihre derzeitigen Kommandanten als wahnsinnige Eiferer, deren Gräueltaten die Ehre des Lichts beschmutzen.",al={"unterstützt die allianz den kreuzzug","gehört kreuzzug zur allianz","allianz bindungen zum kreuzzug"}},ae07147f={q="Befindet sich die Anführerin des Klosters in der Kathedrale?",a="Ja. Sowohl der Scharlachrote Kommandant Mograine als auch Hoher Inquisitor Whitemane residieren in der Kapelle der Kreuzzügler tief im Flügel der Kathedrale, bewacht von einer inneren Garde eifriger Verteidiger.",al={"wo ist whitemane","ist whitemane in der kathedrale","ort des kathedralenbosses"}},["11700a05"]={q="Warum hasst der Scharlachrote Kreuzzug die Verlassenen so sehr?",a="Für den Kreuzzug sind alle Untoten Abscheulichkeiten, die aus der Seuche hervorgegangen sind, welche ihre Familien und ihre Heimat auslöschte. Sie machen keinen Unterschied zwischen den willenlosen Schergen der Geißel und den freien Verlassenen, die die Hauptstadt besetzt halten; beide werden als verrottende Usurpatoren angesehen, die in heiligem Feuer vollständig gereinigt werden müssen.",al={"kreuzzug gegen verlassene","warum hasst kreuzzug untote","fehde zwischen kreuzzug und verlassenen"}},["38169c8a"]={q="Waren die Scharlachroten Kreuzzügler und die Verlassenen einst dasselbe Volk?",a="Ja. Die meisten Kreuzzügler und Verlassenen waren Bürger, Soldaten oder Priester des Königreichs Lordaeron vor dem Dritten Krieg. Als die Seuche durch das Land fegte, wurden diejenigen, die starben und wieder auferstanden, zu Untoten, während die traumatisierten Lebenden flohen oder sich zusammenschlossen, wodurch ehemalige Nachbarn und Verwandte zu erbitterten, geschworenen Feinden wurden.",al={"kannten sich kreuzzügler und verlassene","waren beide bürger von lordaeron","überreste von lordaeron"}},["80c0e472"]={q="Woher kam der Scharlachrote Kreuzzug?",a="Der Kreuzzug entstand aus den überlebenden Rittern der Silbernen Hand und Soldaten Lordaerons, die von Hochlord Alexandros Mograine und General Abbendis angeführt wurden. Überwältigt vom Verlust ihres Königreichs, spalteten sich die überlebenden Anführer: Diejenigen, die unerbittlichen, kompromisslosen Fanatismus befürworteten, bildeten den Scharlachroten Kreuzzug, während Gemäßigte sich abspalteten, um die Argentumdämmerung zu gründen.",al={"ursprung des scharlachroten kreuzzugs","wie wurde kreuzzug gegründet","wer gründete kreuzzug"}},c4a70323={q="Was war die Silberne Hand?",a="Die Ritter der Silbernen Hand waren der legendäre heilige Orden der Paladine, der während des Zweiten Kriegs von Erzbischof Alonsus Faol und Uther der Lichtbringer gegründet wurde. Sie dienten als vorderste Vorkämpfer der Allianz und Lordaerons, bis Prinz Arthas ihre Reihen während der Invasion der Geißel zerschlug.",al={"was war die silberne hand","ritter der silbernen hand","paladine der silbernen hand"}},d5472427={q="Warum tötet der Scharlachrote Kreuzzug auch lebende Menschen?",a="Tiefe Paranoia hat den Bezug des Kreuzzugs zur Realität untergraben. Sie glauben, dass jeder Außenstehende ein heimlicher Träger der Untotenseuche sein könnte. Jeder, der nicht ihre Uniform trägt und sich ihrer starren Autorität unterwirft, wird als korrumpiert gebrandmarkt und zu Folter oder Tod verurteilt.",al={"warum lebende menschen töten","kreuzzug tötet menschen","warum töten sie ihresgleichen"}},b6568619={q="Ist der Scharlachrote Kreuzzug eine Bedrohung für Sturmwind?",a="Nicht direkt im Sinne einer geografischen Eroberung, da ihre Bemühungen in den nördlichen Ruinen von Lordaeron verankert sind. Ihr Wahnsinn und ihre Bereitschaft, jeden Reisenden zu ermorden, machen sie jedoch zu einer aktiven Gefahr für Bürger, Botschafter und Abenteurer der Allianz, die sich in die Nähe ihrer Gebiete wagen.",al={"ist kreuzzug eine bedrohung für die allianz","kreuzzug gegen sturmwind","bedrohung durch den kreuzzug"}},["6889160e"]={q="Warum will jeder, dass ich in Das Scharlachrote Kloster gehe?",a="Beide Fraktionen haben wichtige Interessen in Tirisfal. Die Verlassenen können eine schwer bewaffnete Festung voller Eiferer direkt vor ihrer Hauptstadt nicht dulden, während Vertreter der Allianz versuchen, heilige Texte zu bergen, gefährliche Abtrünnige zu unterdrücken und der wahnsinnig gewordenen Führung Gerechtigkeit widerfahren zu lassen.",al={"warum werde ich ins kloster geschickt","wer will das kloster tot","grund für kloster quests"}},["0c6b4a7d"]={q="Wofür ist Scarlet Monastery Library da?",a="Die Library, die das Athenaeum und die Gallery of Treasures umfasst, beherbergt alte Schriften aus Lordaeron, historische Aufzeichnungen und arkanes Wissen. Sie dient sowohl als intellektuelles Archiv als auch als abgeschiedenes Forschungsheiligtum, dem Arkanist Doan vorsteht.",al={"zweck des bibliotheksflügels","was machen sie in der bibliothek","athenaeum des scharlachroten klosters"}},["29dc31ee"]={q="Wofür werden die Flügel der Waffenkammer und der Kathedrale genutzt?",a="Die Waffenkammer dient als militärisches Herz des Kreuzzugs und beherbergt Trainingsgelände, Kasernen und Waffenlager, die von Herod dem Scharlachroten Champion beaufsichtigt werden. Die Kathedrale steht als höchstes geistiges Heiligtum und Befehlsstand, wo Mograine Elitetruppen drillt und Whitemane Predigten hält und die Präsenz des Kreuzzugs in Tirisfal koordiniert.",al={"wozu waffenkammer und kathedrale","zweck waffenkammer","zweck kathedrale"}},f04a1b7f={q="Wie bin ich im Scharlachroten Kloster gelandet?",a="Ihr seid in die weit nordöstlichen Hügel von Tirisfal gereist und durch das neblige Land zum befestigten Sitz des Scharlachroten Kreuzzugs vorgedrungen. Ob Ihr im Auftrag der Horde aus der Unterstadt heraufgekrochen seid, um eine Bedrohung durch Eiferer vor ihrer Haustür zu beseitigen, oder vom Vorgebirge des Hügellands nach Norden marschiert seid, um dem Ruf enttäuschter Kreuzzügler zu folgen, die die fanatische Führung des Klosters stürzen wollten, der Weg führte Euch unweigerlich vor diesen schwer bewachten Komplex.",al={"wie bin ich hierhergekommen","weg zum scharlachroten kloster","warum bin ich hier"}},be779d1d={q="Was soll ich im Scharlachroten Kloster tun?",a="Ihr seid hier, um die vier Flügel des Kreuzzugs zu durchbrechen und ihren Halt über die Region zu brechen. Je nachdem, wer Euch geschickt hat, jagt Ihr vielleicht gefallene Anführer wie den Scharlachroten Kommandanten Mograine und Hoher Inquisitor Whitemane, entdeckt verlorene Bände und Wissen in der Bibliothek, sammelt Herzen des Eifers für die Apothekervereinigung oder bergt heilige Artefakte und erschlagt korrupte Anführer, die jeden außerhalb ihrer Ränge als verseuchte Untote brandmarken.",al={"was mache ich hier","warum bin ich hier","meine mission hier"}},["3ffc247b"]={q="Was ist das Scharlachrote Kloster?",a="Das Scharlachrote Kloster liegt in den nordöstlichen Tirisfal und ist ein befestigtes Heiligtum sowie die wichtigste Bastion des Scharlachroten Kreuzzugs in der Region. Einst ein friedlicher Kathedralenkomplex, der dem Heiligen Licht und klerikalem Lernen gewidmet war, wurde die Festung in ein schwer bewaffnetes Hauptquartier, Trainingsgelände und ideologisches Bollwerk für den fanatischen Feldzug des Kreuzzugs gegen das Untodtum umgewandelt.",al={"was ist das scharlachrote kloster","scharlachrotes kloster lore","über das scharlachrote kloster"}},fd7417a7={q="War das Scharlachrote Kloster schon immer ihres?",a="Nein. Vor dem Fall von Lordaeron war es einfach als das Alte Kloster bekannt. Ursprünglich vom adligen Haus Godwyn gefördert, diente es als Erzbischofssitz und Priesterseminar unter Erzbischof Alonsus Faol. Nach der Verwüstung des Dritten Krieges befreiten überlebende Paladine seine Hallen von den verweilenden Geißel-Infestationen und benannten es in Scharlachrotes Kloster um.",al={"war das scharlachrote kloster immer kreuzzug","geschichte des scharlachroten klosters","wem gehörte das scharlachrote kloster früher"}},e7b85043={q="Wer hat das Scharlachrote Kloster erbaut?",a="Das Alte Kloster wurde als Zufluchtsort der Kirche des Heiligen Lichts unter der Schirmherrschaft des adligen Hauses Godwyn errichtet. Seine Bibliotheken und Archive wurden über Generationen von Archivaren wie Blake Godwyn kuratiert und standen bis zum Zusammenbruch des Königreichs als stolzes Zentrum des Priestertums und der Paladinausbildung in Lordaeron.",al={"wer baute das kloster","ursprünge des klosters"}},fbd0569e={q="Wer hat das Kommando über das Scharlachrote Kloster?",a="Die militärische Garnison der Festung untersteht Scharlach-Kommandant Renault Mograine, der eine ergebene Streitmacht von Kriegern befehligt. Die wahre geistliche und doktrinäre Herrscherin des Komplexes ist jedoch Hochinquisitorin Weißsträhne, eine mächtige Priesterin, die imstande ist, die Gefallenen wiederzuerwecken, damit sie in ihrem Namen kämpfen.",al={"wer fuehrt das scharlachrote kloster an","wer leitet das kloster","anfuehrer des scharlachroten klosters"}}},fp="17,291,18.495.0,14.492.0,31.517.1,66.284.0,55.301.1,46.170.0,46.213.0,57.280.1,74.218.0"}
P.entries["zone:searinggorge"] = {n="Sengende Schlucht",s="Die Sengende Schlucht ist ein verbrannter, trostloser Canyon im südlichen Khaz Modan, der im Süden an den Schwarzfels grenzt. Einst ein fruchtbarer Ausläufer des Rotkammgebirges, wurde sie vor über zwei Jahrhunderten durch die apokalyptische Beschwörung von Ragnaros dem Feuerfürsten verwüstet. Heute wird die Schlucht intensiv vom Dunkeleisenzwergen-Klan ausgebeutet, dessen weitläufige Sklavenminen im Kessel von der abtrünnigen Thoriumbruderschaft scharf überwacht werden.",h="Die Sengende Schlucht ist ein verbrannter, trostloser Canyon im südlichen Khaz Modan, der im Süden an den...",kw={"der schwarzfels","der kessel","dunkeleisenzwergen-klan","ragnaros","sengende schlucht","die schlackengrube","steinwerkpass","thoriumbruderschaft","thoriumspitze"},ang={["class:Rogue"]="Schurken mit erfahrener Schlossknackerfertigkeit sind hier geschätzte Gefährten, da sie das verriegelte Tor am Steinwerkpass öffnen können, welches Loch Modan direkt mit der Schlucht verbindet.",["faction:Alliance"]="Die Allianz hält das Tor am Steinwerkpass verschlossen, um die Dunkeleisenzwerge von friedlichen Zwergensiedlungen in Loch Modan fernzuhalten, gestattet jedoch mutigen Abenteurern, in die Schlucht vorzustoßen.",["faction:Horde"]="Mit Kargath als Aufmarschgebiet schlug die Horde einen Überlandzugang in die Schlucht, um Informationen über den Schwarzfels zu sammeln und die Operationen der Dunkeleisenzwerge in Khaz Modan zu stören.",["profession:Mining"]="Die vulkanische Landschaft und die tiefen Grabungen in der Schlackengrube machen die Sengende Schlucht zu einem der ergiebigsten Jagdreviere für reiche Adern aus Mithril, Echtsilber und begehrtem Dunkeleisenerz.",["race:Dwarf"]="Für die Zwerge von Eisenschmiede ist die Sengende Schlucht eine bittere Mahnung an den Krieg der drei Hämmer und die verhängnisvolle Torheit des Dunkeleisen-Klans, dessen Ausgrabungen nun die südlichen Zugänge von Khaz Modan bedrohen."},sec={{t="Ein verbranntes Ödland",b="Vor dem Krieg der drei Hämmer war das Gebiet der heutigen Sengenden Schlucht eine grüne, hügelige Bergregion, die mit der Kette des Rotkammgebirges verbunden war. Diese üppige Landschaft fand vor über zweihundertdreißig Jahren ein jähes Ende, als Zauberer-Thane Thaurissan in seiner Verzweiflung über die drohende Niederlage Ragnaros aus den Tiefen unter der Welt herbeirief. Das kataklysmische Erscheinen des Feuerfürsten riss die Erde entzwei, türmte den Schwarzfels auf, legte die prächtige Dunkeleisenstadt Thaurissan in rauchende Trümmer und verbrannte das nördliche Tal zu einer rissigen Weite aus Asche, Schwefel und Vulkanglas."},{t="Der Kessel und die Schlackengrube",b="Auf der Suche nach Rohstoffen für ihre Kriegsmaschinerie nach dem Verlust ihrer alten Hauptstadt bemächtigten sich die Dunkeleisenzwerge der trostlosen Schlucht. Im Zentrum des Tals liegt der Kessel, eine gigantische Tagebaugrabung, die tief in den Fels hinabführt. In ihren unteren Tiefen befindet sich die Schlackengrube, ein brutaler unterirdischer Minenkomplex. Hier treiben Aufseher der Dunkeleisenzwerge und schwerfällige Kriegsgolems gefangene Feinde zu zermürbender Sklavenarbeit an, um unter ständiger Bedrohung durch aufsteigende Lava und umherstreifende Bestien Eisen, Mithril und seltene Vorkommen von Dunkeleisenerz aus dem glühenden Gestein zu schlagen."},{t="Thoriumbruderschaft und umkämpfte Pfade",b="Auf den nördlichen Klippen über der Ausgrabung thront die Thoriumspitze, der befestigte Außenposten der Thoriumbruderschaft. Diese Meisterschmiede haben sich von ihren Verwandten im Schwarzfels losgesagt und bieten Reisenden neutrale Zuflucht, die bereit sind, die Unternehmungen der Dunkeleisenzwerge zu sabotieren oder sie mit seltenen Schmelzkomponenten zu versorgen. Der Zugang zur Schlucht selbst ist streng reglementiert: Die Allianz hält den Steinwerkpass hinter schweren Eisentoren in Richtung Loch Modan verriegelt, während Expeditionen der Horde aus dem nahen Kargath einen schmalen Pfad durch das östliche Ödland geschlagen haben, um das Gebiet aufzuklären."}},faq={{q="Warum ist die Sengende Schlucht verbrannt und voller Asche?",a="Vor über zweihundertdreißig Jahren, während des Kriegs der drei Hämmer, versuchte der Dunkeleisen-Zauberer-Thane Thaurissan, eine übernatürliche Macht herbeizurufen, um die Niederlage abzuwenden. Stattdessen beschwor er Ragnaros den Feuerfürsten. Der kataklysmische Ausbruch zerschmetterte den südlichen Teil des Rotkammgebirges, schuf den Vulkan des Schwarzfels und verbrannte die umliegenden Täler zur Sengenden Schlucht und der Brennenden Steppe.",al={"warum ist sie verbrannt","sengende schlucht lore","wie entstand die sengende schlucht"}},{q="Wer sind die Zwerge an der Thoriumspitze?",a="Sie gehören der Thoriumbruderschaft an, einer unabhängigen Fraktion von Dunkeleisenzwergen, die ihre Bande zu ihrer imperialen Verwandtschaft unter dem Schwarzfels gekappt hat. Von ihrem Lager auf der Thoriumspitze aus arbeiten sie als Meisterschmiede und Konstrukteure und handeln mit Wissen sowie Handwerksgeheimnissen mit jedem Reisenden, der ihnen gegen die Dunkeleisentruppen in der Tiefe beisteht.",al={"zwerge der thoriumspitze","wer ist die thoriumbruderschaft","thoriumbruderschaft lore"}},{q="Was geschieht im Kessel?",a="Der Kessel ist eine gewaltige offene Ausgrabung unter der Kontrolle des Dunkeleisen-Klans, in der sich die unterirdische Schlackengrube befindet. Aufseher der Dunkeleisenzwerge und Kriegsgolems zwingen gefangene Gefangene zu Sklavenarbeit, um wertvolle Erze – darunter begehrte Dunkeleisenvorkommen – abzubauen und damit die großen Schmieden im Inneren des Schwarzfels zu befeuern.",al={"was ist der kessel","die schlackengrube lore","was bauen dunkeleisenzwerge ab"}},{q="Wie gelangt man von Loch Modan in die Sengende Schlucht?",a="Der Durchgang von Loch Modan über den Steinwerkpass ist durch ein schweres, verschlossenes Tor versperrt, das von Gebirgsjägern aus Eisenschmiede bewacht wird. Reisende müssen sich entweder den Schlüssel zur sengenden Schlucht durch eine offizielle Aufgabe für Kurator Thorius verdienen, das Schloss von einem geschickten Schurken knacken lassen oder das Tor gänzlich umgehen, indem sie den offenen Pfad südlich von Kargath im Ödland nehmen.",al={"stonewroughtpass tor","tor zur sengenden schlucht öffnen","schlüssel zur sengenden schlucht"}},{q="Warum interessiert sich die Horde für die Sengende Schlucht?",a="Von der nahe gelegenen Festung Kargath im Ödland aus schlugen Kriegsherren der Horde einen Gebirgspass in die Schlucht, um Truppenbewegungen der Dunkeleisenzwerge auszuspähen und taktische Routen zum Schwarzfels zu sichern, der von immenser strategischer Bedeutung ist.",al={"warum ist die horde hier","kargath schlucht verbindung","hordenpräsenz"}},{q="Gibt es Dungeons oder Schlachttore in der Sengenden Schlucht?",a="In der Schlucht selbst gibt es keine Instanzportale, aber der südliche Ausgang führt direkt in den Schwarzfels. Dieser Berg beherbergt die Schwarzfelstiefen, die Schwarzfelsspitze und die tiefen Gänge, die in den Geschmolzenen Kern führen.",al={"sengende schlucht instanzen","dungeons in der sengenden schlucht","wo ist der geschmolzene kern"}}},fp="13,249,20.456.0,29.498.0,39.549.0,51.376.0,44.359.0,33.260.0,50.303.0,45.225.0,62.207.0"}
P.entries["zone:shadowfang"] = {n="Burg Shadowfang",s="Auf den schroffen Klippen über Lohenscheit thronend, ist Burg Shadowfang die düstere Festung des abtrünnigen Kirin-Tor-Magiers, Erzmagier Arugal. Einst der Stammsitz von Baron Silberlein, wimmelt die Bastion nun von wilden Worgenbestien und den gepeinigten Phantomen ihrer abgeschlachteten Verteidiger. Für Abenteurer, die den südlichen Silberwald durchqueren, stellt die Burg das finstere Epizentrum der bestialischen Geißel dar, die die Region heimsucht.",h="Auf den schroffen Klippen über Lohenscheit thronend, ist Burg Shadowfang die düstere Festung des abtrünnigen...",kw={"arugal","fenrus","lohenscheit","sfk","shadowfang","silberlein","silberwald","gruental","worgen"},ang={["class:Mage"]="Die Tragödie von Shadowfang dient als finstere Warnung davor, was geschieht, wenn sich ein Magier der Kirin Tor an extradimensionalen Beschwörungen versucht, die sich jeder sterblichen Kontrolle entziehen.",["class:Paladin"]="Der ruhelose Geist von Kommandant Grüntal steht als traurige Mahnung an gefallene Paladinverteidiger, deren heilige Eide durch den Tod verzerrt wurden.",["class:Warlock"]="Die finsteren Energien, Leerwandler und dunklen Zauber innerhalb der Burg wecken das Interesse von Praktizierenden, die uralte Relikte wie die Kugel von Soran'ruk bergen wollen.",["faction:Horde"]="Die Verlassenen betrachten Arugals vordringende Rudel als unmittelbare Bedrohung für ihr aufkeimendes Territorium im Silberwald, was die Burg zu einem vorrangigen Ziel für Agenten der Todespirscher und die Königliche Apothekervereinigung macht."},sec={{t="Der Fall der Dynastie Silberlein",b="Bevor sie von einem Albtraum umhüllt wurde, war Shadowfang als Burg Silberlein bekannt, ein edler Herrschaftssitz, der von dem frommen Kommandanten Grüntal besetzt war. Als die Geißel während des Dritten Krieges durch Lordaeron fegte, fielen Dalarans Magier in Scharen. Verzweifelt darum bemüht, das Vordringen der Toten einzudämmen, widersetzte sich Erzmagier Arugal der Führung der Kirin Tor und vertiefte sich in die Forschungen des Magiers Ur, indem er extradimensionale Worgen herbeirief, um das Blatt zu wenden. Die beschworenen Bestien fielen grausam über die Untoten her, entzogen sich jedoch rasch jeder sterblichen Kontrolle, brachen in den südlichen Silberwald ein und stürmten die Bastion. Baron Silberlein und sein gesamter Hofstaat wurden niedergemetzelt und dazu verdammt, an der Seite der wilden Monster, die ihre Heimat überrannten, durch die steinernen Hallen zu spuken."},{t="Arugals Kinder",b="Von Schuld und Wahnsinn zerrüttet, zog sich Arugal hinter die blutbefleckten Zinnen zurück, nahm die unersättlichen Wolfsmenschen als seine geliebten „Kinder“ an und taufte die Festung Burg Shadowfang. Tief in den steinernen Gemächern gedeihen Wolfsrudel und Schattenhunde unter Züchtern wie Wolfsmeister Nandos, bewacht von Arugals gewaltiger Wolfsbestie, Fenrus dem Verschlinger. Außerhalb der Mauern machte der Fluch nicht halt; das nahe gelegene Lohenscheit bleibt in einem schrecklichen nächtlichen Zyklus gefangen, dessen Bewohner tagsüber als Menschen umhergehen und im Mondschein als unersättliche Worgen jagen, unerbittlich an den verrückten Erzmagier hoch oben auf den Höhen gebunden."},{t="Der Vorstoß der Verlassenen",b="In Erkenntnis der ernsten Bedrohung, die Arugal für ihre Herrschaft im Silberwald darstellt, entsandte Fürstin Sylvanas Windläufer die Königliche Apothekervereinigung und Elite-Todespirscher, um den Ursprung des Worgenfluchs auszumerzen. Infiltrationstrupps erlitten in den Kerkern brutale Verluste, doch Helden der Horde, die dem Ruf aus dem Grabmal folgen, brechen schließlich in den höchsten Turm ein. Das Niederschlagen des Erzmagiers setzt dem Herrn des Rudels ein formelles Ende, trennt den Geist ab, der die Ausbreitung der Bestien über die Wildnis lenkt, und fordert seinen Kopf als Beweis für Lordaerons Vergeltung ein."}},faq={{q="Was geschieht, wenn Erzmagier Arugal besiegt wird?",a="Die Tötung von Arugal enthauptet die zentrale Macht, die die Worgenrudel im südlichen Silberwald kontrolliert. Abenteurer der Horde überbringen Dalar Morgenweber im Grabmal auf Befehl von Fürstin Sylvanas Windläufer seinen abgetrennten Kopf. Während sein Untergang den unmittelbaren Willen bricht, der das Rudel von Shadowfang lenkt, bleiben die wilden Bestien und geisterhaften Überreste, die in der Burg und den umliegenden Wäldern verweilen, eine anhaltende Gefahr für Reisende.",al={"ausgang arugal toedten","arugal tot lore","was passiert nach arugals tod"}},{q="Warum hat Arugal die Worgen beschworen?",a="Während des Dritten Krieges erlitten die Streitkräfte von Dalaran verheerende Niederlagen gegen die Geißel. Gefallene Magier wurden vom Lichkönig fortwährend als untote Soldaten wiedererweckt. Auf der Suche nach einer Waffe, um das Blatt zu wenden, nutzte Arugal die arkanen Forschungen des Magiers Ur, um extradimensionale Worgen zu beschwören, in dem Glauben, ihre Grausamkeit könnte die Geißel aufhalten.",al={"warum worgen beschworen wurden","arugal motiv","dalaran worgen beschwoerung"}},{q="Wer war Baron Silberlein?",a="Baron Silberlein war der menschliche Adlige, der vor dem Dritten Krieg über die Burg herrschte und das benachbarte Dörfchen Lohenscheit beaufsichtigte. Als Arugals beschworene Bestien außer Kontrolle gerieten, stürmten sie die Festung und metzelten den Baron, sein Gefolge und seine Wachen nieder. Silberleins rachsüchtiger Geist spukt noch immer durch die großen Speisesäle, verflucht dazu, an der Seite der Monster zu wandeln, die ihn erschlugen.",al={"baron silberlein lore","urspruenglicher lord von shadowfang"}},{q="Warum sind die Dorfbewohner von Lohenscheit tagsüber friedlich?",a="Arugal belegte die Bewohner des nahe gelegenen Lohenscheit mit seiner dunklen Magie. Bei Tag behalten sie ihre menschliche Gestalt, ihren Verstand und ihr friedliches Verhalten gegenüber Reisenden der Allianz. Bei Sonnenuntergang greift der Fluch und verwandelt die gesamte Bevölkerung in wilde Worgen, die dem verrückten Erzmagier in der Burg die Treue halten.",al={"lohenscheit menschen","lohenscheit fluch","warum lohenscheit zu worgen wird"}},{q="Wer ist Kommandant Grüntal?",a="Kommandant Grüntal war ein Paladin und der militärische Befehlshaber, der für die Verteidigung von Burg Silberlein zuständig war. Als die Worgen die Festung überrannten, kämpfte er bis in den Tod. Sein ruheloser Geist patrouilliert noch immer durch die oberen Korridore und hält selbst im Untod an seiner soldatischen Pflicht fest.",al={"gruental lore","geisterhafter paladin boss"}},{q="Was ist das Buch von Ur?",a="Das Buch von Ur ist ein Foliant, der die Forschungen von Ur enthält, einem Erzmagier von Dalaran, der extradimensionale Wesenheiten einschließlich der Worgen untersuchte. Arugal nutzte Urs Schriften, um seine verhängnisvolle Beschwörung durchzuführen. Die Königliche Apothekervereinigung in Unterstadt trachtet nach dem Buch, um das Wesen der Wolfskreaturen und ihre bizarre Magie zu verstehen.",al={"das buch von ur quest","ur lore"}}},fx={["4bfedcc6"]={q="Was ist Burg Shadowfang?",a="Burg Shadowfang ist eine heimgesuchte Burg, die auf den hohen Klippen des südlichen Silberwalds thront und auf Lohenscheit hinabblickt. Ursprünglich als Silberleins Burg bekannt, diente sie einst als Festung der Allianz, die die Grenzen nahe Gilneas bewachte. Heute steht sie korrumpiert und in dunkle Nebel gehüllt als Festung für Erzmagier Arugal und seine wilden Worgen-Nachkommen.",al={"was ist burg shadowfang","erzähle mir von shadowfang","lore burg shadowfang"}},["1d3b32c5"]={q="Wer hat Burg Shadowfang erbaut?",a="Die Festung war der Sitz von Baron Silberlein, einem Adligen, dessen Familie lange vor dem Dritten Krieg die Herrschaft über die umliegenden Ländereien und Lohenscheit innehatte. Unter seiner Herrschaft stand sie als stolze Bastion der Menschen, bewacht von Kommandant Grüntal und vereidigten Soldaten des Reiches.",al={"wer baute burg shadowfang","ursprung von shadowfang","wer schuf shadowfang"}},["7c8f83a0"]={q="War der Silberwald ein Gebiet von Lordaeron?",a="Ja. Der Silberwald bildete den rauen westlichen Rand des Königreichs Lordaeron und grenzte im Süden an Gilneas. Seine Anwesen und Siedlungen waren an die Allianz gebunden, bevor die Seuche das Königreich zerschlug.",al={"war dies lordaeron","geschichte von silberwald und lordaeron","gehörte der silberwald zu lordaeron"}},["91da6ffd"]={q="Warum ist der Silberwald heute so verlassen?",a="Zwischen der Invasion der Geißel, dem Schließen des großen Walls durch Gilneas und Arugals tobendem Worgenfluch wurde die lebende Bevölkerung abgeschlachtet, verflucht oder floh ins Ausland. Die wenigen, die geblieben sind, klammern sich verzweifelt an umkämpfte Weiler wie Lohenscheit.",al={"warum ist der silberwald leer","verlassener silberwald","warum ist der silberwald eine ruine"}},["2ee73ad9"]={q="Warum hat Arugal überhaupt Worgen in den Silberwald gebracht?",a="Als die untote Geißel nach Süden marschierte, starben die Zauberer von Dalaran in Scharen, nur um im Dienst des Lichkönigs wieder aufzuerstehen. Arugal glaubte, dass durch extra-dimensionale Beschwörungen herbeigerufene Verbündete die Untoten dort überwältigen könnten, wo konventionelle sterbliche Armeen gescheitert waren.",al={"warum worgen in den silberwald bringen","grund für arugals worgenbeschwörung","warum hier worgen beschwören"}},["671a79f5"]={q="Wen wollte Arugal aufhalten?",a="Er beschwor sie speziell, um die untoten Armeen der Geißel zu vernichten, die anschwollen, indem sie jeden Soldaten und Zauberer, der in der Schlacht fiel, abschlachteten und wiedererweckten.",al={"gegen wen kämpfte arugal","arugals feind","gegen wen beschwor arugal worgen"}},eeb57b84={q="Hat Arugals Plan gegen die Geißel funktioniert?",a="Taktisch ja – die Worgen zerfleischten die Untoten mühelos. Aber strategisch war es eine Katastrophe. Die wilden Wolfsmenschen ließen sich nicht kontrollieren, wandten sich gegen menschliche Soldaten und Zauberer gleichermaßen und verbreiteten einen tödlichen Fluch in der gesamten Region.",al={"besiegten worgen die geißel","funktionierte die beschwörung","worgenerfolg gegen geißel"}},["2bfe7e75"]={q="Sind die Worgen in der Burg dieselben, die Lohenscheit überrannt haben?",a="Ja. Arugals Rudel, einschließlich der Rudel von Shadowfang und Moonrage, haben denselben verfluchten Ursprung. Die Bestien, die durch die Hallen der Burg streifen, sind Arugals eigene Brut und eng mit dem Fluch verbunden, der die Dorfbewohner unterhalb plagt.",al={"stammen shadowfang worgen aus lohenscheit","lohenscheit worgen shadowfang","dasselbe worgenrudel"}},b78b86f3={q="Was ist mit den Dorfbewohnern von Lohenscheit passiert?",a="Die Dorfbewohner überlebten den Dritten Krieg nur, um von Arugals dunkler Magie gefangen genommen zu werden. Obwohl sie bei Tageslicht wie normale Menschen erscheinen, verwandelt der Sonnenuntergang sie in wilde, blutrünstige Worgen, die dem wahnsinnigen Erzmagier treu ergeben sind.",al={"was passierte mit den leuten aus lohenscheit","schicksal von lohenscheit","stadtbewohner von lohenscheit"}},["39fbc1b5"]={q="Sind die Dorfbewohner von Lohenscheit auch verflucht?",a="Ja. Sie sind Opfer des lykanthropischen Worgenfluchs. Bei Tag bewahren sie ihren Verstand und handeln friedlich mit Wanderern der Allianz; bei Nacht raubt ihnen der Fluch ihre Menschlichkeit und macht sie zu reißenden Bestien.",al={"ist lohenscheit verflucht","fluch von lohenscheit","sind dorfbewohner infiziert"}},d6e89a88={q="Wer sind die Geister in Burg Shadowfang?",a="Es sind die ruhelosen Geister von Baron Silberlein, Kommandant Grüntal und der ehemaligen Dienerschaft der Burg. Sie wurden während des überraschenden Worgenangriffs erschlagen und ihre Seelen sind durch Qual und Gram an die zerstörten Steine gebunden.",al={"geister in shadowfang","wer sind die geister in burg shadowfang","gespenster in shadowfang"}},["0a399272"]={q="Sind die Geister die alten Diener der Burg?",a="Ja. Von geisterhaften Köchen und schattenhaften Begleitern bis hin zu ehemaligen Wachen sind die spektralen Verteidiger, die durch die Hallen wandern, die abgeschlachteten Bediensteten, die Baron Silberlein einst zu Lebzeiten dienten.",al={"sind geister ehemalige diener","geister der burghofdiener","silberleins diener"}},["3f532512"]={q="Warum können die Geister nicht ruhen?",a="Das pure Entsetzen ihres Massakers in Verbindung mit der schweren Schattenmagie, die die Burg durchdringt, verhindert ihre Erlösung. In ihrer ewigen Qual schlagen sie mit unheiliger Wut gegen jeden lebenden Eindringling, der ihre Gräber stört.",al={"warum sind geister ruhelos","warum spuken geister in shadowfang","ruhelose geister shadowfang"}},["59c03d52"]={q="Arbeitet Arugal für die Geißel?",a="Nein. Arugal verachtet die Geißel; er beschwor die Worgen gerade deshalb, um sie zu vernichten. Obwohl er wahnsinnig geworden ist, gilt seine Loyalität seinen 'Kindern' und nicht dem Lichkönig.",al={"ist arugal geißel","arbeitet arugal für die geißel","dient arugal der geißel"}},["99eb22e3"]={q="Kontrolliert der Lichkönig Arugal?",a="Nein. Arugals Wahnsinn ist völlig selbstverschuldet und entspringt Schuldgefühlen und Magie, nicht dem telepathischen Griff des Frostthrons. Er agiert unabhängig als Herr seines eigenen dunklen Reiches.",al={"kontrolliert der lichkönig arugal","lichkönig arugal","arugal gedankenkontrolle"}},["501c4a9b"]={q="Endet der Fluch, nachdem Arugal tot ist?",a="Nein. Arugals Tod enthauptet zwar die Führung von Burg Shadowfang, aber der Worgenfluch hat bereits das Blut der Sterblichen im gesamten Wald infiziert. Das Leiden besteht noch lange fort, nachdem der Erzmagier gefallen ist.",al={"endet der worgenfluch","verschwindet der worgenfluch","ist lohenscheit geheilt"}},["6cb01af1"]={q="Werden die Verlassenen Burg Shadowfang einnehmen?",a="Momentan begnügen sich die Verlassenen damit, die Bedrohung für ihre südliche Grenze zu beseitigen und das Buch von Ur wiederzuerlangen. Die Ruine bleibt eine düstere, heimgesuchte Hülle, die über die Wälder blickt, statt ein befestigter Außenposten zu werden.",al={"werden verlassene shadowfang einnehmen","erobern verlassene shadowfang","wer kontrolliert shadowfang danach"}},["3f22b397"]={q="Wie bin ich in Burg Shadowfang gelandet?",a="Ihr seid der Spur des Schreckens durch den Silberwald bis zu den Klippen oberhalb von Lohenscheit gefolgt. Wenn Ihr der Horde dient, wurdet Ihr wahrscheinlich vom Grabmal oder der Unterstadt nach Süden geschickt, um die Worgenplage zu untersuchen, die die Region erstickt. Wenn Ihr für die Allianz kämpft, haben Euch Gerüchte über die verfluchten Wälder, verlorene heilige Relikte oder den gefallenen Kirin Tor tief in das feindliche Gebiet der Verlassenen geführt. Ihr seid die windigen Klippen hinter den Toren von Lohenscheit hinaufgestiegen, seid an reißenden Wolfsbestien vorbeigedrungen und durch das uralte Tor der Burg gebrochen, um das Versteck des wahnsinnigen Erzmagiers zu betreten.",al={"wie kam ich hierher","wie erreiche ich burg shadowfang","wie fand ich diesen ort"}},["31a8c552"]={q="Was soll ich in Burg Shadowfang tun?",a="Euer oberstes Ziel ist es, Euch durch die heimgesuchten Hallen zu kämpfen und Erzmagier Arugal niederzustrecken, um seine verdrehte Herrschaft über den Silberwald zu beenden. Unterwegs müsst Ihr die Worgen niedermetzeln, die durch die Höfe streifen, und die ruhelosen Geister von Baron Silberlein und seiner erschlagenen Dienerschaft zur Ruhe betten. Wenn Ihr im Namen der Verlassenen handelt, habt Ihr die Aufgabe, das Buch von Ur zu bergen und das Schicksal der vermissten Todespirscher zu entdecken, die hineingeschickt wurden. Helden, Paladine und Hexenmeister der Allianz suchen nach verlorenen Artefakten der Macht, heiligen Waffen und Vergeltung für die dunkle Magie, die das Land vergiftet.",al={"was mache ich hier","warum bin ich hier","was ist mein ziel in burg shadowfang"}},efb02893={q="Warum ist Burg Shadowfang voller Worgen?",a="Als die heraufbeschworenen Worgen sich aus der Kontrolle der Kirin Tor befreiten, wüteten sie durch den Wald und belagerten die Burg. Sie metzelten Baron Silberlein und seinen gesamten Haushalt nieder. Vom Schuldgefühl über das, was er entfesselt hatte, in den Wahnsinn getrieben, adoptierte Erzmagier Arugal die Bestien als seine eigenen 'Kinder', beanspruchte die Ruine für sich und benannte sie in Burg Shadowfang um.",al={"warum sind hier worgen","burg shadowfang worgen grund","warum worgen drinnen"}},["7d419eb0"]={q="Warum interessiert sich die Horde für diese Burg?",a="Die Worgen, die aus der Burg streifen, sind eine unkontrollierte Plage, die den Griff der Verlassenen über den Silberwald bedroht. Von ihrer Basis im Grabmal aus erkannten die Anführer der Verlassenen, dass die umliegenden Lande niemals sicher sein werden, solange Arugal seine wolfsartigen Schrecken von den Burgzinnen aus befehligt.",al={"warum interessiert sich die horde für burg shadowfang","interesse der horde an burg shadowfang","warum nach burg shadowfang"}},d6cbfc07={q="Wer hat Euch hierher geschickt?",a="Kommandeure der Verlassenen im Grabmal ordneten den Angriff an, um Arugal zu eliminieren und das Schicksal ihrer vermissten Späher aufzudecken. Währenddessen entsandte die Königliche Apothekervereinigung in der Unterstadt Agenten, um Urs magische Forschungen aus der Library des Erzmagiers zu bergen.",al={"wer schickte mich nach burg shadowfang","questgeber für burg shadowfang","wer will arugal tot sehen"}},a794fece={q="Ist dies jetzt Land der Verlassenen?",a="Die Verlassenen beanspruchen den nördlichen Silberwald, doch ihr Griff nach dem Süden ist heiß umkämpft. Burg Shadowfang bleibt fest unter Arugals Herrschaft, während verbliebene Geißel, wilde Bestien und überlebende menschliche Siedlungen der Dunklen Fürstin die Herrschaft über die Region streitig machen.",al={"ist silberwald land der verlassenen","gehört dies sylvanas","gebiet der verlassenen burg shadowfang"}},b918d1de={q="Wer hat in Burg Shadowfang das Sagen?",a="Die Burg untersteht vollständig Erzmagier Arugal. Wahnsinnig geworden durch den Dritten Krieg, herrscht er über die oberen Türme, flankiert von seinen monströsen Worgen und seinem gewaltigen Schoßworg, Fenrus, und befehligt die Burg durch dunkle Hexerei.",al={"wer herrscht in burg shadowfang","wer hat drinnen das sagen","meister von burg shadowfang"}},ecad974c={q="Ist Arugal der Boss der Burg?",a="Ja. Arugal ist der Meister von Burg Shadowfang. Er orchestriert den Worgenbefall im gesamten Silberwald und thront an der Spitze des Burgturms als dessen höchste Autorität.",al={"ist arugal der boss","endboss burg shadowfang","meister arugal"}},["3b086809"]={q="Hatte jemand vor ihm das Sagen?",a="Baron Silberlein herrschte über die Burg, als sie noch ein Stützpunkt der Allianz war. Er und seine Familie regierten die Burg, bis Arugals Worgen während des Dritten Krieges die Mauern durchbrachen und jeden darin niedermetzelten.",al={"wer herrschte vor arugal","früherer meister von burg shadowfang","früherer herr der burg"}},["7f02160f"]={q="Woher kommen die Worgen?",a="Es handelt sich um gefräßige, extra-dimensionale Wesen, die aus einer anderen Ebene gerissen wurden. Verzweifelt versucht, die Geißel während des Dritten Krieges aufzuhalten, wandte Arugal sich der verbotenen Forschung des Magiers Ur aus Dalaran zu und beschwor diese jenseitigen Bestien nach Azeroth.",al={"woher kamen die worgen","ursprung der worgen","quelle der worgen"}},["4fa8e666"]={q="Hat Arugal die Worgen alleine beschworen?",a="Arugal führte die Beschwörung gegen den ausdrücklichen Rat seiner Gefährten in Dalarans Kirin Tor durch. Sich stark auf die Schriften im Buch von Ur verlassend, zwang er die Entitäten über die Ebenengrenzen hinweg.",al={"handelte arugal allein","wer half beim beschwören der worgen","beschwörung arugal"}},a6a018be={q="Können die Worgen kontrolliert werden?",a="Kaum, und nur durch dunkle Magie. Obwohl beschworen, um als Verbündete gegen die Untoten zu dienen, wandten sie sich sofort gegen ihre Beschwörer. Arugal schafft es nur, einige von ihnen zu lenken, weil sein gebrochener Verstand sie als Familie betrachtet und er Verzauberungen nutzt, um zerbrechlichen Gehorsam zu erzwingen.",al={"können worgen kontrolliert werden","kontrolle der worgen","sind worgen zahm"}},["24ed31c3"]={q="Was ist mit den The Deathstalkers Adamant und Vincent passiert?",a="Die The Deathstalkers Adamant und Vincent schlichen auf Befehl aus dem Grabmal in Burg Shadowfang, um Arugals Stärke auszukundschaften. Sie wurden von den Verteidigern der Burg gefangen genommen; Vincent wurde eingekerkert und im Innenhof hingerichtet, während Adamant in den Kerkern gefangen auf Rettung wartet.",al={"adamant und vincent","was ist mit den the deathstalkers passiert","späher der verlassenen burg shadowfang"}},cc7bdeae={q="Warum wurden die The Deathstalkers in die Burg Shadowfang geschickt?",a="Das Kommando der Verlassenen benötigte präzise Informationen über den tierischen Befall, der ihre südliche Front bedrohte. Adamant und Vincent erhielten den Auftrag, die Burg zu infiltrieren, Arugals wahre Truppenstärke zu bestimmen und den Weg für einen entscheidenden Schlag zu ebnen.",al={"warum the deathstalkers schicken","auskundschaften von burg shadowfang","mission der the deathstalkers"}},["4cfa60a4"]={q="Leben die The Deathstalkers noch?",a="Vincent ist tot, er wurde nach seiner Gefangennahme erschlagen. Adamant jedoch bleibt tief in den unteren Haltezellen der Burg eingekerkert, lebendig genug, um jedem Horde-Abenteurer zu helfen, der zu ihm durchdringt.",al={"leben vincent und adamant noch","überlebten die the deathstalkers","schicksal der the deathstalkers"}},c6ee2849={q="Was sind The Deathstalkers?",a="Die The Deathstalkers sind die elitären verdeckten Assassinen und Schurken der Verlassenen. Spezialisiert auf Verstohlenheit, Spionage und plötzlichen Tod, agieren sie als die stillen Dolche der Unterstadt an den Grenzen von Lordaeron.",al={"was ist ein the deathstalker","wer sind die the deathstalkers","the deathstalkers der verlassenen"}},["40c5e48b"]={q="Wem unterstehen die The Deathstalkers?",a="Sie unterstehen einer strikten Befehlskette, die von Offizieren und Kommandeuren der Verlassenen geleitet wird, welche in den Gebieten stationiert sind, und dienen letztlich dem Willen des herrschenden Rats der Unterstadt.",al={"führung der the deathstalkers","wer befehligt die the deathstalkers","wer führt die the deathstalkers"}},["63a10ab0"]={q="Arbeiten die The Deathstalkers direkt für Sylvanas?",a="Ja. Jeder The Deathstalker ist der Banshee-Königin, Fürstin Sylvanas Windläufer, verschworen. Sie bilden ihr persönliches Geheimdienstnetzwerk und spüren Bedrohungen für ihre untoten Anhänger mit freiem Willen in ganz Lordaeron auf.",al={"dienen the deathstalkers sylvanas","sylvanas the deathstalkers","the deathstalkers banshee-königin"}},f68cd02f={q="Warum schickt mich jeder in die Burg Shadowfang?",a="Weil die anfängliche Aufklärung der Verlassenen mit der Gefangennahme ihrer elitären The Deathstalkers völlig zusammengebrochen ist. Arugals Versteck ist zu tückisch für normale Infanterie, es erfordert bewährte Abenteurer, die sich sowohl durch Bestien als auch durch rachsüchtige Geister kämpfen können.",al={"warum schickt man mich nach burg shadowfang","warum mache ich das","warum held in burg shadowfang"}},ebbfbfb0={q="Bin ich der Einzige, der das tun kann?",a="Die Ressourcen der Verlassenen im Silberwald sind extrem knapp, da sie gegen Faulhufgnolle, Geißel-Versprengte und Patrouillen aus Dalaran kämpfen müssen. Da ihre eigenen Vorauskommandos kompromittiert sind, sind Ihr und Eure Verbündeten die einzige Streitmacht, die in der Lage ist, die Burg zu stürmen.",al={"bin ich der einzige","niemand sonst zur säuberung von burg shadowfang","einzige wahl"}},["0f7e4add"]={q="Haben andere vor mir versucht, die Burg zu stürmen?",a="Ja. Neben den gescheiterten The Deathstalker-Spähern betraten Kirin Tor-Ermittler wie Zauberer Ashcrombe die Burg, um Arugal zu beurteilen, nur um gefangen genommen oder in ihren verfluchten Hallen eingesperrt zu werden.",al={"haben andere burg shadowfang versucht","frühere versuche burg shadowfang","wer hat es vorher versucht"}},["13386e7c"]={q="Was ist mit dem Silberwald passiert?",a="Der Silberwald war einst ein grünes Reich mit hoch aufragenden, silbern borkigen Kiefern, das von der Allianz bewacht wurde. Als die Geißel während des Dritten Krieges über Lordaeron hinwegfegte, ließ die Plage die Wälder verwelken, Ernten wurden verbrannt und die Bevölkerung massakriert oder hinter den Greymane-Wall getrieben.",al={"geschichte silberwald","was geschah mit silberwald","warum ist der silberwald so"}}},fp="15,249,31.608.0,17.575.0,19.531.1,46.300.1,33.314.0,26.353.0,59.258.0,28.263.0,23.300.0"}
P.entries["zone:shendralas"] = {n="Shen'dralas",s="Shen'dralas ist eine zerklüftete, umkämpfte Wildnis zwischen Feralas, Mulgore und dem südöstlichen Desolace. Geprägt von uralten nachtelfischen Überresten und unruhigen Grenzen dient es als brisanter Knotenpunkt, an dem vordringende Zentauren, vertriebene Ausgestoßene und aggressive Stacheleber aufeinandertreffen.",h="Shen'dralas ist eine zerklüftete, umkämpfte Wildnis zwischen Feralas, Mulgore und dem südöstlichen Desolace.",kw={"rückzugsort der borstennacken","desolace","evenshade overlook","feralas","lake dumont","front der magram","mulgore","zuflucht der ausgestoßenen","shendralas","tal der knochen"},ang={["faction:Alliance"]="Eine abgelegene, umkämpfte Wildnis, die alternative Routen zwischen Feralas und dem zentralen Kalimdor bietet und voller Gefahren steckt, die stete Wachsamkeit erfordern.",["faction:Horde"]="Direkt vor den südlichen Ausläufern von Mulgore gelegen, ist die Eindämmung der Magram und Stacheleber an diesem Ort unerlässlich zum Schutz der Grenzen der Horde.",["race:NightElf"]="Der Name beschwört das uralte Wissen der Hochgeborenen von Eldre'Thalas herauf und weckt die Aufmerksamkeit der Schildwachen, die unvorsichtige Arkanmagie im südlichen Kalimdor mit Misstrauen betrachten.",["race:Tauren"]="Da die Region an Mulgore und Desolace grenzt, stellt die Aggression von Stachelebern und Zentauren entlang dieser Kämme eine direkte Bedrohung für die nahe gelegenen angestammten Jagdgründe dar."},sec={{t="Ein Grenzland in Aufruhr",b="Versteckt in den Höhen südöstlich von Desolace und umgeben von Mulgore und Feralas, ist Shen'dralas ein raues Grenzland weit abseits der großen Hauptstädte der Fraktionen. Seine felsigen Pässe und verborgenen Enklaven beherbergen verzweifelte Gruppen, die am Rande des wilden Kalimdor um ihre Existenz kämpfen. Von abgelegenen Aussichtspunkten wie dem Evenshade Overlook bis hin zu gesetzlosen Zufluchtsorten wie der Zuflucht der Ausgestoßenen wird die Zone von jenen geprägt, die ungesehen beobachten oder vergessen bleiben wollen."},{t="Zentauren, Stacheleber und uralte Ruinen",b="Das Land trägt die deutlichen Spuren des Erbes der Hochgeborenen, das ihm seinen Namen gab, doch es ist keineswegs friedlich. Zentaurenkonflikte schwappen über die Front der Magram hinweg und halten alte Blutfehden entlang der Grenzen am Leben. Unterdessen halten vordringende Stacheleber befestigte Schanzen wie den Rückzugsort der Borstennacken, wodurch jede schattige Schlucht zu einem umkämpften Gebiet für jeden durchreisenden Wanderer wird."},{t="Das Tal der Knochen",b="Nach Nordwesten in Richtung Desolace führt das Tal der Knochen, ein finsterer Korridor, der als wichtigste Überlandroute nach Shen'dralas dient. Von Sonne und Wind gebleicht, steht dieser Durchgang als Mahnmal für die gewaltsamen Kämpfe, die diese Klippen immer wieder erschüttern."}},faq={{q="Wo befindet sich Shen'dralas?",a="Shen'dralas liegt südöstlich von Desolace, eingebettet zwischen den Grenzen von Feralas und Mulgore. Reisende, die zu Fuß unterwegs sind, betreten das Gebiet typischerweise von Desolace aus durch das Tal der Knochen.",al={"wo liegt shendralas","shendralas lage","wie kommt man nach shendralas"}},{q="Wird Shen'dralas von der Allianz oder der Horde kontrolliert?",a="Keine der beiden Fraktionen hält hier die Herrschaft inne. Shen'dralas ist eine umkämpfte Grenzzone, die von umherziehenden Zentauren, feindseligen Stachelebern, Ausgestoßenen und isolierten Lagern bevölkert wird.",al={"gehört shendralas zur horde","gehört shendralas zur allianz","wem gehört shendralas"}},{q="Welche größeren Siedlungen oder Orientierungspunkte gibt es hier?",a="Zu den markanten Orientierungspunkten zählen das Tal der Knochen, der Rückzugsort der Borstennacken, der Evenshade Overlook, die Front der Magram, die Zuflucht der Ausgestoßenen sowie die zentrale Weite von Shen'dralas selbst.",al={"shendralas teilgebiete","orientierungspunkte in shendralas","sehenswürdigkeiten shendralas"}},{q="Warum gibt es hier Zentauren?",a="Die Gebietskriege der Zentauren reichen von den Ebenen von Desolace direkt entlang der Front der Magram in das Gebiet hinein, wo der Clan mit örtlichen Verteidigern und rivalisierenden Fraktionen aneinandergerät.",al={"zentauren in shendralas","front der magram","warum sind magram hier"}},{q="Was ist der Rückzugsort der Borstennacken?",a="Der Rückzugsort der Borstennacken ist ein befestigter Außenposten der Borstennackenstacheleber, die an den Rändern des Gebiets festen Fuß gefasst haben.",al={"rückzugsort der borstennacken","stacheleber in shendralas"}},{q="Welche Verbindung besteht zwischen diesem Gebiet und dem Lake Dumont?",a="Geografisch erstreckt sich die Wildnis von Shen'dralas über das bergige Terrain, in dem auf alten Vermessungskarten der abgelegene Lake Dumont verzeichnet ist.",al={"lake dumont","shendralas kartengeschichte"}}},fp="11,141,23.322.0,36.313.0,19.222.0,29.144.0,55.152.0,45.155.0,27.159.0,28.132.0,57.115.0"}
P.entries["zone:silithus"] = {n="Silithus",s="Silithus ist eine trostlose, vom Wind gepeitschte Wüste in der weit südwestlichen Ecke von Kalimdor. Unter ihrem trockenen Sand liegen riesige Kolonien der insektenartigen Silithiden und die uralten Ruinen von Ahn'Qiraj, die vor einem Jahrtausend hinter dem gewaltigen Skarabäuswall versiegelt wurden. Heute halten die Druiden vom Zirkel des Cenarius eine umkämpfte Wache gegen die kriechenden Schwärme und Weltuntergangskultisten.",h="Silithus ist eine trostlose, vom Wind gepeitschte Wüste in der weit südwestlichen Ecke von Kalimdor.",kw={"ahn'qiraj","burg cenarius","bau des ashischwarms","bau des regalschwarms","bau des zoraschwarms","die skarabäushöhe","der skarabäuswall","silithid","silithus","hammer des zwielichts"},ang={["class:Druid"]="Als Herzstück der Operationen vom Zirkel des Cenarius im südlichen Kalimdor fordert Silithus Druiden dazu auf, die Verderbnis des Landes einzudämmen und sich den unnatürlichen Brutstätten zu stellen, die das Gleichgewicht der Natur bedrohen.",["profession:Herbalism"]="Trotz des rauen Wüstengeländes gedeihen hier seltene botanische Wunder, darunter Bergsilberweisling, Traumblatt, Sonnengras und der außergewöhnlich geschätzte Schwarzer Lotus.",["profession:Mining"]="Die trockenen Felsen und Insektentunnel von Silithus beherbergen einige der reichhaltigsten Thoriumvorkommen der Welt, einschließlich seltener, schlammbedeckter Adern, die in den Silithidenbauten verborgen sind.",["race:NightElf"]="Silithus ist die düstere Ruhestätte, an der Eure Vorfahren während des Krieges der Sandstürme bluteten und Tausende opferten, um die Tore von Ahn'Qiraj zu versiegeln."},sec={{t="Die Wüstengrenze",b="Um Silithus zu erreichen, müsst Ihr durch den urzeitlichen Dschungel vom Krater von Un'Goro reisen und einen breiten, felsigen Pass in dessen nordwestlicher Ecke hinaufsteigen. Der Übergang ist drastisch: Üppiges urzeitliches Wachstum verschwindet in einer weiten Ausdehnung aus wandernden Dünen, gezackten Steinen und unnatürlichen, hoch aufragenden Bauten. Wasser ist so gut wie nicht vorhanden und die Winde tragen das Summen von Insektenflügeln und den flüsternden Sand mit sich. Der Zirkel des Cenarius unterhält die Burg Cenarius nahe der Mitte der Wüste, die als einziges Bollwerk der Zivilisation und Zufluchtsort für Reisende, Forscher und Krieger dient, die den feindseligen Einöden trotzen."},{t="Echos des Krieges der Sandstürme",b="Vor tausend Jahren diente diese trockene Weite als Schlachtfeld für den Krieg der Sandstürme. Eine alliierte Armee aus Nachtelfen und großen Drachenschwärmen kämpfte verzweifelt, um die Qiraji zurückzudrängen, ein heimtückisches insektenartiges Imperium, das aus der uralten Aqiri-Zivilisation hervorging. Als ein totaler Sieg unmöglich erschien, versiegelten die Verteidiger die Schwärme mithilfe vom Skarabäuswall und der verzauberten Skarabäushöhe in ihrer Festung. Während die monumentalen Tore hielten, erlaubten unterirdische Tunnel den bestienartigen Silithiden, sich nach außen zu graben und weitläufige Kolonien wie den Bau des Ashischwarms, den Bau des Zoraschwarms und den Bau des Regalschwarms im gesamten Sand zu errichten."},{t="Ein zusammenlaufender Sturm",b="Der apokalyptische Kult des Hammer des Zwielichts hat sich in mehreren befestigten Außenposten verschanzt, beschwört elementare Schrecken herauf und verehrt die dunkle Macht, die unter Ahn'Qiraj schlummert. Beobachter vom Zirkel des Cenarius überwachen die sich ausbreitenden Silithidenkolonien der Wüste und die uralte Bedrohung hinter dem Skarabäuswall."}},faq={{q="Wie komme ich zu Fuß nach Silithus?",a="Reist zur nordwestlichen Ecke vom Krater von Un'Goro. Nahe der gewundenen Flussbiegung, zwischen zwei markanten natürlichen Steinsäulen, führt ein ansteigender Schotterweg die bergige Kraterwand hinauf direkt in die Wüste Silithus.",al={"eingang silithus","wie komme ich nach silithus","weg nach silithus"}},{q="Was ist der Skarabäuswall?",a="Der Skarabäuswall ist eine massive, verzauberte Barriere im Süden von Silithus. Er wurde vor tausend Jahren von den Nachtelfen und den Drachenschwärmen während des Krieges der Sandstürme errichtet, um das bösartige Imperium der Qiraji in Ahn'Qiraj einzusperren.",al={"tor von ahn'qiraj","der skarabäuswall","die große mauer in silithus"}},{q="Wer leitet die Burg Cenarius?",a="Die Burg Cenarius ist ein Außenposten, der vom Zirkel des Cenarius errichtet wurde und geleitet wird. Seine Druiden und verbündeten Wächter beobachten die vordringenden Silithidenschwärme, untersuchen uralte Ruinen und heißen neutrale Reisende der Allianz wie der Horde willkommen.",al={"wer ist in der burg cenarius","fraktion burg cenarius","burg cenarius freundlich"}},{q="Was sind die riesigen Insektenhügel im gesamten Gebiet?",a="Es sind die bedeutenden unterirdischen Bauten der Silithiden: Bau des Ashischwarms, Bau des Zoraschwarms und Bau des Regalschwarms. Jeder Bau ist ein weitläufiges Netzwerk aus Tunneln, in denen verschiedene Kasten insektenartiger Kreaturen leben, die den Willen derer hinter Ahn'Qiraj erfüllen.",al={"silithidenbauten","insektenbauten silithus","bau des ashischwarms bau des zoraschwarms"}},{q="Was macht der Hammer des Zwielichts hier?",a="Der Kult des Hammer des Zwielichts unterhält mehrere befestigte Stützpunkte in Silithus, darunter das Basislager der Twilight und den Twilight-Posten. Sie führen üble Rituale durch, um Elementare zu beschwören und die uralten, bösartigen Wesen anzubeten, die hinter dem Skarabäuswall eingemauert sind.",al={"twilight-kultisten silithus","twilight-außenposten silithus","warum ist der hammer des zwielichts in silithus"}}},fp="8,245,19.408.0,28.509.0,18.272.0,33.207.0,24.219.0,23.205.0,49.212.0,41.243.0"}
P.entries["zone:silverpine"] = {n="Silberwald",s="Der Silberwald ist ein unheimliches, nebelverhangenes Waldland, das sich entlang der Westküste Lordaerons zwischen Tirisfal und dem versiegelten Greymane-Wall erstreckt. Von den verbliebenen Narben der Seuche der Geißel heimgesucht, dient er als umkämpfte Südgrenze der Verlassenen. Reisende begegnen hier wilden Worgen, die durch die Schatten streifen, verkrüppelten, verseuchten Gnollen und feindseligen Enklaven der Menschen.",h="Der Silberwald ist ein unheimliches, nebelverhangenes Waldland, das sich entlang der Westküste Lordaerons...",kw={"mühlenbern","arugal","insel fenris","der greymane-wall","lohenscheit","rot hide","das grabmal","shadowfang","silberwald"},ang={["class:Mage"]="Die Anwesenheit von Mühlenbern und der Fall von Erzmagier Arugal in den wölfischen Wahnsinn machen den Silberwald zu einem düsteren Mahnmal für Magie der Kirin Tor, die verheerend fehlgeschlagen ist.",["faction:Alliance"]="Allianz-Forscher werden einen zutiefst feindseligen Wald vorfinden, der nur durch eine fragile Garnison Dalarans in Mühlenbern und die tragischen, verfluchten Dorfbewohner von Lohenscheit aufgelockert wird.",["race:Undead"]="Der Silberwald stellt die unmittelbare Frontlinie der Expansion der Verlassenen südlich von Tirisfal dar, an der die Königliche Apothekervereinigung neue Gebräue erprobt und die Todeswache gegen verbliebene Agenten der Geißel kämpft."},sec={{t="Eine heimgesuchte Grenze",b="Einst als üppiges Wunder Lordaerons gefeiert, durch das adlige Reisende nach Capital City zogen, ist der Silberwald unter der Berührung des Dritten Krieges dahingewelkt. Geisterhafte Nebel weben sich zwischen sterbenden Kiefern mit silberner Rinde hindurch, und verfallene Gehöfte liegen verlassen in der Wildnis. Im Norden liegt Tirisfal, während das Ostufer an den Lordameresee grenzt. Im Süden ragt der imposante und verschlossene Greymane-Wall auf, der das isolationistische Königreich Gilneas vom umgebenden Chaos abschirmt. Die Verlassenen unterhalten ihren zentralen Außenposten beim Grabmal und bemühen sich, die Wälder vor Feinden von allen Seiten zu sichern."},{t="Rivalisierende Enklaven und die Geißel",b="Der Anspruch der Verlassenen auf den Silberwald ist von lebenden wie auch von untoten Fraktionen heiß umkämpft. Im Osten auf der Insel Fenris führt Thule Ravenclaw eine Streitmacht von Überresten der Geißel an, während er die seuchenverwirrten Rot Hide-Gnolles befehligt, die das nördliche Farmland plagen. Im Süden halten menschliche Magier aus Dalaran die befestigte Siedlung Mühlenbern, führen mystische Forschungen durch und stellen sich der Expansion der Verlassenen entgegen. Die Königliche Apothekervereinigung und Hochexekutor Hadrec beim Grabmal führen einen brutalen, vielschichtigen Feldzug, um diese Bedrohungen auszuschalten und tödliche neue Seuchen zu testen."},{t="Die Worgen und Shadowfang",b="Die berüchtigtste Gefahr des Silberwalds ist der Worgenfluch. Hoch über den Wäldern im Südwesten thront Burg Shadowfang, der ehemalige Sitz von Baron Silberlein, der nun vom wahnsinnigen Dalaran-Erzmagier Arugal beherrscht wird. In dem Bestreben, die Geißel während des Dritten Krieges abzuwehren, beschwor Arugal extradimensionale Wolfsbestien. Die Kreaturen wandten sich gegen ihre Beschwörer und verbreiteten einen lykanthropischen Fluch über die südlichen Wälder. In Lohenscheit gehen gewöhnlich wirkende menschliche Dorfbewohner bei Tageslicht ihren Pflichten nach, verwandeln sich jedoch unter dem Nachthimmel in wilde Worgen."}},faq={{q="Was ist der Greymane-Wall an der Südgrenze?",a="Der Greymane-Wall ist ein massives Steinbollwerk, das von König Genn Greymane errichtet wurde, um sein Königreich Gilneas vollständig vom Rest Lordaerons zu isolieren. Als die Geißel den Kontinent während des Dritten Krieges verwüstete, verriegelte Gilneas seine Tore, verweigerte Hilfe von außen und überließ die Länder nördlich des Walls – einschließlich des südlichen Silberwalds – ihrem eigenen Schicksal.",al={"warum gibt es eine riesige mauer","hintergrundgeschichte zum greymane-wall","tor nach gilneas"}},{q="Warum greifen die Dorfbewohner von Lohenscheit nachts an?",a="Die Bewohner von Lohenscheit leiden unter Erzmagier Arugals Worgenfluch. Am Tag behalten sie ihre menschliche Gestalt, gehen ihren täglichen Abläufen nach und bleiben der Allianz wohlgesinnt. Wenn der Mond aufgeht, gewinnt der Fluch die Oberhand und verwandelt die gesamte Bevölkerung in wilde, blutrünstige Worgen, die jeden in ihrer Nähe gewaltsam angreifen.",al={"geheimnis von lohenscheit","lohenscheit-worgen","warum menschen in lohenscheit nachts feindselig sind"}},{q="Wer ist Thule Ravenclaw?",a="Thule Ravenclaw ist ein mächtiger Nekromant im Dienste der Geißel. Von Burg Fenris auf der Insel Fenris im Lordameresee aus befehligt er Legionen von Untoten und übt Einfluss auf die verseuchten Rot Hide-Gnolles im gesamten östlichen Silberwald aus, wodurch er die östliche Flanke der Verlassenen direkt bedroht.",al={"wer beherrscht die insel fenris","hintergrundgeschichte zu thule ravenclaw","geißel auf der insel fenris"}},{q="Warum besetzt Dalaran Mühlenbern?",a="Mühlenbern wird von Zauberern aus Dalaran unter der Führung von Erzmagier Ataeric gehalten. Aus dem Dorf heraus überwachen diese menschlichen Magier die Truppenbewegungen der Verlassenen, untersuchen die magischen Leiden, die den Wald plagen, und versuchen, den nahegelegenen Worgenausbruch einzudämmen, der von Burg Shadowfang ausgeht.",al={"magier von mühlenbern","warum die allianz in mühlenbern ist","dalaran im silberwald"}},{q="Was ist das Grabmal?",a="Das Grabmal ist der wichtigste militärische Außenposten und Reiseknotenpunkt der Verlassenen im Silberwald. Unter dem Befehl von Hochexekutor Hadrec dient es als Operationsbasis für Patrouillen der Todeswache, Todespirscher-Kundschafter und die Königliche Apothekervereinigung bei ihrem Kampf um die Sicherung des Waldes.",al={"horde-stadt im silberwald","wo ist die flugroute","hintergrundgeschichte zum grabmal"}},{q="Können Allianz-Spieler im Silberwald questen?",a="Der Silberwald bietet keine Questknotenpunkte oder freundlich gesinnten Städte für die Allianz; alle örtlichen Quests sind ausschließlich für die Horde bestimmt. Abenteurer der Allianz betreten den Wald in der Regel nur, wenn sie von Süderstade aus anreisen, um Burg Shadowfang zu erkunden oder feindselige Streitkräfte der Verlassenen zu bekämpfen.",al={"ist der silberwald nur für die horde","allianz-quests im silberwald","kann die allianz in den silberwald"}}},fx={["21fc6836"]={q="Was ist der Silberwald?",a="Der Silberwald ist ein riesiges, uraltes Waldgebiet entlang der rauen Westküste von Lordaeron, direkt südlich von Tirisfal und im Osten begrenzt durch den Lordameresee. Einst ein üppiger und grüner Wald, geschützt von der Allianz, ist er heute in geisterhafte Nebel, krankhaft blasse Kiefern und eine unheimliche Stille gehüllt, die nur durch entferntes Heulen unterbrochen wird. Die Verlassenen halten den Norden vom Grabmal aus, aber ihr Anspruch wird ständig von den Überresten der Geißel, wilden Rotkamm-Gnollen, Zauberern aus Dalaran und den verfluchten Worgen von Burg Shadowfang bestritten.",al={"was ist der silberwald","erzähl mir vom silberwald","silberwald lore"}},["01503e92"]={q="Was ist im Silberwald passiert?",a="Der Silberwald ähnelte einst der unberührten Wildnis des Hinterlands, aber der Dritte Krieg ruinierte ihn. Als die Geißel des Lichkönigs nach Süden zog, brannten untote Armeen Gehöfte nieder, schlachteten die ländliche Bevölkerung ab und verseuchten das Land mit der Seuche des Untods. König Genn Greymane schloss Gilneas hinter seiner massiven Mauer ab und gab nördliche Gebiete wie Lohenscheit und Mühlenbern auf. Um die Geißel abzuwehren, entfesselte Erzmagier Arugal wilde Worgen, doch der Fluch breitete sich außer Kontrolle aus. Mit dem Zusammenbruch von Lordaeron wurden die verseuchten Wälder zu einem umkämpften Schlachtfeld.",al={"silberwald geschichte","was passierte im silberwald","untergang des silberwalds"}},b9edb2aa={q="Wer lebte hier vor den Verlassenen?",a="Vor dem Dritten Krieg wurde der Silberwald von menschlichen Bauern, Bergleuten und Soldaten aus Lordaeron und Gilneas bewohnt. Südliche Siedlungen wie Lohenscheit und Mühlenbern blieben draußen, als sich Gilneas hinter dem Greymane-Wall verschanzte. Die Insel Fenris beherbergte eine geschäftige Militärgarnison von Lordaeron in Burg Fenris. Die meisten dieser ehemaligen Bewohner kamen während der Invasion der Geißel ums Leben, flohen nach Süden hinter den versiegelten Wall oder erlagen dem Untod und dem Worgenfluch.",al={"wer lebte früher im silberwald","ehemalige bewohner des silberwalds","frühere einwohner des silberwalds"}},["5b2addb4"]={q="Warum sieht der Wald so tot aus?",a="Der Wald trägt die tiefen, bleibenden Narben des Dritten Krieges. Silberwald markiert das südlichste Ausmaß, in dem die Seuche der Untoten der Geißel die Flora sichtbar verdarb, die Lebenskraft aus dem Boden zog und die uralten Kiefern mit ihrer silbernen Rinde bleich, kränklich und ihre verdorbenen Nadeln abwerfend zurückließ. Da Lordaeron zerstört und Gilneas abgeriegelt wurde, blieben keine Pfleger zurück, um die verwüsteten Haine zu heilen oder die verbrannten Äcker zu bestellen, wodurch kalte Nebel und Fäulnis über die Wälder zogen.",al={"warum stirbt der silberwald","warum sieht der silberwald tot aus","verdorrte bäume silberwald"}},["67376895"]={q="Ist der Silberwald gefährlich?",a="Äußerst gefährlich. Wilde Raubtiere wie verseuchte Bären, riesige Spinnen und grausame Worgs schleichen unter den Bäumen. Die seuchenbefallenen Rotkammgnolle schlachten Reisende entlang der Straßen brutal ab, während menschliche Magier aus Dalaran Mühlenbern gegen das Eindringen der Horde befestigen. Im Süden terrorisieren die wilden Mondzorn-Worgen unter dem Einfluss von Erzmagier Arugal die Täler. Außerhalb des befestigten Zufluchtsorts Das Grabmal erfordert das Überleben ständige Wachsamkeit.",al={"wie gefährlich ist der silberwald","bedrohungen im silberwald","ist es hier sicher"}},["6dcc337b"]={q="Warum hat die Horde mich in den Silberwald geschickt?",a="Ihr wurdet von Tirisfal aus nach Süden geschickt, um die Grenze der Verlassenen zu verstärken. Die Unterstadt betrachtet den Silberwald als entscheidend für die Sicherung ihrer Südgrenze, doch ihr Halt ist zerbrechlich und überdehnt. Hochexekutor Hadrec und die Todeswache benötigen fähige Recken, um eindringende Nekromanten der Geißel zurückzuschlagen, feindselige Gnolle zu eliminieren, Dalarans verdeckte Manöver zu überwachen und die blutrünstigen Worgen einzudämmen, die zu überrennen drohen.",al={"warum bin ich im silberwald","horde ankunft silberwald","warum hierher geschickt"}},ab9ff98b={q="Ist dies noch Land der Verlassenen?",a="Die Verlassenen beanspruchen den Silberwald als souveränes Territorium der Unterstadt, doch ihre Kontrolle ist stark umstritten. Während sie im nördlichen Silberwald und im befestigten Zufluchtsort Das Grabmal festen Besitzstand wahren, haben sie keine unbestrittene Herrschaft über den gesamten Wald. Feindselige Rotkammgnolle beherrschen die östlichen Gewässer, Dalaran-Zauberer besetzen Mühlenbern und Arugals wilde Worgen dominieren die südwestlichen Regionen.",al={"gehört silberwald den verlassenen","wer kontrolliert den silberwald","territorium der verlassenen silberwald"}},["858ebaa5"]={q="Wer hat Das Grabmal erbaut?",a="Vor dem Dritten Krieg war Das Grabmal einfach ein großer, ruhiger menschlicher Friedhof mit einer Krypta am Straßenrand, die von den Bewohnern Lordaerons errichtet wurde, um ihre Toten entlang der westlichen Hauptstraße beizusetzen. Nach dem Fall von Lordaeron beschlagnahmten die überlebenden Verlassenen das Bestattungsgelände und bauten die Krypta zu einem befestigten Militäraußenposten, einer Karawanenstation und einem logistischen Hauptquartier für ihre südlichen Operationen um.",al={"wer hat das grabmal gebaut","ursprung das grabmal","geschichte das grabmal"}},f51f7d3d={q="Warum haben die Verlassenen ihre Basis im Grabmal?",a="Das Grabmal liegt verteidigungstechnisch günstig in den westlichen Hügeln und bietet den Verlassenen einen natürlichen Aussichtspunkt über die Küste und die Hauptstraße. Positioniert zwischen der Geißel im Osten, Dalaran im Südosten und wilden Worgen im Süden, dient es als einziger sicherer Außenposten, von dem aus Patrouillen der Todeswache und Forscher der Königlichen Apothekervereinigung die Verteidigung koordinieren und die Route nach Tirisfal schützen können.",al={"warum sind verlassene im das grabmal","basis der verlassenen das grabmal warum","bedeutung von das grabmal"}},["0581536d"]={q="Wer ist Hochexekutor Hadrec?",a="Hochexekutor Hadrec ist der militärische Kommandant der Operationen der Verlassenen im Silberwald und im Grabmal stationiert. Streng und pragmatisch leitet er die Todeswache und die Späher der Todespirscher bei der Befriedung der Wildnis an, deckt versteckte Bedrohungen auf und koordiniert Angriffe gegen feindselige Kräfte wie Thule Ravenclaw und die Rotkammgnolle.",al={"hadrec","wer ist hadrec","hochexekutor hadrec silberwald"}},ff53d58c={q="Wem ist Hochexekutor Hadrec unterstellt?",a="Hadrec ist direkt Fürstin Sylvanas Windläufer, der Banshekönigin der Verlassenen, und ihrem Oberkommando in der Unterstadt unterstellt. Als hochrangiger Offizier der Todeswache besteht sein Mandat darin, die Grenzen ihres neugeborenen Königreichs zu sichern und jede Macht zu eliminieren, die die Souveränität der Verlassenen gefährden könnte.",al={"wer ist hadrecs chef","hadrecs vorgesetzter","wem berichtet hadrec"}},["6c73f41e"]={q="Wer sind die Rotkammgnolle und warum sind sie hier?",a="Die Rotkammgnolle sind ein bösartiger Gnollklan, der den Silberwald bewohnt, hauptsächlich von Insel Fenris aus operiert und die Ufer des Lordameresee durchstreift. Im Gegensatz zu gewöhnlichen Gnollen sind sie von der Seuche der Untoten befallen, haben fleckiges graues Fell und trübe, gelbe Augen. Sie führen einen brutalen Guerillakrieg gegen die Verlassenen, plündern Schlachtfelder und greifen jeden, der sich ihren Lagern nähert, heftig an.",al={"rotkammgnolle","warum sind gnolle im silberwald","rotkammgnoll silberwald"}},ad054bc9={q="Wer kontrolliert die Rotkammgnolle?",a="Die Rotkammgnolle stehen unter dem Bann von Thule Ravenclaw, einem verräterischen Nekromanten, der sich der Geißel angeschlossen hat. Von seiner Festung auf Insel Fenris aus nutzt Thule dunkle Magie, um diese verdorbenen Bestien zu manipulieren und sie zu ausgehobenen Schlachtfeldern zu schicken, um frische Leichen für seine wachsenden Legionen von Untoten zu ernten.",al={"wer befehligt die rotkammgnolle","meister der rotkammgnolle","wer führt die rotkammgnolle"}},["97f89d60"]={q="Was sind Das Todesfeld?",a="Das Todesfeld ist eine verdorbene landwirtschaftliche Fläche im zentralen Silberwald, entlang der Straße, die zum Lordameresee führt. Einst ein friedliches Gehöft, wurde es während des Dritten Krieges zu einem Massenmordplatz, als die Geißel Lordaeron überrannte. Heute ist es ein offener Friedhof, übersät mit flachen Gräbern und aufgewühlter Erde.",al={"das todesfeld silberwald","das todesfeld","was ist das todesfeld"}},d487a8f2={q="Warum graben die Gnolle in Das Todesfeld?",a="Die Rotkammgnolle graben Das Todesfeld um, um die während des Dritten Krieges dort begrabenen menschlichen Leichen auszugraben. Auf Befehl von Thule Ravenclaw graben sie Körper und konservierte Überreste aus, um den Nekromanten mit Rohmaterial für den Bau von Konstrukten der Geißel und zur Verstärkung seiner untoten Armee auf Insel Fenris zu versorgen.",al={"warum graben die rotkammgnolle","gnolle das todesfeld warum","gnoll gräbt nach leichen"}},["3bca491d"]={q="Was befindet sich auf Insel Fenris?",a="Insel Fenris ist eine große Insel, die im Lordameresee vor der Ostküste des Silberwaldes liegt. Sie wird von Burg Fenris dominiert, einer ehemaligen Militärfestung von Lordaeron, die in einen dunklen Verfall geraten ist. Heute dient die Insel als schwer befestigte Zuflucht, die von Rotkammgnollen und den untoten Schergen von Thule Ravenclaw wimmelt.",al={"insel fenris","was ist auf insel fenris","burg fenris"}},bd044bca={q="Warum will Hadrec, dass Insel Fenris angegriffen wird?",a="Hadrec erkennt Insel Fenris als das schlagende Herz der Bedrohung durch die Geißel im östlichen Silberwald. Thule Ravenclaw in Burg Fenris verschanzt zu lassen, gibt der Geißel einen unangreifbaren Aufmarschpunkt, um untote Gnolle zu erheben, Versorgungskarawanen zu überfallen und den östlichen Zugang nach Tirisfal zu bedrohen. Der Angriff auf die Insel ist entscheidend, um Thules Macht zu brechen und den See zu sichern.",al={"warum insel fenris angreifen","hadrec insel fenris motiv","angriff auf insel fenris grund"}},["574e415e"]={q="Arbeiten die Dalaran-Zauberer in Mühlenbern mit der Allianz zusammen?",a="Ja. Während Dalaran sich stark auf den Wiederaufbau seiner zerstörten Stadt konzentriert, bleiben die in Mühlenbern stationierten Streitkräfte der Kirin Tor der Allianz gegenüber offen freundlich gesinnt und der Horde gegenüber erbittert feindselig. Dalaran schickt häufig Unterstützung an die überlebenden menschlichen Enklaven im Silberwald, widersetzt sich der Expansion der Verlassenen und arbeitet eng mit den südlichen Überresten zusammen.",al={"mühlenbern dalaran allianz","ist dalaran hier bei der allianz","kirin tor allianz silberwald"}},fd7851b2={q="Wer ist Arugal und was ist 'Arugals Torheit'?",a="Erzmagier Arugal war ein Zauberer aus Dalaran, der in seiner Verzweiflung, sich während des Dritten Krieges gegen die Geißel zu verteidigen, zu verbotener Magie griff und monströse Wolfbestien, bekannt als Worgen, beschwor. Die wilden Bestien wandten sich jedoch gegen die Zauberer der Kirin Tor und unschuldige Einheimische gleichermaßen und verbreiteten einen gefräßigen Lykanthropie-Fluch im südlichen Silberwald. Getrieben vom Wahnsinn durch Schuldgefühle und Entsetzen über das, was er entfesselt hatte, zog sich Arugal in Burg Shadowfang zurück und nahm die Worgen als seine 'Kinder' an.",al={"arugal","arugals torheit","wer war arugal","erzmagier arugal lore"}},f38b73fd={q="Woher kamen die Worgen?",a="Die Worgen sind außerweltliche Wolfbestien, die von Erzmagier Arugal durch Dimensionen gezogen wurden. Auf der Suche nach einer Waffe, um Dalaran während des Dritten Krieges gegen die Geißel zu stärken, beschwor Arugal diese Kreaturen in den Silberwald, wo sie sich schnell gegen ihre Beschwörer wandten und einen transformierenden Fluch verbreiteten.",al={"woher kamen die worgen","worgen ursprung silberwald","wie kamen worgen hierher"}},fc903f13={q="Ist Arugal noch am Leben?",a="Ja, Erzmagier Arugal ist sehr wohl am Leben. Umhüllt von Wahnsinn residiert er hoch oben in den Türmen von Burg Shadowfang und überblickt Lohenscheit. Von seiner Festung aus lenkt er sein Rudel Shadowfang-Worgen und bewacht seine verdrehte lupine Domäne vor jedem, der mutig genug ist, seine Tore zu durchbrechen.",al={"ist arugal am leben","wo ist arugal jetzt","arugal status"}},["5dc043c6"]={q="Was ist Lohenscheit?",a="Lohenscheit ist eine menschliche Siedlung im südwestlichen Silberwald, direkt unter den imposanten Klippen von Burg Shadowfang. Sie blieb draußen, als Gilneas vor dem Dritten Krieg den Greymane-Wall versiegelte. Die überlebenden Bewohner kämpfen darum, tagsüber einen Anschein von normalem Leben aufrechtzuerhalten, obwohl eine uralte Dunkelheit sie verzehrt, sobald die Sonne untergeht.",al={"lohenscheit lore","was ist lohenscheit","stadt lohenscheit"}},["20eec241"]={q="Wo führt das alles nach dem Silberwald hin?",a="Sobald Ihr den Silberwald stabilisiert habt, indem Ihr Thule Ravenclaw konfrontiert und Arugal in Burg Shadowfang beseitigt, führt Eure Reise normalerweise nach Osten über die Berge in das Vorgebirge des Hügellands, um die Verlassenen bei Tarrens Mühle zu unterstützen. Alternativ nehmen viele Reisende der Horde einen Zeppelin nach Kalimdor, um durch die weiten Ebenen im Brachland zu kampieren.",al={"wohin nach dem silberwald","nächstes gebiet nach silberwald","silberwald nächster schritt"}},da147569={q="Wie bin ich im Silberwald gelandet?",a="Ihr seid wahrscheinlich der Straße nach Süden aus Tirisfal gefolgt und habt den Gebirgspass südwestlich der Ruinen von Unterstadt durchquert. Charaktere der Verlassenen sichern ihre nördliche Heimat in Tirisfal und stoßen dann ganz natürlich nach Süden in den Silberwald vor, um das junge Reich zu erweitern. Alternativ kommen Reisende der Horde von anderen Kontinenten per Zeppelin vor der Unterstadt an, bevor sie die Küste hinunterwandern, während seltene Abenteurer aus dem Süden möglicherweise das Vorgebirge des Hügellands durchqueren, um diese verseuchten Wälder zu erreichen.",al={"wie bin ich hierher gekommen","wie erreiche ich den silberwald","weg zum silberwald"}},["97a9302a"]={q="Was soll ich im Silberwald tun?",a="Ihr seid hier, um den Verlassenen dabei zu helfen, ihre südliche Grenze gegen wachsende Gefahren zu sichern. Meldet Euch bei Hochexekutor Hadrec und den Todespirschern am Grabmal. Ihr müsst die krankheitsbefallenen Rotpelzgnolle aufhalten, die aus den Todesfeldern und von der Insel Fenris plündern, die Nekromanten der Geißel wie Thule Rabenklaue ausrotten und die Zauberer von Dalaran im Auge behalten, die sich in Mühlenbern verschanzt haben. Weiter südlich werdet Ihr außerdem die gefräßigen Wolfsbestien untersuchen, die Lohenscheit terrorisieren, sowie den Schatten, der von Burg Shadowfang ausgeht.",al={"was ist meine mission hier","warum wurde ich in den silberwald geschickt","was tun wir im silberwald"}}},fp="17,230,18.551.0,30.531.1,25.482.1,49.319.0,57.270.1,23.261.1,35.243.0,22.247.0,48.232.0"}
P.entries["zone:stockade"] = {n="Das Verlies",s="Das Verlies ist der Hochsicherheitsgefängniskomplex von Sturmwind, der unter dem Kanalviertel der Stadt nahe dem Magierviertel verborgen liegt. Die Einrichtung wurde gebaut, um die gefährlichsten Halsabschneider, politischen Aufrührer und gefangenen Staatsfeinde des Königreichs festzuhalten, doch kürzlich ist sie in gewaltsame Anarchie versunken. Aufseher Thelwasser wurde auf den Eingangsbereich zurückgedrängt und rekrutiert verzweifelt fähige Abenteurer, um den Aufstand von innen heraus niederzuschlagen, bevor er auf die Hauptstadt übergreift.",h="Das Verlies ist der Hochsicherheitsgefängniskomplex von Sturmwind, der unter dem Kanalviertel der Stadt nahe...",kw={"bazil thredd","bruegal eisenfaust","kanäle","defias","dextren ward","hamhock","kam tiefenzorn","aufstand","verlies","sturmwind","targorr","aufseher thelwasser"},ang={["class:Mage"]="Das direkt am Kanalrand des Magierviertels gelegene Gefängnis beherbergt körperliche Schläger, die anfällig für verlangsamende Zauber sind, während der Ogermagier Hamhock Kettenblitzschlag entfesseln kann.",["class:Rogue"]="Das Layout des Gefängnisses bietet ein komplexes Netz aus verschlossenen Eisenzellen und Verbindungen zu den Defias, was einzigartige Übungsmöglichkeiten für das Schlossknacken und Einblicke in Bazil Thredds Unterwelt-Syndikat bietet.",["faction:Alliance"]="Die Rebellion bedroht das Herz der Hauptstadt; die Niederschlagung des Aufstands bewahrt die innere Sicherheit von Sturmwind und ehrt gleichzeitig informelle Kopfgelder für das Rotkammgebirge, Dämmerwald und Eisenschmiede.",["race:Dwarf"]="Die Anwesenheit von Kam Tiefenzorn in den Zellen von Sturmwind ist eine Beleidigung für Dun Modr; das Königreich Eisenschmiede fordert seinen Kopf, um die zwergischen Leben zu rächen, die in den Sumpfland verloren gingen."},sec={{t="Ein Gefängnis unter Belagerung",b="Unter den friedlichen Kanälen von Sturmwind ist das Verlies zu einer Kriegszone geworden. Als die reguläre Armee ausrückte, um an entfernten Fronten zu kämpfen, war das unterbesetzte Gefängnis darauf angewiesen, unerfahrene Jugendliche – darunter vierzehnjährige Rekruten – einzusetzen, um die Ordnung aufrechtzuerhalten. Das hielt nicht lange an. Die Insassen starteten eine blutige, koordinierte Rebellion, zerrissen ihre Wolldecken zu Gang-Schals und metzelten die verbliebenen Wachen nieder. Aufseher Thelwasser konnte die Kontrolle über den Eingangsbereich nur mit Mühe halten, während er die Zellen, Flure und Haftblöcke in die rücksichtslosen Hände der Sträflinge überließ."},{t="Adlige und Meuchelmörder",b="Der Aufstand legte die hässliche Kehrseite des politischen Apparats von Sturmwind offen. Gebiete außerhalb der Stadt waren schon lange frustriert darüber, dass das Haus der Adligen Hinrichtungen aus eigenem politischem Kalkül aufschob. Wache Berton aus dem Rotkammgebirge wollte den gefangenen Orc Targorr der Schreckliche für seine Gräueltaten hinrichten lassen, musste aber zusehen, wie Adlige das Urteil aussetzten. Ratsherr Millstipe aus Dunkelhain musste mitansehen, wie der Grabräuber Dextren Ward trotz der Schändung von Gräbern für den Nekromanten Morbent Teufel vor dem Galgen bewahrt wurde. Sogar die Zwerge aus Dun Modr sandten Forderungen nach dem Tod des Dunkeleisensaboteurs Kam Tiefenzorn. Da das Verlies im Chaos versank, heuerten die örtlichen Behörden im Stillen Abenteurer an, um die Hinrichtungen zu vollstrecken, die die Gerichte der Hauptstadt nicht durchführen wollten."},{t="Der Drahtzieher und die Aufrührer",b="Hinter dem synchronisierten Zusammenbruch des Gefängnisses steckt Bazil Thredd, ein gerissener Verbrecher mit direkten Verbindungen zur Bruderschaft der Defias, der den Aufstand von seiner Zelle aus orchestrierte. Unter den Aufrührern befindet sich Bruegal Eisenfaust, ein gefährlicher zwergischer Schläger. Er ist einer von mehreren hartgesottenen Sträflingen, denen Abenteurer begegnen könnten, während sie Aufseher Thelwater dabei helfen, das Gefängnis zurückzuerobern."}},faq={{q="Warum befindet sich das Verlies in offenem Aufstand?",a="Die Bruderschaft der Defias organisierte einen gefängnisweiten Aufstand, während die Einrichtung stark unterbesetzt war. Da die Armee von Sturmwind an entfernten Fronten stationiert war, blieben jugendliche Freiwillige zurück, um hartgesottene Mörder zu bewachen. Die Sträflinge überfielen das Personal, ergriffen Waffen und drängten Aufseher Thelwasser aus den Zellenblöcken.",al={"warum aufstand","was geschah im verlies","ursache aufstand verlies"}},{q="Wer leitet den Aufstand im Inneren?",a="Der Drahtzieher hinter dem Aufstand ist Bazil Thredd, ein einflussreicher Sträfling der Defias, der im östlichen Zellentrakt inhaftiert ist. Zu den anderen gefährlichen Gefangenen zählen Bruegal Eisenfaust, Hamhock und Kam Tiefenzorn.",al={"boss im verlies","wer führt den aufstand an","wer leitet das verlies"}},{q="Warum sind Gefangene wie Targorr und Dextren Ward noch am Leben?",a="Beide wurden zum Tode verurteilt, aber korrupte Politiker innerhalb des Hauses der Adligen verhängten bürokratische Sperren für ihre Hinrichtungen, um sie als politisches Druckmittel zu nutzen. Diese Einmischung verärgerte die Verbündeten in Seenhain und Dunkelhain, was sie dazu veranlasste, Abenteurer auszusenden, um die Gefangenen während des Chaos auszuschalten.",al={"warum wurde targorr nicht hingerichtet","dextren ward gericht","korruption im haus der adligen"}},{q="Was bedeutet es für das Gefängnis, Bruegal Eisenfaust zu besiegen?",a="Bruegal Eisenfaust ist ein gefährlicher zwergischer Schläger unter den Aufrührern. Ihn zu besiegen beseitigt eine Bedrohung aus dem Gefängnis, während Abenteurer daran arbeiten, den Aufstand niederzuschlagen.",al={"hintergrund bruegal eisenfaust","bruegal töten","wer ist bruegal"}},{q="Warum befinden sich Dunkeleisenzwerge und Orcs in einem menschlichen Gefängnis?",a="Das Verlies dient als Hochsicherheitsgefängnis für wertvolle Kriegsgefangene. Targorr der Schreckliche führte Angriffe der Schwarzfelsorcs im Rotkammgebirge an, während Kam Tiefenzorn im Sumpfland Sabotageakte für den Dunkeleisenclan durchführte, bevor beide gefangen genommen und in die Hauptstadt überstellt wurden.",al={"warum sind hier dunkeleisenzwerge","hintergrund kam tiefenzorn","targorr im verlies"}},{q="Können Spieler der Horde das Verlies betreten?",a="Ja, aber es ist außerordentlich gefährlich. Der Dungeon-Eingang befindet sich direkt in Sturmwind nahe den Kanälen des Magierviertels. Infiltratoren der Horde müssen sich an den Stadtwachen und den Verteidigern der Hauptstadt vorbeischleichen, um das Portal zu erreichen.",al={"kann die horde das verlies betreten","horde im gefängnis von stormwind"}}},fx={["07af5e0b"]={q="Was ist das Verlies?",a="Das Verlies ist Sturmwinds Hochsicherheitsgefängnis, das unter dem Kanalviertel der Hauptstadt errichtet wurde. Es dient als Verwahrungsort für Kleinkriminelle, Halsabschneider, politische Aufständische und hochkarätige Feinde des Königreichs, die auf ihr Urteil warten.",al={"was ist das verlies","gefängnis das verlies","sturmwind gefängnis"}},["2fc364a6"]={q="Ist das Verlies nur für die Defias?",a="Nein. Während die Bruderschaft der Defias den Kern des Aufstands bildet, beherbergen die Zellen auch Kleinkriminelle, Grabräuber wie Dextren Ward, gefangene Schwarzfels-Orcs wie Targorr der Schreckliche und sogar Dunkeleisensabotöre wie Kam Tiefenzorn.",al={"ist das verlies nur für defias","wer ist im verlies","sind alle gefangenen defias"}},["0d433487"]={q="Warum sind hier so viele Defias eingesperrt?",a="Sturmwinds Behörden haben Agenten der Bruderschaft in ganz Westfall, dem Wald von Elwynn und in der Stadt selbst gefasst. Anstatt sie sofort hinzurichten, hat die Krone sie in das Verlies verfrachtet und damit ein gefährliches Netzwerk von Aufständischen direkt unter den Dielen der Stadt konzentriert.",al={"warum so viele defias hier","warum defias im verlies","gefangene der bruderschaft der defias"}},e96a18b2={q="Wer leitet dieses Gefängnis?",a="Aufseher Thelwasser leitet die Einrichtung. Als der Aufstand ausbrach, wurden seine Wachen überwältigt und aus den Zellentrakten vertrieben. Thelwasser konnte gerade noch den Eingangsbereich halten, was ihn dazu zwang, verzweifelt nach fähigen Abenteurern zu suchen, um die Korridore zurückzuerobern.",al={"wer leitet das verlies","aufseher des verlieses","aufseher thelwasser"}},["06cbacdc"]={q="Warum können Aufseher Thelwassers Wachen den Aufstand nicht bewältigen?",a="Die Gefängniswache war bereits extrem dünn besetzt, sodass man sogar Freiwillige im Alter von nur vierzehn Jahren einsetzte, um gefährliche Sträflinge zu bewachen. Als die Defias sich zusammenschlossen und angriffen, wurde das Personal völlig unvorbereitet erwischt, niedergemetzelt oder zur Flucht in die Eingangshalle gezwungen.",al={"warum können wachen aufstand nicht stoppen","wo sind die gefängniswachen","wachen im verlies"}},["7c158547"]={q="Warum schickt Sturmwind mich hinein und nicht die Armee?",a="Ein Großteil von Sturmwinds Militär ist an weit entfernten Fronten im Einsatz, und die korrupte Bürokratie im Haus der Adligen lähmt schnelles kommunales Handeln. Zudem sind Stadtbeamte verzweifelt bemüht, den Aufstand geheim zu halten, um eine offene Panik in den Straßen zu vermeiden.",al={"warum abenteurer schicken","warum nicht die armee ins verlies","wo ist die armee von sturmwind"}},a2006c52={q="Wissen die Wachen draußen, was im Inneren vor sich geht?",a="Die Wachen halten die Aufständischen an der Schwelle des Kerkers auf, und Aufseher Thelwasser sucht Hilfe, um die Ordnung im Inneren wiederherzustellen. Die Stadtbeamten halten den Vorfall geheim, um die normalen Bürger nicht zu beunruhigen.",al={"wissen wachen draußen bescheid","weiß sturmwind vom aufstand","geheimnis des verlieses"}},b1798127={q="Was ist der Unterschied zwischen den Gefangenen, Sträflingen und Aufständischen hier drin?",a="Die Insassen reichen von gewöhnlichen Gaunern und Taschendieben, die von den Straßen aufgelesen wurden, bis hin zu verurteilten Schwerverbrechern und kompromisslosen Defias-Aufständischen. Während gewöhnliche Sträflinge die Gelegenheit nutzten, zu randalieren und zu plündern, erhalten die Aufständischen aktiv Befehle von Bazil Thredd, um das Gefängnis zu übernehmen.",al={"sträflinge aufständische gefangene","gegnerarten im verlies","wer sind die insassen"}},["378bbf14"]={q="Wie kamen die Insassen an Waffen und wie haben sie sich organisiert?",a="Der Aufstand wurde akribisch vom Defias-Anführer Bazil Thredd geplant. Unter seiner Regie zerrissen die Gefangenen ihre Wolldecken zu roten Bandenschals, überfielen die unterbesetzten Wachen, stahlen deren Waffen und Schlüssel und befreiten methodisch die Zellen in jedem Flügel.",al={"wie kamen gefangene an waffen","wie haben sich defias organisiert","wer hat die gefangenen bewaffnet"}},["855deb71"]={q="Warum baut man ein Gefängnis direkt unter die Stadt?",a="Der Gefängniskomplex liegt unter den Kanälen von Sturmwind. Die ursprüngliche Platzierung wird nicht erklärt.",al={"warum gefängnis unter sturmwind","standort des verlieses warum","gefängnis unter den kanälen"}},caa2e4bf={q="Wie bin ich im Verlies gelandet?",a="Ihr seid durch die schweren Eisentüren von den nördlichen Kanälen in Sturmwind eingetreten. Unter den Straßen brach ein massiver Aufstand aus, und die verbliebenen Wachen von Aufseher Thelwasser wurden bis zur Schwelle zurückgedrängt, wodurch die Sträflinge die Kontrolle übernahmen. In der Verzweiflung, das Chaos vor den Bürgern oben geheim zu halten, heuerte der Aufseher fähige Abenteurer an, um direkt in die Zellentrakte zu marschieren und die Einrichtung mit Gewalt zurückzuerobern.",al={"wie bin ich hierher gekommen","warum bin ich hier","wie habe ich das verlies betreten"}},["45edc40e"]={q="Was soll ich im Verlies tun?",a="Eure Hauptmission ist es, den Aufstand niederzuschlagen und seinem Anführer, dem Drahtzieher der Defias Bazil Thredd, ein Ende zu setzen. Verbündete im ganzen Königreich haben diesen Moment des Chaos jedoch genutzt, um überfällige Schulden zu begleichen: Dunkelhain sucht Vergeltung für den Grabräuber Dextren Ward, Seenhain will den rücksichtslosen Orc Targorr der Schreckliche tot sehen, und Eisenschmiede fordert den Kopf des Saboteurs Kam Tiefenzorn.",al={"was ist meine mission hier","was tue ich hier","warum bin ich hier"}}},fp="12,345,20.476.0,20.680.1,30.277.1,38.302.0,35.174.0,60.285.0,60.151.0,61.253.0,37.213.0"}
P.entries["zone:stonetalon"] = {n="Steinkrallengebirge",s="Das Steinkrallengebirge ist eine zerklüftete, vom Wind gezeichnete Kette schroffer Gipfel, die an Eschental, das Brachland und Desolace grenzt. Von Nachtelfen und Tauren gleichermaßen als heilige Zuflucht verehrt, stehen die sakralen Höhen der Region in scharfem Kontrast zum Rauch und den Maschinen, die ihre tieferen Canyons ersticken. Heute ist das Gebirge von Abholzung, unberechenbarer elementarer Verwüstung und schwelenden Grenzfeindseligkeiten gezeichnet.",h="Das Steinkrallengebirge ist eine zerklüftete, vom Wind gezeichnete Kette schroffer Gipfel, die an Eschental...",kw={"das verbrannte tal","gerenzo pfeifzang","malaka'jin","steinkrallengebirge","der steinkrallengipfel","sonnenfels","talondeep pass","scherwindklippe"},ang={["class:Druid"]="Die Schändung der Scherwindklippe und die verbrannte Verderbnis des verbrannten Tals sind ein ernster Ruf für Druiden, die erzürnte Naturgeister beruhigen und heilige Nistplätze beschützen wollen.",["class:Shaman"]="Der Schrei der Berggeister unter dem Ansturm der Goblinbohrer ist bis nach Orgrimmar zu hören und ruft Schamanen dazu auf, wütende Felselementare zu bändigen und das Gleichgewicht der Gipfel wiederherzustellen.",["faction:Alliance"]="Hoch oben auf dem Steinkrallengipfel und in versteckten Lagern rund um die Scherwindklippe stationiert, verteidigt die Allianz uralte Grabhügel der Kaldorei vor den Maschinen der Goblins und vordringenden territorialen Rivalen.",["faction:Horde"]="Abenteurer der Horde verlassen sich auf den abgelegenen Zufluchtsort Sonnenfels und den südlichen Trollposten Malaka'jin, um die industrielle Verschmutzung der Venture Company einzudämmen und verräterische Gesetzlose der Grimtotem auszulöschen."},sec={{t="Die bösen Winde und die Gipfel",b="Steil aus dem Herzen Kalimdors aufragend, fängt die Kette des Steinkrallengebirges die von den westlichen Meeren herüberziehende Feuchtigkeit auf, was zu plötzlichen Wolkenbrüchen und tückischen, regennassen Sandsteinpfaden führt. Das dominierende Merkmal der tieferen Täler ist der unaufhörlich scheuernde Sturm, der als die Bösen Winde bekannt ist und Reisende mit Sandkörnern blenden oder Unachtsame direkt von steilen Klippen reißen kann. Weiter oben bedecken immergrüne Wälder die Grate rund um den Steinkrallengipfel, wo die Nachtelfen uralte Grabhügel und Haine pflegen und über die heiligen Nester der Wyvern und Hippogryphen wachen, die entlang des Mirkfallonsees nisten."},{t="Industrie und Übergriffe",b="Die friedliche Einsamkeit des Gebirges wurde durch die Ankunft der Venture Company gewaltsam gestört. Die Goblins haben in der Scherwindklippe weitläufige Holzfällerlager errichtet und tiefe Tagebaue gegraben – unterstützt von dem wahnsinnigen Lepragnom Gerenzo Pfeifzang. Sie haben jahrhundertealten Baumbestand gerodet, den Himmel mit Ofenrauch geschwärzt und industriellen Schlamm in die Gebirgsabflüsse geleitet. Ihre Gier hat rasche Vergeltung hervorgerufen: Schamanen aus Orgrimmar erhörten die gepeinigten Schreie der Berggeister, während nahe gelegene kleine Lager der Allianz gegen die Schänder kämpfen, um die Überreste des Hochlands zu schützen."},{t="Narben der Vergangenheit",b="Im Süden liegt das verbrannte Tal, einst eine blühende Wildnis, heute eine aschebedeckte Ödnis voller abtrünniger Feuerelementare, schwarzer Drachenbrut und Harpyien. Während die Gipfel der historische Ort waren, an dem Horde und Allianz während des Dritten Krieges unter der Führung des mysteriösen Orakels einen unsicheren Waffenstillstand schlossen, bröckeln die derzeitigen Beziehungen. Abtrünnige Grimtotem-Tauren operieren aus eroberten Lagern heraus, und Dunkelspeere in Malaka'jin stoßen mit Vorstößen der Allianz zusammen, die aus dem Brachland und Eschental vordringen."}},faq={{q="Wie gelange ich in das Steinkrallengebirge?",a="Die meisten Reisenden erreichen das Gebiet über den Talondeep Pass, einen Gebirgspfad, der vom südwestlichen Eschental in die Kette führt. Es gibt auch hochgelegene Pfade, die nach Süden nach Desolace führen, sowie Wege, die nach Osten direkt in die nördlichen Weiten des Brachlands hinabführen.",al={"steinkrallengebirge eingang","weg ins steinkrallengebirge","steinkrallengebirge straße"}},{q="Warum ist das verbrannte Tal verbrannt und zerstört?",a="Das verbrannte Tal war einst ein üppiger Zufluchtsort, doch eine kataklysmische Verwüstung verzehrte das Tal in Flammen. Es wurde zu einer schwelenden Ruine reduziert, in der aggressive Feuerelementare, abtrünnige Drachen und tödliche Harpyien ihr Unwesen treiben.",al={"das verbrannte tal feuer","was geschah im verbrannten tal","warum das verbrannte tal brennt"}},{q="Was tut die Venture Company in der Scherwindklippe?",a="Die Venture Company holzt rücksichtslos Bäume ab und bohrt auf der Suche nach Bodenschätzen tief in den Berghang. Ihre Aktivitäten haben den Felskesselsee mit Maschinenschmiere verschmutzt, die Täler kahlgeschlagen und die lokalen Geister sowie die einheimischen Bewohner erzürnt.",al={"venture company steinkrallengebirge","scherwindklippe goblins","warum fällen goblins bäume"}},{q="Wo befinden sich die wichtigsten Flugmeister?",a="Helden der Allianz nutzen den Flugmeister im hochgelegenen Heiligtum auf dem Steinkrallengipfel im Norden, während Abenteurer der Horde das zentrale Bergdorf Sonnenfels als Stützpunkt nutzen.",al={"steinkrallengebirge flugroute","flugpunkt steinkrallengebirge","steinkrallengebirge fp"}},{q="Was geschah am Steinkrallengipfel während des Dritten Krieges?",a="Geleitet von Visionen des Propheten Medivh stiegen Thrall und Jaina Prachtmeer auf der Suche nach dem Orakel in die Höhlen des Steinkrallengipfels hinab. Dort schmiedeten die beiden Anführer der Fraktionen das historische temporäre Bündnis, das sich am Hyjal gemeinsam gegen die Brennende Legion stellte.",al={"steinkrallengipfel geschichte","orakel steinkrallengebirge","dritter krieg steinkrallengebirge"}},{q="Wer sind die Grimtotem im Steinkrallengebirge?",a="Die Grimtotem sind ein skrupelloser, abtrünniger Taurenstamm, der jedem Einfluss von außen feindselig gegenübersteht. Im Steinkrallengebirge haben sie einen Gebirgsposten nahe der Grenze zum Brachland besetzt, von wo aus sie Reisende terrorisieren und Gefangene nehmen.",al={"posten der grimmtotem","grimtotem steinkrallengebirge"}}},fx={["4946a833"]={q="Was ist das Steinkrallengebirge?",a="Das Steinkrallengebirge ist eine raue, vom Wind geformte Gebirgskette im Zentrum von Kalimdor, gelegen westlich des Brachlands, südlich des Eschentals und nördlich von Desolace. Bekannt für extreme Winde, tiefe Schluchten und steile Sandsteingipfel, die während des Großen Bruchs entstanden, bildet die Region ein historisches Grenzland, in dem Nachtelfen und Tauren seit Generationen koexistieren. Die hohen, heiligen Gipfel sind immer noch üppig mit Nadelbäumen bewachsen, während die tiefer gelegenen Täler trocken, felsig und durch die Industrie schwer gezeichnet sind.",al={"gebiet steinkrallengebirge","was ist steinkrallengebirge","über das steinkrallengebirge"}},["4e995438"]={q="Ist das Steinkrallengebirge gefährlich?",a="Ja, Reisende sind sowohl natürlichen Gefahren als auch erbitterten Feinden ausgesetzt. Heftige Stürme und plötzlicher Regen können die hohen Sandsteinklippen so glatt machen, dass Menschen in den Tod stürzen. Jenseits des Wetters wimmelt es in den Bergen von aggressiven Blutwutharpien, räuberischen Wyvern, Spinnen, Kobolden und aufgebrachten Elementaren. Zudem machen die rücksichtslosen Maschinen und bewaffneten Vollstrecker der Venture Company umkämpfte Täler wie die Scherwindklippe außergewöhnlich gefährlich.",al={"gefahr im steinkrallengebirge","ist das steinkrallengebirge sicher","gefahren des steinkrallengebirges"}},["9d849e11"]={q="Wer lebt im Steinkrallengebirge?",a="Die Region beherbergt eher verstreute Fraktionen als eine einzelne herrschende Macht. Die Nachtelfen halten den Steinkrallengipfel und bewachen heilige Stätten auf den Höhen, während die Horde Siedlungen am Sonnenfels und das Trodorf Malaka'jin unterhält. Einheimische Blutwutharpien nisten in den Klippen, feindselige Grimtotemtauren besetzen nahegelegene Posten und die Venture Company der Goblins besetzt abgeholzte Landstriche um die Scherwindklippe.",al={"wer lebt im steinkrallengebirge","fraktionen im steinkrallengebirge","bewohner des steinkrallengebirges"}},a4f73e64={q="Warum betreibt die Venture Company Holzwirtschaft in der Scherwindklippe?",a="Die Venture Company ist ein rücksichtsloser Handelskonzern, der durch unbegrenzten Ressourcenabbau Profit sucht. In der Scherwindklippe roden sie mithilfe schwerer Maschinen wie dem Super Reaper 6000 alte Wälder und sprengen die Erde nach wertvollem Erz auf. Ihre Missachtung der Natur erfüllt die Luft mit Ruß und vergiftet lokale Gewässer mit Schlamm und Öl, was ihnen den wütenden Widerstand sowohl der örtlichen Druiden als auch der Horde einbringt.",al={"abholzung durch venture company","warum fällen goblins bäume","holzfällerei venture company steinkrallengebirge"}},["66935983"]={q="Wer leitet die Venture Company in der Scherwindklippe?",a="Die örtlichen Abholzungs- und Minenarbeiten in der Scherwindklippe werden von einem aussätzigen Gnom namens Gerenzo Wrenchwhistle geleitet. Gerenzo überwacht die Rodungen von einer Plattform hoch über dem Felskesselsee aus und setzt sein technisches Fachwissen ein, um die Zerstörung zu maximieren. Seine schurkischen Operationen haben sogar den Zorn rivalisierender Goblintüftler der Tüftlergewerkschaft auf sich gezogen, die versuchen, ihn auszuschalten.",al={"wer leitet die scherwindklippe","gerenzo wrenchwhistle","anführer der venture company im steinkrallengebirge"}},ff0da62d={q="Wer sind die Blutwutharpien?",a="Die Blutwutharpien sind ein bösartiger Stamm von Vogelmenschen, die im Steinkrallengebirge heimisch sind. Historisch gesehen war dieses Gebirge ihr angestammtes Kernland, bevor sie sich in das Brachland und darüber hinaus ausbreiteten. Sie verteidigen ihr Territorium aggressiv gegen Eindringlinge, fangen lokale Bestien und geraten gewaltsam mit sowohl Taurenpilgern als auch eindringenden Goblinmaschinen an Orten wie dem verbrannten Tal aneinander.",al={"blutwutharpien","harpien im steinkrallengebirge","wer sind die harpien hier"}},["66599fe7"]={q="Was ist der Sonnenfels?",a="Der Sonnenfels ist eine friedliche Siedlung der Horde, eingebettet in ein abgelegenes Bergtal südlich des Mirkfallonsees. Er dient als primäre Basis für Tauren und Orcs in der Region und beherbergt Schamanen und Druiden, die sich der Wiederherstellung des Landes von der Verschmutzung durch die Venture Company und der Bekämpfung der Bedrohungen widmen, die in die heiligen Berge eindringen.",al={"hintergrund zum sonnenfels","was ist der sonnenfels","tauren am sonnenfels"}},["5a5a6e9c"]={q="Warum haben sich die Tauren am Sonnenfels niedergelassen?",a="Seit Generationen verehren die Tauren dieses Tal als einen Ort mit einer tiefen Verbindung zur Geisterwelt. Alte Legenden besagen, dass der Sonnengott An'she den Gipfel küsste, auf dem sich die Zuflucht befindet. Die Tauren unternahmen hier lange Zeit heilige Pilgerreisen, um mit Geistern in Kontakt zu treten und große rituelle Freudenfeuer zu entzünden, um die schattigen Berge zu erhellen.",al={"warum siedelten tauren am sonnenfels","geschichte des sonnenfelses","an'she sonnenfels"}},["51d42c77"]={q="Was ist die Scherwindklippe?",a="Die Scherwindklippe war einst ein üppiger Urwald, wurde aber durch industrielle Ausbeutung verwüstet. Die Venture Company rodete das Tal zu einer kargen Ausdehnung aus Baumstümpfen, Erde und rauchenden Maschinen. Zwischen der Entwaldung durch die Venture Company, dem fauligen Abfluss im Felskesselsee und Kobolden, die die örtliche Mine befallen, steht sie als ruiniertes Denkmal ungezügelter Gier.",al={"über die scherwindklippe","gebiet scherwindklippe","hintergrund zur scherwindklippe"}},d850bc0a={q="Was befindet sich in der Scherwindmine?",a="Die Scherwindmine, die sich in den südöstlichen Klippen der Scherwindklippe befindet, ist von aggressiven Scherwindkobolden überrannt. Die Kobolde, die von den regulären Bergleuten vertrieben wurden oder von ihnen verlassen wurden, graben nun wütend nach Adern von Rauchigen Eisenerzbarren und greifen jeden heftig an, der versucht, in ihre unterirdischen Grabungen einzudringen.",al={"kobolde der scherwindmine","was gibt es in der scherwindmine","rauchiges eisenerz scherwindmine"}},d3863c46={q="Was ist der Krallenbau auf dem Steinkrallengipfel?",a="Der Krallenbau ist ein alter Nachtelfen-Barrow-Bau, der in die Höhen des Steinkrallengipfels gehauen wurde. Er wird von Cenariondruiden unterhalten, die mit den Geistern der Natur und dem Smaragdgrünen Traum kommunizieren. Tief im Inneren haben Druiden traditionell in heiliger Kontemplation geschlafen, bewacht von Dryaden, Hütern und den magischen Schutzzaubern des Gipfels.",al={"krallenbau","der bau am steinkrallengipfel","barrow-bau steinkrallengebirge"}},a547ffd6={q="Verbindet das Eschental das Steinkrallengebirge?",a="Ja. Der raue Steinkrallenpfad verbindet das südwestliche Eschental direkt mit dem nordöstlichen Steinkrallengebirge durch einen höhlenartigen Gebirgspass. Reisende und Abenteurer gelangen häufig zwischen den unberührten, umkämpften Wäldern des Eschentals und den kargen Höhen des Steinkrallengebirges, während sie Bedrohungen durch die Venture Company oder die anhaltenden Fraktionskonflikte verfolgen.",al={"wie verbindet das eschental das steinkrallengebirge","steinkrallenpfad eschental","eschental grenze steinkrallengebirge"}},a5c2784c={q="Wie bin ich im Steinkrallengebirge gelandet?",a="Die meisten Reisenden erreichen diese zerklüfteten Höhen über den Steinkrallenpfad, einen alten Gebirgstunnel, der in das südwestliche Eschental gehauen wurde. Andere Wanderer klettern die rauen Pfade hinauf, die westlich aus dem Brachland führen, und steigen die windgepeitschten Pässe hinauf in die felsigen Klippen. Ob von Nachtelfenkommandanten in Astranaar nach Süden geschickt oder westwärts über die verbrannte Grenze vom Wegekreuz aus entsandt, die hohen Schluchten und heulenden Ill Winds begrüßen jeden, der die beschwerliche Reise in das Gebirge unternimmt.",al={"wie bin ich hierher gekommen","wie komme ich ins steinkrallengebirge","ankunft im steinkrallengebirge"}},["4abc7ef6"]={q="Was soll ich im Steinkrallengebirge tun?",a="Ihr seid hier, um den wachsenden Bedrohungen entgegenzutreten, die diese heiligen Höhen entweihen. An der Scherwindklippe reißen die rücksichtslosen Goblins der Venture Company alte Wälder nieder und verschmutzen die Flüsse mit Maschinen, was den Zorn beider Fraktionen auf sich zieht. Unterdessen stiftet der Grimtotemstamm Unruhe entlang der östlichen Grenze, während bösartige Harpien und wütende Feuerelementare das versengte Becken des verbrannten Tals befallen. Ihr müsst Eure Verbündeten dabei unterstützen, diese Umweltverschmutzer und Monster zurückzudrängen, um das Land zu schützen.",al={"was soll ich hier tun","warum bin ich hier","was ist meine mission im steinkrallengebirge"}}},fp="20,167,27.462.0,22.461.0,17.474.0,41.202.0,42.194.0,52.224.0,42.161.0,54.229.0,36.181.0"}
P.entries["zone:stormwind"] = {n="Sturmwind",s="In Sturmwind ruht die Krone auf dem Haupt eines jungen Prinzen, während König Varian vermisst wird. Nach dem Ersten Krieg wiederaufgebaut, ist die Stadt nun das Herz der Großen Allianz, doch Schulden und politische Unruhen erschüttern ihre Viertel aus weißem Stein.",h="In Sturmwind ruht die Krone auf dem Haupt eines jungen Prinzen, während König Varian vermisst wird.",kw={"anduin","bolvar","kathedrale","tiefenbahn","prestor","steinmetze","sturmwind","vancleef","wrynn"},ang={["class:Paladin"]="Als Paladin findet Ihr die Kathedrale des Lichts, das wichtigste Heiligtum Eures Glaubens im Süden. Sie bildet Ritter der Silbernen Hand aus und sorgt für Gerechtigkeit.",["class:Rogue"]="Als Schurke findet Ihr den Hauptsitz von SI:7 unter den steinernen Straßen der Altstadt. Das Netzwerk leitet die wichtigste Allianz-Organisation für Aufklärung und Spionage.",["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr in Sturmwind auf Seemacht, spirituellen Halt und wichtige diplomatische Führung zählen. Es ist die bevölkerungsreichste Metropole der Großen Allianz.",["race:Dwarf"]="Als Zwerg könnt Ihr mit der Tiefenbahn zu Euren Verwandten im Zwergendistrikt reisen. Sie pflegen enge Handels- und Militärbeziehungen zum Königreich der Menschen.",["race:Human"]="Als Mensch ist Sturmwind der letzte große Sitz souveräner Macht Eures Volkes, nachdem Lordaeron, Alterac und Dalaran im Norden gefallen sind."},sec={{t="Aus der Asche auferstanden",b="Sturmwind wurde vor mehr als tausend Jahren von Nachfahren der Arathi gegründet. Generationenlang war es ein blühendes, selbstversorgendes Reich. Die Orcische Horde durchquerte das Dunkle Portal und verwüstete den südlichen Kontinent, wobei sie während des Ersten Krieges die Hauptstadt dem Erdboden gleichmachte. Die Überlebenden folgten Sir Anduin Lothar über Das große Meer nach Lordaeron. Nach dem Fall der Horde im Zweiten Krieg bezahlten König Terenas Menethil II und die Allianz den Wiederaufbau der Stadt. Die Steinmetzgilde errichtete Neu-Sturmwind aus behauenem weißen Stein, mit Kanälen, die durch die Stadtviertel fließen."},{t="Ein gespaltener Hof",b="Sturmwinds prachtvolles Äußeres verbirgt ein verschuldetes Königreich und einen gespaltenen Hof. Das Haus der Edlen und die Steinmetzgilde stritten um Löhne, und der Streit lähmte das Königreich mit Schulden. Die Arbeiter der Gilde randalierten und wurden aus der Stadt vertrieben, die sie erbaut hatten. König Varian Wrynn ist auf dem Weg zu einem diplomatischen Gipfeltreffen verschwunden. Um Panik zu verhindern, ging die Krone an seinen zehnjährigen Sohn, Prinz Anduin Wrynn. Hochlord Bolvar Fordragon regiert nun als Regent und Heerführer, mit der königlichen Beraterin Lady Katrana Prestor an seiner Seite."},{t="Herz der Großen Allianz",b="Da Lordaeron von der Geißel überrannt wurde, ist Sturmwind zum größten Zufluchtsort der Menschheit und zum Zentrum der Allianz geworden. Hochschrauber Mekkadrills unterirdische Tiefenbahn verbindet die Stadt direkt mit Eisenschmiede, dem Königreich der Zwerge. Jenseits des Tals der Helden ehren gewaltige Statuen die Söhne Lothars, die hinter dem Dunklen Portal verschwanden. Die Kathedrale des Lichts zieht die Gläubigen an, während das Zauberersanktum der arkanen Studien dient. Handel, Kultur und Verteidigung über die südlichen Meere hinweg treffen alle in Sturmwind zusammen."},{t="Wohin die Steinmetze gingen",b="Die Steinmetze versammelten sich unter ihrem Gildenmeister Edwin van Cleef erneut in Westfall. Dort wurden sie zur Bruderschaft der Defias, rot maskierten Banditen, die nun das Ackerland des Königreichs strangulieren. Die Erbauer von Sturmwinds weißen Mauern haben geschworen, das Haus der Edlen für jeden Stein bezahlen zu lassen."},{t="Ein Freund am Hof",b="Die Bruderschaft der Defias fand Hilfe in Burg Sturmwind. Lord Gregor Lescovar vom Haus der Edlen verhandelte heimlich mit der Bruderschaft und gab ihr die Pläne des Königreichs weiter, während er unter den Lords saß, die die Steinmetze betrogen hatten."},{t="Schatten in der Burg",b="Lady Katrana Prestor hat heimlich die Entscheidungen des Hauses der Edlen gelenkt. Sie schürte dessen Konflikt mit den Steinmetzen und ignorierte Bitten um militärische Hilfe aus Siedlungen wie Westfall und dem Rotkammgebirge. Außerdem flüsterte sie Hochlord Bolvar Gift ins Ohr und hielt Sturmwinds Legionen untätig und gespalten, während Unruhen jenseits der Stadtmauern den Thron bedrohen."}},faq={{q="Wer regiert gerade Sturmwind?",a="Der zehnjährige Prinz Anduin Wrynn trägt Sturmwinds Krone, während Hochlord Bolvar Fordragon als Regent regiert und das Militär befehligt. Bolvar verlässt sich auf den Rat der königlichen Beraterin Lady Katrana Prestor, während König Varian Wrynn weiterhin vermisst wird.",al={"aktueller könig","wer ist der könig","wer führt sturmwind","könig von sturmwind"}},{q="Was ist mit König Varian Wrynn geschehen?",a="König Varian verschwand unter verdächtigen Umständen, als er zu einem diplomatischen Gipfeltreffen in Theramore segelte. Sein Verschwinden wurde geheim gehalten, um die Stabilität zu wahren, obwohl sich Gerüchte durch Straßen und Landschaft verbreiteten.",al={"wo ist varian","vermisster könig","varian verschwunden","varian wrynn vermisst"}},{q="Warum wurde die Stadt wiederaufgebaut und von wem?",a="Die Orcische Horde brannte die ursprüngliche Stadt während des Ersten Krieges bis auf die Grundmauern nieder. Nach dem Zweiten Krieg finanzierte die Allianz von Lordaeron den Wiederaufbau, und der Meisterhandwerker Edwin van Cleef führte die Steinmetzgilde beim Errichten der Hauptstadt aus weißem Stein an.",al={"wer hat sturmwind wiederaufgebaut","steinmetzgilde","neu-sturmwind","wiederaufbau der stadt"}},{q="Warum lehnten sich die Steinmetze gegen die Krone auf?",a="Das Haus der Edlen häufte beim Ausbau von Sturmwinds Militär hohe Schulden an und weigerte sich dann, der Steinmetzgilde die versprochenen Löhne zu zahlen. Als Edwin van Cleef die Bezahlung einforderte, lösten die Edlen die Gilde auf. Die Arbeiter randalierten und wurden aus der Stadt vertrieben.",al={"ursprung der defias","warum sind die defias wütend","aufstand der steinmetze"}},{q="Wen zeigen die riesigen Statuen im Tal der Helden?",a="Das Tal der Helden ehrt die Söhne Lothars: General Turalyon, Waldläuferhauptmann Alleria Windläufer, Erzmagier Khadgar, Kurdran Wildhammer und Danath Trollbann. Die Statuen erinnern an die Helden, die das Dunkle Portal nach Draenor betraten, um den Riss zu versiegeln und Azeroth zu schützen.",al={"statuen am eingang","statuen im tal der helden","statuen der söhne lothars"}},{q="Wie ist Sturmwind mit Eisenschmiede verbunden?",a="Die Tiefenbahn, eine unterirdische Eisenbahn, verbindet Sturmwind mit Eisenschmiede. Hochschrauber Gelbin Mekkadrill baute sie auf Wunsch von König Magni Bronzebart, damit die Hauptstädte schnell Handel treiben und sich im Krieg gegenseitig verstärken konnten.",al={"die tiefenbahn","zug nach eisenschmiede","wie kommt man nach eisenschmiede"}},{q="Warum schickt Sturmwind keine Truppen, um Westfall und das Rotkammgebirge zu helfen?",a="Der königliche Hof erklärt unter dem Einfluss von Lady Katrana Prestor, Sturmwind könne keine Truppen von seinen Mauern und den nahegelegenen Grenzen abziehen. Die Finanzen des Königreichs sind angespannt, und politische Machtkämpfe haben das Haus der Edlen gelähmt, sodass die Städte der Region auf ihre örtlichen Milizen angewiesen sind.",al={"sturmwinds fehlendes heer","warum gibt es keine hilfe für westfall","verstärkung verweigert"}}},fx={["9beefbfb"]={q="Was ist Sturmwind?",a="Sturmwind ist die Hauptstadt des Menschenkönigreichs Sturmwind und die größte Bastion der Menschheit, die in Azeroth noch steht. Erbaut nördlich des Waldes von Elwynn entlang der Küste, dient sie als pulsierendes Herz, primärer Hafen und kulturelles Zentrum der Großen Allianz. Wiederaufgebaut aus der Asche des Ersten Krieges, bieten ihre befestigten Steinmauern Handwerkern, Gelehrten, Soldaten und Flüchtlingen Schutz, die die Stadt als Symbol menschlicher Ausdauer betrachten.",al={"über sturmwind","hauptstadt sturmwind","was ist sturmwind"}},edb1c1aa={q="Was ist in der Vergangenheit mit Sturmwind passiert?",a="Ursprünglich vor über tausend Jahren von Nachkommen der Arathor-Blutlinie gegründet, florierte das Königreich jahrhundertelang durch Konflikte mit Gnollen und Dschungeltrollen. Während des Ersten Krieges belagerte jedoch die Orcische Horde die Hauptstadt. Nach der tragischen Ermordung von König Llane Wrynn wurde die Stadt durchbrochen, geplündert und bis auf die Grundmauern niedergebrannt. Sir Anduin Lothar führte die überlebenden Flüchtlinge nach Norden über das Meer nach Lordaeron und kehrte erst nach dem Zweiten Krieg zurück, um ihre Heimat zurückzuerobern und wiederaufzubauen.",al={"geschichte von sturmwind","zerstörung von sturmwind","sturmwind erster krieg"}},d0a4b7c8={q="Ist Sturmwind gefährlich?",a="Hinter ihren kolossalen Toren und der wachsamen Stadtwache ist Sturmwind eines der am stärksten befestigten Refugien der Welt. Dennoch lauern unsichtbare Gefahren im Inneren. Das nahe gelegene Gefängnis war Schauplatz gewaltsamer Aufstände, Kultisten und Diebe schleichen durch die schattigen Canals, und politische Unruhen, geschürt von der Bruderschaft der Defias, lassen das Haus der Adligen nervös werden. Während offener Krieg selten die Mauern durchbricht, flüstern Korruption, Verrat und verborgene Verschwörungen durch die Burg und die Gassen gleichermaßen.",al={"ist sturmwind sicher","gefahr in sturmwind","bedrohungen für sturmwind"}},["163d181d"]={q="Wer ist die Bruderschaft der Defias?",a="Die Bruderschaft der Defias ist eine rücksichtslose Gilde von Gesetzlosen, Briganten, Dieben und Piraten, die die Stabilität des Königreichs offen bedrohen. Sie sind an ihren charakteristischen roten Bandanas zu erkennen, die das Blut symbolisieren sollen, das für ihre Sache vergossen wurde. Obwohl sie stark von Westfall, dem Rotkammgebirge und den Todesminen aus operieren, reicht ihr Einfluss direkt bis nach Sturmwind, wo ihre Spione und Sympathisanten die Autorität der Krone untergraben und Zwietracht unter der Arbeiterklasse säen.",al={"bruderschaft der defias","wer ist die defias","defias-bande"}},b1d432aa={q="Was ist die Kathedrale des Lichts?",a="Die Kathedrale des Lichts, die über dem Kathedralenplatz thront, ist das herausragende geistige Zentrum für die Menschheit und die Große Allianz. Nach dem Zweiten Krieg unter Erzbischof Alonsus Faol und dem damaligen Bischof Benedictus wiederaufgebaut, dient sie als Sitz der Kirche des Heiligen Lichts und als Hauptquartier des Ordens der Silbernen Hand. Paladine und Priester reisen aus allen Teilen der Reiche an, um zu trainieren, Weisheit zu suchen und in ihren großen, friedlichen Hallen zu meditieren.",al={"kathedrale des lichts","kathedrale von sturmwind","kirche des lichts sturmwind"}},["3414b788"]={q="Wie bin ich in Sturmwind gelandet?",a="Wenn Ihr Eure Reise in Nordhain begonnen und Euch durch den Wald von Elwynn gearbeitet habt, führte Euch die Hauptstraße direkt durch das Tal der Helden und in die befestigten Tore der Hauptstadt. Wenn Ihr aus Dun Morogh oder Eisenschmiede stammt, seid Ihr wahrscheinlich mit der Tiefenbahn gefahren, dem Wunderwerk gnomischer Ingenieurskunst, das die Zwergenfestung direkt mit dem Zwergendistrikt unter den Bergen verbindet. Reisende aus anderen Teilen von Azeroth erreichen die Tore von Sturmwind nach langen Märschen durch die südlichen Königreiche, auf der Suche nach dem letzten großen Bollwerk der Menschheit.",al={"wie bin ich hierhergekommen","wie komme ich nach sturmwind","wie gelange ich nach sturmwind"}},["68c43aeb"]={q="Was soll ich in Sturmwind tun?",a="Sturmwind ist das schlagende Herz der Allianz und ein Zufluchtsort, um sich auszuruhen, zu trainieren und sich zu versorgen. Unter den glänzend weißen Stadtmauern ist das Königreich jedoch tief gespalten. König Varian Wrynn ist unter mysteriösen Umständen verschwunden, was den jungen König Anduin und Hochlord Bolvar Fordragon in der Festung mit politischer Lähmung kämpfen lässt. Währenddessen rufen die umliegenden Grenzgebiete in Westfall und dem Rotkammgebirge nach Hilfe gegen grassierendes Banditentum, und die The Defias Brotherhood schmiedet Pläne aus den Schatten heraus. Ihr seid hier, um Euer Handwerk zu verfeinern, Euren Fraktionsführern Bericht zu erstatten und einem bedrängten Reich Euer Schwert zu leihen.",al={"warum bin ich hier","was soll ich hier tun","was ist meine aufgabe in sturmwind"}}},fp="14,142,19.590.0,15.532.0,27.258.0,21.287.1,17.236.1,19.351.2,30.238.0,35.216.0,38.251.1,48.261.1,50.272.0,40.223.0,65.267.0"}
P.entries["zone:stranglethorn"] = {n="Schlingendorntal",s="Das Schlingendorntal ist ein ungezähmter, dichter Dschungel, der die Südspitze der Östlichen Königreiche südlich des Dämmerwalds dominiert. Einst der Sitz des großen Gurubashi-Reichs, ist der Regenwald heute übersät mit verfallenden Trollruinen, wilden Tieren und konkurrierenden Lagern von Goblins, Piraten und Soldaten. Die Kontrolle über die Region ist zwischen lokalen Trollstämmen, der Venture Company und rivalisierenden Fraktionen, die sich in der Hitze Fuß fassen wollen, heiß umkämpft.",h="Das Schlingendorntal ist ein ungezähmter, dichter Dschungel, der die Südspitze der Östlichen Königreiche...",kw={"blutsegelbukaniere","beutebucht","grom'gol","gurubashi","kurzen","nesingwary","revilgaz","schlingendorntal","venture company","zul'gurub"},ang={["class:Hunter"]="Am nördlichen Flussufer residiert der berühmte Großwildjäger Hemet Nesingwary, der Scharfschützen dazu herausfordert, ihr Können beim Aufspüren der wildesten Raptoren, Panther und Krokilisken des Dschungels unter Beweis zu stellen.",["faction:Alliance"]="Sturmwinds historische Versuche, den Dschungel zu erobern und zu befrieden, stürzten das Königreich in schwere Schulden, und heute werden seine Interessen nur noch von bedrängten Meuterern im Rebellenlager verteidigt.",["faction:Horde"]="Das Basislager Grom'gol bietet der Horde eine unverzichtbare strategische Festung auf dem südlichen Kontinent, die direkt von Zeppelinen aus Durotar und Unterstadt versorgt wird.",["profession:Herbalism"]="Das feuchte Blätterdach nährt eine wertvolle Flora, was die Flussufer und Küsten zu idealen Jagdgründen für Wildstahlblume, Blassblatt, Golddorn und Lila Lotus macht.",["race:Troll"]="Das Schlingendorntal ist die angestammte Wiege der Dschungeltrolle, deren uraltes Gurubashi-Reich nach der Anbetung von Hakkar dem Seelenschinder im Bürgerkrieg unterging und Stämme wie die Dunkelspeere über die Meere trieb."},sec={{t="Ruinen eines Imperiums",b="Jahrtausertelang wurde das Tal vom mächtigen Gurubashi-Imperium aus ihrer Hauptstadt Zul'Gurub regiert. Diese Vorherrschaft zerbrach, als radikale Priester Hakkar den Seelenschinder beschworen und die Region in einen verheerenden Bürgerkrieg stürzten. Obwohl die Zandalari eingriffen, um den Aufstand des Blutgottes niederzuschlagen, zersplitterte das Reich unwiederbringlich. Heute wird der Dschungel von kriegführenden Nachfolgefraktionen überrannt – allen voran den Bloodscalp im Nordwesten und den Schädelspaltern im Osten –, die beide eifrig Außenstehende abschlachten, um ihre angestammte Heimat zurückzufordern."},{t="Piraten und Profiteure",b="Wo uralte Ruinen verstummen, füllt kommerzielle Gier die Leere. An der Südspitze liegt Beutebucht, eine geschäftige Zuflucht, die vom Steamwheedle-Kartell errichtet wurde und von den Blackwater Raiders unter Baron Revilgaz geführt wird. Der Hafen dient als wichtigster Knotenpunkt für den südlichen Handel und den Seeverkehr, wird jedoch ständig von den rivalisierenden Blutsegelbukanieren belagert, die vor der Küste ankern. Weiter im Landesinneren holzt die Venture Company aggressiv den Dschungel ab und schürft in den Hügeln nach seltenen singenden Kristallen."},{t="Eine umkämpfte Wildnis",b="Das Schlingendorntal dient als eines der unbeständigsten Grenzgebiete der Welt. Die Horde befehligt das Basislager Grom'gol an der Westküste, das über Goblin-Zeppeline mit Durotar und Tirisfal verbunden ist, während Allianz-Loyalisten aus dem Rebellenlager heraus operieren, um den abtrünnigen Colonel Kurzen aufzuspüren. Inmitten des dichten Dickichts führt der legendäre Jäger Hemet Nesingwary waghalsige Großwildexpeditionen an und verwickelt Wanderer in gefährliche Begegnungen mit lauernden Panthern, riesigen Affen und feindlichen Soldaten."},{t="Der Wahnsinn im Dschungel",b="Nicht alle Bedrohungen im nördlichen Schlingendorntal sind wilde Tiere. Colonel Kurzen, einst ein verdienter Kommandant, der von Sturmwind entsandt worden war, verfiel im Dickicht dem Wahnsinn und errichtete eine tyrannische Söldnerbastion. In Wahrheit wurde Kurzens Verstand durch die Zauberei des Gedankenauges verstrickt, einem Artefakt, das der Ogermagier Mai'Zoth vom nahe gelegenen Ogerhügel der Mosh'Ogg führte; dies trieb die Expedition in den schieren Wahnsinn und veranlasste seine ehemaligen Männer, das abtrünnige Rebellenlager zu gründen."}},faq={{q="Wer beherrscht das Schlingendorntal?",a="Keine einzelne Macht beherrscht das Tal. Der Dschungel ist unter rivalisierenden Dschungeltrollstämmen wie den Bloodscalps und Schädelspaltern, abtrünnigen Lagern wie Kurzens Truppenlager, der Söldner-Venture-Company und verstreuten Militärposten von Horde und Allianz aufgeteilt. Die größte städtische Siedlung ist der neutrale Goblinhafen Beutebucht, der von Baron Revilgaz und den Blackwater Raiders regiert wird.",al={"wem gehört das schlingendorntal","wer herrscht über das schlingendorntal","fraktionen im schlingendorntal"}},{q="Was ist Beutebucht?",a="Beutebucht ist eine weitläufige Hafenstadt, die auf den südlichen Klippen des Kaps des Schlingendorntals erbaut wurde. Ursprünglich eine menschliche Siedlung namens Schwarzmeerbucht, wurde sie von Trollen erobert und schließlich vom Steamwheedle-Kartell gesichert. Heute leiten Baron Revilgaz und Flottenmeister Seehorn die Stadt als neutralen Handelshafen, der Reisende über das Große Meer mit Ratschet verbindet.",al={"was ist beutebucht","hafen beutebucht","wer leitet beutebucht"}},{q="Warum wurde Colonel Kurzen abtrünnig?",a="Colonel Kurzen führte im Auftrag von Sturmwind eine Expedition in den Dschungel, doch sein Verstand geriet unter den Einfluss von Mai'Zoth, einem Ogermagier, der ein mächtiges Relikt namens Gedankenauge schwang. Kurzen wurde zunehmend unberechenbar und despotisch, was loyale Soldaten wie Lieutenant Doren dazu zwang, sich abzuspalten und das Rebellenlager zu gründen, um ihn aufzuhalten.",al={"warum ist kurzen böse","was geschah mit kurzen","kurzen hintergrundgeschichte"}},{q="Was ist Zul'Gurub?",a="Zul'Gurub ist die uralte, von Tempeln gesäumte Hauptstadt des Gurubashi-Imperiums, eingebettet im nordöstlichen Schlingendorntal. Sie war das Epizentrum des Bürgerkriegs, der das Reich vor fünfzehn Jahrhunderten beendete, nachdem radikale Priester den Blutgott Hakkar den Seelenschinder herbeigerufen hatten. Obwohl sie längst von Lianen und Ruinen überwuchert ist, bedrohen finstere Rituale weiterhin ihre Hallen.",al={"was ist zg","geschichte von zul'gurub","hauptstadt der gurubashi"}},{q="Was war der Stein der Gezeiten?",a="Der Stein der Gezeiten ist ein legendäres Relikt aus der uralten Geschichte der Gurubashi, das an der Küste von einem Trollkrieger entdeckt wurde. Es verlieh seinem Träger die Herrschaft über das Wasser und das Beschwören von Elementaren ähnlich einem mächtigen Magier, was dem Träger den Titel „Gezeitenträger“ einbrachte. Es trug jedoch einen Fluch in sich, der dazu führte, dass der Träger langsam aus dem physischen Reich verblasste, was jeden von ihnen dazu trieb, ins Meer zu waten und zu verschwinden.",al={"stein der gezeiten","legende des gezeitenträgers","gurubashi wasserstein"}},{q="Wie reise ich in das Schlingendorntal?",a="Reisende können vom Dämmerwald aus nach Süden über die Flussgrenze ins nördliche Schlingendorntal wandern. Die Horde unterhält direkte Zeppelintürme, die das Basislager Grom'gol mit Durotar und Tirisfal verbinden. Reisende aus Kalimdor können auch das reguläre Handelsschiff besteigen, das zwischen Ratschet im Brachland und Beutebucht verkehrt.",al={"weg ins schlingendorntal","reise ins schlingendorntal","schlingendorntal anreise"}}},fp="18,166,18.455.0,22.346.0,22.414.0,25.340.1,32.270.0,18.322.0,32.268.1,18.294.0,32.328.0,38.256.0"}
P.entries["zone:swampofsorrows"] = {n="Sümpfe des Elends",s="Die Sümpfe des Elends sind ein trübes, brackiges Feuchtgebiet, eingebettet zwischen dem Gebirgspass der Totenwinde und den dürren Verwüsteten Landen. Einst die nördliche Ausdehnung des uralten Schwarzen Morastes, beherbergen ihre salzverkrusteten Moore gefährliche Wildtiere, grüne Drachenbrut und die ruinenhafte Tempelanlage von Atal'Hakkar, die unter dem Tränenteich versunken liegt. Während die Horde die befestigte Garnison von Steinard unterhält, besitzt die Allianz keinen sicheren Zufluchtsort im Morast, sodass die Wildnis weitgehend ungezähmt bleibt.",h="Die Sümpfe des Elends sind ein trübes, brackiges Feuchtgebiet, eingebettet zwischen dem Gebirgspass der...",kw={"schwarzer morast","zerschlagene","der sichere hafen","verirrte","tränenteich","sorgendunkel","steinard","versunkener tempel","sümpfe des elends","der tempel von atal'hakkar"},ang={["faction:Alliance"]="Ohne einen Außenposten als Rückzugsort ist das Reisen durch den Sumpf ein einsames, feindseliges Unterfangen, das sorgfältige Vorbereitung in Dunkelhain oder Burg Nethergarde erfordert.",["faction:Horde"]="Steinard dient als Eure wichtige vorderste Bastion auf dem südlichen Kontinent und bietet direkte Wyvernrouten nach Kargath, zum Flammenkamm, zum Basislager Grom'gol, nach Beutebucht und nach Rog'mar in den Flusslanden.",["profession:Blacksmithing"]="Widerstandsfähige Abenteurer können entlang der felsigen Klippen, die die nördlichen und südlichen Ränder des Sumpfes säumen, Eisen, Gold, Mithril und Echtsilber abbauen.",["profession:Herbalism"]="Das Moor ist einer der wenigen Orte in Azeroth, an denen Blindkraut reichlich vorkommt, neben ergiebigen Vorkommen von Lebenswurz, Blassblatt und Würgetang.",["race:Troll"]="Die versunkenen Ruinen von Atal'Hakkar stehen als düstere Mahnung an die dunkle Blutmagie, die das Gurubashi-Reich spaltete und den Zorn der Drachenaspekte heraufbeschwor."},sec={{t="Eine ertrunkene Geschichte",b="Lange vor dem Erscheinen der orcischen Horde bildeten diese Sümpfe die nördliche Hälfte eines gewaltigen Sumpflands, das als Schwarzer Morast bekannt war. Nach dem Zerfall des Gurubashi-Reiches flohen die fanatischen Atal'ai-Trolle in das Moor, um den Tempel von Atal'Hakkar zu errichten, mit der Absicht, ihren blutrünstigen Loa Hakkar den Seelenschinder zu beschwören. Als der Aspekt Ysera die Katastrophe spürte, entfesselte sie ihre Kräfte und ertränkte die verfluchte Pyramide in den Fluten des Tränenteichs. Wächter des grünen Drachenschwarms unter der Führung von Eranikus wurden abgestellt, um das versunkene Bauwerk wachsam zu bewachen. Als der Kataklysmus des Dunklen Portals später den südlichen Morast zu den Verwüsteten Landen verbrannte, erhielt dieses nördliche Moor seinen heutigen klagenden Namen."},{t="Außenposten und Zerschlagene Exilanten",b="Steinard dient als wichtigster zivilisierter Stützpunkt im Sumpf. Ursprünglich während des Ersten Krieges neben den inzwischen zerstörten Siedlungen Rockard und Kyross gegründet, wurde der Außenposten unter Thrall wieder aufgebaut, um als südlichstes Aufmarschgebiet der Horde in den Östlichen Königreichen zu dienen. Jenseits der Palisaden von Steinard streifen seltsame Wanderer durch das Moor. Eine Gruppe von Draenei-Nachzüglern, die auf Azeroth gestrandet waren, erlag dem Heimweh und dem Wahnsinn und degenerierte zu wilden Verirrten. Eine kleine Enklave geistig klarer Zerschlagener Exilanten verweilt jedoch im sicheren Hafen, vorsichtig, aber bereit, friedlich mit Reisenden zu handeln."},{t="Der versinkende Morast",b="Das Überleben im Sumpf erfordert ständige Wachsamkeit gegenüber den dortigen Raubtieren. Tiefe Moore verbergen vorschnellende Krokilisken, giftige Spinnen, lauernde Sumpfjaguare und umherstreifende Moorbestien, die mit Sumpfschutt verkrustet sind. In Küstenhöhlen und am Nebelschilfstrand wimmelt es von bösartigen Murlocs, während die salzgeschwängerte Flut unaufhörlich landeinwärts kriecht und verrottete Baumstämme in dicken Salzlaugenkrusten konserviert. Weiter östlich liegt das Sorgendunkel, wo aggressive Elite-Drachenbrut die Zugänge zum Versunkenen Tempel erbittert bewacht und jeden angreift, der ihrer Wacht zu nahe kommt."}},faq={{q="Wie erreiche ich die Sümpfe des Elends?",a="Die gängigste Überlandroute führt von Dunkelhain im Dämmerwald nach Osten, durch den gefährlichen, heimgesuchten Gebirgspass der Totenwinde und geradewegs hinab in das Moor. Alternativ können Reisende aus dem Süden der Hauptstraße aus den Verwüsteten Landen nach Norden folgen.",al={"wie man in die sümpfe des elends gelangt","straße zu den sümpfen des elends","weg nach steinard"}},{q="Warum liegt der Tempel von Atal'Hakkar unter Wasser?",a="Vor Jahrhunderten versuchte die Priesterschaft der Atal'ai, Hakkar den Seelenschinder nach Azeroth zu beschwören. Ysera, der Drachenaspekt des grünen Schwarms, entdeckte ihre dämonischen Blutriten und versenkte den gesamten Tempel im Moor, um das Unheil abzuwenden, wobei sie grüne Drachenbrut zurückließ, um die überfluteten Hallen zu bewachen.",al={"warum der versunkene tempel versank","wer den tempel versenkte","lore des versunkenen tempels"}},{q="Was ist Steinard?",a="Steinard war eine der ersten Siedlungen, die von der orcischen Horde erbaut wurden, nachdem sie während des Ersten Krieges das Dunkle Portal durchschritten hatte. Obwohl es während der Kämpfe verwüstet wurde, wurde es vor kurzem auf Befehl von Thrall zurückerobert und wieder aufgebaut, um die Logistik der Horde nahe den Verwüsteten Landen zu sichern.",al={"geschichte von steinard","orc-basis im sumpf","wer steinard baute"}},{q="Gibt es hier Siedlungen der Allianz?",a="Nein. Die Allianz unterhält in den Sümpfen des Elends weder Städte noch Wachen oder Flugpunkte. Allianz-Abenteurer, die in der Region unterwegs sind, müssen ihre Basis in Dunkelhain im Dämmerwald im Westen oder in Burg Nethergarde in den Verwüsteten Landen im Süden aufschlagen.",al={"allianz-basis sümpfe des elends","allianz-flugpunkt sumpf","wo ist das allianz-lager"}},{q="Wer sind die seltsamen mutierten Humanoiden im Sumpf?",a="Es sind Draenei, die nach dem Zusammenbruch des Dunklen Portals auf Azeroth gestrandet sind. Abgeschnitten von ihrer Welt wurden die meisten vor Verzweiflung wahnsinnig und verwandelten sich in feindselige Verirrte. Eine kleine Gruppe bei Verstand gebliebener Zerschlagener Exilanten suchte im Nordwesten im sicheren Hafen Zuflucht und wählte das neutrale Überleben statt blinder Wut.",al={"wer sind die verirrten","was ist der sichere hafen","draenei im sumpf"}},{q="Was ist das Sorgendunkel?",a="Das Sorgendunkel ist das dichte Sumpfgebiet direkt östlich des Tränenteichs. Es dient als Patrouillengebiet für grüne Elite-Drachenbrut und Welpen, die Sterbliche gewaltsam vertreiben, um die Geheimnisse des Versunkenen Tempels zu schützen.",al={"drachengebiet sümpfe des elends","drachen im sorgendunkel","grüne drachenbrut sumpf"}}},fp="16,249,17.556.0,26.487.0,16.475.0,36.188.0,44.259.0,16.248.0,40.179.0,51.307.0,19.185.0"}
P.entries["zone:tanaris"] = {n="Tanaris",s="Tanaris ist eine riesige, glühend heiße Wüste, die sich über die südlichen Gefilde von Kalimdor erstreckt und von sanften Sanddünen und sengender Hitze geprägt ist. In ihrem Herzen liegt Gadgetzan, ein neutraler Handelsposten, der von den Goblins des Dampfdruckkartells betrieben wird. Jenseits der geschäftigen Siedlungen verbergen die Dünen feindselige Sandtrolle, gefährliche Silithidenbauten und die verborgene Domäne des bronzenen Drachenschwarms.",h="Tanaris ist eine riesige, glühend heiße Wüste, die sich über die südlichen Gefilde von Kalimdor erstreckt und...",kw={"die höhlen der zeit","wüste","freebooters","gadgetzan","nozdormu","sandfury","silithiden","steamwheedle","tanaris","uldum","zul'farrak"},ang={["faction:Alliance"]="Da es zwischen den Düstermarschen und Feralas keine größeren Stützpunkte der Allianz gibt, dient der Flugmeister der Allianz im neutralen Gadgetzan als lebenswichtiger Etappenort für Reisen durch das südliche Kalimdor.",["faction:Horde"]="Gadgetzan bietet Spähern der Horde einen praktischen Handelsknotenpunkt, der Routen vom Freiwindposten und Camp Mojache direkt mit den silithidenverseuchten Ödlanden des tiefen Südens verbindet.",["profession:Herbalism"]="Die trockene Hitze begünstigt das Gedeihen der schwer fassbaren Feuerblüte in den Wanderdünen, während schattige Ruinen und feuchte Oasen wertvollem Lila Lotus Zuflucht bieten.",["profession:Mining"]="Die ariden Klippen und felsigen Ausläufer rund um die Dünen bieten reiche Vorkommen an Mithril, Echtsilber, Eisen und Gold sowie verstreute Ablagerungen von Kleinem Thorium in den tieferen Gebieten.",["race:Troll"]="Der Anblick der Sandfury von Zul'Farrak bietet Trollen einen eindringlichen Einblick in das Leben ihrer uralten Vettern, die in der Abgeschiedenheit der Wüste zu einer brutalen Kultur erstarrten."},sec={{t="Ein Meer aus Dünen",b="Tanaris ist eine karge, sonnenverbrannte Wildnis. Innerhalb der ummauerten Stadt Zul'Farrak bewachen die abgehärteten Sandfury-Trolle ihr isoliertes Reich. Heute wird der Wüstenboden von Hyänen, Basilisken und Skorpiden beherrscht, während sich unterirdische Tunnel unter der brennenden Erde schlängeln."},{t="Goblin-Unternehmungsgeist",b="Da Tanaris ihrer Inselheimat Kezan so nah liegt, wie das Festland es erlaubt, hat das Dampfdruckkartell hier ein florierendes Unternehmen aufgebaut. Von der ummauerten Oase Gadgetzan bis zu den Küstendocks des Dampfdruckpiers wahren die Goblins strikte Neutralität und nehmen Münzen sowohl von der Allianz als auch von der Horde entgegen. Ihr Frieden wird durch schwere Schlägermuskeln aufrechterhalten, obwohl abtrünnige Bedrohungen wie die Southsea Freebooters die Schifffahrt und Ausgrabungsstätten entlang der Küstenlinie unablässig schikanieren."},{t="Uralte Geheimnisse und aufkeimende Gefahren",b="Der Sand verbirgt Mächte, die weit älter sind als die Reiche der Sterblichen. In den östlichen Weiten liegen Die Höhlen der Zeit, das angestammte Reich von Nozdormu und seinem bronzenen Drachenschwarm, dessen Drachen man gelegentlich dabei beobachten kann, wie sie die thermischen Aufwinde der Wüste nutzen. Im Süden markieren gewaltige Steintore den Titankomplex Uldum. Doch eine noch finsterere Gefahr regt sich in unterirdischen Nestern wie der klaffenden Schlucht und dem giftigen Unterschlupf, wo kriechende Silithidenschwärme begonnen haben, sich quer durch den Sand nach außen zu graben."}},faq={{q="Wie reise ich nach Tanaris?",a="Reisende zu Fuß ziehen durch Tausend Nadeln in die Schimmernde Ebene. Ein Gebirgspass, der am südlichen Ende der Salzwüste durch die Klippen geschlagen wurde, führt direkt hinab in die Wüste und bringt Euch unmittelbar in Sichtweite der Mauern von Gadgetzan. Zudem verkehrt ein Schiff vom Hafen von Powderfuse in den Flusslanden zum Dampfdruckpier an der Ostküste.",al={"wie man nach tanaris gelangt","anreise nach tanaris","eingang nach tanaris"}},{q="Warum ist Gadgetzan beiden Fraktionen gegenüber neutral?",a="Gadgetzan wird vom Dampfdruckkartell regiert, dessen einzige Loyalität dem Profit gilt. Um den Handel zu maximieren und die Handelsrouten durch die Wüste zu schützen, setzen die Goblins strikte Neutralität durch und setzen Schläger ein, um jeden niederzuschlagen, der töricht genug ist, innerhalb ihrer Stadtmauern Fraktionsprügeleien anzuzetteln.",al={"warum ist gadgetzan neutral","können horde und allianz nach gadgetzan","goblin-neutralität gadgetzan"}},{q="Was ist Zul'Farrak?",a="Zul'Farrak ist die befestigte Wüstenhauptstadt der Sandfury-Trolle. Da der Stamm der Sandfury lange Zeit in der Wüste isoliert war, wurde er allen Außenstehenden gegenüber feindselig und bewacht seine heiligen Teiche und geheimnisvollen Schreine vor zudringlichen Abenteurern.",al={"was ist zul'farrak","wer lebt in zul'farrak","sandtrollstadt"}},{q="Was sind das für Insektenkreaturen, die in der Wüste nisten?",a="Bei den insektoiden Bestien handelt es sich um Silithiden, monströse Koloniegräber, die riesige Bauten wie Die klaffende Schlucht und den giftigen Unterschlupf errichten. Ihre aufkeimende Präsenz in Tanaris hat Beobachter wie den Leitenden Feldmesser Rutenwünschels beunruhigt und erinnert an die uralten Schrecken des Krieges der Sandstürme.",al={"was sind die insekten in tanaris","insektenbauten in tanaris","silithiden in tanaris"}},{q="Was verbirgt sich hinter den massiven Steintoren im Süden?",a="Die monumentalen Tore im Tal der Behüter markieren den Eingang nach Uldum, einer legendären Forschungseinrichtung und Liegenschaft der uralten Titanen. Der Eingang bleibt fest versiegelt, bewacht von kolossalen Steinsenten und aus der Ferne von neugierigen Gelehrten und Goblins beobachtet.",al={"riesige tore im süden von tanaris","ruins of uldum tore","titantor tanaris"}},{q="Wer weilt in den Höhlen der Zeit?",a="Die Höhlen der Zeit dienen als angestammter Hort des bronzenen Drachenschwarms und ihres Aspekts Nozdormu. Aus diesen verborgenen, gewundenen Tiefen wachen die zeitlosen Drachen über den Lauf der Geschichte und patrouillieren gelegentlich hoch über den südlichen Dünen am Himmel.",al={"die höhlen der zeit lore","was befindet sich in den höhlen der zeit","drachen in tanaris"}}},fp="7,203,14.233.0,17.333.0,35.335.0,27.288.0,42.224.0,19.175.0,56.255.0,52.219.0,38.232.0"}
P.entries["zone:teldrassil"] = {n="Teldrassil",s="Teldrassil, was „Krone der Erde“ bedeutet, ist ein riesiger neuer Weltenbaum, der vor der Nordwestküste Kalimdors emporgewachsen ist. Nach dem Dritten Krieg von den Druiden herangezogen, tragen seine gewaltigen Äste eine ganze dämmerige Wildnis und Darnassus, die Hauptstadt der Nachtelfen. Doch unter seinem friedvollen, mondbeschienenen Blätterdach beginnt sich eine schleichende Verderbnis zu regen.",h="Teldrassil, was „Krone der Erde“ bedeutet, ist ein riesiger neuer Weltenbaum, der vor der Nordwestküste...",kw={"rat der urahnen","krone der erde","darnassus","dolanaar","fandral hirschhaupt","rut'theran","laubschattental","teldrassil","weltenbaum"},ang={["class:Druid"]="Während Malfurion im Smaragdgrünen Traum gefangen ist, leitet Erzdruide Fandral Hirschhaupt hier den Zirkel des Cenarius, wenngleich viele Druiden fürchten, Teldrassil sei übereilt herangezogen worden.",["faction:Alliance"]="Teldrassil dient als nördlichste Bastion der Allianz auf Kalimdor und sichert die Seeverbindung sowie den Handel zwischen Darnassus und den Reichen des Festlands.",["profession:Herbalism"]="Zwar fehlen Mineralien und Erz gänzlich, doch das saftige Blätterdach des Baumes gleicht dies aus, indem es sich als Paradies für Sammler von Friedensblume, Silberblatt und Erdwurzel erweist.",["race:NightElf"]="Dieser gewaltige Baum ist der Neubeginn Eures Volkes nach der Verheerung von Hyjal, doch das Fehlen des Segens der Aspekte macht seine Verteidigung zu einer dringlichen Pflicht."},sec={{t="Ein Blätterdach über dem Meer",b="Teldrassil ist nicht bloß ein Baum; er ist ein erhabenes Ökosystem hoch über den Wogen des Verhüllten Meeres. Seine riesenhaften Äste tragen sanfte Hügel, von Morgentau gespeiste fließende Flüsse, neblige Seen und dichte, uralte Lichtungen. An seinem westlichen Rand liegt Darnassus, die prächtige Hauptstadt der Kaldorei. Am Fuße seines gewaltigen Stammes liegt Rut'theran, das durch ein mystisches Portal mit der Krone darüber verbunden ist und als wichtigster Hafen der Insel dient."},{t="Die Weigerung der Aspekte",b="Nach dem Opfer von Nordrassil während des Dritten Krieges und dem rätselhaften Verschwinden von Shan'do Malfurion Sturmgrimm in den Smaragdgrünen Traum überzeugte Erzdruide Fandral Hirschhaupt den Rat der Urahnen, einen Ersatz heranzuziehen. Staghelm hoffte, den Kaldorei ihre verlorene Unsterblichkeit zurückzugeben. Nozdormu und die Drachenaspekte hielten dieses Unterfangen jedoch für anmaßend und verweigerten ihre Segnungen. Ohne ihren lebenswichtigen Schutz leidet Teldrassils Wachstum unter unnatürlichen Makeln."},{t="Ein schleichendes Übel",b="Trotz seiner äußeren Erhabenheit birgt der junge Weltenbaum eine finstere Krankheit. Die hiesige Tierwelt ist gewalttätig geworden: Friedliche Furbolgstämme sind dem Wahnsinn verfallen, verzerrte Grells vermehren sich in den Grabhügeln, und abscheuliche Satyrn vollziehen dunkle Riten in Schatten wie dem Teufelsfels. An den Gestaden der Dunkelküste stranden Riesen des Meeres, Drescher und Schildkröten, um den verderbten Gewässern rings um den Baum zu entfliehen. Naturforscher und Schildwachen mühen sich nun auf den Ästen rastlos ab, um den Schatten ausfindig zu machen, der ihre neue Heimat langsam erdrosselt."}},faq={{q="Warum wurde Teldrassil erschaffen?",a="Nachdem Nordrassil am Ende des Dritten Krieges verheert worden war, verloren die Nachtelfen ihre Unsterblichkeit. Erzdruide Fandral Hirschhaupt drängte den Rat der Urahnen und die Cenariusdruiden dazu, einen neuen Weltenbaum im Meer zu pflanzen, um wiederzuerlangen, was ihr Volk verloren hatte.",al={"warum erschaffen","wer erschuf teldrassil","teldrassil ursprung"}},{q="Warum stellte Teldrassil die Unsterblichkeit der Nachtelfen nicht wieder her?",a="Nordrassil gewährte ursprünglich Unsterblichkeit, weil Nozdormu, der Zeitlose, ihn gesegnet hatte. Als Teldrassil emporwuchs, erachtete Nozdormu das Verlangen der Nachtelfen als anmaßend und weigerte sich, dem neuen Baum seinen Segen zu verleihen.",al={"unsterblichkeit","warum nicht unsterblich","nozdormu segen"}},{q="Wie verlässt man Teldrassil?",a="Reisende müssen Darnassus durchqueren und das rosa Portal in den Tempelgärten aufsuchen, das sie hinab nach Rut'theran am Fuße des Stammes befördert. Von Rut'theran aus setzt ein Schiff über das Meer nach Auberdine auf dem Festland der Dunkelküste über; zudem stehen Hippogryphenrouten zur Verfügung.",al={"wie wegkommen","baum verlassen","teldrassil schiff"}},{q="Warum gibt es auf Teldrassil keine Erzvorkommen?",a="Das gesamte Gebiet ruht auf den lebendigen Zweigen und dem Holz eines kolossalen Weltenbaums und nicht auf natürlichem kontinentalen Gestein. Da es keine steinernen unterirdischen Schichten gibt, bilden sich hier weder Metalladern noch Erzlagerstätten, obgleich Kräuter in großer Fülle gedeihen.",al={"wo ist kupfer","kein erz","teldrassil bergbau"}},{q="Was treibt die Furbolgs und Tiere in den Wahnsinn?",a="Eine finstere Präsenz hat begonnen, in Teldrassils ungesegnete Wurzeln einzusickern. Siechtum hat das hiesige Wasser und die Flora verdorben, was friedliche Holzkotze und den Stamm der Knorzfurbolgs in rasende Raserei treibt, während Überreste von Satyrn die Verderbnis eifrig nähren.",al={"verderbte furbolgs","knorzkiefern wahnsinnig","was ist die verderbnis"}},{q="Was ist Laubschattental?",a="Laubschattental ist ein geschütztes, abgeschiedenes Tal auf den östlichen Ästen von Teldrassil rings um den großen Baum Aldrassil. Es dient als friedliches Refugium, in dem junge Nachtelfen ihre Ausbildung beginnen, ehe sie in die weite Welt hinausziehen.",al={"laubschattental","startgebiet","aldrassil zone"}}},fx={["11a6d5e5"]={q="Was ist Teldrassil?",a="Teldrassil ist ein riesiger Weltenbaum, der auf einer Insel vor der nordwestlichen Küste von Kalimdor gewachsen ist. Sein gigantischer Stamm ragt aus dem Nebelmeer empor und breitet sich in Äste aus, die so gewaltig sind, dass sie ein ganzes bewaldetes Reich mit Seen, Flüssen und der Hauptstadt Darnassus auf ihrem Blätterdach tragen.",al={"was ist das für ein ort","über teldrassil","erzähl mir von teldrassil"}},["313cd5a2"]={q="Was ist auf Teldrassil passiert?",a="Nach dem Dritten Krieg und dem Schaden, der am Nordrassil des Hyjal entstanden war, verschwand der Druide Malfurion Sturmgrimm. In seiner Abwesenheit überzeugte Erzdruide Fandral Hirschhaupt den Zirkel der Ältesten, einen neuen Weltenbaum zu züchten, um das Verlorene zu ersetzen. Obwohl er erfolgreich gewachsen ist, hat seitdem eine schleichende Verderbnis begonnen, seine Äste zu befallen.",al={"geschichte von teldrassil","wie entstand teldrassil","ereignisse auf teldrassil"}},c5e34e84={q="Wer lebt auf Teldrassil oder verwaltet es?",a="Teldrassil ist der angestammte Zufluchtsort und die heutige Heimat der Nachtelfen. Spirituell und zivil leiten die Hohepriesterin Tyrande Wisperwind und Erzdruide Fandral Hirschhaupt ihr Volk von der Hauptstadt Darnassus aus, unterstützt von der Schwesternschaft der Elune, den cenarischen Druiden und den Wächterinnen, die die Waldsiedlungen schützen.",al={"wer führt teldrassil an","anführer von teldrassil","wer lebt hier"}},b86e706e={q="Ist Teldrassil gefährlich?",a="Obwohl Teldrassil von Wächterinnen geschützt wird, wird es zunehmend gefährlicher. Ein dunkles Leiden hat die einheimischen Bestien und lokalen Furbolgs in den Wahnsinn getrieben, während bösartige Satyrn, blutrünstige Harpyien und umherstreifende Holzschlinger die Siedlungen jenseits der patrouillierten Straßen bedrohen.",al={"ist es hier sicher","bedrohungen auf teldrassil","gefahren auf teldrassil"}},["2863bed2"]={q="Warum heißt es Teldrassil?",a="In der darnassischen Sprache der Nachtelfen lässt sich Teldrassil direkt mit 'Krone der Erde' übersetzen. Es wurde zu Ehren seiner Rolle als monumentaler Weltenbaum benannt, der dazu bestimmt ist, ihre Zivilisation zu behüten und zu beschützen.",al={"was bedeutet teldrassil","bedeutung des namens teldrassil"}},["514d23b0"]={q="Wer ist Fandral Hirschhaupt?",a="Fandral Hirschhaupt ist der Erzdruide, der nach Malfurion Sturmgrimms Verschwinden in den Smaragdgrünen Traum die Führung der nachtelfischen Druiden übernahm. Leidenschaftlich, stur und aggressiv, setzte sich Fandral für die Pflanzung von Teldrassil ein und gerät häufig mit der Hohepriesterin Tyrande Wisperwind über die Politik aneinander.",al={"wer ist der erzdruide","fandral hirschhaupt geschichte","hirschhaupt"}},["52c333ac"]={q="Wer ist Tyrande Wisperwind?",a="Tyrande Wisperwind ist die Hohepriesterin der Göttin Elune und das oberste Oberhaupt des nachtelfischen Volkes. Nachdem sie ihr Volk zehntausend Jahre lang durch die lange Mahnwache und den Dritten Krieg geführt hat, leitet sie nun vom The Temple of the Moon in Darnassus aus die Geschicke.",al={"wer ist tyrande","hohepriesterin tyrande","wer führt die nachtelfen an"}},["29b1e9e4"]={q="Wie bin ich auf Teldrassil gelandet?",a="Wenn Ihr ein Nachtelf seid, ist dieser kolossale Weltenbaum die neue Heimat Eures Volkes. Nachdem Ihr Nordrassil und Eure uralte Unsterblichkeit auf dem Hyjal geopfert habt, um die Brennende Legion zu besiegen, siedelten die Kaldorei vor der Nordwestküste von Kalimdor um. Erzdruide Fandral Hirschhaupt und der Zirkel der Ältesten ließen Teldrassil im Nebelmeer wachsen, um Eurer Rasse einen neuen Zufluchtsort zu geben, und Ihr begann Eure Reise in seinen grünen Ästen im Laubschattental. Wenn Ihr von außerhalb hierher gereist seid, seid Ihr wahrscheinlich von der Dunkelküste zum Hafen von Rut'theran am Fuße des Baumes gesegelt und dann durch das leuchtende Portal geschritten, das Reisende direkt in die Krone befördert.",al={"wie gelange ich nach teldrassil","wie bin ich hierhergekommen","warum fange ich hier an"}},["8381279f"]={q="Was soll ich auf Teldrassil tun?",a="Ihr seid dazu berufen, den jungen Weltenbaum zu beschützen und das dunkle Leiden aufzudecken, das seine Äste beunruhigt. Trotz seiner üppigen Wälder greift eine finstere Verderbnis um sich: Holzschlinger werden aggressiv, friedliche Furbolgs des Gnarlpine-Stammes verfallen dem Wahnsinn und abscheuliche Satyrn lauern in schattigen Dickichten wie dem Teufelsfels. Angefangen im Laubschattental und bei der Hilfe für Siedlungen wie Dolanaar müsst Ihr den Wächterinnen und Druiden helfen, das Gleichgewicht wiederherzustellen. Ihr werdet die heiligen Mondbrunnen auffüllen, verdorbenes Ungeziefer ausrotten und die Geschichte Eures Volkes lernen, bevor Ihr Euch in die Hauptstadt Darnassus und über das Meer zum Festland von Kalimdor begebt.",al={"was soll ich auf teldrassil tun","warum bin ich hier","was ist meine mission hier"}}},fp="10,168,21.379.0,26.466.0,17.410.1,25.260.0,52.182.0,28.253.0,44.210.0,52.248.0,19.205.0"}
P.entries["zone:thousandneedles"] = {n="Tausend Nadeln",s="Tausend Nadeln ist ein weitläufiger Canyon aus steilen Sandsteinsäulen und sonnenverbrannten Salzpfannen im südlichen Kalimdor. Taurenstämme klammern sich an Siedlungen auf hoch aufragenden Hochebenen, um aggressiven Zentaurenrudeln zu entgehen, während gnomische und Goblin-Tüftler mit rasanten Raketenwagen über den ausgetrockneten Meeresboden der schimmernden Ebene jagen.",h="Tausend Nadeln ist ein weitläufiger Canyon aus steilen Sandsteinsäulen und sonnenverbrannten Salzpfannen im...",kw={"klippenbehüter langhorn","düsterwolkengipfel","fizzel kupferbolz","freiwindposten","der große aufzug","grimmtotem","kravel kohlebart","illusionenrennbahn","pozzik","die schimmernde ebene","tausend nadeln"},ang={["faction:Horde"]="Der Große Aufzug verbindet das Brachland mit Eurer Festung am Freiwindposten und dient als strategische Südgrenze gegen Zentaurenklans und abtrünnige Tauren.",["profession:Engineering"]="Die Salzebenen sind ein Pilgerort für Tüftler, die auf der Illusionenrennbahn Raketentreibstoff, Fahrzeugteile und Hochgeschwindigkeitsantriebe studieren möchten.",["race:Gnome"]="Die Illusionenrennbahn in der schimmernden Ebene ist die beste Gelegenheit für Eure Fraktion, die Präzision und Eleganz gnomischer Ingenieurskunst gegenüber minderwertigen Goblinkonstruktionen unter Beweis zu stellen.",["race:Tauren"]="Der Freiwindposten erinnert daran, wie hoch Euer Volk steigen musste, um dem Gemetzel der Zentauren zu entkommen, und dient als Aufmarschgebiet gegen die tückischen Grimmtotem am Düsterwolkengipfel."},sec={{t="Ein Wald aus Stein",b="Bevor die Große Zerschlagung das alte Kalimdor zerriss, war dieses Gebiet eine üppige Flussschlucht, gespeist von Binnengewässern, die dem Meer zuströmten. Die Katastrophe riss den Kontinent auseinander, hob das Flussbett über den Grundwasserspiegel und veränderte den Lauf des Flusses, bis nur noch trockener Fels und Sandsteinspitzen übrig blieben. Heute ragen Dutzende schlanker, zylindrischer Säulen wie ein versteinertes Waldgebiet aus dem Grund der Schlucht empor. Tauren ließen sich auf den Gipfeln nieder und spannten gewagte Seilbrücken zwischen den Spitzen, um Dörfer außerhalb der Reichweite der feindseligen Zentaurenplünderer zu errichten, die den schattenverhangenen Grund der Schlucht durchstreifen."},{t="Gefahr auf den Mesas",b="Auf den nadelartigen Spitzen ist das Leben alles andere als friedlich. Am Freiwindposten müssen sich die Horde-treuen Tauren nicht nur mit räuberischen Windnattern und Wyvern vom Steilhang auseinandersetzen, sondern auch mit ihrer verräterischen Verwandtschaft: dem kriegerischen Grimmtotemklan, der sich auf dem Düsterwolkengipfel verschanzt hat. Klippenbehüter Langhorn überwacht die Verteidigung des Plateaus und sucht mutige Kämpfer, um gegen die Grimmtotem-Aufwiegler vorzugehen und die zerbrechlichen Brücken zwischen den Gipfeln zu sichern. Im Norden befördern die gewaltigen mechanischen Winden des Großen Aufzugs Reisende aus dem südlichen Brachland hinab, doch die Durchquerung des Canyongrunds bleibt ein tödliches Wagnis."},{t="Die Illusionenrennbahn",b="Im Südosten weichen die Canyonwände zurück und geben den Blick auf die schimmernde Ebene frei, eine gewaltige, ausgetrocknete Salzpfanne unter dem Meeresspiegel. In dieser rauen, blendend weißen Weite wahren Gnome und Goblins eine brüchige Neutralität rund um die Illusionenrennbahn. Die rivalisierenden Ingenieure Pozzik und Fizzel Kupferbolz lassen experimentelle Raketenwagen über das harte Salz rasen, um zu klären, welches Volk die technologische Überlegenheit besitzt. Das Fahrerlager zieht Schurken, Schwindler wie Kravel Kohlebart und Jäger an, die den zähen Skorpionen, Schildkröten und Basilisken nachstellen, welche das glühend heiße Becken durchstreifen."}},faq={{q="Wie kam Tausend Nadeln zu seinem Namen?",a="Das Gebiet ist nach den Dutzenden gewaltigen, zylindrischen Sandsteinsäulen benannt, die aus dem Grund der Schlucht emporragen. Ursprünglich vor der Großen Zerschlagung von reißenden Flussströmungen geformt, gleichen diese geologischen Türme heute einem Wald aus riesigen Nadeln.",al={"warum heißt es tausend nadeln","nadel säulen ursprung","felsspitzen lore"}},{q="Wie gelangt man aus dem Brachland hinunter nach Tausend Nadeln?",a="Reisende nutzen Den großen Aufzug, eine riesige Doppelkabinen-Aufzugsanlage an der südlichen Grenze des Brachlands, die von Wachen der Horde betrieben wird. Ein Schritt über den Rand ist tödlich, weshalb das Warten auf die Plattform unerlässlich ist. Reisende der Allianz können auch von Westen her über Thalanaar in Feralas anreisen.",al={"weg nach tausend nadeln","eingang großer aufzug","aufzug nach tausend nadeln"}},{q="Warum leben die Tauren auf den Hochebenen?",a="Kriegstrupps der Zentauren brachten die nomadischen Tauren einst an den Rand der Auslöschung. Die Errichtung von Außenposten wie dem Freiwindposten auf unzugänglichen Steinsäulen schützte sie vor Bodenangriffen. Sie verbanden die Mesas mit hölzernen Hängebrücken, was das Reisen in luftiger Höhe über den Raubtieren und Plünderern am Boden ermöglichte.",al={"warum tauren auf felsspitzen","geschichte freiwindposten","tauren anhöhe"}},{q="Was ist die Illusionenrennbahn?",a="Die Illusionenrennbahn ist ein Testgelände für Ingenieure auf der Salzpfanne der schimmernden Ebene. Gnomische und Goblin-Tüftler jagen mit experimentellen, raketengetriebenen Rennwagen über das flache Salzbett, um ihre anhaltende Rivalität darüber beizulegen, welches Volk die besten Maschinen konstruiert.",al={"rennstrecke salzebene","gnom goblin rennen","raketenwagen rennstrecke"}},{q="Welche Präsenz haben die Grimmtotem in der Schlucht?",a="Der Grimmtotemklan besetzt den Düsterwolkengipfel, eine befestigte Ansammlung von Felsspitzen direkt gegenüber dem Freiwindposten. Im Gegensatz zu den übrigen Taurenstämmen, die der Horde die Treue schwuren, greifen die Grimmtotem aktiv andere Tauren an und planen insgeheim, die Vorherrschaft über die Mesas an sich zu reißen.",al={"grimmtotem tausend nadeln","düsterwolkengipfel tauren","böse tauren nadeln"}},{q="Was ist Die schimmernde Ebene?",a="Die schimmernde Ebene ist ein riesiges, ausgetrocknetes Seebett östlich der Canyon-Mesas. Die Salzkruste entstand, als das uralte Binnenmeer nach der Zerschlagung verdampfte. Die sengende Hitze, das blendend weiße Salz und gefährliche Raubtiere machen sie zu einer unwirtlichen Wüste, die vor allem für Hochgeschwindigkeits-Fahrzeugtests genutzt wird.",al={"salzpfanne","weiße wüste tausend nadeln","östliche wüste"}}},fx={["0eee4587"]={q="Warum fahren Goblins und Gnome in der Wüste mit Raketenautos?",a="Der flache, offene Salzuntergrund der schimmernden Ebene bietet das perfekte Testgelände für den Test von Hochgeschwindigkeitsmotoren. Gnome und Goblins gründeten die Illusionenrennbahn, um den langjährigen Streit darüber, welche Rasse die bessere Technik besitzt, endgültig beizulegen.",al={"warum rennwagen","goblin gnom rennen","raketenauto rivalität"}},e421f132={q="Was hat es mit dem Düsterwolkengipfel und diesen geheimen Notizen auf sich?",a="Der Düsterwolkengipfel ist die schwer bewachte Festung des Stammes der Grimtotem auf den Tafelbergen östlich des großen Aufzugs. Dort gefundene geheime Korrespondenz enthüllt geheime Kontakte zwischen den Anführern der Grimtotem, wie Arnak Grimtotem, und einer unbekannten dunklen Macht, was auf verräterische Ambitionen weit jenseits einfacher Stammesfehden hindeutet.",al={"düsterwolkengipfel notizen","grimtotem notizen","düsterwolkengipfel geheimnis"}},["7b560411"]={q="Was planen die Grimtotem?",a="Die Grimtotem lehnen die Führung von Cairne Bluthuf und die kulturellen Veränderungen, die der Beitritt zur Horde mit sich brachte, grundlegend ab. Sie trachten danach, Cairne zu stürzen, die Autorität der Horde zu untergraben und verbünden sich sogar mit finsteren Mächten und beschwören Wesen der Vergeltung, um ihre Vorherrschaft durchzusetzen.",al={"grimtotem plan","was wollen grimtotem","grimtotem verschwörung"}},["853c4dd1"]={q="Was ist der Steilhang und warum wollen wir Wyverneier?",a="Der Steilhang ist der angestammte Nistplatz wilder Wyverns in Tausend Nadeln. Tauren aus dem Freiwindposten klettern zu diesen hohen Felsvorsprüngen hinauf, um befruchtete Wyverneier zu sammeln, damit diese sorgfältig aufgezogen und als treue Flugreittiere für die Horde ausgebildet werden können.",al={"steilhang wyverns","warum wyverneier sammeln","steilhang eier"}},dc3189d8={q="Wie bin ich in Tausend Nadeln gelandet?",a="Die meisten Reisenden kommen von Norden, indem sie durch das Brachland an Camp Taurajo vorbeireiten, bis sie schließlich den steilen Abhang erreichen, wo der massive, von Tauren konstruierte Der große Aufzug einen direkt auf den Boden des Canyons hinablässt. Alternativ können Abenteurer, die durch die dichten Wälder von Feralas nach Osten wandern, die westliche Schlucht zu Fuß betreten, während wagemutige Entdecker, die den Gefahren der Düstermarschen trotzen oder nach Theramore segeln, durch die umkämpften Lücken schlüpfen. Ein langer Marsch über Land nach Norden von den Wüsten von Tanaris bringt einen ebenfalls direkt in die weitläufige Salzfläche der schimmernden Ebene.",al={"wie kam ich hierher","wie erreiche ich tausend nadeln","nach tausend nadeln kommen"}},["16801326"]={q="Was soll ich in Tausend Nadeln tun?",a="Ihre Anwesenheit hier hängt von Ihren Loyalitäten und Ambitionen ab. Champions der Horde haben die Aufgabe, den Freiwindposten zu unterstützen: die Galak-Zentaurenhorden, die den Schluchtenboden durchstreifen, zurückzudrängen, Harpyienhorste zu überwachen, Wyverneier vom Steilhang zu sammeln und den verräterischen Grimtotem-Stamm zu bekämpfen, der sich auf dem Düsterwolkengipfel verschanzt hat. Für unabhängige Wanderer und Reisende der Allianz dient die dramatische Weite als gefährliche Überlandkreuzung zwischen dem zentralen und südlichen Kalimdor, die zur schimmernden Ebene führt, wo Goblin- und Gnom-Waghälse gutes Gold für Teile, Treibstoff und Hilfe bei ihrer ewigen Raketenauto-Rivalität zahlen.",al={"warum bin ich hier","was ist mein zweck hier","was mache ich in tausend nadeln"}},d1fb42e2={q="Was sind die Tausend Nadeln?",a="Tausend Nadeln ist ein riesiger, arider Canyon, der das zentrale und südliche Kalimdor teilt. Sein Canyonboden ist übersät mit hoch aufragenden Sandsteinfelsen, die sich wie ein versteinerter Wald in den Himmel strecken und oben durch zarte Seil- und Holzbrücken verbunden sind. Im Osten geht der Canyon in die schimmernde Ebene über, eine blendend weiße Salzpfanne.",al={"was ist das für ein ort","über tausend nadeln","erzähl mir von tausend nadeln"}},["98fcff4e"]={q="Warum ist hier alles aus Canyons und Säulen?",a="Vor langer Zeit, vor dem Großen Zerwürfnis, war diese Region ein grüner Fluss-Canyon, der von reißenden Wassern geformt wurde, die von Feralas nach Osten in ein Binnenmeer flossen. Als die Welt zerbrach, stieß das Kataklysmus das Flussbett in die Höhe und veränderte den Lauf des Flusses. Ohne Wasser trocknete das Land aus und hinterließ hoch aufragende Sandsteinsäulen und ein vertrocknetes Salzbett.",al={"warum gibt es felsnadeln","wie entstanden die nadeln","warum sandsteinsäulen"}},["05d5c74f"]={q="Sind die Tausend Nadeln gefährlich?",a="Es ist ziemlich gefährlich. Barbarische Galak-Zentauren patrouillieren in Raubzügen auf dem Canyonboden, während räuberische Geier, Skorpide und abtrünnige Harpyien die Klippen heimsuchen. Selbst die Seilbrücken zwischen den hohen Felsnadeln bergen Gefahren, da Raubvögel häufig auf unachtsame Reisende herabstürzen oder die Spannweiten beschädigen.",al={"wie gefährlich sind die tausend nadeln","gefahren hier","ist es sicher"}},["1b8e8bea"]={q="Warum hat die Horde mich in die Tausend Nadeln geschickt?",a="Die Horde unterhält hier eine wichtige Präsenz, um den lokalen Tauren-Stämmen zu helfen, die unter unerbittlichen Angriffen stehen. Der Freiwindposten ist ein wichtiges Bollwerk, das das Brachland mit den südlichen Wüsten verbindet, und die Horde braucht mutige Helden, um marodierende Zentauren zurückzudrängen und interne Bedrohungen zu unterdrücken.",al={"horde mission tausend nadeln","warum bin ich hier horde","was will die horde hier"}},a7c3b539={q="Ist das Land der Tauren?",a="Ja. Die kargen Canyons und hohen Mesas der Tausend Nadeln sind seit unzähligen Generationen traditionell das angestammte Gebiet mehrerer Tauren-Stämme, obwohl bösartige Zentaurenclans sie an den Rand des Überlebens drängten, bevor die Horde eintraf.",al={"gehören die tausend nadeln den tauren","gebiet der tauren","ist das land der shu'halo"}},fef8bf7c={q="Was ist der Freiwindposten?",a="Der Freiwindposten ist der primäre Außenposten der Horde in den Tausend Nadeln. Er wurde auf einer massiven Mesa hoch über dem Talboden errichtet und verfügt über hölzerne Aufzüge, einen Flugturm und ein Netzwerk von Hängebrücken, die zu benachbarten Felsnadeln führen.",al={"freiwindposten","was ist freiwindposten"}},["6ac472b0"]={q="Wer sind die Galak-Zentauren und warum greifen sie uns an?",a="Der Stamm der Galak sind die lokalen Zentauren, die den Canyonboden für sich beanspruchen. Wie alle Zentauren sind sie extrem territorial, nomadisch und gewalttätig. Sie jagen jeden Reisenden, der durch die Schluchten zieht, und versuchen, die Siedlungen der Tauren vollständig auszulöschen.",al={"galak-zentauren","warum greifen zentauren an","stamm der galak"}},["9f0b1de8"]={q="Warum hassen sie die Tauren?",a="Die Feindschaft zwischen Tauren und Zentauren ist uralt und unerbittlich. Über Generationen hinweg jagten umherziehende Zentauren auf den Ebenen von Kalimdor Tauren zum Zeitvertreib und führten brutale, grundlose Kriege, die die friedlichen Stämme ständig auf der Flucht hielten.",al={"warum hassen zentauren tauren","zentauren tauren fehde","zentauren groll"}}},fp="16,179,17.529.0,18.553.0,18.535.0,38.222.0,59.251.0,43.279.0,27.248.0,45.235.0,30.284.0"}
P.entries["zone:thunderbluff"] = {n="Donnerfels",s="Donnerfels ist die prächtige Hauptstadt der Tauren, gelegen auf windgepeitschten roten Felsplateaus, die sich über das Grasland von Mulgore erheben. Gegründet von Oberhäuptling Cairne Bluthuf nach der Vereinigung der nomadischen Stämme mit Hilfe der neuen Horde, dient sie als kulturelles, spirituelles und merkantiles Herz seines Volkes. Verbunden durch schwankende Hängebrücken und hölzerne Aufzüge bietet die Stadt Schutz vor marodierenden Zentauren und eine friedliche Zuflucht für Reisende aus ganz Kalimdor.",h="Donnerfels ist die prächtige Hauptstadt der Tauren, gelegen auf windgepeitschten roten Felsplateaus, die sich...",kw={"cairne bluthuf","die anhöhe der ältesten","aufzüge","hamuul runentotem","die anhöhe der jäger","magatha grimmtotem","mulgore","die teiche der visionen","die anhöhe der geister","donnerfels"},ang={["class:Druid"]="Die Anhöhe der Ältesten dient als oberstes Heiligtum der Naturmagie der Horde, geführt von Erzdruide Hamuul Runentotem, dem ersten Taurendruiden, der seit Jahrtausenden unterwiesen wurde.",["class:Shaman"]="Die Anhöhe der Geister und die unterirdischen Teiche der Visionen bieten einen friedvollen Knotenpunkt, an dem die Elementargeister und die Geister der Taurenahnen verehrt und gehört werden.",["faction:Horde"]="Weitaus friedlicher und spiritueller als die rauen Wehranlagen von Orgrimmar dient Donnerfels als ländlicher Anker des südlichen Einflusses der neuen Horde in Kalimdor.",["race:Tauren"]="Donnerfels steht für die hart erkämpfte Einheit und Wiedergeburt Eures Volkes nach Generationen des nomadischen Wanderns und der Zentaurenangriffe unter Oberhäuptling Cairne Bluthuf."},sec={{t="Ein dauerhafter Zufluchtsort",b="Unzählige Generationen lang lebten die Tauren als nomadische Wanderer in Kalimdor, verstrickt in einen brutalen Überlebenskampf gegen unersättliche Zentaurenstämme. Diese verzweifelte Ära endete während des Dritten Krieges, als sich Cairne Bluthuf mit Kriegshäuptling Thrall zusammenschloss. Gemeinsam brachen die Orcs und Tauren die Angriffe der Zentauren und sicherten die üppigen Weidegründe von Mulgore. Um ihre Zukunft zu schützen, führte Cairne die verbündeten Stämme in die Sicherheit dieser natürlichen Felsenbastionen und gründete Donnerfels als die erste vereinte, dauerhafte Heimat, die die Tauren seit Jahrhunderten besaßen."},{t="Eine Stadt in den Wolken",b="Über mehrere hohe Hochebenen verteilt, die durch Hängebrücken miteinander verbunden sind, verbindet Donnerfels nahtlos natürliche Architektur mit der Zweckmäßigkeit der Tauren. Die zentralen Plateaus beherbergen die belebten Märkte, die Bank, das Gasthaus und den hoch aufragenden Windreiterhorst, während sich drei spezialisierte Hochebenen über den Abgrund erstrecken. Die Anhöhe der Jäger dient den Spähern und Fährtenlesern der Stadt; die Anhöhe der Ältesten beherbergt Schriftgelehrte und den Zirkel des Cenarius unter Erzdruide Hamuul Runentotem; und die Anhöhe der Geister ist der spirituellen Zwiesprache gewidmet und beherbergt Schamanen, Priester sowie die geheimnisvollen unterirdischen Höhlen, die als die Teiche der Visionen bekannt sind."},{t="Unruhige Einigkeit",b="Während Cairne Bluthuf von fast jedem Stamm immensen Respekt genießt, verläuft die Führung eines erst kürzlich sesshaft gewordenen, stolzen Volkes nicht ohne Spannungen. Bemerkenswerterweise unterhält der Stamm der Grimmtotem – angeführt von der scharfsinnigen und scharfzüngigen Obersten Matriarchin Magatha Grimmtotem – eine finstere Präsenz auf der Anhöhe der Ältesten. Magatha stellt Cairnes versöhnliche Methoden und seine Loyalität gegenüber den fremden Völkern der Horde offen in Frage. Obwohl unter dem wachsamen Blick des Häuptlings Frieden herrscht, schwelen an den Ratsfeuern über den Ebenen ideologische Klüfte."}},faq={{q="Wer regiert Donnerfels?",a="Oberhäuptling Cairne Bluthuf regiert Donnerfels und führt die vereinten Taurenstämme an. Verehrt für seine Weisheit, Geduld und gewaltige Stärke, gründete Cairne die Stadt, nachdem er sich mit Thralls Horde verbündet und die Zentauren aus Mulgore vertrieben hatte.",al={"anführer von donnerfels","wer hat das sagen","häuptling von donnerfels","cairne"}},{q="Wie gelangt man hinauf nach Donnerfels?",a="Besucher, die zu Fuß oder auf einem Kodo anreisen, müssen gewaltige hölzerne Plattformaufzüge an der südwestlichen und nordöstlichen Seite der zentralen Hochebene nutzen. Alternativ verfügt die Stadt über einen Windreiterhorst mit Flugverbindungen über ganz Kalimdor.",al={"aufzug donnerfels","wie man hineinkommt","eingang zu donnerfels","hinaufkommen"}},{q="Warum bauten die Tauren auf hohen Mesas statt auf dem Boden?",a="Jahrhunderte nomadischen Daseins waren von unerbittlichen Überfällen aggressiver Zentaurenclans geprägt. Die steilen Klippen von Mulgores Hochebenen bieten natürlichen Schutz, bewahren die Behausungen, Schmieden und heiligen Ältesten der Tauren vor Hinterhalten am Boden und ermöglichen es ihnen, sich dauerhaft in Frieden niederzulassen.",al={"warum mesas","warum auf klippen","klippen von donnerfels","tauren anhöhe"}},{q="Welche verschiedenen Anhöhen gibt es in der Stadt?",a="Die Stadt erstreckt sich über eine zentrale Mesa (unterteilt in untere, mittlere und obere Ebenen), die von drei äußeren Hochebenen umgeben ist. Die Anhöhe der Jäger ist Kriegern, Jägern und Fährtenleserhütten gewidmet. Die Anhöhe der Ältesten ist die Heimat von Druiden, Weisen und der Grimmtotem-Fraktion. Die Anhöhe der Geister beherbergt Schreine für die Erdenmutter, Ausbilder für Schamanen, Priester und Magier sowie die höhlenartigen Teiche der Visionen.",al={"bereiche von donnerfels","welche anhöhen gibt es","viertel von donnerfels"}},{q="Was sind die Teiche der Visionen?",a="Die Teiche der Visionen sind heilige unterirdische Höhlen unterhalb der Anhöhe der Geister. Seher der Tauren, Geisterwandler und Ausübende des Arkanen versammeln sich in diesen stillen, nebelverhangenen Gewässern, um mit den Elementen Zwiesprache zu halten und Vorzeichen für die Zukunft ihres Volkes zu deuten.",al={"die teiche der visionen","höhle anhöhe der geister","höhle in donnerfels"}},{q="Wer ist Magatha Grimmtotem?",a="Magatha Grimmtotem ist die Matriarchin und Älteste des furchterregenden Grimmtotemclans. Obwohl sie auf der Anhöhe der Ältesten residiert und äußerlich an Cairnes Rat teilnimmt, ist sie streng traditionsbewusst, misstraut Außenstehenden und stellt die nachgiebige Haltung des Stammes der Bluthufe gegenüber der Horde im Stillen infrage.",al={"magatha","oberste matriarchin","wer führt die grimmtotem an"}}},fx={["6fa5b073"]={q="Was ist Donnerfels?",a="Donnerfels ist die Hauptstadt der Tauren, hoch oben auf den windgepeitschten Tafelbergen im nördlichen Mulgore gelegen. Sie wurde von Oberhäuptling Cairne Bluthuf gegründet, nachdem er die Zentauren mit Thralls Horde zurückgedrängt hatte, und bietet einen sicheren, dauerhaften Zufluchtsort für ein Volk, das über Generationen als umherziehende Nomaden lebte.",al={"was ist diese stadt","erzähl mir von donnerfels","donnerfels stadt"}},fc90632b={q="Ist Cairne Bluthuf ein König?",a="Nein. Cairne Bluthuf trägt den Titel eines Oberhäuptlings der vereinten Taurenstämme. Die Gesellschaft der Tauren krönt keine Monarchen; Cairne regiert durch den tiefen Respekt, die Weisheit und die Stärke, die er über Jahrzehnte bewiesen hat, und nicht durch ein erbliches, königliches Gottesgnadentum.",al={"cairne bluthuf könig","ist cairne ein könig","tauren könig"}},["047fa056"]={q="Steht Cairne Bluthuf unter Thralls Befehl?",a="Thrall ist der Kriegshäuptling der Horde, aber seine Bindung zu Cairne gründet auf gegenseitiger Ehre und Bündnis und nicht auf strikter Unterwerfung. Cairne verpflichtete sein Volk der Horde aus Dankbarkeit und einer gemeinsamen Vision und steht Thrall als einer seiner vertrauenswürdigsten Berater und als Gleichgestellter zur Seite.",al={"steht cairne unter thralls befehl","ist thrall cairnes boss","cairne und thrall"}},["85c1a10f"]={q="Warum sind die Tauren der Horde beigetreten?",a="Zentaurenplünderer hatten die nomadischen Tauren im Brachland an den Rand der Ausrottung getrieben. Als Kriegshäuptling Thrall und die Orcs in Kalimdor landeten, halfen sie Cairnes Volk, die Belagerung der Zentauren zu brechen und Mulgore zu sichern, wodurch ein unzerbrechliches Band zwischen ihren Kulturen geschmiedet wurde.",al={"warum der horde beitreten","tauren horde allianz","wie traten die tauren bei"}},["3180b5ca"]={q="Was hat es mit dem Stamm der Grimtotem auf sich?",a="Die Grimtotem sind ein wilder und aggressiver Clan unter der Führung der Elder Crone Magatha. Im Gegensatz zum friedlichen Stamm der Bluthuf hegen sie tiefes Misstrauen gegenüber Außenstehenden und stellen offen Cairnes friedliche Führung in Frage, da sie glauben, die Tauren sollten Kalimdor erobern und die anderen Rassen vertreiben.",al={"grimtotem stamm","wer sind die grimtotem","grimtotem tauren"}},ca8246e8={q="Sind die Grimtotem Feinde von Cairne?",a="Offiziell bleiben sie Teil der vereinten Taurennation, und Magatha wohnt sogar auf Die Anhöhe der Ältesten. Unter der Oberfläche jedoch brodelt eine bittere politische Rivalität, da Magatha ständig Ränkespiele betreibt und glaubt, dass sie allein die rechtmäßige Vision hat, die Tauren zu regieren.",al={"sind grimtotem böse","grimtotem gegen cairne","magatha gegen cairne"}},["54829977"]={q="Ist Donnerfels gefährlich?",a="Innerhalb der Stadt sorgen die tapferen Wachen für Ordnung und Sicherheit vor den Bestien und Stachelebern, die auf den Ebenen darunter schleichen. Die größte unmittelbare Gefahr für Besucher ist der steile Abgrund – ein unvorsichtiger Schritt von den Rändern der Tafelberge oder den Holzbrücken aus endet tödlich.",al={"ist donnerfels sicher","bedrohungen in donnerfels","gefahr hier"}},["7db56847"]={q="Wie bin ich in Donnerfels gelandet?",a="Wenn Ihr ein junger Taure seid, begann Eure Reise im Süden auf dem geschützten Grasland der Hochwolkenebene und führte durch das Dorf der Bluthufe, bevor Ihr hierher kamt. Der Weg führt zum Fuß dieser gewaltigen Tafelberge, wo große hölzerne Seilaufzüge Reisende hunderte Fuß in den Himmel hieven. Alternativ reisen Besucher aus fernen Ländern über Kalimdor oft mit einem Wind Rider zum zentralen Wind Rider Roost auf den Felsen.",al={"wie kam ich hierher","wie kam ich nach donnerfels","wie erreiche ich donnerfels"}},["347b5cac"]={q="Was soll ich in Donnerfels tun?",a="Donnerfels ist das spirituelle und kulturelle Herz der vereinten Taurenstämme. Hier könnt Ihr fortgeschrittene Ausbildung von den Ältestenschamanen, Druiden, Jägern und Kriegern suchen, die sich auf den Anhöhen versammelt haben. Oberhäuptling Cairne Bluthuf und die Stammesältesten verlassen sich ebenfalls auf fähige Champions, um Mulgore vor anhaltenden Bedrohungen zu schützen – einschließlich marodierender Zentauren, der vordringenden Venture Company, Harpyien und rebellischen Stachelebern –, bevor sie Euch nach Osten in die größeren Prüfungen der Horde senden.",al={"was sollte ich in donnerfels tun","warum bin ich hier","was ist mein zweck hier"}}},fp="13,326,17.466.0,20.453.0,12.391.1,24.277.0,35.194.0,61.212.0,41.395.0,29.239.0,25.233.0"}
P.entries["zone:tirisfal"] = {n="Tirisfal",s="Tirisfal ist das unheimliche nördliche Gebiet von Lordaeron und dient nun als Herzland von Fürstin Sylvanas Windläufer und der Verlassenen. Unter verdorbenen Himmeln und verrottenden Ästen liegen gefallene Anwesen, ruhende Krypten und die riesige unterirdische Hauptstadt der Unterstadt. Umgeben von hirnloser Geißel und eifrigen Scharlachroten Kreuzzüglern ist es ein gefährliches Reich, in dem Untote mit freiem Willen um ihr Überleben kämpfen.",h="Tirisfal ist das unheimliche nördliche Gebiet von Lordaeron und dient nun als Herzland von Fürstin Sylvanas...",kw={"agamand","balnir","brill","todesend","verlassene","tiefland","lordaeron","scharlachroter kreuzzug","sylvanas","tirisfal","unterstadt"},ang={["class:Priest"]="Historische heilige Stätten wie Faols Ruheplatz – das Grab von Erzbischof Alonsus Faol, dem Gründer der Silbernen Hand – liegen hier, durch den Tod entstellt und umkämpft zwischen Eiferern und Schattenpriestern.",["faction:Alliance"]="Für die überlebenden Nationen der Allianz ist Tirisfal ein tragisches Denkmal für den Fall Lordaerons, gefüllt mit den entweihten Gräbern ehemaliger Glaubensbrüder und -schwestern.",["faction:Horde"]="Tirisfal ist die entscheidende Bastion der Horde in den nördlichen Östlichen Königreichen, die diplomatische Beziehungen zu den Verlassenen festigt und gleichzeitig menschliche Extremisten und die Geißel abwehrt.",["race:Undead"]="Dies ist Eure angestammte Heimat gleich zweimal: das Königreich, das Ihr im Leben aufgebaut habt, und der unsichere Zufluchtsort, den Ihr im Untod unter Fürstin Sylvanas verteidigen müsst."},sec={{t="Ein Land in der Dämmerung",b="Einst die fruchtbare Wiege der Menschheit, ist Tirisfal unter dem Fluch der Seuche des Lichkönigs verdorrt. Die Sonne dringt nur selten durch die trübe Finsternis und wirft einen ewigen, krankhaft blassen Schein auf sterbende Wälder, vernachlässigte Kürbisfelder und kalte Küstenhügel. Während Überreste alter Bauernhöfe wie Agamands Mühlen und Balnirs Bauernhof bestehen bleiben, wurden ihre ehemaligen Herren größtenteils in Massengräber gespült oder sind als ruhelose Tote auferstanden. Trotz der Verwüstung durchdringt eine dunkle Widerstandskraft die Landschaft, verankert durch Städte wie Brill und den abgeschiedenen Zufluchtsort Todesend, wo frisch erwachte Verlassene lernen, ihr zweites Leben zu ertragen."},{t="Ein Krieg an zwei Fronten",b="Obwohl Fürstin Sylvanas die Herrschaft über die Region von den unterirdischen Ruinen von Lordaeron aus beansprucht, sind die Verlassenen weiterhin von allen Seiten bedrängt. Überreste von Geißel-Schergen befallen immer noch Senken, Felder und verfallene Krypten und sind dem Frostthron von Nordend vollständig untertan. Im Osten hat der fanatische Scharlachrote Kreuzzug das nördliche Tirisfal zu seiner Hauptbastion gemacht und operiert vom Scharlachroten Kloster aus. Eifrig der Ausrottung aller untoten Kreaturen verschrieben, führen ihre Außenposten und Patrouillen einen ständigen Guerillakrieg gegen Kundschafter der Verlassenen und zivile Reisende."},{t="Echos der alten Vergangenheit",b="Lange bevor menschliche Königreiche ihre ersten Monarchen krönten, trug Tirisfal ein altes Vermächtnis. Exilanten der Hochelfen versuchten kurzzeitig, sich in diesen Wäldern niederzulassen, bevor schattenhafte Energien tief unter der Erde begannen, sie in den Wahnsinn zu treiben, was sie zur Abwanderung in den Norden veranlasste. In späteren Jahrhunderten wählte die geheime sterbliche Kabale, bekannt als der Rat von Tirisfal, diese schattigen Haine, um einsame Wächter zu stärken und Azeroth vor dämonischem Eindringen zu schützen."}},faq={{q="Warum ist der Himmel grün und das Land verrottet?",a="Während des Dritten Krieges entfesselten Prinz Arthas und die Geißel die Seuche des Untodes über das Königreich Lordaeron. Die magische Fäulnis vergiftete nicht nur die Bevölkerung, sondern auch den Boden, die Bäume und das Wasser selbst und hinterließ das Gebiet in einem ewigen Zustand unheimlichen, krankhaften Verfalls.",al={"warum ist tirisfal verdorben","was geschah mit tirisfal","warum stirbt tirisfal"}},{q="Was ist der Unterschied zwischen den Verlassenen und der Geißel hier?",a="Die Verlassenen sind Untote, die sich nach der Schlacht am Hyjal von der telepathischen Beherrschung des Lichkönigs befreit haben und sich aus freiem Willen dazu entschlossen haben, Fürstin Sylvanas Windläufer zu folgen. Die Geißel, die auf den Bauernhöfen und in den Ruinen umherstreift, bleibt aus hirnlosen Sklaven bestehen, die an die Befehle des Lichkönigs gebunden sind.",al={"verlassene gegen geißel","warum greifen zombies untote an","sind alle untoten böse"}},{q="Wer sind die rotgepanzerten Soldaten, die Reisende angreifen?",a="Sie gehören zum Scharlachroten Kreuzzug, einer kompromisslosen Splittergruppe ehemaliger Paladine der Silbernen Hand und Überlebender. Davon überzeugt, dass alle Untoten unrettbare Abscheulichkeiten sind, die durch Schwert und Feuer gereinigt werden müssen, richten sie sowohl hirnlose Schergen als auch Verlassene mit freiem Willen mit fanatischem Hass hin.",al={"scharlachroter kreuzzug","rote menschen","kloster menschen"}},{q="Woher kommt der Name Tirisfal?",a="Der Name ist älter als jedes menschliche Königreich, und sein wahrer Ursprung ist in der Geschichte verloren gegangen. Er ist am besten durch den Rat von Tirisfal bekannt, den geheimen Orden der Magier, der die Wächter ermächtigte, Azeroth vor Dämonen zu schützen.",al={"bedeutung tirisfal","ursprung von tirisfal"}},{q="Wo beginnen neu erwachte Verlassene ihre Reise?",a="Neu erwachte Verlassene entsteigen den Krypten des Schattengrabes in Todesend, einer abgeschiedenen Stadt im südwestlichen Tirisfal. Dort bewerten Administratoren und Vollstrecker, ob die auferstandenen Toten den Verstand und die Loyalität besitzen, die erforderlich sind, um der Dunklen Fürstin zu dienen.",al={"startgebiet untote","wo ist todesend","startgebiet der verlassenen"}},{q="Wie verlassen Reisende Tirisfal in Richtung anderer Kontinente?",a="Ein großer, von Goblins betriebener Zeppelinturm befindet sich am Hang südlich von Brill, direkt außerhalb der Ruinen von Lordaeron. Diese Luftschiffe bieten eine direkte, regelmäßige Verbindung über die Meere nach Orgrimmar in Kalimdor und zum Basislager Grom'gol im Schlingendorntal.",al={"tirisfal zeppeline","wie kommt man nach orgrimmar","wie kommt man ins schlingendorntal"}}},fx={["6c272224"]={q="Was ist Tirisfal?",a="Tirisfal ist das Kernland der Verlassenen an der Nordküste von Lordaeron. Einst das friedliche, fruchtbare Herz eines stolzen Menschenkönigreichs, wurde es während des Dritter Krieg von der Pest des Untodes der Geißel verwüstet. Heute bedecken verseuchte Wälder und ein ewiges grünes Zwielicht die Hügel, eingerahmt von den Ruinen von Lordaeron und umgeben von feindseligen Eiferern, wilden Bestien und verbliebenen Untoten.",al={"was ist tirisfal","erzähl mir von tirisfal","tirisfal gebietsüberlieferung"}},["342b65f9"]={q="War dies schon immer das Land der Untoten?",a="Nein. Über tausende von Jahren war Tirisfal die Wiege der menschlichen Zivilisation und das blühende Herz des Königreichs von Lordaeron. Friedliche Gehöfte, wohlhabende Mühlen und kleine Weiler florierten unter König Terenas Menethil. Diese Ära endete gewaltsam während des Dritter Krieg, als Prinz Arthas und der Kult der Verdammten mit der Pest durch das Land fegten und die Bewohner in untote Sklaven verwandelten, bevor Sylvanas Windläufer sie befreite.",al={"war tirisfal immer untot","wer lebte hier vorher","tirisfal vor der pest"}},["4790468d"]={q="Wer lebt oder herrscht in Tirisfal?",a="Die Verlassenen beanspruchen Tirisfal unter der Herrschaft von Königin Sylvanas Windläufer aus der Unterstadt. Ihr Griff ist jedoch ständig umkämpft. Der fanatische Scharlachroter Kreuzzug befehligt Befestigungen und sein großes Kloster im Nordosten, während geistlose Geißel-Kreaturen verlassene Farmen durchstreifen. An der östlichen Grenze beim Bollwerk koordinieren die Verlassenen ihre Aktionen mit der Argentumdämmerung, um die Schrecken der Westliche Pestländer einzudämmen.",al={"wer regiert tirisfal","wer kontrolliert tirisfal","tirisfal fraktionen"}},["97ffdb73"]={q="Ist Tirisfal gefährlich?",a="Extrem gefährlich. Außerhalb der Mauern der Außenposten der Verlassenen begegnet Ihr geistlosen Resten der Geißel, wilden Gnollen, riesigen Arachniden und bösartiger Tierwelt, die von der Pest verseucht wurde. Noch schlimmer sind die Eiferer des Scharlachroter Kreuzzug, die jeden Untoten auf Sicht hinrichten. Im fernen Osten liegen die Westliche Pestländer, wo Monster, die weitaus tödlicher sind als alles in Tirisfal, die Unvorsichtigen zerfleischen werden.",al={"wie gefährlich ist tirisfal","tirisfal bedrohungen","ist es hier sicher"}},["30e6283a"]={q="Wer hat in Brill das Sagen?",a="Magistrat Sevren beaufsichtigt die zivile Verwaltung von Brill und leitet den Wiederaufbau und das tägliche Überleben der Stadt. Die militärische Autorität und die taktischen Operationen, insbesondere der Feldzug gegen den nahegelegenen Scharlachroter Kreuzzug, werden von Exekutor Zygand befehligt.",al={"brill anführer","wer führt brill","das sagen in brill"}},["3fc3649e"]={q="Wem untersteht Magistrat Sevren?",a="Sevren dient der Dunklen Fürstin, Königin Sylvanas Windläufer. Als Magistrat von Brill vertritt er die zivile Autorität der Krone der Verlassenen in der Region und arbeitet dabei direkt mit den königlichen Exekutoren und der Royal Apothecary Society mit Sitz in der Unterstadt zusammen.",al={"vorgesetzter von sevren","wem untersteht sevren","führungskette in brill"}},["381a9b46"]={q="Wo befindet sich die Bansheekönigin?",a="Fürstin Sylvanas Windläufer residiert im Royal Quarter der Unterstadt, tief unter den Ruinen von Capital City, direkt südlich von Brill. Von ihrem Thronsaal aus leitet sie die Verlassenen in ihrem Krieg gegen die Geißel und den The Scarlet Crusade.",al={"wo ist sylvanas","sylvanas finden","standort der bansheekönigin"}},e7993821={q="Was ist Brill?",a="Brill ist die wichtigste Siedlung der Verlassenen im zentralen Tirisfal, gelegen an der Kreuzung nördlich von Capital City. Einst eine lebende Siedlung unter der Barov-Herrschaft, wurde sie nach dem Dritten Krieg wiederaufgebaut, um neu erweckten Untoten einen Ort der Ruhe, des Handels und der Organisation zu bieten, bevor sie in die Welt hinausziehen.",al={"über brill","was für eine stadt ist brill","hintergrundgeschichte von brill"}},["529e09c8"]={q="Lebten hier früher einmal lebende Menschen?",a="Ja. Brill war einst eine ruhige menschliche Gemeinde innerhalb des Königreichs Lordaeron. Es wurde zum Ausgangspunkt früher Experimente mit der Seuche, die von Kel'Thuzad orchestriert wurden, was zu Massenopfern und riesigen Massengräbern führte, noch bevor Prinz Arthas jemals eintraf, um Nachforschungen anzustellen.",al={"lebten menschen in brill","lebendige geschichte von brill","wer lebte in brill"}},["7b7ff5e2"]={q="Was ist die Taverne Zur Galgenschlinge?",a="Die Taverne Zur Galgenschlinge ist der zentrale Treffpunkt und das Gasthaus von Brill. Sie bietet Schutz, üble Getränke und eine Atempause vor den düsteren Wäldern außerhalb. In ihren dunkleren Ecken halten die Verlassenen gefangene Feinde – wie etwa die Eiferer des The Scarlet Crusade – für finstere Versuche der Apotheker gefangen.",al={"taverne zur galgenschlinge","gasthaus von brill","was ist die taverne zur galgenschlinge"}},["0d8014ee"]={q="Was hat es mit Agamands Mühlen auf sich?",a="Agamands Mühlen war einst das wohlhabendste und produktivste landwirtschaftliche Anwesen in Tirisfal, berühmt für Mehl und Getreide. Als die Seuche zuschlug, wurde der gesamte Komplex überrannt und ein Gemetzel folgte. Heute steht es als eine verrottende, von Windmühlen gesäumte Ruine da, die von den untoten Dienern der Geißel heimgesucht wird.",al={"hintergrundgeschichte von agamands mühlen","was geschah mit agamands mühlen","agamands mühlen"}},["001d4abe"]={q="Wer waren die Agamands?",a="Die Agamands waren eine adelige, wohlhabende menschliche Dynastie, die die weitläufigen Mühlen entwickelte und Grundbesitz in ganz Tirisfal hielt, einschließlich Brill. Während des Dritten Krieges konnte ihr Reichtum sie nicht retten; die Familie fiel der Geißel zum Opfer und ihre reanimierten Patriarchen suchen weiterhin das Anwesen heim.",al={"familie agamand","wer lebte in agamands mühlen","die agamands"}},eeb96a2c={q="Warum sind sie uns gegenüber feindselig, wenn sie auch Untote sind?",a="Die Untoten, die Agamands Mühlen heimsuchen, haben ihren freien Willen nie wiedererlangt. Im Gegensatz zu den Verlassenen, die sich von der mentalen Kontrolle des Lichkönigs befreit haben, bleiben diese Kreaturen als gedankenlose Sklaven der Geißel gefangen, gezwungen, jeden Lebenden oder abtrünnigen Toten zu vernichten, der ihr Gebiet betritt.",al={"warum greifen die agamands uns an","warum sind die untoten der agamands feindselig","warum gegen andere untote kämpfen"}},a357af07={q="Wohin führt das alles nach Tirisfal?",a="Die meisten Verlassenen reisen durch den Gebirgspass nach Süden in den Silberwald, um bei der Sicherung der südlichen Grenze zu helfen und gegen Agenten von Dalaran und Rot Hide-Gnolle zu kämpfen. Alternativ bieten Zeppeline südlich von Brill eine Passage nach Orgrimmar oder zum Basislager Grom'gol auf der anderen Seite des Meeres.",al={"wohin nach tirisfal","nächstes gebiet nach tirisfal","nach tirisfal"}},["50336b90"]={q="Was ist die Unterstadt?",a="Die Unterstadt ist die weitläufige unterirdische Hauptstadt der Verlassenen, erbaut innerhalb der alten Abwasserkanäle, Krypten und Katakomben unter den zerstörten Ruinen von Lordaeron. Sie dient als Festung von Königin Sylvanas und als Command Center für die Operationen der Verlassenen in ganz Azeroth.",al={"was ist die unterstadt","hintergrundgeschichte der unterstadt","über die unterstadt"}},ddddba9f={q="Ist die Grenze zum Silberwald als Nächstes dran?",a="Ja. Wenn Ihr der Straße nach Süden aus Tirisfal folgt, gelangt Ihr direkt in den Silberwald. Dies ist die natürliche Fortsetzung Eures Dienstes für die Verlassenen, wo Ihr Euch der wachsenden Bedrohung entlang der südlichen Grenzen von Lordaeron stellt.",al={"als nächstes in den silberwald","gehe ich als nächstes in den silberwald","grenze zum silberwald"}},["789ead4d"]={q="Wie bin ich in Tirisfal gelandet?",a="Wenn Ihr ein neu erweckter Verlassener seid, seid Ihr während des Falls von Lordaeron an die Geißel gestorben und hier begraben worden. Da der Griff des Lichkönigs gebrochen ist, kehrte Euer freier Wille zurück und Ihr habt Euch aus dem Grab im abgelegenen Tal von Todesend herausgekämpft. Wenn Ihr zu den anderen Völkern der Horde gehört, seid Ihr wahrscheinlich über die Zeppeltürme zwischen Brill und der Unterstadt angekommen, die dieses verseuchte Reich direkt mit Orgrimmar und dem Basislager Grom'gol verbinden.",al={"wie bin ich hierher gekommen","wie bin ich nach tirisfal gekommen","wie bin ich angekommen"}},["89135166"]={q="Was soll ich in Tirisfal tun?",a="Euer Ziel ist es, den Verlassenen dabei zu helfen, ihren brüchigen Halt über die verseuchten Herzlande von Lordaeron zu sichern. Von den Krypten von Todesend in Richtung Brill müsst Ihr die gedankenlose Geißel ausmerzen, die verlassene Bauernhöfe heimsucht, die fanatischen Eiferer des The Scarlet Crusade ausschalten, die aus dem Norden vordringen, und die verseuchten Bestien ausdünnen, die durch die verrottenden Wälder streifen. Dies beweist Euren Wert für Fürstin Sylvanas und bereitet Euch darauf vor, ihrem wachsenden Königreich unter den Ruinen von Capital City zu dienen.",al={"was soll ich hier tun","warum bin ich in tirisfal","was ist mein ziel hier"}}},fp="15,338,18.442.0,19.456.0,26.372.0,42.269.0,65.287.0,53.289.0,39.222.0,53.244.0,53.247.0"}
P.entries["zone:undercity"] = {n="Unterstadt",s="Tief unter den zerschlagenen Ruinen der Hauptstadt von Lordaeron liegt Unterstadt, die dunkle Festung der Verlassenen. Ursprünglich von der Geißel aus uralten königlichen Krypten und Kerkern geschlagen, wurde sie von Fürstin Sylvanas Windläufer eingenommen und in eine uneinnehmbare unterirdische Zuflucht verwandelt. Heute dient sie als Sitz der Macht der Verlassenen und als lebenswichtige Bastion der Horde in den nördlichen Östlichen Königreichen.",h="Tief unter den zerschlagenen Ruinen der Hauptstadt von Lordaeron liegt Unterstadt, die dunkle Festung der...",kw={"das apothekarium","arthas","verlassene","lordaeron","geißel","sylvanas","terenas","tirisfal","unterstadt","varimathras"},ang={["faction:Horde"]="Als wichtigster Stützpunkt der Horde in den Östlichen Königreichen sichert Unterstadt direkte Zeppelinverbindungen zurück nach Durotar und in das Basislager Grom'gol.",["race:Human"]="Unter dem Boden Eures gefallenen angestammten Königreichs liegt eine düstere Verkehrung der königlichen Krypten von Lordaeron, besetzt von den wandelnden Leichen Eurer einstigen Brüder.",["race:Orc"]="Tief in diesen Verliesen war einst der legendäre Kriegshäuptling Orgrim Schicksalshammer von der Allianz von Lordaeron eingekerkert, ehe ihm seine historische Flucht gelang.",["race:Undead"]="Unterstadt ist Eure souveräne Zuflucht und Heimat, mit Euren eigenen Händen erbaut, nachdem Ihr den eisernen Griff des Lichkönigs über Euren Verstand gebrochen hattet."},sec={{t="Von königlichen Krypten zur Schanze der Geißel",b="Lange bevor die Seuche über Lordaeron hereinbrach, waren die Katakomben, Verliese und Abwasserkanäle unter dem Palast kollektiv als Unterstadt bekannt. Sie bargen die Gräber des Adels, die tiefsten Kerker des Königreichs – in denen der ehemalige Kriegshäuptling Orgrim Schicksalshammer einst vor seiner Flucht eingesperrt war – und die ärmsten Bewohner des Reiches. Als Arthas Menethil im Jahr 20 n. d. P. König Terenas ermordete und die Hauptstadt verwüstete, befahl der Prinz seinen untoten Dienern, die unterirdischen Gänge auszuheben und zu einem befestigten Herrschaftssitz der Geißel auszubauen."},{t="Aufstieg der Verlassenen",b="Die Geißel erlebte die Vollendung ihrer dunklen Hauptstadt nie. Als die Mächte des Lichkönigs nach der Schlacht um den Hyjal schwanden, riss sich Fürstin Sylvanas Windläufer vom Schwarmbewusstsein los und riss Tausende von Untoten mit sich. Sie lockte Arthas in einen Hinterhalt und trieb ihn nach Nordend zurück. Nach einem erbitterten Dreifronten-Bürgerkrieg gegen Überreste der Geißel, Schreckenslords und den menschlichen Widerstand beanspruchte Sylvanas die halbfertigen Katakomben für sich. Sie gab ihrem Volk den Namen die Verlassenen und leitete die jahrelangen Arbeiten zur Fertigstellung der weitläufigen unterirdischen Stadt."},{t="Architektur der Verdammten",b="Unterstadt ist in konzentrischen Ringen angelegt, die in funktionale Viertel unterteilt sind. In ihrem Herzen liegt das Handwerksviertel, das über gewaltige Aufzüge mit den Palastruinen darüber verbunden ist. Darum herum liegen das Kriegsviertel, das Schurkenviertel, das Magieviertel und das giftige Apothekarium, wo die Königliche Apothekervereinigung in von grünem Schleim gefüllten Kanälen bösartige Seuchen braut. Noch tiefer liegt das Königsviertel, wo die Bansheekönigin an der Seite ihres Schreckenslord-Kommandanten Varimathras Hof hält, bewacht von Legionen turmhoher Monstrositäten."}},faq={{q="Was war Unterstadt, bevor die Untoten sie übernahmen?",a="Unter dem Palast von Lordaeron lagen die uralten Krypten des menschlichen Königshauses sowie der Kerkerkomplex der Stadt und ein gewaltiges Kanalisationsnetz. Es beherbergte Kriegsgefangene, darunter Orgrim Schicksalshammer, sowie verarmte Bürger, die in den unterirdischen Schatten hausten. Nach der Plünderung der Hauptstadt begann Prinz Arthas, diese Katakomben in eine Festung der Geißel zu verwandeln, bevor Sylvanas sie eroberte.",al={"ursprünge von unterstadt","was war unterstadt ursprünglich","geschichte der kanalisation von lordaeron"}},{q="Warum wurde die Stadt unter der Erde erbaut statt an der Oberfläche?",a="Die oberirdische Stadt von Lordaeron wurde während des Dritten Krieges vollkommen zerstört, was eine Verteidigung gegen den Scharlachroten Kreuzzug, Streitkräfte der Geißel und Überlebende der Allianz erschwerte. Die unterirdischen Tunnel boten natürliche Befestigungen, Engpässe und Geheimhaltung, was es den Verlassenen ermöglichte, die ursprünglichen Bauarbeiten der Geißel zu vollenden und im Verborgenen zu gedeihen.",al={"warum unterirdisch leben","warum lordaeron nicht wiederaufbauen","warum unterstadt unter ruinen liegt"}},{q="Wer herrscht über Unterstadt?",a="Die Stadt wird von Fürstin Sylvanas Windläufer regiert, der Bansheekönigin und Königin der Verlassenen. Sie herrscht vom Königsviertel aus, bewacht von königlichen Wachen der Verlassenen und ihrem unterworfenen Schreckenslord-Leutnant Varimathras.",al={"wer ist anführer von unterstadt","herrscher von unterstadt","wer regiert unterstadt"}},{q="Was ist das Denkmal für König Terenas in den Ruinen darüber?",a="Über den Hauptaufzügen der Stadt befindet sich ein steinernes Denkmal für den ermordeten König Terenas Menethil II. Es enthält nicht seinen Leichnam, da dieser eingeäschert und seine Asche während Kel'Thuzads Wiedererweckung verstreut wurde. Überlebende Menschen der Allianz meißelten das Monument mutig inmitten der Ruinen, damit die Erinnerung an Lordaerons letzten wahren König fortbesteht.",al={"könig terenas grab","thronsaal grab lordaeron","wer baute das grab über unterstadt"}},{q="Was sind die seltsamen Geräusche im Thronsaal von Lordaeron?",a="Im zerstörten Thronsaal über den Aufzügen von Unterstadt hallen noch immer spektrale Echos der Vergangenheit nach. Besucher, die im Zentrum stehen, können leise Geistergeräusche vernehmen: die feierlichen Glocken und Rosenblüten bei Arthas' Rückkehr, die warnenden Worte des Propheten Medivh und das letzte Gespräch zwischen König Terenas und seinem vatermörderischen Sohn.",al={"geistergeräusche thronsaal","flüstern im thronsaal","stimmen im thronsaal von lordaeron"}},{q="Warum dulden die Verlassenen andere Mitglieder der Horde hier?",a="Die Verlassenen schlossen aus reinem Überlebenstrieb ein Zweckbündnis mit Kriegshäuptling Thralls Horde, umringt wie sie von feindseligen scharlachroten Eiferern und Legionen der Geißel waren. Obwohl lebende Völker der Horde die giftigen Dämpfe und alchemistischen Flüsse als erstickend empfinden, wird Abgesandten und Reisenden Zutritt gewährt, um diplomatische und militärische Bande zu pflegen.",al={"warum orcs in unterstadt sind","horde in unterstadt","warum unterstadt zur horde gehört"}}},fx={a590d153={q="Was ist die Unterstadt?",a="Die Unterstadt ist die unterirdische Hauptstadt der Verlassenen, die direkt unter den zerstörten Ruinen der Hauptstadt in Tirisfal erbaut wurde. Sie wurde aus alten königlichen Krypten, Abwasserkanälen und Katakomben herausgehauen und von Prinz Arthas als Festung der Geißel ausgebaut, bevor Fürstin Sylvanas Windläufer und ihre abtrünnigen Untoten sie während des Bürgerkriegs einnahmen. Heute dient sie als befestigter Zufluchtsort für Untote mit freiem Willen, durchzogen von giftigem Schlamm und wachsam bewacht gegen alle lebenden Eindringlinge.",al={"was ist die unterstadt","erzähl mir von der unterstadt","unterstadt hintergrundgeschichte"}},c51b16b2={q="Was geschah mit dem alten König von Lordaeron?",a="König Terenas Menethil II. wurde im Thronsaal direkt über dieser Stadt von seinem eigenen Sohn, Prinz Arthas, ermordet. Nachdem er aus Nordend zurückgekehrt war, verdorben durch die Runenklinge Frostgram, erschlug Arthas seinen Vater und ließ die Geißel über das Königreich hereinbrechen. Terenas' Asche wurde später vom Todesritter gestohlen, um Kel'Thuzad wiederzubeleben, wobei nur der Gedenkstein und die getrocknete Blutspur zurückblieben, die Ihr noch immer in der Nähe des zerstörten Throns sehen könnt.",al={"schicksal von könig terenas","was geschah mit könig terenas","wer tötete könig terenas"}},c11144c7={q="Wer war Arthas?",a="Arthas Menethil war der Kronprinz von Lordaeron und ein berühmter Paladin der Silbernen Hand. In seinem verzweifelten Versuch, die Plage des Untodes, die seine Heimat überrollte, aufzuhalten, wurde sein Kreuzzug rücksichtslos und fanatisch. In Nordend bemächtigte er sich der verfluchten Runenklinge Frostgram, die seine Seele verschlang und ihn zum schrecklichen Champion des Lichkönigs machte. Er kehrte nur nach Hause zurück, um seinen Vater abzuschlachten, Lordaeron dem Erdboden gleichzumachen und schließlich nach Norden zurückzukehren, um mit dem Frostthron zu verschmelzen.",al={"wer ist arthas","prinz arthas hintergrund","arthas menethil"}},["7f6bbd49"]={q="Wer ist Sylvanas Windläufer?",a="Fürstin Sylvanas Windläufer war einst die tapfere Waldläufergeneral von Silbermond, die Quel'Thalas während des Dritten Krieges gegen die Geißel verteidigte. Als sie fiel, riss Arthas ihre Seele aus ihrem Körper und verwandelte sie in eine Banshee, um sie zu quälen. Als der Griff des Lichkönigs schwächer wurde, brach sie frei, nahm ihre körperliche Form zurück und scharte andere unabhängige Untote um sich, die Verlassenen. Jetzt regiert sie als ihre Bansheekönigin vom Königsviertel aus.",al={"wer ist die bansheekönigin","sylvanas hintergrund","wer ist sylvanas"}},["2a8de90f"]={q="Warum wird Sylvanas die Dunkle Fürstin genannt?",a="Die Verlassenen ehren Sylvanas als die Dunkle Fürstin, weil sie sie aus der sinnlosen Knechtschaft des Lichkönigs befreit und ihnen Zuflucht gewährt hat, als der Rest von Azeroth nach ihrer totalen Ausrottung strebte. Der Beiname wird neben ihrem Titel als Bansheekönigin verehrt und spiegelt sowohl ihre schattenhafte Meisterschaft über den Tod als auch die wilde, unnachgiebige Hingabe ihrer untoten Untertanen wider.",al={"warum dunkle fürstin","titel dunkle fürstin sylvanas","bedeutung dunkle fürstin"}},["84f18f47"]={q="Warum sind die Verlassenen Teil der Horde?",a="Umgeben von feindseligen Scharlachroten Kreuzzüglern, der unerbittlichen Geißel und rachsüchtigen Überresten der Allianz, konnten die Verlassenen in Lordaeron nicht allein überleben. Fürstin Sylvanas nahm über das Meer Kontakt mit Kriegshäuptling Thrall auf und schmiedete ein pragmatisches Zweckbündnis. Die Horde gewann einen entscheidenden militärischen Stützpunkt in den Östlichen Königreichen, während die Verlassenen wesentliche Verstärkungen und politische Legitimität in ihrem Überlebenskampf sicherten.",al={"warum sind die verlassenen bei der horde","untote treten der horde bei","verlassene horde allianz"}},["71200045"]={q="Was ist die Geißel und sind sie noch in der Nähe?",a="Die Geißel ist die riesige, gefräßige Armee aus sinnlosen Untoten, die von der Brennenden Legion erschaffen wurde und vom Lichkönig aus Nordend regiert wird. Obwohl die Verlassenen die Unterstadt und Tirisfal ihrem Griff entrissen haben, bleibt die Geißel eine unmittelbare, tödliche Gefahr. Ihre Legionen unter dem Kommando von Kel'Thuzad ersticken noch immer die nahegelegenen Pestländer und befallen verlassene Gehöfte und Krypten in Tirisfal.",al={"ist die geißel in der nähe","was ist die geißel","geißel in lordaeron"}},["501548ab"]={q="Wo ist der Lichkönig jetzt?",a="Der Lichkönig residiert auf dem Frostthron in den fernen, eisigen Einöden von Nordend. Nach dem Bürgerkrieg in den Pestländern floh Prinz Arthas aus Lordaeron, um seinen schwächer werdenden Meister zu beschützen. Er bestieg den Gletscher und verschmolz ihre Essenzen zu einer einzigen schrecklichen Entität. Von dieser arktischen Bastion aus wacht sein eisiger Blick noch immer über Azeroth.",al={"wo ist der lichkönig","standort des lichkönigs","wo ist arthas jetzt"}},["4cc7f971"]={q="Wer ist der Scharlachrote Kreuzzug?",a="Der Scharlachrote Kreuzzug ist ein fanatischer Orden menschlicher Eiferer, der aus den Ruinen der Verteidigung von Lordaeron hervorgegangen ist. Geblendet von ihrem rechtschaffenen Hass auf die Untoten, unterscheiden sie nicht zwischen der sinnlosen Geißel und den Verlassenen mit freiem Willen. Sie betrachten jeden, der vom Untod gezeichnet ist – sowie jeden lebenden Außenseiter, der sie toleriert – als abscheuliche Kreaturen, die nur auf den Scheiterhaufen gehören. Ihre Hauptbastion in Tirisfal ist das Scharlachrote Kloster.",al={"wer ist der scharlachrote kreuzzug","scharlachrote kreuzzügler","scharlachroter kreuzzug hintergrund"}},["271820ed"]={q="Ist die Unterstadt gefährlich?",a="Sie ist außerordentlich gefährlich, besonders für Lebende. Kanäle mit rohen alchemistischen Abfällen und giftigem Schlamm durchziehen die Straßen der Stadt und füllen die höhlenartigen Hallen mit giftigen Dämpfen, die das Atmen für Besucher aus Fleisch und Blut gefährlich machen. Unter den gepflasterten Vierteln liegen verseuchte Abwasserkanäle, und noch tiefer finden geheime Experimente statt, bei denen täglich dunkle Alchemie und rücksichtslose Attentate geplant werden.",al={"ist die unterstadt sicher","gefahr in der unterstadt","gefahren in der unterstadt"}},["2539a3c3"]={q="Wie bin ich in der Unterstadt gelandet?",a="Als ein Verlassener führte Euer Weg Euch natürlich hierher, nachdem Ihr in Todesend aus dem Tod erwacht seid und Eure Loyalität in Tirisfal bewiesen habt, indem Ihr den Straßen vorbei an Brill gefolgt seid, um unter die zerstörten Ruinen der Hauptstadt hinabzusteigen. Wenn Ihr aus Kalimdor oder fernen Ländern stammt, seid Ihr wahrscheinlich an Bord eines Zeppelins der Horde angekommen, der an den Türmen direkt außerhalb der Hauptstadt anlegt, oder Ihr seid durch die verheerte Landschaft gewandert. Die Unterstadt ist der wichtigste Stützpunkt der Horde im nördlichen Lordaeron und bietet Schutz und Bestimmung unter den alten Palastkatakomben.",al={"wie bin ich hierher gekommen","wie erreiche ich die unterstadt","wie kommt man in die unterstadt"}},b63c4cf2={q="Was soll ich in der Unterstadt tun?",a="Ihr seid hier, um die Verlassenen zu unterstützen und die Stärke der Horde gegen die Gefahren zu versammeln, die Lordaeron umgeben. Innerhalb der konzentrischen Viertel der Stadt könnt Ihr Klassenlehrer aufsuchen, Vorräte erwerben und die dunklen Forscher der Royal Apothecary Society konsultieren. Jenseits Eures Handwerks ist es Eure Pflicht, Aufträge für Fürstin Sylvanas Windläufer und ihre Leutnants anzunehmen. Die Verlassenen führen einen Krieg an mehreren Fronten: die Überreste der sinnlosen Geißel säubern, den fanatischen Scharlachroten Kreuzzug zurückschlagen und sicheren Boden für die Untoten mit freiem Willen sichern, damit sie überdauern können.",al={"was mache ich hier","was soll ich in der unterstadt tun","warum bin ich hier"}}},fp="9,318,36.556.0,20.416.0,26.421.0,54.450.0,60.340.0,24.362.0,51.333.0,57.328.0,51.322.0"}
P.entries["zone:ungoro"] = {n="Krater von Un'Goro",s="Der Krater von Un'Goro ist ein versunkener, urzeitlicher Dschungel, der zwischen den trockenen Einöden von Tanaris und Silithus eingebettet liegt. Beherrscht von umherstreifenden Dinosauriern, lebenden Elementaren und einem zentralen Vulkan, ist diese üppige Caldera reich an uralten Titanenrelikten und Machtkristallen, deren Ursprünge ein tiefes Geheimnis bleiben.",h="Der Krater von Un'Goro ist ein versunkener, urzeitlicher Dschungel, der zwischen den trockenen Einöden von...",kw={"teufelssaurier","feuersäulengrat","goetterlaender","lakkari","marschalls zuflucht","machtkristalle","torwa pfadfinder","ungoro","krater von ungoro"},ang={["class:Druid"]="Druiden des Zirkels des Cenarius erforschen Un'Goros isoliertes Ökosystem und ernten seine fruchtbare Erde, um Morgenkorn zu vermehren, mit dem Ziel, die reine, ungezähmte Lebenskraft zu verstehen, die die Caldera speist.",["faction:Alliance"]="Naturforscher der Allianz sammeln sich um Williden Marschall und J.D. Collie in Marschalls Zuflucht und wetteifern darum, die Pylonen der Titanen zu entschlüsseln, während sie gleichzeitig Darnassus-Forscher beim Sammeln von Bodenproben beschützen.",["faction:Horde"]="Abenteurer der Horde reisen oft über Tanaris an, um ihr Können an legendären Teufelssauriern zu messen und den Kräuterkundigen von Donnerfels dabei zu helfen, Morgenkorn aus Un'Goros urzeitlicher Erde zu züchten.",["profession:Herbalism"]="Die reiche Feuchtigkeit des Beckens erhält seltene Flora und macht es zu einem der wenigen Orte in Kalimdor, an denen Erdenwurzel, Traumblatt und Goldener Sansam zusammen mit der Feuerblüte an den Hängen des Vulkans gedeihen.",["profession:Mining"]="Die steilen Kraterwände und die Felsen des Feuersäulengrats sind dicht mit Mithrilvorkommen und Reichen Thoriumadern besetzt, was die Zone zu einem erstklassigen Ziel für hochwertige Erze macht."},sec={{t="Die Götterländer",b="Eingebettet zwischen Wüstenweiten trotzt der Krater von Un'Goro der Geographie des südlichen Kalimdor. Uralte Aufzeichnungen der Nachtelfen über den Krieg der Sandstürme belegen, dass die insektoiden Qiraji an den Rändern des Kraters zurückgeschlagen wurden, unfähig, in das vorzudringen, was ihre Sprache als die „Götterländer“ bezeichnete. Gelehrte stellen Theorien auf, wonach die Caldera den Titanen während der Formung von Kalimdor als Testgelände oder uralte Wohnstätte diente. Entlang der Grate erheben sich steinerne Pylonen, die vor Energie summen, während Kristallformationen in Blau, Rot, Grün und Gelb aus der urzeitlichen Erde sprießen."},{t="Ein wildes Ökosystem",b="Un'Goro beherbergt keine Städte, Dörfer oder einheimische humanoide Gesellschaften. Stattdessen gedeiht das Leben in einem ungezähmten, urzeitlichen Zustand. Spitzenprädatoren wie Teufelssaurier durchstreifen die Weiten der Terrorflucht, räuberische Blutblüten peitschen in den Marschen um sich, und Schleime kriechen über die Teergruben von Lakkari. Im Herzen des Kraters ragt der Feuersäulengrat empor, ein aktiver Vulkangipfel voller feindseliger Feuerelementare, angeführt von dem Wesen Feuerläufer. Für Entdecker und Kürschner bietet das Becken einen unübertroffenen natürlichen Reichtum – einschließlich der begehrten Bälge von Teufelssauriern –, vorausgesetzt, man überlebt die Nahrungskette."},{t="Marschalls Zuflucht",b="Die zivilisierte Präsenz im Krater beschränkt sich fast ausschließlich auf Marschalls Zuflucht, ein erhöhtes Lager in den nördlichen Klippen. Angeführt von Williden Marschall versuchte eine Expedition aus Wissenschaftlern, Naturforschern und Glückssuchern, die Schätze des Beckens zu katalogisieren, nur um von der monströsen Tierwelt heimgesucht und auf höher gelegenes Gelände vertrieben zu werden. Heute dient die Zuflucht als umkämpfter Stützpunkt für unerschrockene Reisende, die die geheimnisvollen Machtkristalle des Kraters studieren, die vulkanische Aktivität kartieren und ein wachsames Auge auf die vordringenden Silithidenschwärme haben, die die südlichen Grate durchbrechen."}},faq={{q="Wie gelangt Ihr in den Krater von Un'Goro?",a="Reisende können über natürliche Rampen hinabsteigen, die die Kraterwände hinunterführen: Eine ist von der südwestlichen Ecke von Tanaris nahe dem Disteltal aus zugänglich, eine andere führt aus dem nordöstlichen Silithus hinein. Während waghalsige Abenteurer zuweilen die Klippen hinabspringen, endet der Sturz ohne magische Unterstützung tödlich. Marschalls Zuflucht im Norden bietet Flugverbindungen nach Gadgetzan und Burg Cenarius.",al={"wie man ungoro betritt","ungoro eingang","wie man den krater von ungoro erreicht"}},{q="Wofür werden die farbigen Machtkristalle verwendet?",a="Über den Dschungelboden verstreut liegen rote, blaue, grüne und gelbe Machtkristalle. Unter Anleitung der Gnomforscherin J.D. Collie in Marschalls Zuflucht können Forscher Anweisungen zur Nutzung dieser Kristalle am Nördlichen, Östlichen und Westlichen Pylon entschlüsseln. Die Kombination bestimmter Farben an den entsprechenden Pylonen nutzt latente Titanenenergien, um schützende oder wiederherstellende Talismane herzustellen.",al={"ungoro kristalle","rote blaue gruene gelbe kristalle ungoro","machtpylonen"}},{q="Warum ist Un'Goro trotz der umgebenden Wüsten so üppig?",a="Gelehrte glauben, dass Un'Goros unnatürliche Lebenskraft künstlich ist und von den Titanen herrührt, die die Welt formten. Titanische Leitungen, warme vulkanische geothermische Aktivität vom Feuersäulengrat und uralte Ley-Energie nähren ein isoliertes, extrem beschleunigtes Ökosystem, das den ariden Bedingungen des benachbarten Tanaris und Silithus trotzt.",al={"warum ist ungoro ein dschungel","ungoro wuesten verbindung","wie hat ungoro pflanzen"}},{q="Warum nannten die Qiraji diesen Ort die „Götterländer“?",a="Laut Tafeln, die aus dem Krieg der Sandstürme übersetzt wurden, hielten die Insektenschwärme ihren Vormarsch an der Schwelle des Kraters an. Geologe Larksbane, der den Bericht übersetzte, verknüpft den Namen mit Theorien, wonach die Titanen einst im Krater weilten, und fragt sich, ob Aman'Thul selbst über die Götterländer wachte.",al={"goetterlaender bedeutung","qiraji ungoro","warum konnten die silithiden ungoro nicht einnehmen"}},{q="Wofür wird Un'Goro-Erde verwendet?",a="Haufen fruchtbarer, wirkmächtiger Erde liegen im gesamten Kraterbecken. Nach der Ernte kann diese Erde mit Tharlendris-Samen in einem Immergrünbeutel kombiniert werden, um Morgenkorn heranzuzüchten – ein mystisches Kraut, das von Forschern in Donnerfels, Darnassus und dem Zirkel des Cenarius heiß begehrt wird.",al={"ungoro erdenprobe","was bewirkt ungoro erde","morgenkorn erde"}},{q="Gibt es hier humanoide Siedlungen oder Dungeons?",a="Der Krater von Un'Goro beherbergt einen Dungeon, Die Terrasse des Formers, für etwa die Stufen 58 bis 60, aber keine einheimischen humanoiden Gesellschaften. Die einzige dauerhafte Siedlung ist Marschalls Zuflucht, ein kleiner Expeditionsaußenposten am nördlichen Rand. Abgesehen von vereinzelten Einsiedler-Jägern oder verirrten Forschern ist der Rest der Caldera vollkommen wild.",al={"ungoro dungeons","wer lebt in ungoro","humanoide in ungoro"}}},fp="14,269,13.410.0,18.462.0,16.490.0,35.282.0,45.336.0,56.270.0,51.330.0,30.235.0,52.287.0"}
P.entries["zone:wailing"] = {n="Die Höhlen des Wehklagens",s="Verborgen unter Der blühenden Oase im dürren Brachland liegen Die Höhlen des Wehklagens, ein labyrinthisches System unterirdischer Quellen und Klüfte, benannt nach dem unheimlichen Pfeifen des eingeschlossenen Dampfes. Was als edles druidisches Bestreben begann, Kalimdors sonnengebleichte Savanne wiederzubeleben, hat sich zu einer verzerrten, giftigen Unterwelt entwickelt. Die Höhlen wimmeln nun von entstellter Tierwelt und gefallenen Jüngern, die von einem tiefen, unnatürlichen Alptraum korrumpiert wurden.",h="Verborgen unter Der blühenden Oase im dürren Brachland liegen Die Höhlen des Wehklagens, ein labyrinthisches...",kw={"deviat","druiden des giftzahns","smaragdgrüner alptraum","lady anakondra","lord kobrahn","lord pythas","lord serpentis","die blühende oase","mutanus","naralex","verdan"},ang={["class:Druid"]="Für Druiden sowohl der Tradition des Cenarius als auch des Pfades der Tauren sind die Höhlen eine tragische Warnung vor den Gefahren im Smaragdgrünen Traum und eine feierliche Pflicht, ihre gefallenen Brüder, die Druiden des Giftzahns, zu läutern.",["race:NightElf"]="Naralex war eine verehrte Persönlichkeit unter den Nachtelfen-Druiden, und die Tragödie seiner Korrumpierung durch den Smaragdgrünen Alptraum stellt eine schmerzhafte Katastrophe für sein Volk jenseits des Meeres dar.",["race:Tauren"]="Die vergifteten Gewässer bedrohen die zerbrechlichen Oasen, die das Leben im gesamten Brachland erhalten, weshalb die Reinigung der Quellen für die Stämme von Mulgore und Das Wegekreuz von entscheidender Bedeutung ist."},sec={{t="Eine edle Vision wird giftig",b="Der Nachtelfen-Druide Naralex entdeckte ursprünglich dieses gewaltige Wassersystem und fasste einen ehrgeizigen Plan: Indem er einen Kanal direkt in Den Smaragdgrünen Traum öffnete, wollte er reine, urtümliche Lebensessenz durch die unterirdischen Quellen leiten und das ausgedörrte Brachland wieder in ein blühendes, fruchtbares Paradies verwandeln. Tief in den Höhlen versank Naralex in Trance zur Zwiesprache mit dem Traum, verankert durch seine treuen Akolythen. Tragischerweise berührte der schlafende Geist des Druiden, anstatt reine Vitalität anzuzapfen, den Smaragdgrünen Alptraum. Die schwärende Verderbnis ergriff sofort Besitz von ihm und verwandelte seinen wohlmeinenden Kanal in ein Ventil, das Gift und Wahnsinn in die unterirdischen Wasserwege goss."},{t="Die Druiden des Giftzahns",b="Als die dunkle Energie des Alptraums von Naralex' hilfloser Gestalt ausstrahlte, erlagen seine Schüler dem Wahnsinn. Sie sagten sich von der friedvollen Weisheit des Zirkels des Cenarius los und gründeten die fanatischen Druiden des Giftzahns. Die Anführer der Sekte – Lady Anakondra, Lord Kobrahn, Lord Pythas und Lord Serpentis – nahmen reptilienartige Gestalten an und nahmen die giftige Mutation der Höhlen an, anstatt sie zu bekämpfen. Sie schirmen ihren schlafenden Meister aktiv vor jeglicher Einmischung von außen ab, im Glauben, dieses entstellte Wachstum sei die wahre Evolution der Natur."},{t="Der fleischgewordene Alptraum",b="Den Griff der Druiden des Giftzahns zu brechen, rettet Naralex nicht automatisch. Wenn seine verbliebenen, unkorrumpierten Jünger am Dreamer's Rock das Ritual einleiten, um ihn sanft aus seiner Trance zu wecken, stößt das sich windende Unterbewusstsein des schlummernden Elfen gewaltsam seinen tiefsten Schrecken aus. Die Kreatur, die daraus hervorbricht – ein monströser, entstellter Murloc namens Mutanus der Verschlinger –, ist die physische Manifestation von Naralex' schlimmsten Alpträumen. Nur durch das Erschlagen dieser Abscheulichkeit kann die Verbindung zum Alptraum gekappt werden, was Naralex ermöglicht zu erwachen, die Gestalt eines Vogels anzunehmen und aus den besudelten Höhlen zu fliehen."}},faq={{q="Warum heißen sie Die Höhlen des Wehklagens?",a="Die Höhle verdankt ihren Namen den klagenden, heulenden Schreien, die in den gesamten Tunneln zu hören sind. Diese Geräusche entstehen auf natürliche Weise, wenn unterirdische Dampfschlote und unter hohem Druck stehende Windstöße ihren Weg durch enge Klüfte im Kalksteinfelsen erzwingen.",al={"warum höhlen des wehklagens","ursprung des namens","warum wehklagen sie"}},{q="Was ließ die Bestien im Inneren zu 'Deviat'-Kreaturen werden?",a="Als Naralex dem Einfluss des Smaragdgrünen Alptraums verfiel, drangen die verdorbenen Traumenergien direkt in die unterirdischen Quellen ein. Das Trinken und Leben in diesen kontaminierten Gewässern mutierte die natürlichen Raptoren, Krokilisken und Schlangen zu unnatürlichen 'Deviat'-Varianten.",al={"deviatverderbnis","warum mutieren raptoren","ursprung der deviatbestien"}},{q="Wer sind die Druiden des Giftzahns?",a="Sie waren einst die hingebungsvollen Nachtelfen- und Tauren-Akolythen von Naralex. Gemeinsam mit ihm durch den Alptraum korrumpiert, zerbrach ihr Verstand und verdrehte ihre druidischen Künste zur Verehrung von Schlangen und Gift, wobei sie Titel wie Kobrahn, Pythas und Anakondra annahmen.",al={"giftzahnrudiden","druiden des giftzahns lore","wer ist serpentis"}},{q="Warum ist der Endboss ein riesiger Murloc namens Mutanus?",a="Mutanus erscheint während des Versuchs, Naralex zu erwecken. Sein Wesen und seine Verbindung zum schlafenden Druiden offenbaren sich im Verlauf des Rituals.",al={"warum mutanus murloc","was ist mutanus","endboss lore"}},{q="Was geschieht, nachdem Mutanus besiegt ist?",a="Der Versuch der Jünger, Naralex zu erwecken, geht nach der Konfrontation weiter. Das Schicksal des Druiden offenbart sich am Ende des Rituals.",al={"naralex erwecken","naralex ende","was geschieht mit naralex"}},{q="Wer lebt in der Höhle über dem Höhleneingang?",a="In der totenkopfartigen Felsenaugenhöhle über den Höhlen haben sich Getreue des Zirkels des Cenarius niedergelassen, darunter Nalpak und Ebru. Sie suchen mutige Reisende, um Deviatbälge zu erbeuten und die Verderbnis zu reinigen, bevor sie das Brachland vollständig verschlingt.",al={"höhle über eingang","schlangenschädel auge npcs","wer sind nalpak und ebru"}}},fx={["38e519c2"]={q="Warum macht sich jeder solche Sorgen um diesen Ort?",a="Die unterirdischen Quellen in den Höhlen speisen die primären Oasen, die das Leben im ariden Brachland erhalten. Sollte der Makel des Smaragdgrünen Traums ungehindert in diese Wasserwege sickern, könnten sich die verdrehten Mutationen und der Wahnsinn, die die Flora und Fauna der Höhlen korrumpieren, über die gesamte Region ausbreiten und das Land in einen Albtraum bei Tageslicht verwandeln.",al={"warum sorgen um die höhlen des wehklagens","die höhlen des wehklagens bedrohung für das brachland","wie schlimm sind die höhlen des wehklagens"}},["81917ac6"]={q="Wie bin ich in den Höhlen des Wehklagens gelandet?",a="Ihr seid vom Wegekreuz nach Süden in Die blühende Oase gereist, den Berichten über bizarre Bestien und korrumpiertes Wasser folgend, das durch das Brachland sickerte. Hinter dem üppigen Blattwerk und den Lagern der Kolkar-Zentauren liegt eine gewaltige, schädelförmige Höhle, die in den Fels gehauen wurde. Angelockt durch Hilferufe aus Donnerfels, durch Goblins aus Ratschet, die nach seltsamen Essenzen suchten, oder durch Jünger, die im Auge des Schädels oben kampierten, seid Ihr an den gewundenen Spalten und dem Zischen unterirdischer Geysire vorbei in die stöhnenden Tiefen hinabgestiegen.",al={"wie bin ich hierher gekommen","wie erreiche ich die höhlen des wehklagens","woher bin ich hierher gekommen"}},["28a012f3"]={q="Was soll ich in den Höhlen des Wehklagens tun?",a="Ihr seid hier, um die Korruption zu tilgen, die diese unterirdische Quelle befallen hat. Der Nachtelf-Druide Naralex fiel in einen albtraumhaften Schlaf, als er versuchte, das Brachland wiederzubeleben, was die Kreaturen darin verdrehte und seine Jünger in die giftigen Druiden des Giftzahns verwandelte. Ihr müsst die vier Giftzahnfürsten – Lady Anakondra, Lord Kobrahn, Lord Pythas und Lord Serpentis – zur Strecke bringen, um ihren Griff zu brechen, und dann den verbliebenen Jüngern helfen, Naralex zu wecken, bevor sein fiebriger Albtraum die Oase vollständig verschlingt.",al={"was ist mein ziel hier","warum bin ich in den höhlen des wehklagens","was mache ich hier unten"}},["3386ab3f"]={q="Was sind Die Höhlen des Wehklagens?",a="Die Höhlen des Wehklagens sind ein weitläufiges unterirdisches Höhlensystem, das unter dem trockenen Brachland, nahe der blühenden Oase, verläuft. Seine natürlichen unterirdischen Quellen leiten Wasser kilometerweit unter der Erde und speisen die seltenen Oasen an der Oberfläche, die über die Region verstreut sind. Entdeckt von dem Nachtelf-Druiden Naralex, sollten sie das Herz eines großen Projekts zur natürlichen Regeneration werden. Stattdessen wurden sie zu einem Epizentrum gefährlicher Verderbnis, nachdem eine tragische Katastrophe die Druiden darin ergriffen hatte.",al={"was sind die höhlen des wehklagens","übersicht der höhlen des wehklagens","über die höhlen des wehklagens"}},e070a543={q="Wer lebt dort unten?",a="Die Höhlen wimmeln von unnatürlicher Tierwelt und abtrünnigen Druiden. Naralex' korrumpierte Anhänger, die Leaders of the Fang, haben die Tunnel zusammen mit mutierten Schlangen, Schlämmen, Raptoren und Krokilisken als ihr Gebiet beansprucht. Außerhalb des Instanzeingangs lauern wilde Bestien, Schlämme und sogar Ausgestoßene in den feuchten Gängen, während die korrumpierten Druiden die inneren Kammern bewachen und ihren schlafenden Meister beschützen.",al={"wer ist in den höhlen des wehklagens","kreaturen in den höhlen des wehklagens","bewohner der höhlen des wehklagens"}},["49d47201"]={q="Warum hat mich die Horde hierher geschickt?",a="Die seltsamen Mutationen der einheimischen Bestien und die faulen Energien, die aus der blühenden Oase sprudeln, bedrohen das gesamte Brachland. Die Horde und die Cenarion-Druiden von Donnerfels können es nicht dulden, dass eine unkontrollierte dunkle Macht das Land und die Wasserwege direkt vor der Haustür des Wegekreuzes vergiftet. Ihr wurdet ausgesandt, um Nachforschungen anzustellen, den abtrünnigen Leaders of the Fang ein Ende zu bereiten und dabei zu helfen, die wachsende Gefahr zu unterdrücken.",al={"warum bin ich in den höhlen des wehklagens","mission der horde in den höhlen des wehklagens","warum hat man mich in die höhlen des wehklagens geschickt"}},d445bb78={q="Ist das Teil eines größeren Problems im Brachland?",a="Ja. Die unterirdischen Kanäle unter diesen Höhlen speisen die Oasen an der Oberfläche im gesamten Brachland. Die Verderbnis des Alptraums, die das Wasser in den Höhlen korrumpiert, hat begonnen, in die umliegende Landschaft überzulaufen, was dazu führt, dass wilde Kreaturen wie Raptoren und Krokilisken mutieren und die blühende Oase in eine Brutstätte für seltsames Deviatleben verwandelt.",al={"problem mit den oasen im brachland","deviatverderbnis im brachland","beeinflussen die höhlen des wehklagens das brachland"}},["038fd1cf"]={q="Breiten sich die Deviatwesen außerhalb der Höhlen aus?",a="Das tun sie bereits. Die unterirdischen Quellen fließen direkt in oberirdische Oasen wie die blühende Oase und bringen unnatürliches Wachstum und mutierte Kreaturen in die offene Savanne. Seltsame Kreaturen wie Deviatfisch können aus den Gewässern außerhalb gefischt werden, und aggressive mutierte Raubtiere belästigen zunehmend Reisende zwischen den Oasen und dem Wegekreuz.",al={"breiten sich die deviatwesen aus","deviatbestien im brachland","deviatfisch außerhalb"}},["8502642f"]={q="Wer hat hier das Sagen?",a="Während Naralex tief in den Höhlen in seinem korrumpierten Schlummer gefangen liegt, gehört die tägliche Herrschaft über die Höhlen den Druiden des Giftzahns. Sie werden von Lord Serpentis angeführt, einst Naralex' bester Schüler, der seine verdrehten Brüder versammelte, um das Land in ihr eigenes verzerrtes Paradies zu verwandeln, zusammen mit anderen fang lords wie Cobrahn, Pythas und Lady Anakondra.",al={"wer führt die höhlen des wehklagens","anführer der höhlen des wehklagens","boss der höhlen des wehklagens"}},["32be29c8"]={q="Was ist der Smaragdgrüne Traum und wie hängt er mit dieser Höhle zusammen?",a="Der Smaragdgrüne Traum ist ein riesiges Geisterreich, das Azeroth unberührt und wild darstellt, von dem grünen Drachenschwarm behütet und für Druiden zugänglich. Naralex glaubte, er könne die reinen, wiederherstellenden Energien des Traums in die unterirdischen Aquifere der Höhlen des Wehklagens leiten, um üppiges Pflanzenleben im Brachland wiederherzustellen. Als er ihn jedoch anzapfte, wurde er vom Smaragdgrünen Alptraum gefangen genommen, was eine verdrehte Version der Natur in die physischen Höhlen projizierte.",al={"verbindung zum smaragdgrünen traum","höhlen des wehklagens smaragdgrüner traum","naralex smaragdgrüner traum"}}},fp="15,278,31.501.0,22.495.0,24.481.1,37.218.0,50.226.0,31.267.0,51.127.1,39.123.1,52.229.0"}
P.entries["zone:warsonggulch"] = {n="Kriegshymnenschlucht",s="Die Kriegshymnenschlucht ist ein bewaldetes Tal an der Grenze zwischen dem Eschental und dem Brachland und Schauplatz eines Kampfes zwischen Horde und Allianz, der niemals wirklich endet. Orcs des Kriegshymnenklans schlagen dort für die Horde Holz im Eschental, während die Nachtelfen der Feste Silverwing sie aus dem heiligen Wald zu vertreiben versuchen. Kämpfer aller Völker kommen, um mit Schwert oder Zauber beizustehen; jede Seite überfällt die Festung der anderen, um deren Flagge zu erbeuten.",h="Die Kriegshymnenschlucht ist ein bewaldetes Tal an der Grenze zwischen dem Eschental und dem Brachland und...",kw={"kriegshymnenschlucht","schlachtfeld","vorhut des kriegshymnenklans","schildwachen der silberschwingen","feste silverwing","warsong mill","flagge","holz","eschental","grom hellscream"},ang={["faction:Alliance"]="Soldaten der Allianz kämpfen hier für ihre Nachtelfenverbündeten, deren heiliger Wald Baum für Baum den Äxten des Kriegshymnenklans zum Opfer fällt.",["faction:Horde"]="Jeder Baumstamm, der die Warsong Mill verlässt, errichtet irgendwo in Kalimdor eine Mauer der Horde; das Halten der Schlucht sichert den Aufbau der Horde.",["race:NightElf"]="Diese Wälder kennen die Schritte der Kaldorei seit zehntausend Jahren. Jeder aus der Schlucht vertriebene Orc ist ein Stück zurückgewonnenes Eschental.",["race:Orc"]="Der Kriegshymnenklan ist Grom Hellscreams eigenes Volk, und in der Schlucht verdienen sich seine Krieger noch immer ihren Namen, mit der Axt in der Hand gegen die Schildwachen."},sec={{t="Holz und Blut",b="Die Horde baute ihre neue Heimat in Kalimdor aus Holz, und ein Großteil dieses Holzes stammt aus dem Eschental. Der Kriegshymnenklan, Grom Hellscreams Krieger, dringt seit der ersten Landung der Horde in den Wald vor, und ihre Warsong Mill am Ende der Schlucht versorgt die Lager und Mauern der Horde. Für die Nachtelfen verwundet jeder gefällte Baum einen Wald, den sie seit zehntausend Jahren behütet haben, und sie haben nicht vergessen, dass Groms Krieger einst Cenarius in diesen Wäldern erschlugen."},{t="Vorhut und Schildwachen",b="Die Kämpfer der Horde sind hier die Vorhut des Kriegshymnenklans. Sie werden vom Mor'shan-Stützpunkt am nördlichen Rand des Brachlands versorgt, wo Kelm Hargunth sie bewaffnet und verpflegt. Ihnen stellen sich die Schildwachen der Silberschwingen aus der Feste Silverwing entgegen, Nachtelfenkrieger, die geschworen haben, jeden Eindringling aus dem Eschental zu vertreiben. Illiyana Mondflamm versorgt sie vom Hain der Silberschwingen aus. Verbündete beider Seiten strömen in die Schlucht: Zwerge und Menschen stehen den Schildwachen bei, Tauren, Trolle und Verlassene der Vorhut."},{t="Der Kampf um die Banner",b="Jede Seite hält an einem Ende der Schlucht eine Festung: die Kriegshymnenmühle für die Horde und die Feste Silverwing für die Nachtelfen. Dort bewahrt jede Seite ihre Standarte auf. Die Schlacht ist ein Wettstreit um Überfälle: Kämpfer dringen in die feindliche Festung ein, ergreifen deren Flagge und eilen damit zu ihrer eigenen zurück, während die Verteidiger sie verfolgen. Jede heimgebrachte Flagge ist ein Schlag gegen den Stolz des Feindes, und die Seite, die die meisten erbeutet, gewinnt den Tag."}},faq={{q="Was ist die Kriegshymnenschlucht?",a="Die Kriegshymnenschlucht ist ein Schlachtfeld in einem bewaldeten Tal zwischen dem Eschental und dem Brachland. Die Vorhut des Kriegshymnenklans der Horde und die Schildwachen der Silberschwingen der Nachtelfen kämpfen dort um den Holzschlag der Horde im Eschental, wobei jede Seite versucht, die Flagge der anderen zu erobern.",al={"was ist die kriegshymnenschlucht","kriegshymnenschlucht schlachtfeld","wsg"}},{q="Warum kämpft die Horde in der Kriegshymnenschlucht?",a="Die Horde benötigt das Holz des Eschentals, um ihre Heimat in Kalimdor aufzubauen und zu behaupten. Die Sägemühle des Kriegshymnenklans an der Schlucht ist eine ihrer Hauptquellen, und die Vorhut verteidigt sie, damit die Lager und Mauern der Horde weiter wachsen.",al={"horde ziele kriegshymnenschlucht","warum schlagen die orcs holz im eschental","vorhut des kriegshymnenklans beweggrund"}},{q="Warum kämpfen die Nachtelfen in der Kriegshymnenschlucht?",a="Für die Nachtelfen ist das Eschental ein heiliger Wald, den sie seit zehntausend Jahren behütet haben, und der Kriegshymnenklan erschlug dort einst den Halbgott Cenarius. Die Schildwachen der Silberschwingen kämpfen darum, den Holzschlag zu stoppen und die Orcs aus ihren Wäldern zu vertreiben, und der Rest der Allianz steht ihnen zur Seite.",al={"allianz ziele kriegshymnenschlucht","warum kaempfen die schildwachen","schildwachen der silberschwingen beweggrund"}},{q="Wer ist die Vorhut des Kriegshymnenklans?",a="Die Vorhut des Kriegshymnenklans sind die Kämpfer der Horde in der Kriegshymnenschlucht, gestellt vom einst von Grom Hellscream angeführten Kriegshymnenklan. Sie werden vom Mor'shan-Stützpunkt im nördlichen Brachland aus versorgt, wo Kelm Hargunth jene ausrüstet, die für sie kämpfen.",al={"vorhut des kriegshymnenklans","kriegshymnenklan kaempfer","kelm hargunth"}},{q="Wer sind die Schildwachen der Silberschwingen?",a="Die Schildwachen der Silberschwingen sind Nachtelfenkrieger der Feste Silverwing, die geschworen haben, die Horde aus dem Eschental zu vertreiben. Illiyana Mondflamm im Hain der Silberschwingen versorgt die Champions der Allianz, die ihnen in der Schlucht beistehen.",al={"schildwachen der silberschwingen","feste silverwing","illiyana mondflamm"}},{q="Wie wird die Schlacht in der Kriegshymnenschlucht gewonnen?",a="Jede Seite bewahrt ihre Flagge in ihrer eigenen Festung auf. Kämpfer überfallen den Stützpunkt des Feindes, ergreifen dessen Flagge und tragen sie zu ihrer eigenen zurück, während sie ihr eigenes Banner verteidigen, und die Seite, die die meisten Flaggen heimbringt, gewinnt.",al={"kriegshymnenschlucht ziele","flagge erobern kriegshymne","kriegshymnenschlucht gewinnen"}}},fp="13,291,16.424.0,23.488.0,28.315.0,22.226.0,42.201.0,46.259.0,30.223.0,33.216.0,39.193.0"}
P.entries["zone:westernplaguelands"] = {n="Westliche Pestländer",s="Einst die fruchtbare landwirtschaftliche Kornkammer des nördlichen Lordaeron, ersticken die Westlichen Pestländer nun unter giftigem Nebel und Legionen von Untoten. Obwohl Kel'Thuzads Kessel die Höfe und Städte der Region ruinierten, klammert sich der Boden immer noch hartnäckig an das Leben. Die Argentumdämmerung, die Allianz, die Verlassenen und der Scharlachrote Kreuzzug führen allesamt verzweifelte Feldzüge auf ihren verseuchten Feldern.",h="Einst die fruchtbare landwirtschaftliche Kornkammer des nördlichen Lordaeron, ersticken die Westlichen...",kw={"andorhal","das bollwerk","darrowehr","kessel","zugwindlager","herdweiler","burg mardenholde","scholomance","uthers grabmal","westliche pestländer"},ang={["class:Paladin"]="Die entweihten Felder Lordaerons stellen eine düstere Prüfung für heilige Krieger dar; sie bieten Pilgerfahrten zu Uthers Grabmal ebenso wie einen gerechten Krieg gegen die Schrecken von Scholomance und Herdweilers verderbte Fanatiker.",["faction:Alliance"]="Das Zugwindlager dient als vorderste Garnison der Allianz, von wo aus Kommandant Ashlam Faustwacht Feldzüge leitet, um die Pestkessel zu stören und die gefallenen Städte Lordaerons zu rächen.",["faction:Horde"]="Das Bollwerk markiert die Grenze der Souveränität der Verlassenen; von hier aus stößt die Horde nach Osten vor, um Kommandanten der Geißel auszuschalten und scharlachrote Fanatiker an ihrer verwundbaren Flanke zu bekämpfen.",["profession:Herbalism"]="Die verbliebene Verderbnis macht die Region zu einem der wenigen Orte, an denen seltene, gefährliche Pflanzen wie Pestblüte und Arthas' Tränen zwischen verseuchten Kiefernhainen Wurzeln schlagen können."},sec={{t="Die Kornkammer von Lordaeron",b="Vor dem Dritten Krieg war dieses Land ein saftig grüner Korridor aus Bauernhöfen, der sich von Tirisfal ostwärts in Richtung des Darrowmeresees erstreckte. Herdweiler leitete die nördliche Verwaltung von Burg Mardenholde aus, während die weitläufige Stadt Andorhal die Lagerung und den Export von Getreide im gesamten Königreich koordinierte. Diese entscheidende landwirtschaftliche Rolle machte die Region zu Kel'Thuzads Hauptziel. Indem der Kult der Verdammten die Seuche des Untods direkt in die Getreidelieferungen in Andorhal einschleuste, verwandelte er Lordaerons Lebensgrundlage in seinen Untergang."},{t="Ein Land unter Belagerung",b="Um den Boden dauerhaft zu vergiften, errichtete die Geißel vier gewaltige Pestkessel auf den größten landwirtschaftlichen Gütern: Teufelssteinfeld, Dalsons Tränenfeld, Das trostlose Feld und Gahrrons Trauerfeld. Heute warten monströse Kessellords diese giftigen Bottiche, die giftigen Nebel in die Atmosphäre pumpen. Die umliegenden Bäume winden sich vor geschwollenen, tumorartigen Wucherungen, und verseuchte Wildtiere wüten durch das Dickicht. Unterhalb von Darrowehr auf dem Darrowmeresee bildet Dunkelmeister Gandling innerhalb von Scholomance Nekromanten aus und verstärkt so die untote Bedrohung."},{t="Gespaltene Fraktionen",b="Trotz der Omnipräsenz der Geißel halten mehrere Fraktionen umkämpfte Stützpunkte. Der Scharlachrote Kreuzzug kontrolliert die Festung Herdweiler im Norden und läutert mit fanatischem Eifer alles, was er für verdorben hält. Im Süden sammeln sich die Streitkräfte der Allianz im Zugwindlager, während die Verlassenen ihre Grenzen am Bollwerk verteidigen. Die Vermittlung und Führung des Kampfes gegen die untoten Kessel obliegt der neutralen Argentumdämmerung, die Streiter beider Fraktionen unterstützt und Uthers Grabmal bewacht – den letzten wahrhaft geweihten Boden in der Region."}},faq={{q="Warum traf die Seuche dieses Gebiet so hart?",a="Andorhal war der landwirtschaftliche Umschlagplatz des nördlichen Lordaeron. Kel'Thuzad zielte vorsätzlich auf die regionale Versorgung ab, infizierte Getreidesilos und stellte gewaltige Pestkessel auf vier großen Gehöften auf, um den Untod rasch über Nahrungsmittellieferungen im gesamten Königreich zu verbreiten.",al={"warum westliche pestländer verseucht","was geschah mit andorhal","warum kessel hier"}},{q="Wer kontrolliert Herdweiler im Norden?",a="Herdweiler und seine Festung, Burg Mardenholde, werden vom Scharlachroten Kreuzzug beherrscht. Obwohl es ursprünglich ein regionales Verwaltungszentrum Lordaerons war, richten die Fanatiker nun jeden Außenstehenden hin, der sich ihren Grenzen nähert, und begegnen allen Nicht-Kreuzfahrern mit Misstrauen.",al={"herdweiler fraktion","wer lebt in burg mardenholde","ist herdweiler freundlich"}},{q="Wo finden Spieler der Allianz und der Horde sichere Außenposten?",a="Die Allianz unterhält das Zugwindlager nahe der südlichen Grenze zum Alteracgebirge, das einen Flugmeister und Verbündete der Argentumdämmerung bietet. Die Horde operiert vom Bollwerk an der Westgrenze aus, wenn man aus Tirisfal anreist.",al={"wo sind die flugpunkte","horde lager wpl","allianz lager wpl"}},{q="Welchen Zweck haben die Pestkessel auf den Feldern?",a="Vom Kult der Verdammten auf dem Teufelssteinfeld, Dalsons Tränenfeld, Dem trostlosen Feld und Gahrrons Trauerfeld errichtet, pumpen diese Kessel unentwegt Seuchendämpfe in Luft und Boden. Agenten der Argentumdämmerung rekrutieren Abenteurer, um die Kessellords zu erschlagen und Gegenmittel für die giftigen Gebräue zu entwickeln.",al={"was sind die kessel","kessel zweck","teufelsstein kessel"}},{q="Was ist Scholomance und wo befindet es sich?",a="Scholomance ist eine unterirdische Akademie der Nekromantie, die von der Geißel und dem Kult der Verdammten betrieben wird. Sie liegt verborgen unter den Ruinen von Darrowehr, einer Inselfestung im südöstlichen Gewässer des Darrowmeresees.",al={"scholomance standort","wo ist scholomance","darrowehr dungeon"}},{q="Ist irgendein Teil der Westlichen Pestländer unverderbt?",a="Uthers Grabmal, das auf Trauerhügel nahe dem Südrand der Zone liegt, bleibt vollkommen heilig und von der Seuche unberührt. Es steht als geweihter Gedenkort für den gefallenen Obersten General Uther den Lichtbringer und den verlorenen Orden der Silbernen Hand.",al={"heiliger boden in wpl","ist uthers grabmal rein","uthers grabmal sicher"}}},fp="19,342,28.378.0,18.438.0,16.443.0,41.268.0,37.227.0,56.233.0,58.277.0,44.206.0,51.204.0"}
P.entries["zone:westfall"] = {n="Westfall",s="Die Höfe in Westfall liegen schutzlos da, und die Bruderschaft der Defias beherrscht weite Teile des Umlands. Einst die Kornkammer von Sturmwind, kommt das Gebiet nun ohne Unterstützung der Krone oder militärische Garnisonen kaum zurecht.",h="Die Höfe in Westfall liegen schutzlos da, und die Bruderschaft der Defias beherrscht weite Teile des Umlands.",kw={"die todesminen","defias","erntegolem","miliz","mondbruch","saldean","späherkuppe","starkmantel","vancleef","westfall"},ang={["class:Rogue"]="Als Schurke findest Du in ganz Westfall einen Schattenkrieg vor, in dem Spione von SI:7 auf die abgebrühten Kundschafter, Diebe und Meuchelmörder der Bruderschaft der Defias treffen.",["faction:Alliance"]="Als Reisender der Allianz kannst Du sehen, wie die Volksmiliz die Späherkuppe hält. Ohne sie würde die Bruderschaft der Defias die südlichen Zugänge zum Wald von Elwynn kontrollieren.",["profession:Cooking"]="Als Koch kannst Du erfahren, wie die geplagten Siedler auf Saldeans Farm mit zähen einheimischen Tieren auskommen und Reisenden beibringen, Westfall Stew zuzubereiten.",["race:Human"]="Als Mensch zeigt Westfall den politischen Verfall von Sturmwind. Die Bauern, die im Dreck hungern, wurden von den Adligen im Stich gelassen, für die sie sich abmühten, Nahrung anzubauen."},sec={{t="Ein vergessenes Land",b="Westfall versorgte das Königreich Sturmwind einst mit seinen Weiden und Weizenfeldern. Nach dem Zweiten Krieg wurden die Finanzen des Königreichs knapp, und seine Anführer vernachlässigten das Gebiet. Sturmwind schickte seine Ressourcen anderswohin und zog seine Garnisonen ab, sodass das Land brachlag. Heute machen ödes Weideland, scharfe Küstenwinde, abtrünnige Erntegolems und Gnolle des Flusspfotenstamms den wenigen Siedlern, die noch geblieben sind, das Überleben schwer."},{t="Der Aufstieg der Bruderschaft",b="Die Ankunft der Bruderschaft der Defias beschleunigte Westfalls Niedergang. Die Banditen tragen rote Masken und folgen einem Anführer, dessen Namen niemand im Umland kennt. Sie machten Westfall zu ihrer Hochburg, verbrannten die Felder der Bauern, versalzten den Boden und bemächtigten sich verlassener Minen. Von Mondbruch aus, einer Geisterstadt, beherrscht die Bruderschaft fast das gesamte Umland, auch wenn sie es dem Namen nach nicht tut."},{t="Die Volksmiliz",b="Das Haus der Edlen hat Westfalls Notlage ignoriert, also haben die Einheimischen selbst zu den Waffen gegriffen. Auf der Späherkuppe stellte Gryan Starkmantel die Volksmiliz auf, eine Freiwilligentruppe, die Gnollen und Banditen die Stirn bietet. Sturmwind schickt weder reguläre Soldaten noch Vorräte. Die Miliz ist auf umherziehende Abenteurer angewiesen, die die Defias zurückdrängen und die verbliebenen Höfe schützen."},{t="Steinmetze mit roten Masken",b="Edwin van Cleef führt die Bruderschaft an. Er war der Gildenmeister, der Sturmwind wiederaufbaute, doch das Haus der Edlen verweigerte seinen Steinmetzen den Lohn, und Aufstände trieben sie fort. In Westfall griffen sie zur roten Maske. Die Banditen, die seine Felder niederbrennen, sind dieselben Hände, die die Mauern der Hauptstadt errichteten."},{t="Die Verschwörung in den Todesminen",b="Unter Mondbruch hat Edwin van Cleef in den verlassenen Goldstollen der Todesminen Halsabschneider, Goblins und Abtrünnige versammelt. Die Bruderschaft baut dort einen gewaltigen gepanzerten Koloss, der die Küste hinaufsegeln und Sturmwind bombardieren soll."}},faq={{q="Warum sind so viele Höfe in Westfall verlassen?",a="Sturmwind zog seine Garnisonen ab, als ihr Unterhalt zu teuer wurde, und ließ Westfall ungeschützt zurück. Daraufhin nahm die Bruderschaft der Defias weite Teile des Umlands ein, vertrieb die Siedler, verbrannte Ackerland und programmierte mechanische Erntewächter zu tödlichen Wachposten um.",al={"verlassene höfe","warum ist westfall tot","warum liegt das land brach"}},{q="Warum schickt Sturmwind keine Truppen, um Westfall zu helfen?",a="Die Schatzkammer des Königreichs ist überlastet, und das Haus der Edlen räumt Bedrohungen in anderen Ländern höhere Priorität ein. Auch Intrigen am Hof haben Westfall heimlich um Aufmerksamkeit und Vorräte gebracht, sodass die Bewohner sich selbst verteidigen müssen.",al={"warum schickt sturmwind keine armee","wo sind die wachen","hilfe aus sturmwind"}},{q="Was ist die Volksmiliz?",a="Gryan Starkmantel stellte auf der Späherkuppe die Volksmiliz auf, um Westfall zu verteidigen. Da die Krone keine Soldaten schickt, schlossen sich Bauern und Siedler zusammen, um gegen die Bruderschaft der Defias und die Gnolle des Flusspfotenstamms zu kämpfen.",al={"volksmiliz","miliz auf der späherkuppe","armee von gryan starkmantel"}},{q="Wer führt die Bruderschaft der Defias in Westfall an?",a="Edwin van Cleef, ehemaliger Gildenmeister der Steinmetzgilde, führt die Bruderschaft der Defias an. Er beaufsichtigte den Wiederaufbau von Sturmwind, führte dann seine Arbeiter nach Westfall und bewaffnete sie, nachdem ein erbitterter Streit um die Bezahlung in Aufständen geendet hatte.",al={"anführer der defias","wer führt die defias an","vancleef"}},{q="Was verbirgt sich in Mondbruch?",a="Unter einer unscheinbaren Scheune in Mondbruch liegt der Eingang zu den Todesminen. Die Bruderschaft der Defias machte aus der verlassenen Goldmine eine unterirdische Festung und Werft für ihren Krieg gegen Sturmwind.",al={"geheimnis von mondbruch","was ist in den todesminen","mine von mondbruch"}},{q="Warum greifen die mechanischen Vogelscheuchen Menschen an?",a="Goblinbastler, die mit den Defias verbündet sind, erbeuteten die mechanischen Erntewächter, die ursprünglich für die Feldpflege und zur Vertreibung von Schädlingen gebaut wurden. Sie rüsteten sie um, damit sie Felder patrouillieren und Eindringlinge töten.",al={"angreifende erntegolems","erntewächter","böse vogelscheuchen"}}},fx={cd1e134e={q="Was ist Westfall?",a="Westfall ist das windgepeitschte westliche Territorium des Königreichs Sturmwind, das westlich des Wald von Elwynn und südlich bis zum Meer liegt. Einst die fruchtbare Kornkammer des Königreichs, ernährten seine sanften Hügel und weiten Weiden Sturmwind über Generationen hinweg. Heute, von der Krone vernachlässigt und von Konflikten verwüstet, ist es zu brachliegenden Staubebenen, verfallenen Gehöften und einem Gesetzlosen-Gebiet verkommen.",al={"was ist diese zone","erzähl mir von westfall","westfall lore"}},["44cadea7"]={q="Warum ist es hier so leer?",a="Eine Kombination aus Dürre, Vernachlässigung und Räubertum hat die Landschaft entvölkert. Nach dem Zweiten Krieg konzentrierte Sturmwind seine Soldaten anderswo und ließ die örtlichen Gehöfte schutzlos zurück. Als sich die Bruderschaft der Defias erhob, vertrieben sie Bauern, brannten Ackerland nieder und versalzten die Felder. Ohne königliche Garnisonen, die sie schützen konnten, flohen die meisten Bewohner oder verhungerten.",al={"warum ist westfall unfruchtbar","warum so leer","warum sind hier keine leute"}},["1a97e791"]={q="War Westfall schon immer so arm?",a="Ganz und gar nicht. Über Generationen hinweg war Westfall Sturmwinds stolzes landwirtschaftliches Herzland, berühmt für goldene Weizenfelder, reichen Boden und ertragreiche Goldminen wie Jangolode und die Todesminen. Seine Nahrung ernährte die Hauptstadt, und seine Minen füllten die königlichen Schatzkammern, bevor Kriege und innere Unruhen es unfruchtbar machten.",al={"war westfall schon immer arm","war westfall früher wohlhabend","westfall vergangenheit"}},["1d4a9481"]={q="Wer ist die Bruderschaft der Defias?",a="Die Bruderschaft der Defias ist eine riesige kriminelle Organisation, die sich aus abtrünnigen Steinmetzen, Dieben, Wegelagerern und Ausgestoßenen zusammensetzt. Unter der Führung von Edwin van Cleef besetzten sie die verlassenen Ackerflächen und Minen von Westfall, um einen erbitterten Schattenkrieg gegen das Königreich Sturmwind zu führen, mit der Absicht, Vergeltung für unbezahlte Schulden und vermeintliche Verrate zu üben.",al={"wer sind die defias","was ist die bruderschaft der defias","wer sind diese banditen"}},b6953315={q="Warum tragen die Defias rote Bandanas?",a="Rote Bandanas sind das Markenzeichen der Bruderschaft der Defias, und das Material zeigt den Rang eines Mitglieds an. Red Silk Bandanas kennzeichnen hochrangigere Mitglieder; Späherin Riell bittet Abenteurer, sie als Beweis für deren Tod zu sammeln.",al={"warum rote bandanas","defias rote masken","bedeutung rote masken"}},["908b4fe1"]={q="Was wollen die Defias in Westfall?",a="Sie behandeln Westfall als ihre souveräne Festung und ihren Stützpunkt. Indem sie die Goldminen kontrollieren, Nahrungsmittelvorräte beschlagnahmen und loyale Bauern vertreiben, können sie im Geheimen ihre Streitkräfte und Maschinen abseits von Sturmwinds direktem Blickfeld aufbauen, während sie den Untergang des Königreichs planen.",al={"was wollen die defias","defias ziele westfall","warum sind die defias in westfall"}},d384bc2d={q="Warum wurde ich nach Westfall geschickt?",a="Ihr wurdet hierher geschickt, weil Sturmwinds reguläres Militär sich weigert oder nicht in der Lage ist, Truppen nach Westfall zu entsenden, was das Territorium an den Rand des Zusammenbruchs durch das Räubertum bringt. Die Behörden im Wald von Elwynn leiten fähige Abenteurer nach Westen, um die kämpfenden Einheimischen zu unterstützen, die verzweifelt nach Hilfe suchen.",al={"warum bin ich in westfall","wer hat mich nach westfall geschickt","warum wurde ich hierher geschickt"}},d59f010f={q="Wer ist Gryan Starkmantel?",a="Gryan Starkmantel ist ein Paladin der Silbernen Hand und stammt aus Westfall. Als er nach dem Kampf in Lordaeron während des Dritter Krieg nach Hause zurückkehrte, fand er seine Heimat von Banditen überrannt und vom Militär Sturmwinds verlassen vor. Als Reaktion darauf versammelte er lokale Verteidiger, um die Bürgerwehr bei Späherkuppe zu gründen.",al={"wer ist starkmantel","gryan starkmantel","wer führt späherkuppe"}},af1c3ddb={q="Hat Gryan Starkmantel tatsächlich das Sagen in Westfall?",a="Praktisch gesehen, ja. Während der junge König in Sturmwind rechtlichen Anspruch auf Westfall erhebt, übt die Krone hier so gut wie keine wirkliche Autorität aus. Starkmantel und seine freiwillige Bürgerwehr bei Späherkuppe stellen die einzige funktionierende Verteidigung und Strafverfolgung dar, die im Reich verblieben ist.",al={"wer regiert westfall","ist starkmantel der anführer","wer hat das sagen"}},ec2fd06e={q="Hat Sturmwind sich wirklich geweigert, die Steinmetze zu bezahlen?",a="Ja. Das Haus der Adligen hatte durch die Ausweitung militärischer Expeditionen an anderen Orten erschütternde Schulden angehäuft, was das Königreich fast in den Bankrott trieb. Beeinflusst von Hofintrigen und aristokratischer Arroganz boten die Adligen für die gewaltige Arbeit nur ein Almosen an und weigerten sich schlichtweg, die vollständigen Verträge einzuhalten.",al={"hat sturmwind die steinmetze betrogen","warum haben die adligen nicht bezahlt","bezahlungsstreit der steinmetze"}},cf60f690={q="Warum gibt es so viele Gnolle in Westfall?",a="Die Gnolle des Flusspfotenrudels sind über die Grenze migriert, um das Fehlen von Soldaten aus Sturmwind auszunutzen. Schlimmer noch, die Bruderschaft der Defias heuerte sie aktiv als Söldner an und stationierte sie in den Hügeln und Ebenen, um Reisende zu überfallen und alle überlebenden Gehöfte zu schikanieren.",al={"warum sind hier gnolle","flusspfoten gnolle westfall","danuvin gnolle"}},e40fa3bd={q="Was ist Mondbruch?",a="Mondbruch war einst der primäre Markt und die Bergbaustadt im südlichen Westfall. Über dem alten Eingang zu den Todesminen gelegen, wurde es vollständig von der Bruderschaft der Defias besetzt und geräumt, die nun die leeren Gebäude als perimetrischen Schutz für ihre unterirdische Festung nutzen.",al={"was ist mondbruch","mondbruch lore","erzähl mir von mondbruch"}},["46f1c864"]={q="Wohin führt die Untersuchung der Defias?",a="Eure Ermittlungen decken das geheime Herz der Bruderschaft unter Mondbruch in den Todesminen auf. Dort, tief in den unterirdischen Höhlen, überwacht Edwin van Cleef den Bau eines gewaltigen, eisenbeschlagenen Juggernauts, der Sturmwind vom Meer aus beschießen soll, was zu einem direkten Angriff auf den Gildenmeister selbst führt.",al={"wohin führt die defias-questreihe","wie endet die defias-geschichte","abschluss todesminen"}},["27471424"]={q="Wie bin ich in Westfall gelandet?",a="Ihr seid wahrscheinlich über die Flussbrücke aus dem Wald von Elwynn der Straße nach Westen gefolgt, geschickt von Behörden oder Freunden von Späherkuppe. Da Sturmwind überlastet ist und keine königlichen Truppen entbehren kann, hat sich in den benachbarten Ländern herumgesprochen, dass Gryan Starkmantel und die lokalen Bauern verzweifelt fähige Hände benötigen. Ob Ihr dem Ruf nach Hilfe gefolgt seid oder einfach nur dem Königsweg auf der Suche nach Arbeit gefolgt seid, Ihr seid in ein Reich eingetreten, das die Soldaten des Königreichs so gut wie aufgegeben haben.",al={"wie bin ich hierher gekommen","wie bin ich nach westfall gekommen","wie bin ich hier gelandet"}},["6324593c"]={q="Was soll ich in Westfall tun?",a="Eure Hauptmission ist es, die Bürgerwehr bei Späherkuppe dabei zu unterstützen, die unzähligen Bedrohungen zurückzuschlagen, die die Provinz ersticken. Gryan Starkmantel braucht Freiwillige, um die aggressive Tierwelt auszudünnen, die abtrünnigen Erntebeobachter zum Schweigen zu bringen, die durch brachliegende Felder streifen, und die Gnolle des Flusspfotenrudels zurückzudrängen. Vor allem seid Ihr damit beauftragt, die schwer fassbare Bruderschaft der Defias zu jagen, aufzudecken, wo sie sich verstecken, und ihren Würgegriff auf das zu lösen, was von Westfalls kämpfenden Gehöften übrig geblieben ist.",al={"was sollte ich hier tun","was mache ich in westfall","warum bin ich hier"}},c01912f7={q="Was geschah mit der Stonemasons Guild?",a="Unter Gildenmeister Edwin van Cleef verbrachte die Stonemasons Guild nach dem Ersten Krieg Jahre damit, Sturmwind wiederaufzubauen. Als die Arbeit getan war, weigerte sich das House of Nobles, die vereinbarte Summe zu zahlen. Nachdem friedliche Bitten gescheitert waren, wurde die Gilde gewaltsam aufgelöst, was wütende Aufstände entfachte, die die Steinmetze ins Exil trieben.",al={"was geschah mit den steinmetzen","geschichte der steinmetzgilde","wer waren die steinmetze"}}},fp="8,190,18.391.0,27.355.0,20.380.0,19.294.1,24.254.1,44.264.0,52.230.0,29.199.0,45.227.1,32.204.1,51.187.0"}
P.entries["zone:wetlands"] = {n="Sumpfland",s="Das Sumpfland ist ein weitläufiger, nebelverhangener Sumpf, eingebettet zwischen den Bergen von Khaz Modan und den Ufern der Baradinbucht. Historisch gebeutelt von Kriegen der Zwerge und Invasionen der Orcs, dient es als zerklüftete Pufferzone zwischen Eisenschmiede und den nördlichen Ländern von Lordaeron. Der befestigte Hafen von Menethil bildet die wichtigste Lebensader der Allianz in einer durchnässten Wildnis, die von Orcs des Drachenmals, Murlocs und Gnollen überrannt wird.",h="Das Sumpfland ist ein weitläufiger, nebelverhangener Sumpf, eingebettet zwischen den Bergen von Khaz Modan...",kw={"baradinbucht","drachenmal","dun algaz","dun modr","grim batol","menethil","hafen von menethil","thandol-übergang","sumpfland"},ang={["faction:Alliance"]="Der Hafen von Menethil dient der Allianz als wichtigstes Tiefseetor über das Große Meer und verbindet die Königreiche des Ostens mit den Expeditionsaußenposten in Kalimdor.",["profession:Mining"]="Die Hügel und höhlenartigen Tiefen des Thelgenfelsens bergen reiche Mineraladern, darunter seltene Vorkommen von Pyrophorerz, das von Zwergenbergleuten und Ingenieuren geschätzt wird.",["race:Dwarf"]="Für Zwerge ist das Sumpfland ein bittersüßer Ort, geprägt vom Verlust von Dun Modr, der uralten Tragödie von Grim Batol und den anhaltenden Mühen, König Magnis Handelsroute in den Norden zu verteidigen."},sec={{t="Ein Land aus Wasser und Ruinen",b="Unter dem hoch aufragenden Abgrund des Steinwerkdamms erstreckt sich das Sumpfland als kalte, wasserdurchtränkte Weite, die in ewigen Nebel und einheitlich grauen Himmel gehüllt ist. Einst Heimat blühender Zwergensiedlungen, sind die Marschen heute übersät von versunkenen Steinruinen, nassen Mooren und tückischen Sümpfen. Abenteurer, die die Region betreten, müssen sich durch schmale Pässe schlagen – entweder von Loch Modan aus durch den verbarrikadierten Engpass von Dun Algaz nach Norden oder über die hoch aufragenden Bögen des Thandol-Übergangs aus dem Arathihochland."},{t="Die Narben von Grim Batol",b="Die östlichen Gefilde des Sumpfes werden von der unheilvollen Präsenz von Grim Batol beherrscht, der einstigen Festung der Wildhämmer. Nach ihrer Entweihung während des Krieges der drei Hämmer wurde sie während des Zweiten Krieges zur befestigten Bastion des Drachenmalklans. Als sich der rote Drachenschwarm aus der Gefangenschaft der Orcs befreite, zerschmetterte seine feurige Rache die orcischen Streitkräfte und verwüstete die umliegenden Hänge. Heute bewachen rote Wyrmkin die Tore des Drachenmals vor allen Eindringlingen, während verwilderte Überreste des Drachenmalklans in verstreuten Lagern in den Hügeln hausen und weiterhin Reisende im gesamten Sumpf überfallen."},{t="Hafen der Westküste",b="An den Gestaden der Baradinbucht gelegen, ist der Hafen von Menethil das pulsierende Herz des Handels und der Logistik der Allianz in Khaz Modan. Zu Ehren von König Terenas Menethil II. benannt, verbindet dieser wehrhafte Hafen die Östlichen Königreiche mit dem fernen Kalimdor durch regelmäßige Transportschiffe, die zur Insel Theramore und über Süderstade nach Auberdine fahren. Trotz seiner strategischen militärischen Bedeutung und der soliden Zwergenarchitektur ist der Hafen ständig durch Küstenmurlocs, Sumpfkreaturen und Küstenräuber bedroht, die Schiffen auflauern, welche die felsigen Kanäle befahren."},{t="Belagerte Grenzgebiete",b="Das Sumpfland ist an mehreren Fronten ein aktives Kriegsgebiet. Weit im Norden haben Dunkeleisenzwerge unter dem Hexenmeister Balgaras the Foul den Thandol-Übergang durch Bomben sabotiert und die Stadt Dun Modr überrannt, wodurch Überland-Nachschubzüge abgeschnitten wurden. Unterdessen treiben Mosshide-Gnolle in den zentralen Mooren ihr Unwesen und bedrohen selbst uralte Beschützer wie Rethiel den Sumpfhüter. Zwischen abtrünnigen Kriegstrupps der Orcs, Infiltratoren der Dunkeleisenzwerge und verfluchten Schiffswracks entlang der Küste erfordert das Halten des Sumpfes ständige Wachsamkeit."}},faq={{q="Wie reise ich zu Fuß ins Sumpfland?",a="Abenteurer der Allianz reisen im Allgemeinen von Loch Modan aus nach Norden durch den Gebirgspass von Dun Algaz. Reisende der Horde, die aus dem Norden kommen, können vom Arathihochland aus den Thandol-Übergang überqueren. Passt auf, denn beide Passagen sind von feindlichen Kräften wie Orcs des Drachenmals und Dunkeleisenzwergen umkämpft.",al={"wie man ins sumpfland gelangt","weg ins sumpfland","lauf ins sumpfland"}},{q="Wohin fahren die Schiffe im Hafen von Menethil?",a="An den Docks im Hafen von Menethil werden zwei bedeutende Fährverbindungen nach Kalimdor betrieben: Ein Schiff legt in Süderstade im Vorgebirge des Hügellands an und fährt dann über das Große Meer nach Auberdine an den Gestaden der Dunkelküste, während das andere nach Süden zur Insel Theramore in den Düstermarschen segelt.",al={"schiffe von menethil","schiffe im hafen von menethil","wohin fährt das schiff im sumpfland"}},{q="Was ist Grim Batol und warum wird es bewacht?",a="Grim Batol ist eine uralte Zwergenfestung, die nach dem Krieg der drei Hämmer verlassen und später vom Drachenmalklan besetzt wurde. Nach dem Zweiten Krieg vertrieb der befreite rote Drachenschwarm die Orcs und versiegelte den Berg. Mächtige rote Drachenbrut und Wyrmkin patrouillieren an den Toren des Drachenmals, um zu verhindern, dass irgendjemand die verfluchten Hallen betritt.",al={"warum gibt es drachen bei grim batol","grim batol rote drachen","tore des drachenmals"}},{q="Was geschah mit Dun Modr?",a="Dun Modr war eine nördliche Zwergenfestung, die den Thandol-Übergang bewachte. Vor Kurzem wurde sie von Dunkeleisenzwergen unter der Führung von Balgaras the Foul angegriffen und überrannt. Die Überlebenden unter der Führung von Rhag Garmason halten in der Nähe ein umkämpftes Lager, während sie darum kämpfen, ihre Stadt zurückzuerobern.",al={"wer hat dun modr zerstört","ruinen von dun modr","dunkeleisenzwerge in dun modr"}},{q="Wer ist Rethiel der Sumpfhüter?",a="Rethiel ist eine uralte Sumpfbestie, die im Grünen Gürtel des Sumpflands weilt. Er bittet Reisende um Hilfe, um die Flut der aggressiven Mosshide-Gnolle einzudämmen und erkrankte Fen Creepers zu erlegen, damit sich die Marschen erholen können.",al={"der grüne gürtel","rethiel sumpfland","wer ist der sumpfhüter"}},{q="Woher kamen all die Orcs im Sumpf?",a="Die Orcs gehören dem Drachenmalklan an, der sich ursprünglich während des Zweiten Krieges in Grim Batol verschanzt hatte. Nachdem sie vom befreiten roten Drachenschwarm vernichtend geschlagen worden waren, flohen die überlebenden Orcs hinab in den Sumpf und die Hügel, wo sie immer noch Überfälle auf Straßen und Reisende verüben.",al={"warum gibt es orcs im sumpfland","sumpfland drachenmal","drachenmalklan sumpfland"}}},fx={["4984d286"]={q="Warum ist es hier überall Sumpf?",a="Das Sumpfland liegt in einem tiefen Becken, das an drei Seiten von hoch aufragenden Gebirgszügen begrenzt wird, die den Abfluss aus den Höhen darüber auffangen. Es wird von zahllosen Flüssen, Teichen und Bächen gespeist, die in Richtung der Baradinbucht fließen und die Erde ständig feucht und kalt halten.",al={"warum ist das sumpfland ein sumpf","geografie des sumpflands","warum so viel wasser im sumpfland"}},["60c5b961"]={q="Wer lebt im Sumpfland?",a="Die wichtigste zivilisierte Präsenz ist die Allianz im Hafen von Menethil, zusammen mit zwergischen Bergsteigern, die darum kämpfen, wichtige Außenposten zu halten. Die Wildnis wird jedoch von feindlichen Kräften dominiert: abtrünnige Orcs des Drachenmals, die sich in den östlichen Ausläufern verstecken, Mosshide-Gnolle, die durch die Moore streifen, Murlocs, die an den Küsten kriechen, und gewalttätige Dunkeleisenzwerge, die von Dun Modr aus nach Süden drängen.",al={"wer lebt hier","fraktionen im sumpfland","bewohner des sumpflands"}},["8d21dccb"]={q="Was ist der Hafen von Menethil und wer betreibt ihn?",a="Der Hafen von Menethil ist eine schwer befestigte Hafenstadt auf einer Insel in der Baradinbucht und dient als wichtigstes Küstentor der Allianz in Khaz Modan. Benannt zu Ehren von König Terenas Menethil II. von Lordaeron, wird sie von Zwergen und verbündeten Menschen unterhalten, durch die dicken Steinmauern von Burg Menethil geschützt und von der Garnison von Hauptmann Starkfaust bewacht.",al={"hafen von menethil","wer verwaltet menethil","stadt menethil"}},fd9bb568={q="Warum haben die Zwerge hier einen Hafen gebaut?",a="Während des Zweiten Krieges errichtete Orgrim Schicksalshammer hier eine Werft, um die Horde über die Baradinbucht nach Lordaeron zu übersetzen. Nachdem die Allianz die Orcs vertrieben hatte, beanspruchte sie den Ort für sich und baute ihn zu einem blühenden Hafen aus, wodurch wichtige maritime Versorgungsrouten etabliert wurden, die Khaz Modan sowohl mit menschlichen Verbündeten als auch mit fernen Ländern jenseits des Meeres verbinden.",al={"warum hafen von menethil","warum einen hafen im sumpf bauen","grund für den hafen von menethil"}},["4cff40a7"]={q="Ist der Hafen von Menethil Gebiet der Allianz?",a="Ja. Der Hafen von Menethil ist eine offizielle Festung der Allianz. Obwohl es eine raue, geschäftige Hafenstadt voller Seeleute, Händler, Reisender und grober Hafenarbeiter ist, weht dort das Banner der Allianz und sie wird von den Streitkräften aus Eisenschmiede verteidigt.",al={"ist menethil allianz","fraktion hafen von menethil","wem gehört der hafen von menethil"}},["6dc9c02b"]={q="Wer hat hier das Sagen?",a="Es gibt keinen einzelnen Herrscher über das ungezähmte Marschland. Die Autorität der Allianz konzentriert sich auf den Hafen von Menethil unter Hauptmann Starkfaust und der Garnison innerhalb von Burg Menethil. Außerhalb der Hafenmauern ist der Sumpf ein gesetzloses Grenzland, um das sich Militärpatrouillen, orcische Kriegsherren und urtümliche Bestien streiten.",al={"wer führt das sumpfland","kommandant des sumpflands","wer ist hier der chef"}},b8a9f96f={q="Wer ist Hauptmann Starkfaust?",a="Hauptmann Starkfaust ist der zwergische Kommandant, der die Garnison im Hafen von Menethil befehligt. Von der Sicherheit des Hafens aus koordiniert er Verteidigungsoperationen im gesamten Sumpf und beauftragt fähige Abenteurer damit, die unaufhörlichen Überfälle der nahegelegenen Orcs des Drachenmals einzudämmen.",al={"hauptmann starkfaust sumpfland","starkfaust lore","wer ist starkfaust"}},["38351a9f"]={q="Wer sind die Orcs des Drachenmals und warum sind sie hier?",a="Der Drachenmalclan ist ein brutaler Orcclan, der die Dämonenseele benutzte, um Alexstrasza und den roten Drachenschwarm während des Zweiten Krieges zu versklaven, und der von den Höhen von Grim Batol aus herrschte. Als die Drachenkönigin befreit wurde, zerschlugen die rachsüchtigen Drachen den Clan und zerstreuten die Überlebenden in die Sümpfe und Berge des Sumpflands, wo sie weiterhin eine gewalttätige, anhaltende Bedrohung darstellen.",al={"drachenmal sumpfland","warum sind drachenmal im sumpfland","orcs des drachenmals"}},ecc875bb={q="Wer sind die Dunkeleisenzwerge und warum greifen sie Dun Modr an?",a="Die Dunkeleisen sind ein tückischer, schattenwirkender Zwergenclan, der lange aus Eisenschmiede verbannt war. Sie nutzten aus, dass die Streitkräfte der Allianz im Ausland eingesetzt waren, stießen nach Norden vor, besetzten die Stadt Dun Modr und sabotierten den Thandol-Übergang, um wichtige Kommunikationswege zu kappen und Gebiete in Khaz Modan zurückzuerobern.",al={"dunkeleisen dun modr","warum dunkeleisen im sumpfland","dunkeleisen angriff sumpfland"}},["0f0d7fa8"]={q="Was ist der Thandol-Übergang und warum ist er wichtig?",a="Der Thandol-Übergang ist ein prächtiges Paar massiver steinerner Zwergenbrücken, die die Schlucht zwischen dem nördlichen Khaz Modan und dem Arathihochland überspannen. Er wurde nach dem Krieg der drei Hämmer gebaut, um Handel und Freundschaft mit den Wildhämmern zu erleichtern, und ist die einzige Landverbindung zwischen den südlichen Königreichen und dem nördlichen Lordaeron.",al={"thandol-übergang","thandol brücke","warum ist der thandol-übergang wichtig"}},faff9f74={q="Warum wollen die Dunkeleisen ihn in die Luft jagen?",a="Durch die Zerstörung des Thandol-Übergangs wollen die Dunkeleisen Eisenschmiede und Khaz Modan vollständig von den Verbündeten der Allianz in Lordaeron isolieren. Das Kappen dieser Überland-Lebensader verhindert, dass Verstärkung nach Süden marschiert, um Dun Modr zurückzuerobern oder bei weiteren Einfällen der Dunkeleisen zu helfen.",al={"warum thandol-übergang zerstören","dunkeleisen brückenkomplott","thandol-übergang in die luft jagen"}},eabba297={q="Wie bin ich im Sumpfland gelandet und wohin führt der Weg als Nächstes?",a="Die meisten Reisenden kommen an, indem sie von Loch Modan aus durch den Gebirgspass von Dun Algaz nach Norden marschieren oder die lange Reise mit dem Schiff in den Hafen von Menethil antreten. Von hier aus führt die Straße weiter nach Norden über den Thandol-Übergang in das Arathihochland, während Schiffe, die von den Docks ablegen, Abenteurer westlich über das große Meer tragen.",al={"wohin vom sumpfland aus","nächstes gebiet sumpfland","sumpfland weg"}},["75fb0ece"]={q="Ist das die Straße nach Eisenschmiede?",a="Ja. Wenn Ihr der Straße aus dem Sumpf nach Süden folgt, gelangt Ihr direkt in die engen Tunnel von Dun Algaz. Wenn Ihr das Gebirge durchquert, kommt Ihr nach Loch Modan, von wo aus die Hauptstraße nach Westen durch den Nordtorpass direkt in den Schnee von Dun Morogh und Eisenschmiede führt.",al={"straße nach eisenschmiede sumpfland","wie kommt man von sumpfland nach eisenschmiede","pfad nach eisenschmiede"}},["78aee5e0"]={q="Wie bin ich im Sumpfland gelandet?",a="Die meisten Reisenden der Allianz erreichen das Sumpfland, indem sie von Loch Modan aus nach Norden reisen und die engen Bergtunnel von Dun Algaz trotzen, um in die nebligen Marschlande unterhalb abzusteigen. Andere kommen mit dem Schiff von jenseits des großen Meeres an und segeln von den Küsten von Kalimdor in den Hafen von Menethil. Wer vom Arathihochland aus nach Süden reist, muss stattdessen die gefährlichen Übergänge des zerstörten Thandol-Übergangs meistern.",al={"wie bin ich hierher gekommen","wie kam ich im sumpfland an","woher bin ich gekommen"}},["87ca94d2"]={q="Was soll ich im Sumpfland tun?",a="Das Moor ist ein schwer bedrängtes Grenzland, in dem die Allianz an einem zerbrechlichen Stützpunkt festhält. Vom Hafen von Menethil aus seid Ihr dazu aufgerufen, wichtige Handelsrouten zu sichern und die verbliebenen Orcs des Drachenmals zurückzuschlagen, die das Tiefland überfallen. Weiter östlich und nördlich benötigen zwergische Bergsteiger Euren Stahl, um feindliche Gnollrudel einzudämmen, belagerten Ausgrabungsstätten zu helfen und Dunkeleisenzwerge zurückzudrängen, die drohen, den Thandol-Übergang vollständig zu unterbrechen.",al={"was soll ich hier tun","warum bin ich hier","was ist meine mission im sumpfland"}},["2cd88152"]={q="Was ist das Sumpfland?",a="Das Sumpfland ist ein kaltes, weitläufiges Marschland, eingebettet zwischen den Bergen von Khaz Modan und dem westlichen Meer. In ewigen grauen Nebel gehüllt, liegt es unmittelbar nördlich von Loch Modan und südlich vom Arathihochland. Einst Heimat zahlreicher Zwergensiedlungen, wurde die Region von vergangenen Kriegen verwüstet und dient nun als raue, ungezähmte Wildnis, die die Zwergenkönigreiche von den Ruinen von Lordaeron trennt.",al={"was ist das sumpfland","sumpfland lore","erzähl mir vom sumpfland"}}},fp="8,284,24.340.0,23.473.0,22.380.0,18.430.0,40.227.0,41.185.0,41.317.0,26.225.0,31.198.1,46.224.0"}
P.entries["zone:winterspring"] = {n="Winterquell",s="Winterquell ist ein riesiges, schneebedecktes Tal hoch an den nordöstlichen Hängen des Hyjal, direkt über den verzauberten Wäldern von Mondlichtung und dem Teufelswald. Die für ihre bittere Kälte, uralten Hochgeborenenruinen und umherstreifenden Spitzenprädatoren bekannte Region wird vom neutralen Goblin-Außenposten Ewige Warte zusammengehalten. Sie bleibt ein Land voller ungezähmter natürlicher Gefahren, das Überreste des blauen Drachenschwarms birgt und gleichzeitig an seinen südlichen Höhen gegen dämonische Verderbnis ankämpft.",h="Winterquell ist ein riesiges, schneebedecktes Tal hoch an den nordöstlichen Hängen des Hyjal, direkt über den...",kw={"blaue drachen","die flüsternde schlucht","donova schneeweh","ewige warte","frostsäbler","eiskappe","kel'theril","mazthoril","holzschlund","winterquell"},ang={["class:Druid"]="Hoch über Mondlichtung gelegen, besitzt Winterquell eine heilige Bedeutung als jener Ort, an dem Malfurion Sturmgrimm die Druiden der Kralle während des Dritten Krieges aus ihrem uralten Schlaf erweckte.",["faction:Alliance"]="Helden der Allianz besuchen regelmäßig Rivern Frostwind am Frostsäblerfelsen und arbeiten unermüdlich in der extremen Kälte, um sich die Treue der prestigeträchtigen Winterquell-Frostsäbler als Reittiere zu verdienen.",["profession:Herbalism"]="Winterquell ist der einzige bekannte Lebensraum für Eiskappen, ein unverzichtbares Gebirgskraut, das für fortgeschrittene alchemistische Rezepturen heiß begehrt ist, zusammen mit verstreutem Bergsilberweisling und seltenen Blüten von Schwarzem Lotus.",["profession:Mining"]="Die eisigen Felsen und Höhlenwände im gesamten Tal sind reich an wertvollen Mineralien und bergen häufig kleine sowie reiche Thoriumvorkommen nebst seltenen Echtsilberadern.",["race:NightElf"]="Winterquell ist eng mit der Geschichte der Elfen verknüpft: Hier befinden sich die Grabhügelbauten, in denen die Druiden der Kralle Jahrtausende lang ruhten, die tragischen Ruinen von Kel'Theril sowie freiliegende Wurzeln von Nordrassil, die während der Schlacht um den Hyjal beschädigt wurden."},sec={{t="Ein Reich des ewigen Frosts",b="Tausende Meter über der umliegenden Wildnis gelegen, ruht Winterquell unter klarer Bergluft und unerbittlichen Schneestürmen. Enorme, freiliegende Wurzeln des Weltenbaums Nordrassil durchziehen die Schneewehen wie hoch aufragende Holzbögen, verzerrt und verdreht während der Entscheidungsschlachten des Dritten Krieges. Während weite Teile des nördlichen Kalimdor von dichten Wäldern und warmem Klima geprägt sind, ist Winterquell ein stilles Land aus gemäßigten Gebirgswäldern, felsigen Klippen und gefrorenen Seen – Heimat beeindruckender Frostsäbler, Chimären, Yetis und dickfelliger Winterbären."},{t="Kreuzungen und Außenposten",b="Um dieses Hochplateau zu erreichen, müssen die uralten, in den Fels geschlagenen Gänge der Holzschlundfeste durchquert werden. Diese werden von unverdorbenen Furbolgs bewacht, die jeden Reisenden aus dem Teufelswald oder Mondlichtung genau mustern. Im Herzen des Tals liegt Ewige Warte, eine blühende Handelsstadt des Steamwheedle-Kartells. Die Goblins heißen sowohl Abenteurer der Allianz als auch der Horde mit offenen Kassenbüchern willkommen und bieten einen unverzichtbaren Zufluchtsort voller Ingenieurskunst, Handel und wärmender Feuer gegen den schneidenden Bergfrost."},{t="Alte Geister und blaue Drachen",b="Jahrhunderte bevor moderne Siedlungen entstanden, errichteten uralte Elfen die Stadt Kel'Theril am Seeufer. Nachdem leichtsinnige Zauberer der Hochgeborenen den verfluchten Kristall von Zin-Malor zerschlugen, verfielen sie dem Wahnsinn, sodass rastlose Phantome bis zum heutigen Tag zwischen den verfallenen Säulen und auf den gefrorenen Gewässern umherwandern. Weiter südlich erheben sich die höhlenartigen Höhen von Mazthoril, die traditionelle Festung des blauen Drachenschwarms auf Kalimdor. Hier wacht die Brut des Zauberwirkers Malygos unter der Führung der Schutzmatrone Haleh über arkane Strömungen und stellt sich lokalen Bedrohungen."},{t="Der drohende Schatten der Schlucht",b="Die Ruhe von Winterquell wird an seiner südlichsten Grenze in der Flüsternden Schlucht jäh gebrochen. Dort kriechen elitäre Dämonenstreitkräfte, verbliebene Legionen aus dem Dritten Krieg, durch zerklüftete Schluchten und versperren die hochgelegenen Zugänge zum Gipfel des Hyjal. Unterdessen sind die einheimischen Winterfall-Furbolgs finsterer Verderbnis anheimgefallen, was unabhängige Forscher wie Donova Schneeweh dazu veranlasst hat, dem um sich greifenden Makel nachzugehen, bevor die gesamte Tierwelt des Tals ihm zum Opfer fällt."}},faq={{q="Wie gelangt man nach Winterquell?",a="Reisende müssen durch die Holzschlundfeste ziehen, ein unterirdisches Tunnelnetz im nordöstlichen Teufelswald. Um die Höhlen friedlich zu durchqueren, muss man das Vertrauen der dort ansässigen Holzschlundfurbolgs gewinnen, die jeden als feindselig erachteten Eindringling angreifen. Hinter dem östlichen Ausgang erstrecken sich unmittelbar die schneebedeckten Hänge von Winterquell.",al={"nach winterquell gelangen","wie man nach winterquell kommt","eingang winterquell","holzschlundtunnel winterquell"}},{q="Wer kontrolliert die Stadt Ewige Warte?",a="Ewige Warte wird vom Steamwheedle-Kartell verwaltet, dem Handelsimperium der Goblins. Dank des strikten Profitstrebens und der Neutralität der Goblins haben sowohl Reisende der Horde als auch der Allianz Zugang zu Flugmeistern, Reparaturhändlern, Bankschließfächern und Handelswaren, sofern Besucher innerhalb der Stadtgrenzen den Frieden wahren.",al={"wer kontrolliert ewige warte","ewige warte fraktion","ist ewige warte neutral"}},{q="Was sind die Geister, die den Kel'Therilsee heimsuchen?",a="Es sind die Seelen der Hochgeborenen-Nachtelfen, die vor zehntausend Jahren die uralte Stadt Kel'Theril bewohnten. Als ihre Zauberer den gestohlenen Kristall von Zin-Malor manipulierten, löste dessen Zerstörung einen verheerenden Fluch aus. Nachfolgende Expeditionen von Hochelfen Jahrhunderte später verfielen gleichermaßen dem Wahnsinn und sind dazu verdammt, an der Seite ihrer Ahnen die gefrorenen Ruinen zu durchstreifen.",al={"kel'therilsee geister","die ruinen von kel'theril geister","wer ist bei kel'theril"}},{q="Warum sind die Winterfall-Furbolgs aggressiv?",a="Die Winterfall-Furbolgs sind einer sich ausbreitenden, unnatürlichen Verderbnis erlegen, die ihren Stamm in rasende Feindseligkeit gestürzt hat. Während die nahe gelegenen Holzschlundfurbolgs eisern an ihrem Verstand festhalten, sind die Winterfall finsteren Einflüssen verfallen. Forscher wie Donova Schneeweh versuchen daher, ihren Makel zu untersuchen und ihre Lager zu säubern.",al={"warum sind winterfall feindselig","winterfall stamm verderbnis","donova schneeweh furbolgs"}},{q="Was haust in Mazthoril?",a="Mazthoril ist der Hauptnistplatz und das Heiligtum des blauen Drachenschwarms auf Kalimdor. Tief in den höhlenartigen Türmen bewachen Drachkin, elitäre Welpen und uralte Drachen mächtige drakonische Relikte und arkane Geheimnisse unter dem wachsamen Auge von Haleh, der Gefährtin des Aspekts Malygos.",al={"mazthoril drachen","was ist mazthoril","blaue drachen in winterquell"}},{q="Was ist Die flüsternde Schlucht?",a="Die flüsternde Schlucht ist eine tückische Schlucht im südlichsten Teil des Tals, die von mächtigen Elitedämonen besetzt ist, welche aus dem Dritten Krieg übriggeblieben sind. Sie dient als schwer bewachter Vorposten entlang der gefährlichen Pfade, die zu den Höhen des Hyjal führen.",al={"die flüsternde schlucht dämonen","was ist in der flüsternden schlucht","hyjal tor winterquell"}},{q="Kann man hier Frostsäbler abrichten oder zähmen?",a="Am Frostsäblerfelsen im äußersten Norden des Tals kümmert sich der Nachtelf Rivern Frostwind um die einheimischen weißen Katzen. Abenteurer, die ihm bei der Beschaffung von Vorräten und dem Schutz des Rudels helfen, können sich als würdig erweisen, die Geheimnisse der Aufzucht und des Reitens eines Frostsäblers zu erlernen.",al={"frostsäbler reittier","rivern frostwind frostsäbler","wie man einen frostsäbler bekommt"}}},fp="12,328,26.408.0,23.361.0,26.385.0,31.374.0,29.250.0,30.220.0,45.324.0,43.293.0,28.244.0,26.191.0,39.225.0"}
P.entries["zone:zephras"] = {n="Insel Zephras",s="Die Insel Zephras ist eine fliegende Insel, die im Himmelswall schwebt, der Elementarebene der Luft. Sie dient den Skyborne als angestammte Heimat und Ausgangsort, deren Gesellschaft nun vor einer existenziellen Krise steht, da die Magie, die die Insel aufrechterhält, stetig schwindet. Da der Kontakt zu den benachbarten Himmelsreichen abgerissen ist, kämpfen ihre Bewohner gegen den elementaren Zusammenbruch und eintreffende Flüchtlinge.",h="Die Insel Zephras ist eine fliegende Insel, die im Himmelswall schwebt, der Elementarebene der Luft.",kw={"luftschiffe","anvilas","elementarebene","siroccas","skyborne","der himmelswall","valanaar","windsteine","zephras"},ang={["class:Shaman"]="Mitten in der Elementarebene der Luft gelegen, zeigt die Insel Zephras, was mit Elementarländern geschieht, wenn die Geister, die sie im Gleichgewicht halten, plötzlich verschwinden.",["race:Skyborne"]="Die Insel Zephras ist Eure angestammte Heimat und Euer Ausgangspunkt, doch ihre noch verweilende Schönheit täuscht über eine dringliche Krise aus einstürzendem Land und schwindender Elementarkraft hinweg."},sec={{t="Ein Reich in den Lüften",b="Die Insel Zephras ist eine isolierte Landmasse, die in den endlosen Winden des Himmelswalls treibt. Seit Generationen lebten die Skyborne hier Seite an Seite mit einheimischen Luftelementaren, die dabei halfen, die magischen Strömungen zu bewahren, die die Insel in der Luft hielten. Vor mehreren Jahrhunderten jedoch verschwanden diese elementaren Wächter spurlos. Beraubt ihrer Gegenwart und Obhut begannen die latenten Verzauberungen, die das Land trugen, langsam zu versagen, was dazu führte, dass Zephras allmählich aufbrach und instabil wurde."},{t="Abgeschnittene Horizonte",b="Zephras war nicht die einzige Zuflucht, die von den Skyborne innerhalb der Elementarebene bewohnt wurde. Auch die Schwesterninseln namens Anvilas und Siroccas trieben durch den Himmelswall, doch die Verbindung zwischen ihnen brach ab, nachdem die Elementare verschwunden waren. In jüngster Zeit ist es Flüchtlingen von diesen zerfallenden benachbarten Landmassen gelungen, auf der Suche nach Sicherheit Zephras zu erreichen, und sie brachten düstere Nachrichten mit: Die anderen Inseln lösen sich unter ihren Füßen vollends auf."},{t="Schwelle nach Azeroth",b="Da ihre eigene Landmasse langsam zerfällt, haben die Skyborne von Zephras begonnen, über die Grenzen des Himmelswalls hinaus nach Azeroth zu blicken. Von den Himmelsdocks von Valanaar brechen nun Luftschiffe auf, um seltene Rettungsanker in das Reich der Sterblichen zu schlagen. Diese Reisen verbinden das luftige Reich direkt mit Orten auf Azeroth, darunter den Ausläufern von Dalaran im Alteracgebirge und dem Himmelsschauerplateau in Mulgore."}},faq={{q="Wo befindet sich die Insel Zephras?",a="Die Insel Zephras liegt im Himmelswall, der Elementarebene der Luft, und nicht auf der Oberfläche von Azeroth. Sie schwebt inmitten der ewigen Wolken und Windströmungen dieser ätherischen Domäne.",al={"insel zephras ort","wo ist zephras","auf welcher ebene liegt zephras"}},{q="Warum bricht die Insel Zephras auseinander?",a="Die Insel war auf die Anwesenheit einheimischer Luftelementare angewiesen, die einst mit den Skyborne koexistierten. Vor mehreren Jahrhunderten verschwanden diese Elementare, wodurch die magischen Fundamente, die das fliegende Land verankern und erhalten, mit der Zeit langsam schwächer wurden und verfielen.",al={"warum stürzt zephras ein","insel zephras zerstörung","sterbende insel"}},{q="Was sind Anvilas und Siroccas?",a="Sie sind benachbarte schwebende Inseln im Himmelswall, die ebenfalls von den Skyborne bevölkert werden. Die Insel Zephras verlor die Verbindung zu beiden, als die Elementare verschwanden, und fliehende Flüchtlinge berichten nun, dass sowohl Anvilas als auch Siroccas im Nichts versinken.",al={"anvilas","siroccas","andere skyborne inseln"}},{q="Wie reist man zwischen der Insel Zephras und Azeroth?",a="Die Skyborne betreiben Himmelsdocks in der Siedlung Valanaar. Von diesen Docks aus starten Luftschiffe über die Grenzen der Ebenen hinweg nach Azeroth und landen nahe Dalaran im Alteracgebirge sowie am Himmelsschauerplateau in Mulgore.",al={"wie man zephras verlässt","zephras luftschiffe","reise nach azeroth"}},{q="Wer sind die Skyborne?",a="Die Skyborne sind die Bewohner, die auf der Insel Zephras und ihren Schwesternreichen am Himmel zu Hause sind. Nachdem sie Generationen lang im Himmelswall gelebt haben, stehen sie nun vor der langsamen Zerstörung ihrer fliegenden Heimat, da deren bindende Magie verblasst.",al={"skyborne volk","wer lebt auf zephras"}},{q="Wer lebt außer den Skyborne auf der Insel Zephras?",a="Abgesehen von friedlichen Dörfern und ankommenden Flüchtlingen wird die Insel von einheimischen Banditen, in Höhlen hausenden Nachtklauen und Bestien heimgesucht, die Gebiete wie den Kreischlingsbau und die Nachtklauenhöhle bewohnen.",al={"zephras bewohner","feinde auf zephras"}}},fx={["6e14d755"]={q="Werde ich die Insel irgendwann verlassen?",a="Ja. Während Insel Zephras als Euer Zuhause und anfänglicher Trainingsort dient, legen Luftschiffe von den Himmelsdocks in Valanaar ab, die durch dimensionale Risse das Festland von Azeroth erreichen und eine direkte Verbindung zu Dalaran im Alteracgebirge sowie zum Himmelsschauerplateau in Mulgore herstellen.",al={"werde ich zephras verlassen","insel zephras verlassen","können wir nach azeroth reisen"}},["19470e71"]={q="Wie bin ich auf Insel Zephras gelandet?",a="Ihr wurdet in das Volk der Himmelsgeborenen hineingeboren, den Shen'dorei, die auf dieser schwebenden Zuflucht hoch über Der Himmelswall, der Elementarebene der Luft, leben. Vor Jahrtausenden flohen Eure Vorfahren vor der Säuberung durch Prinz Tortheldrin in Eldre'Thalas und schlossen einen Pakt mit Windgeistern, die dieses Heiligtum in den Himmel hoben. Während andere Schwesterinseln wie Anvilas und Siroccas zerbröckeln oder in unerreichbare Ferne rücken, war Insel Zephras von Anfang an Euer Zuhause. Ihr beginnt Eure Reise hier inmitten Eures eigenen Volkes.",al={"wie bin ich hierher gekommen","wie habe ich insel zephras erreicht","warum bin ich hier aufgewacht","woher komme ich"}},["5dae6f41"]={q="Was soll ich auf Insel Zephras tun?",a="Euer Zuhause bröckelt unter Euren Füßen. Vor Jahrhunderten verschwanden die wohlwollenden Luftelementare und die arkanen Pylone, die Insel Zephras zusammenhalten, verlieren an Kraft. Flüchtlinge strömen von den zusammenbrechenden äußeren Inseln herbei, während rivalisierende Fraktionen, darunter Der Hohe Orden, die Windformer und die Al'Aketh, um das streiten, was noch übrig ist. Ihr müsst Eurem Volk helfen, interne Bedrohungen und wilde Bestien bezwingen, dabei helfen, die versagende Magie zu stabilisieren und letztendlich einen Weg hinunter nach Azeroth finden, bevor die Insel stürzt.",al={"was soll ich hier tun","was ist mein ziel hier","was mache ich auf insel zephras","warum bin ich hier"}},["1fd88046"]={q="Was ist die Insel Zephras?",a="Die Insel Zephras ist eine hoch aufragende, schwebende Landmasse innerhalb des Himmelswalls, der Elementarebene der Luft. Vor Jahrtausenden handelten verbannte Nachtelfen, die der Verfolgung in Eldre'Thalas entkamen, mit einheimischen Windgeistern, die die Insel in den Himmel hoben, um sie in Sicherheit zu bringen. Sie dient als angestammtes Heiligtum ihrer Nachkommen, den Himmelsgeborenen.",al={"was ist zephras","über die insel zephras","infos zur insel zephras"}},["7ea7c85c"]={q="Was ist auf der Insel Zephras passiert?",a="Die Insel Zephras wurde in den Himmelswall gehoben, nachdem hochgeborene Vorfahren sich von der blutigen Herrschaft von Prinz Tortheldrin in Eldre'Thalas abwandten. Die Himmelsgeborenen lebten jahrtausendelang in Harmonie mit Luftelementaren, doch vor Jahrhunderten verschwanden jene elementaren Gönner ohne Erklärung. Ohne ihre fortwährende Magie begannen die Pylone, die die Insel verankerten, zu verfallen, und Flüchtlinge von benachbarten, einstürzenden Inseln sind hierher geflohen, während interne Fraktionen um schwindende Ressourcen wetteifern.",al={"zephras geschichte","was ist hier auf zephras passiert","zephras lore"}},["70a3c6ae"]={q="Ist die Insel Zephras gefährlich?",a="Ja. Jenseits der drohenden physischen Gefahr, dass die Insel selbst instabil wird und vom Himmel stürzt, hat das Verschwinden der elementaren Beschützer das Land chaotisch hinterlassen. Banditenlager, feindliche Wildtierbaue und explosive politische Reibereien zwischen dem Hohen Orden, den Windformern und Al'Aketh machen Reisen außerhalb befestigter Siedlungen gefährlich.",al={"ist zephras gefährlich","zephras bedrohungen","gefahren auf zephras"}},b4875d06={q="Wo liegt die Insel im Vergleich zum Rest von Azeroth?",a="Die Insel Zephras ruht nicht auf der Oberfläche von Azeroth; sie treibt innerhalb des Himmelswalls, einer separaten dimensionalen Domäne, die von den Titanengeschmiedeten geschaffen wurde, um chaotische Luftelementare einzudämmen. Die einzigen physischen Verbindungen zwischen der Insel und der sterblichen Welt unterhalb sind spezialisierte Luftschiffe, die in Valanaar anlegen und über die Grenze zu Orten wie Dalaran und Mulgore reisen.",al={"wo liegt zephras zu azeroth","ist zephras in azeroth","zephras standort im vergleich zu azeroth"}},["2c89f95d"]={q="Wer sind die Al'Aketh?",a="Die Al'Aketh sind eine der rivalisierenden Fraktionen, die neben dem Hohen Orden und den Windformern um die Vorherrschaft auf der Insel Zephras kämpfen. Da die Pylone, die die Insel verankern, versagen und das Überleben immer verzweifelter wird, wetteifern die Al'Aketh aktiv um die Vorherrschaft und die Kontrolle über die verbleibenden mystischen Ressourcen der Insel.",al={"was sind die alaketh","fraktion al'aketh","wer ist alaketh"}}},fp="12,263,13.353.0,16.350.0,20.265.0,30.156.0,34.190.0,30.197.0,54.178.0,21.180.0,47.152.0"}
